-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('b751e80f-ca3c-58d8-8677-08fa937ac87d'::uuid, 'anglais', '3e', 'Les noms', 'Quel est le pluriel de « tooth » ?', 'mcq', '["tooths","teeth","teeths","toothes"]'::jsonb, 1, '« Tooth » fait partie des pluriels irréguliers, comme foot → feet : on change la voyelle au lieu d’ajouter -s.', 1),
    ('e5733607-bc28-58b7-8dd8-cd466fad2de6'::uuid, 'anglais', '3e', 'Les noms', 'There are three ___ in the field.', 'mcq', '["sheep","sheeps","sheepes","sheepies"]'::jsonb, 0, '« Sheep », comme fish et deer, est inchangé au pluriel : one sheep, three sheep.', 2),
    ('3baede51-9565-527e-8f5d-f51c3cb71ccb'::uuid, 'anglais', '3e', 'Les noms', 'Quel est le pluriel de « box » ?', 'mcq', '["boxs","boxies","boxes","boxen"]'::jsonb, 2, 'Après -s, -sh, -ch, -x ou -o, le pluriel se forme en -es : boxes, watches, potatoes.', 3),
    ('4075ac50-6620-55bc-aadf-6af1b26ffc1d'::uuid, 'anglais', '3e', 'Les noms', 'Quel est le pluriel de « boy » ?', 'mcq', '["boies","boyes","boyies","boys"]'::jsonb, 3, 'Le -y ne devient -ies qu’après une consonne (city → cities) ; après une voyelle, on ajoute simplement -s.', 4),
    ('2d06c5d1-87e6-5162-9ffa-86c25b14ff7f'::uuid, 'anglais', '3e', 'Les articles définis et les articles indéfinis', 'Comment traduit-on « Elle parle anglais » ?', 'mcq', '["She speaks English.","She speaks the English.","She speaks an English.","She speaks the english."]'::jsonb, 0, 'Les langues, comme les pays et les villes, s’emploient sans article (et avec une majuscule).', 1),
    ('a815d094-0117-59b0-bc1b-d192b6eae9ab'::uuid, 'anglais', '3e', 'Les articles définis et les articles indéfinis', 'Look at ___ moon tonight!', 'mcq', '["a","the","an","some"]'::jsonb, 1, 'Un objet unique prend toujours « the » : the sun, the moon.', 2),
    ('da50bddd-f28b-52b1-81ba-c2c9c5e2727f'::uuid, 'anglais', '3e', 'Les articles définis et les articles indéfinis', 'Quelle phrase est correcte ?', 'mcq', '["We have the lunch at noon.","We have a lunch at the noon.","We have lunch at noon.","We have some lunch at the noon."]'::jsonb, 2, 'Les repas s’emploient sans article : have lunch, for breakfast.', 3),
    ('930f32a0-476f-5a53-969e-b86bcd999266'::uuid, 'anglais', '3e', 'Les articles définis et les articles indéfinis', 'I bought a car last week. ___ car is red.', 'mcq', '["A","An","Some","The"]'::jsonb, 3, 'La voiture est déjà mentionnée : on passe de « a » (non identifié) à « the » (connu).', 4),
    ('df46cdc3-21ae-5ca2-9a6d-b55048566bc4'::uuid, 'anglais', '3e', 'Les adjectifs démonstratifs', 'Quelle est la seule différence audible entre « this » et « these » ?', 'mcq', '["La consonne finale","La voyelle : [ɪ] court contre [iː] long","L’accent tonique","Aucune, ils se prononcent pareil"]'::jsonb, 1, 'This se dit avec un [ɪ] bref, these avec un [iː] long : c’est ce qui distingue le singulier du pluriel à l’oral.', 1),
    ('68692a2b-5c21-553d-87e5-7575c5207340'::uuid, 'anglais', '3e', 'Les adjectifs démonstratifs', 'I still remember ___ summer we spent in Spain, years ago.', 'mcq', '["this","these","that","those"]'::jsonb, 2, 'La distance peut être dans le temps : « that » pour un moment passé et singulier.', 2),
    ('415a2a3b-f918-519e-a818-c12eddb22feb'::uuid, 'anglais', '3e', 'Les adjectifs démonstratifs', 'Dans « I prefer these. », quelle est la nature de « these » ?', 'mcq', '["Un adjectif démonstratif","Un pronom démonstratif","Un article","Un pronom personnel"]'::jsonb, 1, 'Employé seul, sans nom derrière lui, le démonstratif est un pronom.', 3),
    ('6c4c04e0-20ee-5761-903d-c3a49f6f1f59'::uuid, 'anglais', '3e', 'Les adjectifs démonstratifs', 'Comment présente-t-on sa sœur à quelqu’un ?', 'mcq', '["These is my sister, Kate.","Those is my sister, Kate.","It’s my sister, Kate, this.","This is my sister, Kate."]'::jsonb, 3, 'Pour présenter quelqu’un, l’anglais emploie « This is… », là où le français dit « Voici… » ou « C’est… ».', 4),
    ('8b41b75f-5d0a-5bd2-8356-fc8ade5d5d58'::uuid, 'anglais', '3e', 'Exprimer la possession', 'Ce téléphone n’est pas à moi, il est à elle : « It’s not mine, it’s … »', 'mcq', '["hers","her","her’s","she’s"]'::jsonb, 0, 'Le pronom possessif de « she » est « hers », sans apostrophe : il remplace « her phone ».', 1),
    ('0a837c9c-574f-596a-b0da-a7fc921ce1de'::uuid, 'anglais', '3e', 'Exprimer la possession', '___ bag is this? — It’s Kate’s.', 'mcq', '["Who","Whose","Which","Who’s"]'::jsonb, 1, 'La question du possesseur se pose avec « whose ». « Who’s » est la contraction de « who is ».', 2),
    ('2dfb690b-038f-5654-9912-7600df0db059'::uuid, 'anglais', '3e', 'Exprimer la possession', 'Comment dit-on « le journal d’aujourd’hui » ?', 'mcq', '["the newspaper of today’s","the today newspaper","today’s newspaper","today newspaper’s"]'::jsonb, 2, 'Le génitif ’s s’emploie aussi avec les expressions de temps : today’s newspaper, a week’s holiday.', 3),
    ('86d13b68-4996-5cf4-aa1d-1244cc3e31e0'::uuid, 'anglais', '3e', 'Exprimer la possession', 'Comment dit-on « Cette maison est la nôtre » ?', 'mcq', '["This house is our.","This house is our’s.","This house is the ours.","This house is ours."]'::jsonb, 3, '« Ours » est le pronom possessif : il s’emploie seul, sans article et sans apostrophe.', 4),
    ('95807c09-ccd1-5dc9-bf22-66ede7105752'::uuid, 'anglais', '3e', 'Exprimer une quantité', 'There is ___ milk in the fridge: we need to buy some.', 'mcq', '["no","any","a few","many"]'::jsonb, 0, '« No » équivaut à « not any » dans une phrase affirmative : There is no milk = There isn’t any milk.', 1),
    ('a871e7e5-0af2-5144-b7e0-d5202400f99a'::uuid, 'anglais', '3e', 'Exprimer une quantité', 'How ___ books have you read this year?', 'mcq', '["much","many","little","a little"]'::jsonb, 1, '« Books » est dénombrable pluriel : on demande « How many ». « Much » est réservé aux indénombrables.', 2),
    ('262274ab-acb5-50e9-844f-8c602c6ead6a'::uuid, 'anglais', '3e', 'Exprimer une quantité', 'I don’t have ___ money to buy this phone.', 'mcq', '["too","very","enough","so"]'::jsonb, 2, '« Enough » (assez) se place devant le nom : enough money. Devant un adjectif, il passe après : fast enough.', 3),
    ('8455176f-deb5-5d4d-b35a-4c7ed1537936'::uuid, 'anglais', '3e', 'Exprimer une quantité', 'Quelle phrase est correcte ?', 'mcq', '["Every students have a book.","Every student have a book.","Every students has a book.","Every student has a book."]'::jsonb, 3, '« Every » est suivi d’un nom singulier, et donc d’un verbe au singulier.', 4),
    ('d4879ba2-2c04-5255-b294-b04048f29c4e'::uuid, 'anglais', '3e', 'Les adjectifs qualificatifs', 'Comment dit-on « Ce film est effrayant » ?', 'mcq', '["This film is frightening.","This film is frightened.","This film is fright.","This film is frightfully."]'::jsonb, 0, 'L’adjectif en -ing décrit ce qui provoque le sentiment ; frightened décrirait la personne qui a peur.', 1),
    ('aa7fe942-45f1-5821-81bd-d6b48ead21ce'::uuid, 'anglais', '3e', 'Les adjectifs qualificatifs', 'The news was really ___: nobody expected it.', 'mcq', '["surprised","surprising","surprise","surprisingly"]'::jsonb, 1, 'La nouvelle provoque la surprise : adjectif en -ing. Ceux qui l’apprennent sont « surprised ».', 2),
    ('3414db45-dd75-5549-be6c-58540e1e17f6'::uuid, 'anglais', '3e', 'Les adjectifs qualificatifs', 'She looks ___ after the long trip.', 'mcq', '["tiredly","tiring","tired","tire"]'::jsonb, 2, 'Après un verbe d’état comme look, on emploie un adjectif ; en -ed, il dit ce que ressent la personne.', 3),
    ('76f200f3-06ba-5981-b5ff-1f06f5deea43'::uuid, 'anglais', '3e', 'Les adjectifs qualificatifs', 'Comment désigne-t-on « les sans-abri » comme groupe ?', 'mcq', '["the homelesses","homeless ones","the homeless’s","the homeless"]'::jsonb, 3, 'Précédé de « the », l’adjectif désigne tout un groupe et reste invariable, avec un verbe au pluriel.', 4),
    ('0f3045e6-d471-509c-9c37-bc32da86968e'::uuid, 'anglais', '3e', 'Les verbes lexicaux et les auxiliaires', 'Que signifie qu’un modal comme « can » est invariable ?', 'mcq', '["Il ne prend jamais de -s à la 3e personne","Il ne se met jamais en question","Il ne s’emploie qu’au présent","Il s’accorde avec le complément"]'::jsonb, 0, 'On dit « she can », jamais « she cans » : les modaux ne changent pas de forme.', 1),
    ('8eeca1f1-ec08-5012-9f4d-efde518ec32d'::uuid, 'anglais', '3e', 'Les verbes lexicaux et les auxiliaires', 'Quelle est la forme négative de « She has finished » ?', 'mcq', '["She doesn’t have finished.","She hasn’t finished.","She has finished not.","She didn’t finished."]'::jsonb, 1, '« Has » est ici l’auxiliaire du temps composé : « not » se place juste après lui.', 2),
    ('74ac94a5-3652-52b6-a213-92d588305926'::uuid, 'anglais', '3e', 'Les verbes lexicaux et les auxiliaires', 'Lequel de ces verbes est un verbe lexical ?', 'mcq', '["must","can","believe","should"]'::jsonb, 2, 'Un verbe lexical porte un sens (believe = croire) ; must, can et should sont des modaux, donc des auxiliaires.', 3),
    ('869d1165-e75e-5bff-84d7-66901798c29e'::uuid, 'anglais', '3e', 'Les verbes lexicaux et les auxiliaires', 'Quelle question correspond à « They are working » ?', 'mcq', '["Do they working?","Do they are working?","They working are?","Are they working?"]'::jsonb, 3, 'L’auxiliaire « be » passe devant le sujet : pas besoin de « do ».', 4),
    ('dad31963-45f3-53e0-b98d-7f7647ca07c1'::uuid, 'anglais', '3e', 'Les auxiliaires BE et HAVE', 'Comment dit-on « J’ai froid » ?', 'mcq', '["I am cold.","I have cold.","I have got cold.","I do cold."]'::jsonb, 0, 'Comme pour l’âge, l’anglais emploie « be » là où le français dit « avoir » : cold, hungry, thirsty, right, afraid.', 1),
    ('2662cec6-ff89-5e12-a873-05ef8b7c6182'::uuid, 'anglais', '3e', 'Les auxiliaires BE et HAVE', 'Que peut valoir la contraction « we’d » ?', 'mcq', '["we did ou we do","we had ou we would","we have ou we are","we were uniquement"]'::jsonb, 1, '« ’d » vaut « had » ou « would » : c’est ce qui suit qui tranche.', 2),
    ('96001887-bc00-5ef7-8786-f352f21b7003'::uuid, 'anglais', '3e', 'Les auxiliaires BE et HAVE', 'Quel est le prétérit de « have » avec « she » ?', 'mcq', '["has","haved","had","hads"]'::jsonb, 2, 'Au prétérit, « have » devient « had » à toutes les personnes.', 3),
    ('08351464-6c75-5c05-a972-34e98fb49a99'::uuid, 'anglais', '3e', 'Les auxiliaires BE et HAVE', 'Comment demande-t-on « As-tu pris ton petit déjeuner ? » au prétérit ?', 'mcq', '["Had you breakfast?","Did you had breakfast?","Have you breakfast?","Did you have breakfast?"]'::jsonb, 3, 'Dans une expression d’action (have breakfast, have a shower), « have » est lexical : la question se fait avec « do », au prétérit « did ».', 4),
    ('ccc0403a-90b9-5fe9-884f-a7f315ee5cdd'::uuid, 'anglais', '3e', 'L’auxiliaire DO', 'Quelle question est correcte ?', 'mcq', '["Can you swim?","Do you can swim?","Does you can swim?","Are you can swim?"]'::jsonb, 0, 'Avec un modal, DO n’apparaît jamais : le modal passe lui-même devant le sujet.', 1),
    ('02d88000-ccf4-5d26-89e1-0a30b7afb6ce'::uuid, 'anglais', '3e', 'L’auxiliaire DO', 'Comment insiste-t-on sur « Je te l’ai bien dit ! » ?', 'mcq', '["I did told you!","I did tell you!","I do told you!","I was tell you!"]'::jsonb, 1, 'L’insistance se fait avec « did » accentué, suivi de la base verbale : une seule marque du passé.', 2),
    ('d8871b39-317f-5595-bb20-67c911f7933d'::uuid, 'anglais', '3e', 'L’auxiliaire DO', 'Comment demande-t-on « Qu’est-ce que tu fais dans la vie ? » ?', 'mcq', '["What you do?","What do you?","What do you do?","What are you do?"]'::jsonb, 2, 'Quand « do » est lexical (faire), il faut un second « do » auxiliaire pour interroger.', 3),
    ('3b108a4e-4bbd-5857-bc5d-bdda4ae38d5d'::uuid, 'anglais', '3e', 'L’auxiliaire DO', 'Quelle forme négative de DO emploie-t-on au prétérit avec « she » ?', 'mcq', '["doesn’t","don’t","hadn’t","didn’t"]'::jsonb, 3, 'Au prétérit, « didn’t » vaut pour toutes les personnes ; doesn’t est réservé au présent.', 4),
    ('03fba863-01d9-58a4-948c-00bf178b7e8b'::uuid, 'anglais', '3e', 'Expression de la modalité : l’obligation', 'At her school, she ___ wear a uniform: it’s the rule.', 'mcq', '["has to","have to","must to","musts"]'::jsonb, 0, 'L’obligation vient d’un règlement extérieur : « have to », qui prend un -s à la 3e personne.', 1),
    ('57b673f3-66e5-5aea-94fb-2b58289f40fc'::uuid, 'anglais', '3e', 'Expression de la modalité : l’obligation', 'Comment dit-on « Je devrai partir tôt demain » ?', 'mcq', '["I will must leave early tomorrow.","I will have to leave early tomorrow.","I must will leave early tomorrow.","I will had to leave early tomorrow."]'::jsonb, 1, '« Must » n’a pas de futur : on emploie « will have to ».', 2),
    ('165a5882-182b-59d4-a105-1e5b9b6c95cf'::uuid, 'anglais', '3e', 'Expression de la modalité : l’obligation', 'Que signifie « You needn’t worry » ?', 'mcq', '["Tu ne dois surtout pas t’inquiéter","Tu devrais t’inquiéter","Tu n’as pas besoin de t’inquiéter","Tu as dû t’inquiéter"]'::jsonb, 2, '« Needn’t » a le sens de « don’t have to » : absence d’obligation, pas interdiction.', 3),
    ('099e3f58-9cd6-5bc4-9462-7a5b960a21fb'::uuid, 'anglais', '3e', 'Expression de la modalité : l’obligation', 'Comment exprime-t-on une interdiction au passé ?', 'mcq', '["mustn’t have","didn’t must","hadn’t to","couldn’t ou wasn’t allowed to"]'::jsonb, 3, '« Mustn’t » n’a pas de passé : on dit « I couldn’t go out » ou « I wasn’t allowed to go out ».', 4),
    ('281b1d8b-a1ac-591d-848a-5f0d7df564cd'::uuid, 'anglais', '3e', 'Expression de la modalité : la capacité', 'Ask her tomorrow: she might ___ help you.', 'mcq', '["be able to","can","could","able"]'::jsonb, 0, 'Deux modaux ne se suivent jamais : après « might », « can » est remplacé par « be able to ».', 1),
    ('065a9e00-627c-5436-95d0-5ce7a7646df1'::uuid, 'anglais', '3e', 'Expression de la modalité : la capacité', 'Comment dit-on « J’ai pu finir » au present perfect ?', 'mcq', '["I have could finish.","I have been able to finish.","I have can finish.","I have able to finish."]'::jsonb, 1, '« Can » n’a pas de participe passé : on passe par « have been able to ».', 2),
    ('bf6f7bc5-7b1c-5909-be8a-1f6461c44b70'::uuid, 'anglais', '3e', 'Expression de la modalité : la capacité', 'Quelle tournure équivaut à « was able to » pour une réussite ponctuelle ?', 'mcq', '["used to","had to","managed to","ought to"]'::jsonb, 2, '« Managed to » dit qu’on est parvenu à faire quelque chose, cette fois-là.', 3),
    ('3d418862-52bd-5be2-8643-6c8e0670bb96'::uuid, 'anglais', '3e', 'Expression de la modalité : la capacité', 'Comment s’écrit la négation de « can » en un seul mot ?', 'mcq', '["can not","cann’t","cantn’t","cannot"]'::jsonb, 3, 'La forme pleine s’écrit « cannot », en un seul mot ; la contraction est « can’t ».', 4),
    ('c20d4fcb-57f7-5bad-b30d-6c3a279792f8'::uuid, 'anglais', '3e', 'Expression de la modalité : la permission', 'Que signifie « You can’t park here » ?', 'mcq', '["Tu n’as pas le droit de te garer ici","Tu ne sais pas te garer ici","Tu n’es pas obligé de te garer ici","Tu ne devrais pas te garer ici"]'::jsonb, 0, 'Dans le registre de la permission, « can’t » exprime le refus : c’est interdit.', 1),
    ('0e93423b-1096-54bc-8b7a-e91d4c1772ad'::uuid, 'anglais', '3e', 'Expression de la modalité : la permission', 'Quelle forme refuse une permission dans un registre formel ?', 'mcq', '["You can’t","You may not","You couldn’t","You don’t have to"]'::jsonb, 1, '« May not » est la forme formelle du refus, celle des règlements écrits.', 2),
    ('102529d6-1884-5f76-b197-3938c5335abe'::uuid, 'anglais', '3e', 'Expression de la modalité : la permission', 'Comment dit-on « Tu auras le droit de voter à 18 ans » ?', 'mcq', '["You will can vote at 18.","You may will vote at 18.","You will be allowed to vote at 18.","You will allowed to vote at 18."]'::jsonb, 2, '« Can » et « may » n’ont pas de futur : « be allowed to » se conjugue à tous les temps.', 3),
    ('aea7c3b7-a5c5-545f-b64f-54fec271b9b7'::uuid, 'anglais', '3e', 'Expression de la modalité : la permission', 'Quelle demande convient pour entrer dans le bureau du principal ?', 'mcq', '["Must I come in?","Do I may come in?","Can I to come in?","May I come in?"]'::jsonb, 3, '« May » est la forme la plus polie et la plus formelle pour demander la permission à un adulte.', 4),
    ('6cc4f530-5ae5-51b3-b413-7443d3dd7df8'::uuid, 'anglais', '3e', 'Expression de la modalité : donner un conseil', 'If I were you, I ___ apologise.', 'mcq', '["would","will","should have","am"]'::jsonb, 0, '« If I were you, I would… » est une façon courante de donner un conseil : « À ta place, je… ».', 1),
    ('36de10e8-badb-520b-812a-3affa89e9cd0'::uuid, 'anglais', '3e', 'Expression de la modalité : donner un conseil', 'Que signifie « The train should arrive at six » ?', 'mcq', '["Le train doit obligatoirement arriver à six heures","Le train devrait normalement arriver à six heures","Le train aurait dû arriver à six heures","Le train arrive toujours à six heures"]'::jsonb, 1, '« Should » exprime aussi ce qui est normal ou attendu, pas seulement un conseil.', 2),
    ('21c0f109-5b77-5f4c-9faa-4509e4979921'::uuid, 'anglais', '3e', 'Expression de la modalité : donner un conseil', 'Quelle phrase exprime une obligation, et non un conseil ?', 'mcq', '["You should rest.","You’d better rest.","You must rest.","Why don’t you rest?"]'::jsonb, 2, 'Should (conseil) < had better (pressant) < must (obligation).', 3),
    ('42692db7-ca0f-5395-907e-25d7d86f8b89'::uuid, 'anglais', '3e', 'Expression de la modalité : donner un conseil', 'Quelle est la négation de « You had better hurry » ?', 'mcq', '["You hadn’t better hurry.","You’d not better hurry.","You didn’t better hurry.","You’d better not hurry."]'::jsonb, 3, 'La négation de « had better » se place après « better » : You’d better not be late.', 4),
    ('6495e51f-cd0e-59bc-b00a-3bd81e99a4e9'::uuid, 'anglais', '3e', 'Expression de la modalité : la suggestion', 'Quelle phrase compare deux choix avec « would rather » ?', 'mcq', '["I’d rather stay home than go out.","I’d rather stay home that go out.","I’d rather to stay home than going out.","I’d rather staying home than go out."]'::jsonb, 0, '« Would rather » + base verbale, et « than » pour introduire le second choix, lui aussi à la base verbale.', 1),
    ('c14d8281-f2c0-594e-91e1-6b2df5c2097e'::uuid, 'anglais', '3e', 'Expression de la modalité : la suggestion', 'Que signifie « Shall I open the window? » ?', 'mcq', '["J’ouvrirai la fenêtre.","Veux-tu que j’ouvre la fenêtre ?","Dois-je obligatoirement ouvrir la fenêtre ?","J’ai ouvert la fenêtre."]'::jsonb, 1, '« Shall I…? » propose de faire quelque chose pour l’autre : c’est une offre, pas un futur.', 2),
    ('e1197b34-464b-5b52-a2e3-b27ea5a03b9d'::uuid, 'anglais', '3e', 'Expression de la modalité : la suggestion', 'Why not ___ again?', 'mcq', '["to try","trying","try","tried"]'::jsonb, 2, '« Why not » est suivi de la base verbale, comme « Let’s » et « Why don’t we ».', 3),
    ('d7005812-88cc-5f97-9d64-e1653abd761d'::uuid, 'anglais', '3e', 'Expression de la modalité : la suggestion', 'Quelle réponse accepte une suggestion ?', 'mcq', '["I’m afraid I can’t.","Sorry, I’m busy.","I’d rather not.","That sounds great!"]'::jsonb, 3, '« That sounds great! », « Good idea! » ou « Why not! » acceptent ; les trois autres refusent poliment.', 4),
    ('22196dd5-d346-54da-97c2-893791cb09be'::uuid, 'anglais', '3e', 'Expression de la modalité : le souhait et le regret', 'Quelle formule propose poliment à boire ?', 'mcq', '["Would you like a drink?","Do you want drink?","Will you like a drink?","Would you want to a drink?"]'::jsonb, 0, '« Would you like…? » est la forme polie de l’offre, plus douce que « want ».', 1),
    ('acd918fd-b3cd-5f25-84c9-4de03e9cfdb9'::uuid, 'anglais', '3e', 'Expression de la modalité : le souhait et le regret', 'Comment dit-on « Je regrette d’avoir dit ça » ?', 'mcq', '["I regret say that.","I regret saying that.","I regretted to said that.","I regret to saying that."]'::jsonb, 1, 'Pour un regret sur ce qu’on a fait, « regret » est suivi du verbe en -ING.', 2),
    ('b56b0d91-5a73-5ab7-b5bc-4ea44e3b6bb6'::uuid, 'anglais', '3e', 'Expression de la modalité : le souhait et le regret', 'Que signifie « If only I had listened! » ?', 'mcq', '["Si seulement j’écoutais !","J’ai bien fait d’écouter !","Si seulement j’avais écouté !","Si j’écoute, tout ira bien."]'::jsonb, 2, 'Comme « wish », « if only » + past perfect exprime un regret sur le passé, avec plus d’émotion.', 3),
    ('bb5031f6-32ff-5c60-a09b-628635bfee9f'::uuid, 'anglais', '3e', 'Expression de la modalité : le souhait et le regret', 'Quelle est la différence entre « would like » et « wish » ?', 'mcq', '["Aucune, ils sont interchangeables","« Wish » est plus poli","« Would like » exprime un regret","« Would like » dit un souhait ordinaire, « wish » un souhait irréel"]'::jsonb, 3, 'On dit « I’d like to travel » pour un souhait réalisable, « I wish I had more time » pour ce qui n’est pas.', 4),
    ('bf9bad33-4382-5b83-969a-c45d6a6a49da'::uuid, 'anglais', '3e', 'Expression de la modalité : la probabilité', 'She ___ be home by now: she left an hour ago.', 'mcq', '["should","mustn’t","can’t","had better"]'::jsonb, 0, '« Should » exprime ici une forte probabilité : ce qui est normalement le cas.', 1),
    ('4914435a-b91c-5a2c-babd-ed09802722e7'::uuid, 'anglais', '3e', 'Expression de la modalité : la probabilité', 'Que signifie « They can’t have arrived yet » ?', 'mcq', '["Ils n’ont pas le droit d’arriver","Ils ne peuvent pas être déjà arrivés","Ils sont peut-être arrivés","Ils auraient dû arriver"]'::jsonb, 1, '« Can’t have » + participe passé exprime une certitude négative sur le passé.', 2),
    ('810ee56b-c9ba-5650-be32-f63e4df319c0'::uuid, 'anglais', '3e', 'Expression de la modalité : la probabilité', 'Look at his face: he ___ be very tired.', 'mcq', '["can’t","mustn’t","must","should have"]'::jsonb, 2, 'Un indice présent mène à une quasi-certitude : « must » (il doit être fatigué, j’en suis sûr).', 3),
    ('6c826449-3d53-552a-a488-ac9ee4ee5701'::uuid, 'anglais', '3e', 'Expression de la modalité : la probabilité', 'Que signifie « It’s likely to rain » ?', 'mcq', '["Il ne pleuvra sûrement pas","Il aime la pluie","Il a plu","Il va probablement pleuvoir"]'::jsonb, 3, '« Be likely to » exprime la probabilité sans modal.', 4),
    ('199c9a0e-103c-510f-9598-ae5f113a7a7d'::uuid, 'anglais', '3e', 'Faire faire quelque chose à quelqu’un', 'Que signifie « The film made me cry » ?', 'mcq', '["Le film m’a fait pleurer","J’ai fait un film triste","Le film m’a laissé pleurer","J’ai fait pleurer le film"]'::jsonb, 0, '« Make » + complément + base verbale : ici, provoquer une réaction.', 1),
    ('51fc2552-c97f-5ab5-90c7-79b9752dcd01'::uuid, 'anglais', '3e', 'Faire faire quelque chose à quelqu’un', 'Comment dit-on « Je fais réparer mon téléphone », de façon familière ?', 'mcq', '["I get fixed my phone.","I get my phone fixed.","I get my phone to fix.","I make my phone fixing."]'::jsonb, 1, '« Get » + objet + participe passé a le même sens causatif que « have », dans un registre plus familier.', 2),
    ('f91b406c-738b-5a35-8514-4dcfeffed7f9'::uuid, 'anglais', '3e', 'Faire faire quelque chose à quelqu’un', 'Quel verbe traduit « autoriser » dans les tournures de « faire faire » ?', 'mcq', '["make","have","let","get"]'::jsonb, 2, '« Let » = laisser, autoriser : She let me borrow her bike.', 3),
    ('341187ea-4ae4-5927-aa93-b82fe3c30e6e'::uuid, 'anglais', '3e', 'Faire faire quelque chose à quelqu’un', 'Dans « We had the car repaired », qui a réparé la voiture ?', 'mcq', '["Nous-mêmes","Personne","La voiture s’est réparée seule","Un professionnel, à notre demande"]'::jsonb, 3, 'Avec « have » causatif, le sujet ne fait pas l’action : il la commande.', 4),
    ('ac105c3a-0549-54de-b977-e9c19c1295ee'::uuid, 'anglais', '3e', 'Les verbes à particule et les verbes prépositionnels', 'It’s cold outside: ___ your coat on.', 'mcq', '["put","take","give","turn"]'::jsonb, 0, '« Put on » signifie mettre un vêtement ; « take off » signifie l’enlever.', 1),
    ('817752c7-8ded-5aa9-87cc-30ab80bea3b9'::uuid, 'anglais', '3e', 'Les verbes à particule et les verbes prépositionnels', 'Que signifie « look forward to » ?', 'mcq', '["Regarder devant soi","Attendre avec impatience","S’occuper de","Chercher"]'::jsonb, 1, '« I look forward to seeing you » : j’ai hâte de te voir.', 2),
    ('ea99f277-383c-50c9-9122-8f249e1a8fad'::uuid, 'anglais', '3e', 'Les verbes à particule et les verbes prépositionnels', 'Que signifie « run out of » ?', 'mcq', '["Sortir en courant","S’enfuir","Être à court de","Dépasser"]'::jsonb, 2, '« We’ve run out of milk » : nous n’avons plus de lait. Le sens ne se déduit pas des mots.', 3),
    ('cc159bda-313c-58e0-ab54-55d7ddfa160c'::uuid, 'anglais', '3e', 'Les verbes à particule et les verbes prépositionnels', 'Quelle phrase est correcte ?', 'mcq', '["I’m waiting you.","I’m waiting to you.","I’m waiting you for.","I’m waiting for you."]'::jsonb, 3, '« Wait for » est un verbe prépositionnel : la préposition est obligatoire et précède son complément.', 4),
    ('bc3c2dd6-d036-52e9-8831-bf5875a2c2b0'::uuid, 'anglais', '3e', 'Infinitif et gérondif', 'They promised ___ on time.', 'mcq', '["to be","being","be","been"]'::jsonb, 0, '« Promise » fait partie des verbes suivis de TO + verbe, comme want, decide ou hope.', 1),
    ('ad67301a-e507-530b-864d-0bc48587bf4a'::uuid, 'anglais', '3e', 'Infinitif et gérondif', 'I remember ___ the door: I’m sure it’s closed.', 'mcq', '["to lock","locking","lock","locked"]'::jsonb, 1, '« Remember » + -ING : se souvenir d’avoir fait. « Remember to lock » voudrait dire « penser à fermer ».', 2),
    ('7dce9349-f8ee-59e1-af6f-f0cda541cd51'::uuid, 'anglais', '3e', 'Infinitif et gérondif', 'Would you mind ___ the window?', 'mcq', '["to open","open","opening","opened"]'::jsonb, 2, '« Mind » est suivi du verbe en -ING : Would you mind opening… ? (Ça te dérangerait d’ouvrir… ?)', 3),
    ('58a4aebe-5ee1-52b1-93fd-7234e9e2c12a'::uuid, 'anglais', '3e', 'Infinitif et gérondif', 'Que signifie « Try opening the window » ?', 'mcq', '["Réussis à ouvrir la fenêtre","N’ouvre surtout pas la fenêtre","Essaie d’ouvrir la fenêtre, même si c’est difficile","Essaie en ouvrant la fenêtre, pour voir si ça aide"]'::jsonb, 3, '« Try » + -ING : faire un essai pour voir le résultat. « Try to open » : faire un effort pour ouvrir.', 4),
    ('45161c39-ff40-5843-ab26-d330243905ef'::uuid, 'anglais', '3e', 'Les adverbes', 'This film is ___ interesting.', 'mcq', '["very","much","enough","a lot"]'::jsonb, 0, 'Les adverbes de degré (very, quite, too, really) se placent devant l’adjectif.', 1),
    ('85415137-c0dc-59b6-9100-8d2b774a41a6'::uuid, 'anglais', '3e', 'Les adverbes', 'Quel est l’adverbe de « happy » ?', 'mcq', '["happyly","happily","happilly","happly"]'::jsonb, 1, 'Pour un adjectif en -y, le y devient i avant -ly : happily.', 2),
    ('28857c60-2c47-52d2-ab97-0fd1649e9d68'::uuid, 'anglais', '3e', 'Les adverbes', 'Quel est l’adverbe de « fast » ?', 'mcq', '["fastly","fastily","fast","faster"]'::jsonb, 2, '« Fast », comme hard, late et early, a la même forme comme adjectif et comme adverbe.', 3),
    ('e5d00f45-2eed-56d7-aaca-4c52a31a7206'::uuid, 'anglais', '3e', 'Les adverbes', 'Comment dit-on « Il travaille dur » ?', 'mcq', '["He works hardly.","He hardly works.","He works hardily.","He works hard."]'::jsonb, 3, 'L’adverbe de « hard » est « hard ». « He hardly works » signifierait « il travaille à peine ».', 4),
    ('9670f6f0-36ae-5abc-a62e-4989ac112c68'::uuid, 'anglais', '3e', 'Le présent simple et le présent en BE + -ING', 'Pourquoi dit-on « The train leaves at six » au présent simple ?', 'mcq', '["Parce que c’est un programme fixe","Parce que l’action est en cours","Parce que c’est un agacement","Parce que c’est un souvenir"]'::jsonb, 0, 'Le présent simple exprime aussi un horaire ou un programme fixé à l’avance.', 1),
    ('e971de8b-c0c8-5162-a06d-8e16e784aeb8'::uuid, 'anglais', '3e', 'Le présent simple et le présent en BE + -ING', 'Water ___ at 100 °C.', 'mcq', '["is boiling","boils","boil","boiling"]'::jsonb, 1, 'Une vérité générale se dit au présent simple, avec le -s de la 3e personne.', 2),
    ('2c197173-5a7c-5548-a170-88aefdb7f2a8'::uuid, 'anglais', '3e', 'Le présent simple et le présent en BE + -ING', 'Quelle est la 3e personne de « watch » au présent simple ?', 'mcq', '["watchs","watchies","watches","watchez"]'::jsonb, 2, 'Après -ch, -sh, -x, -ss et -o, la 3e personne prend -es : watches, goes, misses.', 3),
    ('8b38a11c-33ca-5fd6-ba88-bd0586e3c557'::uuid, 'anglais', '3e', 'Le présent simple et le présent en BE + -ING', 'I ___ with my aunt this week, while my parents are away.', 'mcq', '["stay","stays","staying","am staying"]'::jsonb, 3, 'Une situation temporaire se dit au présent en BE + -ING.', 4),
    ('6f872786-9596-506e-8a6f-1c7989b2bb55'::uuid, 'anglais', '3e', 'Le prétérit simple', 'Quel est le prétérit de « live » ?', 'mcq', '["lived","liveed","livd","lieved"]'::jsonb, 0, 'Quand la base se termine par -e, on n’ajoute que -d : lived.', 1),
    ('43ea007e-0fee-59ef-80f2-f04b9522315e'::uuid, 'anglais', '3e', 'Le prétérit simple', 'Comment se prononce le -ed de « played » ?', 'mcq', '["[t]","[d]","[ɪd]","Il est muet"]'::jsonb, 1, 'Après un son sonore, -ed se prononce [d] ; après un son sourd, [t] (worked).', 2),
    ('afbe31c5-5a2a-5a42-ab08-f0eb150180f6'::uuid, 'anglais', '3e', 'Le prétérit simple', 'Comment se prononce la terminaison -ed de « wanted » ?', 'mcq', '["[t]","[d]","[ɪd]","Elle est muette"]'::jsonb, 2, 'Après un t ou un d, -ed forme une syllabe de plus : [ɪd], wanted, needed.', 3),
    ('95e09898-adc3-52ed-8253-8106779e243c'::uuid, 'anglais', '3e', 'Le prétérit simple', 'She ___ the door, took her coat and left.', 'mcq', '["opens","has opened","was opened","opened"]'::jsonb, 3, 'Une suite d’actions passées se raconte au prétérit simple.', 4),
    ('0e552b7e-60ac-5072-845b-44ed24de7990'::uuid, 'anglais', '3e', 'Le prétérit en BE + -ING', 'Dans « I was walking home when it started to rain », quelle action est l’événement ?', 'mcq', '["it started to rain","I was walking home","Les deux","Aucune"]'::jsonb, 0, 'Ce qui survient est au prétérit simple ; ce qui encadre (le décor) est en BE + -ING.', 1),
    ('473717ea-48b8-505b-97f9-209f57afcabe'::uuid, 'anglais', '3e', 'Le prétérit en BE + -ING', 'What were you doing at eight last night? — I ___ TV.', 'mcq', '["watched","was watching","have watched","am watching"]'::jsonb, 1, 'Une action en cours à un moment précis du passé se dit au prétérit en BE + -ING.', 2),
    ('fd715580-9456-50d6-ace1-eb9de98aee94'::uuid, 'anglais', '3e', 'Le prétérit en BE + -ING', 'Quelle est la forme interrogative de « You were working » ?', 'mcq', '["Did you working?","Was you working?","Were you working?","Did you were working?"]'::jsonb, 2, 'L’auxiliaire « were » passe devant le sujet, sans « did ».', 3),
    ('e83bc51b-8bc6-5442-9368-922d8bc573a2'::uuid, 'anglais', '3e', 'Le prétérit en BE + -ING', 'Quelle phrase est correcte ?', 'mcq', '["He was read when I arrived.","He were reading when I arrived.","He reading when I arrived.","He was reading when I arrived."]'::jsonb, 3, 'Was/were + verbe en -ING : « was » avec he, she, it et I.', 4),
    ('ab2c97f1-331e-56a0-9e2e-6c93746f6874'::uuid, 'anglais', '3e', 'Le present perfect', 'Que signifie « I have never been to Japan » ?', 'mcq', '["Je ne suis jamais allé au Japon","Je ne suis pas allé au Japon l’an dernier","Je n’irai jamais au Japon","Je n’étais pas au Japon"]'::jsonb, 0, 'Le present perfect exprime ici une expérience de vie, sans date.', 1),
    ('b349eeef-89f0-5e2f-9ec8-0952b8235175'::uuid, 'anglais', '3e', 'Le present perfect', '___ you ever eaten sushi?', 'mcq', '["Do","Have","Has","Are"]'::jsonb, 1, 'Present perfect : have + participe passé, et l’auxiliaire passe devant le sujet dans la question.', 2),
    ('c285feff-1e61-500c-ba4d-b9051bc48b44'::uuid, 'anglais', '3e', 'Le present perfect', 'Quelle phrase traduit « Elle travaille ici depuis 2020 » ?', 'mcq', '["She works here since 2020.","She has worked here for 2020.","She has worked here since 2020.","She worked here since 2020."]'::jsonb, 2, 'Une action commencée dans le passé et qui continue se dit au present perfect, pas au présent comme en français.', 3),
    ('54ddd988-692c-5daa-acfe-7cf86f5aff52'::uuid, 'anglais', '3e', 'Le present perfect', 'Quelle forme est correcte avec « he » ?', 'mcq', '["He have seen","He has saw","He is seen","He has seen"]'::jsonb, 3, 'Avec he, she, it, l’auxiliaire est « has », suivi du participe passé (seen, pas saw).', 4),
    ('8a0ca835-a170-5545-b28c-ff5e42287c28'::uuid, 'anglais', '3e', 'Le past perfect', 'She was upset because she ___ the test.', 'mcq', '["had failed","has failed","have failed","fails"]'::jsonb, 0, 'L’échec est antérieur à la tristesse, elle-même passée : past perfect.', 1),
    ('62d616a3-bb2f-58ab-90fa-6357abaf17cc'::uuid, 'anglais', '3e', 'Le past perfect', 'Que signifierait « When I arrived, the train left » ?', 'mcq', '["Le train était déjà parti","Le train est parti après mon arrivée","Le train n’est jamais parti","Je suis arrivé en train"]'::jsonb, 1, 'Sans past perfect, les deux actions se suivent dans l’ordre : j’arrive, puis le train part.', 2),
    ('5b3d020a-3ce5-5c90-aabd-cd1bd6001e5a'::uuid, 'anglais', '3e', 'Le past perfect', 'Quelle est la forme négative de « She had left » ?', 'mcq', '["She didn’t had left.","She hasn’t left.","She hadn’t left.","She had not leave."]'::jsonb, 2, 'La négation se place après « had » : hadn’t + participe passé.', 3),
    ('7f94e6a8-7c0a-5f4d-a4c4-b97fa8ca91dd'::uuid, 'anglais', '3e', 'Le past perfect', 'After he ___ eaten, he went out.', 'mcq', '["has","have","was","had"]'::jsonb, 3, 'Après « after », le past perfect marque l’action la plus ancienne.', 4),
    ('34b09f13-b7b3-5bb4-a0e0-aaf5b7ecfbf8'::uuid, 'anglais', '3e', 'Exprimer le futur', 'Laquelle de ces formes suppose le plus de préparation ?', 'mcq', '["BE + -ING (rendez-vous fixé)","will","be going to","Elles se valent"]'::jsonb, 0, 'Décision immédiate (will) → intention (going to) → rendez-vous fixé, avec date et lieu (BE + -ING).', 1),
    ('6db75ab8-c82f-52a9-9015-fb7b23394fa9'::uuid, 'anglais', '3e', 'Exprimer le futur', 'Quelle est la forme négative de « will » ?', 'mcq', '["willn’t","won’t","wasn’t","don’t will"]'::jsonb, 1, 'La forme contractée de « will not » est « won’t ».', 2),
    ('78e9eeca-f90a-5a7d-9d75-3a62fe1d6b57'::uuid, 'anglais', '3e', 'Exprimer le futur', 'Quelle phrase exprime une promesse ?', 'mcq', '["I am being there for you.","I was going to be there.","I will always be there for you.","I am there tomorrow."]'::jsonb, 2, '« Will » exprime la promesse et l’offre, en plus de la décision immédiate et de la prédiction.', 3),
    ('07359ea4-21c2-57ce-8752-6736504145dd'::uuid, 'anglais', '3e', 'Exprimer le futur', 'Comment demande-t-on « Viendras-tu ? » ?', 'mcq', '["Do you will come?","You come will?","Are you will come?","Will you come?"]'::jsonb, 3, '« Will » est un modal : il passe lui-même devant le sujet, sans « do ».', 4),
    ('0bc415ce-de2b-58c1-85e0-b116bb6ead31'::uuid, 'anglais', '3e', 'Exprimer le conditionnel', 'Quelle phrase est correcte ?', 'mcq', '["If I had time, I would help you.","If I would have time, I would help you.","If I have time, I would help you.","If I had time, I will help you."]'::jsonb, 0, 'Type 2 : if + prétérit, would + base verbale. Jamais de « would » après « if ».', 1),
    ('33abe898-3f42-57f3-afe1-9ad8743fd4a4'::uuid, 'anglais', '3e', 'Exprimer le conditionnel', 'Que signifie « If I had more time, I would travel » ?', 'mcq', '["J’ai du temps, donc je voyage","Je n’ai pas le temps : voyager reste irréel","J’avais du temps et j’ai voyagé","J’aurai du temps et je voyagerai"]'::jsonb, 1, 'Le prétérit après « if » ne parle pas du passé : il marque l’irréel du présent.', 2),
    ('ffad65ce-c808-5e32-9cf8-5a8e88c07385'::uuid, 'anglais', '3e', 'Exprimer le conditionnel', 'Dans quel ordre peut-on écrire une phrase conditionnelle ?', 'mcq', '["« If » doit toujours ouvrir la phrase","« If » doit toujours la terminer","La proposition en « if » peut ouvrir ou suivre la principale","« If » se place au milieu de la principale"]'::jsonb, 2, 'Les deux ordres sont possibles ; la virgule n’apparaît que si « if » ouvre la phrase.', 3),
    ('211f7ec6-f450-5d16-9ab6-378c254e9c2b'::uuid, 'anglais', '3e', 'Exprimer le conditionnel', 'I wish I ___ come to your party.', 'mcq', '["can","will","would can","could"]'::jsonb, 3, 'Hors de « if », le conditionnel apparaît aussi après « wish » : « could » est le passé de « can ».', 4),
    ('358ead0f-b6b6-56d2-beae-6e12f0e62aea'::uuid, 'anglais', '3e', 'Verbes irréguliers', 'Quel verbe suit le modèle « 1 = 3 » (base et participe identiques) ?', 'mcq', '["come","take","buy","go"]'::jsonb, 0, 'Come – came – come : la base et le participe passé sont identiques, comme become et run.', 1),
    ('b27431c0-c8f0-5b9e-9d25-34e558b720c9'::uuid, 'anglais', '3e', 'Verbes irréguliers', 'I have ___ three glasses of water today.', 'mcq', '["drank","drunk","drinked","drink"]'::jsonb, 1, 'Après « have », on emploie le participe passé (3e colonne) : drink – drank – drunk.', 2),
    ('9cf30710-ee52-5b25-af42-9578916e9d96'::uuid, 'anglais', '3e', 'Verbes irréguliers', 'Quelles sont les trois formes de « go » ?', 'mcq', '["go – went – went","go – gone – went","go – went – gone","go – goed – gone"]'::jsonb, 2, 'Go fait partie des verbes à trois formes différentes : go – went – gone.', 3),
    ('8f10aace-555a-546f-b538-641e7dcfc227'::uuid, 'anglais', '3e', 'Verbes irréguliers', 'Quel est le prétérit de « think » ?', 'mcq', '["thinked","thank","taught","thought"]'::jsonb, 3, 'Think – thought – thought (2 = 3). « Taught » est le prétérit de « teach ».', 4),
    ('7fe379fa-1e4b-535b-94c2-b5ca023435c3'::uuid, 'anglais', '3e', 'Phrase simple et phrase complexe', 'Dans « I think he is right », quel mot peut être sous-entendu ?', 'mcq', '["that","which","who","because"]'::jsonb, 0, 'La complétive est introduite par « that », souvent omis : I think (that) he is right.', 1),
    ('ddc0e804-6819-5634-a3e2-4dcf01941ef7'::uuid, 'anglais', '3e', 'Phrase simple et phrase complexe', 'Comment traduit-on « Il y a un problème » ?', 'mcq', '["It is a problem.","There is a problem.","Is a problem.","Has a problem."]'::jsonb, 1, 'Le sujet est obligatoire en anglais : « there is » pose l’existence de quelque chose.', 2),
    ('7b99a287-bda2-52ed-b7e3-1acd54bd1bf9'::uuid, 'anglais', '3e', 'Phrase simple et phrase complexe', 'Quelle conjonction introduit une subordonnée de condition ?', 'mcq', '["until","although","unless","since"]'::jsonb, 2, '« If » et « unless » (à moins que) introduisent une condition ; until marque le temps.', 3),
    ('b51a3942-8b28-5745-a951-4c6d3a20fafe'::uuid, 'anglais', '3e', 'Phrase simple et phrase complexe', 'Quel mot introduit une subordonnée de cause ?', 'mcq', '["until","so that","but","because"]'::jsonb, 3, 'Because, since et as introduisent la cause ; so that introduit le but, but coordonne.', 4),
    ('5277d2e9-61ec-5935-bd44-722bfec39749'::uuid, 'anglais', '3e', 'Les pronoms personnels', 'Comment dit-on « Je l’ai fait moi-même » ?', 'mcq', '["I did it myself.","I did it me.","I myself did it me.","I did it by me."]'::jsonb, 0, 'Le pronom réfléchi sert aussi à insister : I did it myself.', 1),
    ('c202441e-1d21-58de-b39f-d110bf277abc'::uuid, 'anglais', '3e', 'Les pronoms personnels', 'This present is for ___.', 'mcq', '["we","us","our","ours"]'::jsonb, 1, 'Après une préposition, on emploie le pronom complément : for us, with them.', 2),
    ('962ac8ef-b912-599b-9df0-b358335afea1'::uuid, 'anglais', '3e', 'Les pronoms personnels', 'He hurt ___ while playing football.', 'mcq', '["him","hisself","himself","he"]'::jsonb, 2, 'L’action revient sur le sujet : pronom réfléchi « himself » (jamais « hisself »).', 3),
    ('cb851b3c-e627-58fe-bf44-58118b328c79'::uuid, 'anglais', '3e', 'Les pronoms personnels', 'Quel est le pronom réfléchi de « you » au pluriel ?', 'mcq', '["yourself","yourselfs","youselves","yourselves"]'::jsonb, 3, '« Yourself » s’adresse à une personne, « yourselves » à plusieurs.', 4),
    ('7ecc8346-f987-535f-b506-60b4a0c0bd28'::uuid, 'anglais', '3e', 'Les pronoms relatifs', 'I remember the day ___ we met.', 'mcq', '["when","where","who","whose"]'::jsonb, 0, 'Après un antécédent de temps, le relatif est « when ».', 1),
    ('26670aab-67f2-502d-aa25-63a4e3d2ab5e'::uuid, 'anglais', '3e', 'Les pronoms relatifs', 'This is the town ___ I was born.', 'mcq', '["which","where","who","whose"]'::jsonb, 1, 'Après un antécédent de lieu, le relatif est « where ».', 2),
    ('95427361-e8f5-54d5-8f35-aca1a19c8f8f'::uuid, 'anglais', '3e', 'Les pronoms relatifs', 'Comment dit-on « la fille à qui j’ai parlé » en registre soutenu ?', 'mcq', '["the girl whom I spoke","the girl to who I spoke to","the girl to whom I spoke","the girl which I spoke to"]'::jsonb, 2, 'En registre soutenu, la préposition remonte devant le relatif, qui devient « whom ».', 3),
    ('acc01107-cf94-5abf-ba77-7dbcc988c97a'::uuid, 'anglais', '3e', 'Les pronoms relatifs', 'Dans quelle phrase le pronom relatif peut-il être omis ?', 'mcq', '["The man who called me is here.","My brother, who lives in London, is here.","The dog which bit me ran away.","The film that I watched was great."]'::jsonb, 3, '« That » y est complément dans une relative déterminative : on peut dire « the film I watched ».', 4),
    ('72c91944-4149-5d53-8df4-4d524472ff91'::uuid, 'anglais', '3e', 'La phrase interrogative', 'Qu’est-ce qu’une question fermée ?', 'mcq', '["Une question à laquelle on répond par yes ou no","Une question qui commence par un mot en wh-","Une question sans auxiliaire","Une question indirecte"]'::jsonb, 0, 'On y répond par yes ou no : il suffit de placer l’auxiliaire devant le sujet.', 1),
    ('53208377-adfe-5a9e-a64e-7d0afc754838'::uuid, 'anglais', '3e', 'La phrase interrogative', 'Quelle question interroge sur l’âge ?', 'mcq', '["How many years have you?","How old are you?","What age you have?","How old do you have?"]'::jsonb, 1, 'L’âge se demande avec « how old » et le verbe « be ».', 2),
    ('bb0b40f1-8dcd-57de-8653-242c68a01b2d'::uuid, 'anglais', '3e', 'La phrase interrogative', 'Quelle question interroge sur une distance ?', 'mcq', '["How long is the station?","How often is the station?","How far is the station?","How much is the station far?"]'::jsonb, 2, '« How far » demande une distance ; how long, une durée ; how often, une fréquence.', 3),
    ('6aed3e12-f77a-5b28-bb0b-463194f7f98c'::uuid, 'anglais', '3e', 'La phrase interrogative', 'Quelle question est correcte ?', 'mcq', '["What she said?","What did she said?","What does she said?","What did she say?"]'::jsonb, 3, 'Mot interrogatif + auxiliaire (did) + sujet + base verbale : une seule marque du passé.', 4),
    ('07f3af67-f91c-53f9-a8ac-b80fa16e04e8'::uuid, 'anglais', '3e', 'Les question tags', 'Close the door, ___?', 'mcq', '["will you","do you","don’t you","shall we"]'::jsonb, 0, 'Après un impératif, le tag est « will you? ».', 1),
    ('b5411661-f2b2-5404-8764-9e23f095e352'::uuid, 'anglais', '3e', 'Les question tags', 'You can swim, ___?', 'mcq', '["can you","can’t you","don’t you","aren’t you"]'::jsonb, 1, 'Le tag reprend l’auxiliaire (can) avec la polarité inverse : phrase affirmative, tag négatif.', 2),
    ('3f774232-26fd-5f92-ae62-ec8ab6d288d8'::uuid, 'anglais', '3e', 'Les question tags', 'Somebody called, ___?', 'mcq', '["didn’t he","did somebody","didn’t they","didn’t it"]'::jsonb, 2, 'Après un sujet indéfini (somebody, nobody, everyone), le tag reprend « they ».', 3),
    ('5fc6c70f-ae4a-5d23-9e43-270a1709847e'::uuid, 'anglais', '3e', 'Les question tags', 'Que signifie un tag prononcé avec une intonation montante ?', 'mcq', '["On est sûr et on cherche l’accord","On donne un ordre","On exprime la colère","On doute vraiment : c’est une vraie question"]'::jsonb, 3, 'Intonation descendante : on cherche l’accord. Montante : on pose une vraie question.', 4),
    ('d130624e-9cf1-5d22-aa07-7e03eb774439'::uuid, 'anglais', '3e', 'La phrase exclamative', 'They are ___ nice people!', 'mcq', '["such","such a","so","what"]'::jsonb, 0, 'Devant un adjectif + nom pluriel, on emploie « such », sans article.', 1),
    ('2de22e7c-4fc8-53e1-8d58-12ca97e442c4'::uuid, 'anglais', '3e', 'La phrase exclamative', 'Quelle phrase est correcte ?', 'mcq', '["What a terrible weather!","What terrible weather!","How terrible weather!","Such a terrible weather!"]'::jsonb, 1, '« Weather » est indénombrable : « what » sans article.', 2),
    ('d875456a-4016-5f3a-ab0c-6c8cf3788b42'::uuid, 'anglais', '3e', 'La phrase exclamative', 'How ___ he runs!', 'mcq', '["a fast","faster than","fast","such fast"]'::jsonb, 2, '« How » est suivi d’un adjectif ou d’un adverbe, puis du sujet et du verbe, sans inversion.', 3),
    ('9e520d3d-cc11-5f6e-8391-ad0efccc4c49'::uuid, 'anglais', '3e', 'La phrase exclamative', 'Que signifie « How come? » ?', 'mcq', '["Comment viens-tu ?","Viens ici !","Quand viens-tu ?","Comment ça se fait ?"]'::jsonb, 3, '« How come? » est une exclamation toute faite qui marque la surprise : « Comment ça se fait ? ».', 4),
    ('5b2076f6-5fb5-5183-8fbe-999e6e0886b4'::uuid, 'anglais', '3e', 'La voix passive', 'Quel est le passif de « They build houses » ?', 'mcq', '["Houses are built.","Houses built.","Houses are build.","Houses were building."]'::jsonb, 0, 'Au présent, be (are) + participe passé (built), au même temps que l’actif.', 1),
    ('822ddfcb-63be-5706-91b2-b774b7b29782'::uuid, 'anglais', '3e', 'La voix passive', 'Quel est le passif de « Shakespeare wrote Hamlet » ?', 'mcq', '["Hamlet wrote by Shakespeare.","Hamlet was written by Shakespeare.","Hamlet was wrote by Shakespeare.","Hamlet is writing by Shakespeare."]'::jsonb, 1, 'Prétérit → was + participe passé (written), et l’auteur est introduit par « by ».', 2),
    ('454b5d00-2ea5-554a-ad92-546084b91ee8'::uuid, 'anglais', '3e', 'La voix passive', 'Quel est le passif de « They will build a bridge » ?', 'mcq', '["A bridge will built.","A bridge will been built.","A bridge will be built.","A bridge is will built."]'::jsonb, 2, 'Après « will », be reste à la base verbale : will be + participe passé.', 3),
    ('383c687b-0106-5aff-8bad-d96dbce6995e'::uuid, 'anglais', '3e', 'La voix passive', 'Dans quels textes la voix passive abonde-t-elle ?', 'mcq', '["Dans les ordres","Dans les questions uniquement","Dans les dialogues familiers","Dans les textes scientifiques et les journaux"]'::jsonb, 3, 'Le passif met en avant ce qui a été fait plutôt que son auteur, d’où sa fréquence dans ces textes.', 4),
    ('37f9d1c1-0f4a-56d3-aa2d-94eed3134158'::uuid, 'anglais', '3e', 'Le comparatif', 'The more you practise, the ___ you get.', 'mcq', '["better","good","best","more good"]'::jsonb, 0, 'Structure « plus… plus… » : the + comparatif, the + comparatif. Le comparatif de good est better.', 1),
    ('e9b34437-ae40-58d0-a456-ccf0f4b01ce6'::uuid, 'anglais', '3e', 'Le comparatif', 'Quel est le comparatif de « big » ?', 'mcq', '["biger","bigger","more big","biggest"]'::jsonb, 1, 'Voyelle courte + consonne finale : la consonne double devant -er.', 2),
    ('85f8c886-12a4-5db9-bae1-80cc87ec3a79'::uuid, 'anglais', '3e', 'Le comparatif', 'Quel est le comparatif de « happy » ?', 'mcq', '["happyer","more happy than","happier","happiest"]'::jsonb, 2, 'Adjectif de deux syllabes en -y : le y devient i, et on ajoute -er.', 3),
    ('3e827570-9fca-5906-8d14-9d94d19ca38b'::uuid, 'anglais', '3e', 'Le comparatif', 'Comment dit-on « Il n’est pas aussi rapide que toi » ?', 'mcq', '["He is not as fast than you.","He is not so fast that you.","He is less fast as you.","He is not as fast as you."]'::jsonb, 3, 'L’égalité négative se construit avec not as / not so + adjectif + as.', 4),
    ('ce3ada9d-980a-5787-83a3-012e034e4af7'::uuid, 'anglais', '3e', 'Le superlatif', 'It was the coldest day ___ the year.', 'mcq', '["of","in","at","from"]'::jsonb, 0, 'Devant un ensemble ou une période, le superlatif est suivi de « of » ; devant un lieu, de « in ».', 1),
    ('1cfb8734-313c-5512-9d94-ffedec79fc4c'::uuid, 'anglais', '3e', 'Le superlatif', 'Quel est le superlatif de « bad » ?', 'mcq', '["the baddest","the worst","the worse","the most bad"]'::jsonb, 1, 'Bad – worse – the worst : irrégulier. « Worse » est le comparatif.', 2),
    ('42d30739-019d-517f-9212-e08a5aa182d6'::uuid, 'anglais', '3e', 'Le superlatif', 'Quel est le superlatif de « big » ?', 'mcq', '["the bigest","the most big","the biggest","the bigger"]'::jsonb, 2, 'Comme au comparatif, la consonne finale double : the biggest.', 3),
    ('b30db9cf-b6d5-5ac3-8028-972d18671302'::uuid, 'anglais', '3e', 'Le superlatif', 'Comment dit-on « le moins cher » ?', 'mcq', '["the less expensive","the most cheap","the lesser expensive","the least expensive"]'::jsonb, 3, 'Le superlatif d’infériorité se construit avec « the least » + adjectif.', 4),
    ('d39e08be-f8b5-5832-8a66-30f9c58ea990'::uuid, 'anglais', '3e', 'Exprimer l’habitude', 'Every summer, we ___ go to the beach.', 'mcq', '["would","used","are used to","get used to"]'::jsonb, 0, '« Would » + base verbale exprime une action répétée dans le passé.', 1),
    ('add530a6-a79a-5049-a88a-c30cc73cf300'::uuid, 'anglais', '3e', 'Exprimer l’habitude', 'Que signifie « I am used to getting up early » ?', 'mcq', '["J’avais l’habitude de me lever tôt","Je suis habitué à me lever tôt","Je m’habituerai à me lever tôt","Je me levais tôt autrefois"]'::jsonb, 1, '« Be used to » + -ING = être habitué à : c’est une habitude acquise, au présent.', 2),
    ('86357038-2c0c-5986-8ada-ee3655ffaaac'::uuid, 'anglais', '3e', 'Exprimer l’habitude', 'Quelle question est correcte ?', 'mcq', '["Did you used to live here?","Used you live here?","Did you use to live here?","Do you used to live here?"]'::jsonb, 2, 'Après « did », used perd son -d : Did you use to…?', 3),
    ('f7b74a46-ce54-5a24-97b4-0e748284fa7a'::uuid, 'anglais', '3e', 'Exprimer l’habitude', 'Où place-t-on « usually » dans « She plays tennis on Saturdays » ?', 'mcq', '["Usually plays she tennis on Saturdays.","She plays usually tennis on Saturdays.","She plays tennis usually on Saturdays.","She usually plays tennis on Saturdays."]'::jsonb, 3, 'L’adverbe de fréquence se place avant le verbe lexical.', 4),
    ('20612d72-5019-54db-be37-040f815127de'::uuid, 'anglais', '3e', 'Exprimer le but', 'Quel est le sens de « so as to » ?', 'mcq', '["Afin de, en registre formel","Pour que, avec un autre sujet","Si bien que","À cause de"]'::jsonb, 0, '« So as to » et « in order to » expriment le but, en registre formel, avec le même sujet.', 1),
    ('2c3d4e29-4612-5be1-9294-0fdf63162294'::uuid, 'anglais', '3e', 'Exprimer le but', 'I’ll speak slowly so that you ___ understand.', 'mcq', '["to","can","for","are"]'::jsonb, 1, 'Le but concerne un autre sujet : so that + proposition, souvent avec un modal (can, could).', 2),
    ('28b79e64-6d2e-5442-a675-8c6834efa3a4'::uuid, 'anglais', '3e', 'Exprimer le but', 'Que signifie « I went to the shop for bread » ?', 'mcq', '["Je suis allé au magasin à cause du pain","Je suis allé au magasin avec du pain","Je suis allé au magasin chercher du pain","Je suis allé au magasin pour faire du pain"]'::jsonb, 2, '« For » + nom signifie ici aller chercher quelque chose.', 3),
    ('01813647-e996-5da8-a48e-62cb88acd7ca'::uuid, 'anglais', '3e', 'Exprimer le but', 'Que répond-on à « Why did you call? » ?', 'mcq', '["For ask you something.","For asking you something.","So ask you something.","To ask you something."]'::jsonb, 3, 'La réponse à « why » commence souvent par « To… » + base verbale ; jamais « for » + verbe.', 4),
    ('cd2601e2-4fb4-5d7f-9d7f-0a7e9129d387'::uuid, 'anglais', '3e', 'Exprimer la durée', 'I fell asleep ___ the film.', 'mcq', '["during","for","since","ago"]'::jsonb, 0, '« During » est suivi d’un nom (the film, the holidays), jamais d’une durée chiffrée.', 1),
    ('2b33b7de-fe87-5a49-9c87-64e3eed42e8b'::uuid, 'anglais', '3e', 'Exprimer la durée', 'It’s been two years ___ I saw him.', 'mcq', '["for","since","ago","during"]'::jsonb, 1, 'La tournure « it’s been … since » : cela fait deux ans que je ne l’ai pas vu.', 2),
    ('00440bf5-fd5e-5a4f-8359-e1198d3f6355'::uuid, 'anglais', '3e', 'Exprimer la durée', 'Quelle question demande un moment précis ?', 'mcq', '["How long have you been here?","How long ago you arrive?","When did you arrive?","Since when you are here?"]'::jsonb, 2, '« When » + prétérit demande un moment précis ; « how long » demande une durée.', 3),
    ('6d2cb034-2dde-5a06-9494-eecedf3bff58'::uuid, 'anglais', '3e', 'Exprimer la durée', 'À quelle question répond « for » ?', 'mcq', '["Depuis quand ?","Il y a combien ?","Quand ?","Combien de temps ?"]'::jsonb, 3, '« Combien de temps ? » → for. « Depuis quand ? » → since.', 4),
    ('a3d6974f-a62d-59b2-85c2-c7eb67596c83'::uuid, 'anglais', '3e', 'Le discours indirect', '« Don’t be late. » → She told me ___ late.', 'mcq', '["not to be","to not being","don’t be","not be"]'::jsonb, 0, 'Un ordre négatif se rapporte avec tell + complément + not to + base verbale.', 1),
    ('0d9bf7cd-ffae-55c3-bd48-426ade01b5a8'::uuid, 'anglais', '3e', 'Le discours indirect', 'Que devient « tomorrow » au discours indirect ?', 'mcq', '["the day before","the next day","today","then"]'::jsonb, 1, 'Les repères de temps s’adaptent : tomorrow → the next day, yesterday → the day before.', 2),
    ('04681f32-dd01-5c85-bb27-f416cbb49833'::uuid, 'anglais', '3e', 'Le discours indirect', 'Que devient « can » au discours indirect, après « he said » ?', 'mcq', '["can","would","could","may"]'::jsonb, 2, 'Chaque temps recule d’un cran : can → could, will → would.', 3),
    ('0bbf1a53-b66a-5769-ae14-7deaefb2e304'::uuid, 'anglais', '3e', 'Le discours indirect', 'Tom a dit : « I lost my keys. » Comment le rapporte-t-on ?', 'mcq', '["Tom said I had lost my keys.","Tom said he lost my keys.","Tom said he has lost his keys.","Tom said he had lost his keys."]'::jsonb, 3, 'Le prétérit recule au past perfect, et les pronoms s’adaptent au nouveau locuteur : I → he, my → his.', 4),
    ('2f7c9202-f260-57c7-8bc4-c9452dd6627f'::uuid, 'espagnol', '3e', 'Les questions', 'Dans « Si no vienes, ¿qué hago? », où s’ouvre le point d’interrogation ?', 'mcq', '["Toujours en tout début de phrase","Juste avant le verbe","Au début de la partie interrogée","Il est facultatif ici"]'::jsonb, 2, 'Le ¿ s’ouvre au début de la partie réellement interrogée, pas forcément au début de la phrase.', 1),
    ('67a3257f-97f4-59f2-afbc-2975c2868931'::uuid, 'espagnol', '3e', 'Les questions', 'No voy al cine ___ estoy cansado.', 'mcq', '["por qué","porque","porqué","por que"]'::jsonb, 1, 'C’est une réponse, une cause : on écrit porque en un seul mot, sans accent. Por qué, en deux mots accentués, pose la question.', 2),
    ('431c0867-9a49-519b-80d0-14baca782055'::uuid, 'espagnol', '3e', 'Les questions', 'Dans « La casa donde vivo », pourquoi « donde » n’a-t-il pas d’accent ?', 'mcq', '["C’est un relatif, pas un interrogatif","L’accent est facultatif","Il suit un nom féminin","C’est une faute d’orthographe"]'::jsonb, 0, 'L’accent distingue l’interrogatif (¿Dónde vives?) du relatif (la casa donde vivo) : ce n’est pas un ornement.', 3),
    ('55ca38b9-0d7a-52eb-9c87-29acb0157fc4'::uuid, 'espagnol', '3e', 'Les questions', 'Comment pose-t-on une question fermée, à laquelle on répond par oui ou non ?', 'mcq', '["Avec « es que » en tête","Avec un mot interrogatif obligatoire","En doublant le verbe","Seule l’intonation change, avec ¿ et ?"]'::jsonb, 3, 'L’interrogation totale n’a aucun outil particulier : ¿Hablas español? se distingue de la phrase déclarative par l’intonation et les signes.', 4),
    ('4d8bf342-e502-5ebf-9347-ff9629699257'::uuid, 'espagnol', '3e', 'La négation', 'No es rico, ___ es feliz.', 'mcq', '["sino","pero","sino que","ni"]'::jsonb, 1, 'Pero oppose sans rectifier : il n’est pas riche, mais il est heureux. Sino corrigerait une erreur (no es francés sino español).', 1),
    ('1869146f-4561-5360-897f-301a68fa08a6'::uuid, 'espagnol', '3e', 'La négation', 'Comment dit-on « pas encore » ?', 'mcq', '["Ya no","Nunca más","Todavía no","Tampoco"]'::jsonb, 2, 'Todavía no (ou aún no) signifie « pas encore » ; ya no veut dire « ne… plus ».', 2),
    ('af5174c1-3e8d-59ce-8d2f-22af9bdc7373'::uuid, 'espagnol', '3e', 'La négation', 'Quelle phrase est correcte ?', 'mcq', '["Nunca lo hago","Lo hago nunca","Nunca no lo hago","No nunca lo hago"]'::jsonb, 0, 'Placé avant le verbe, le mot négatif suffit : le no disparaît. Après le verbe, il faudrait dire No lo hago nunca.', 3),
    ('95905ac1-aa67-531d-a4e8-199e2be12f64'::uuid, 'espagnol', '3e', 'La négation', 'Quelle nuance « jamás » ajoute-t-il par rapport à « nunca » ?', 'mcq', '["Il signifie « parfois »","Il porte sur le futur seulement","Aucune, il est plus familier","Il est plus emphatique"]'::jsonb, 3, 'Nunca et jamás signifient tous deux « jamais », mais jamás insiste davantage.', 4),
    ('42abb861-b57c-5098-a321-94c3abda9ff2'::uuid, 'espagnol', '3e', 'La proposition subordonnée relative', 'Busco a la secretaria que ___ inglés: se llama Ana.', 'mcq', '["hable","habla","hablar","hablando"]'::jsonb, 1, 'La secrétaire est connue (elle a un nom) : l’antécédent est réel, donc la relative est à l’indicatif.', 1),
    ('dcec9fb4-62a6-5a38-b034-54ac783cec75'::uuid, 'espagnol', '3e', 'La proposition subordonnée relative', 'Que signifie « Los alumnos, que estudian, aprueban » ?', 'mcq', '["Seuls les élèves qui étudient réussissent","Aucun élève ne réussit","Tous les élèves réussissent, et tous étudient","Les élèves étudient pour réussir"]'::jsonb, 2, 'Entre virgules, la relative est explicative : elle ajoute une information sur TOUS les élèves au lieu d’en restreindre le groupe.', 2),
    ('ca4eb8ff-7851-552b-a936-564c53806400'::uuid, 'espagnol', '3e', 'La proposition subordonnée relative', 'Dans une relative explicative, quel pronom peut remplacer « que » pour une personne ?', 'mcq', '["Cuyo","Lo que","Donde","Quien"]'::jsonb, 3, 'En relative explicative, quien est possible pour une personne : Mi hermano, quien vive en Madrid, es médico.', 3),
    ('76a9a12d-38f3-5859-91f0-b4f8f1a07841'::uuid, 'espagnol', '3e', 'La proposition subordonnée relative', 'Dans « Quien mucho abarca, poco aprieta », quel est l’antécédent de « quien » ?', 'mcq', '["Il est implicite : « celui qui »","Mucho","Poco","Le sujet de aprieta, exprimé plus loin"]'::jsonb, 0, 'Quien peut s’employer sans antécédent exprimé : il vaut « celui qui ». Qui trop embrasse mal étreint.', 4),
    ('092fb090-6332-5ca6-950f-e6ae6acd9b25'::uuid, 'espagnol', '3e', 'La proposition subordonnée complétive', 'Veo que ___ cansado.', 'mcq', '["estés","está","estar","estuviera"]'::jsonb, 1, 'Un verbe de perception (ver) introduit un fait constaté : la complétive est à l’indicatif.', 1),
    ('a316a06e-5762-5258-aa1e-aa27f619f5be'::uuid, 'espagnol', '3e', 'La proposition subordonnée complétive', 'Me alegro de que ___ aquí.', 'mcq', '["estás","estarás","estés","estar"]'::jsonb, 2, 'Un verbe de sentiment (alegrarse de) commande le subjonctif dans la complétive.', 2),
    ('7a624e45-7c26-5c68-98cc-d22a34d14b74'::uuid, 'espagnol', '3e', 'La proposition subordonnée complétive', 'Quelle forme équivaut à « Quería que vinieras » ?', 'mcq', '["Quería que vengas","Quería que vendrías","Quería que venías","Quería que vinieses"]'::jsonb, 3, 'L’imparfait du subjonctif a deux formes équivalentes, en -ra et en -se : vinieras = vinieses.', 3),
    ('059bf9d2-74d1-5849-b0f2-e9b8b5ad8d6d'::uuid, 'espagnol', '3e', 'La proposition subordonnée complétive', 'Es verdad que ___ mucho en esta región.', 'mcq', '["llueve","llueva","lloviera","llover"]'::jsonb, 0, 'Es verdad que exprime une certitude : on reste à l’indicatif. C’est sa négation (no es verdad que) qui appellerait le subjonctif.', 4),
    ('be382e96-4f6e-5a97-ba2d-882dcac7d276'::uuid, 'espagnol', '3e', 'Genre et nombre', 'Lequel de ces noms est féminin en espagnol ?', 'mcq', '["árbol","leche","minuto","puente"]'::jsonb, 1, 'On dit la leche, au féminin, alors que « le lait » est masculin en français. El árbol, el minuto et el puente sont masculins : le genre s’apprend avec l’article.', 1),
    ('2eda9767-aaac-54c8-aa8a-245f1ce32eb5'::uuid, 'espagnol', '3e', 'Genre et nombre', 'Quel est le pluriel de « la canción » ?', 'mcq', '["las canciónes","las cancións","las canciones","las canción"]'::jsonb, 2, 'On ajoute -es après une consonne, et l’accent écrit disparaît : la syllabe tonique n’est plus la dernière.', 2),
    ('f075db94-cf4e-5fa8-97a7-bda384f87350'::uuid, 'espagnol', '3e', 'Genre et nombre', 'Quel est le féminin de « francés » ?', 'mcq', '["francésa","franceza","la francés","francesa"]'::jsonb, 3, 'Les noms en -és ajoutent -a au féminin, et l’accent disparaît : francés, francesa.', 3),
    ('77ea754e-a02c-5a2a-90e8-d833c9ee3bde'::uuid, 'espagnol', '3e', 'Genre et nombre', 'Comment dit-on « l’étudiante » ?', 'mcq', '["la estudiante","la estudianta","la estudianto","el estudianta"]'::jsonb, 0, 'Estudiante, comme periodista ou artista, est invariable : seul l’article change.', 4),
    ('aeb38a81-c1ee-51c7-8a7a-3b89ac089ab1'::uuid, 'espagnol', '3e', 'Les articles', 'Es ___ águila blanca.', 'mcq', '["un","una","uno","unos"]'::jsonb, 0, 'Un nom féminin qui commence par un a- tonique prend un (et el) au singulier, mais reste féminin : blanca.', 1),
    ('b8eec0e1-fee5-5b4d-bafb-a9b167eea37e'::uuid, 'espagnol', '3e', 'Les articles', 'No sabes lo cansado ___ estoy.', 'mcq', '["como","que","cual","de"]'::jsonb, 1, 'Lo + adjectif + que exprime l’intensité : tu ne sais pas à quel point je suis fatigué.', 2),
    ('795e7443-b40f-5136-bae8-bef921dffdc0'::uuid, 'espagnol', '3e', 'Les articles', 'Que signifie « lo importante » ?', 'mcq', '["Le monsieur important","Les choses importantes, au pluriel","L’important, ce qui est important","Il est important"]'::jsonb, 2, 'Lo devant un adjectif en fait une qualité abstraite : lo importante, lo mejor, lo difícil.', 3),
    ('ff7c704b-b2fa-570b-92fc-ff7fb35117a9'::uuid, 'espagnol', '3e', 'Les articles', 'Comment dit-on « c’est un excellent professeur » ?', 'mcq', '["Es profesor excelente","Es una profesor excelente","Es uno profesor excelente","Es un profesor excelente"]'::jsonb, 3, 'Sans adjectif, la profession se dit sans article (es profesor) ; dès qu’un adjectif la qualifie, l’article revient.', 4),
    ('d630c3bd-8431-55bc-a5c8-fb41e88dcd90'::uuid, 'espagnol', '3e', 'Les démonstratifs', 'Quel est le masculin singulier de la troisième série de démonstratifs ?', 'mcq', '["aquello","aquelo","aquel","aquell"]'::jsonb, 2, 'C’est aquel, sans -o : la seule irrégularité à retenir. Aquello est le neutre.', 1),
    ('d724fac3-1106-5824-bea9-47416bb3988e'::uuid, 'espagnol', '3e', 'Les démonstratifs', 'Quel adverbe de lieu correspond à « ese » ?', 'mcq', '["aquí","ahí","allí","acá"]'::jsonb, 1, 'Este va avec aquí (près de moi), ese avec ahí (près de toi), aquel avec allí (loin de nous deux).', 2),
    ('5463b644-21e7-55ad-998e-3bc989738b11'::uuid, 'espagnol', '3e', 'Les démonstratifs', 'Que signifie « en aquel entonces » ?', 'mcq', '["Tout de suite","La semaine prochaine","Ici même","À cette époque-là"]'::jsonb, 3, 'Aquel marque la distance dans le temps : en aquel entonces renvoie à une époque éloignée.', 3),
    ('e2d4f28d-6b5d-5ad6-a65f-2f7a0b1cf68a'::uuid, 'espagnol', '3e', 'Les démonstratifs', '___ año voy a aprobar todo.', 'mcq', '["Este","Esto","Aquel","Aquello"]'::jsonb, 0, 'L’année en cours est proche de celui qui parle : este año. Esto, neutre, ne se met jamais devant un nom.', 4),
    ('09651ea7-64ac-58f4-a7d1-ea7a55908a16'::uuid, 'espagnol', '3e', 'Les adjectifs', 'Où se place un adjectif de couleur ?', 'mcq', '["Toujours avant le nom","Toujours après le nom","Avant ou après, sans changement","Seulement après un verbe"]'::jsonb, 1, 'Couleur, forme, nationalité et religion classent objectivement : l’adjectif reste après le nom (un coche rojo).', 1),
    ('d4e30a64-aa9e-5e00-a469-703e213453f5'::uuid, 'espagnol', '3e', 'Les adjectifs', 'Que signifie « libros diferentes » ?', 'mcq', '["Plusieurs livres","Des livres récents","Des livres dissemblables","Quelques livres"]'::jsonb, 2, 'Après le nom, diferentes veut dire « qui ne se ressemblent pas » ; devant (diferentes libros), il signifie « plusieurs ».', 2),
    ('c18f3b2b-2688-5e00-b46c-91a0a4c150c4'::uuid, 'espagnol', '3e', 'Les adjectifs', 'Quel est le féminin de « trabajador » ?', 'mcq', '["trabajador","trabajadriz","trabajadoresa","trabajadora"]'::jsonb, 3, 'Les adjectifs en -or forment un féminin en ajoutant -a : trabajador, trabajadora.', 3),
    ('7200366e-8935-50da-acef-bc82a3eac15c'::uuid, 'espagnol', '3e', 'Les adjectifs', 'Que signifie « un hecho cierto » ?', 'mcq', '["Un fait avéré","Un certain fait","Un fait ancien","Un fait discutable"]'::jsonb, 0, 'Après le nom, cierto veut dire « vrai, avéré » ; devant (un cierto encanto), il signifie « un certain ».', 4),
    ('a9388e61-285f-519f-b07e-5a0f9e5ae8c0'::uuid, 'espagnol', '3e', 'Les pronoms personnels sujets', 'Comment demander poliment à un inconnu : « Vous parlez espagnol ? »', 'mcq', '["¿Usted hablas español?","¿Usted habla español?","¿Usted habláis español?","¿Vos habla español?"]'::jsonb, 1, 'Usted se conjugue à la 3e personne du singulier : ¿Usted habla español?', 1),
    ('49d550ee-fc14-5bfb-b2b0-6357c2249793'::uuid, 'espagnol', '3e', 'Les pronoms personnels sujets', 'Pourquoi exprime-t-on le pronom dans « Tú trabajas y él duerme » ?', 'mcq', '["Parce que le verbe est irrégulier","Pour marquer le vouvoiement","Pour opposer deux personnes","Par obligation grammaticale"]'::jsonb, 2, 'On n’exprime le pronom sujet que pour insister, opposer ou lever une ambiguïté. Ici, il oppose tú et él.', 2),
    ('a436bef5-5a57-5730-baae-f6059f5808e6'::uuid, 'espagnol', '3e', 'Les pronoms personnels sujets', 'D’où vient le pronom « usted » ?', 'mcq', '["Du latin « tu »","De « vosotros »","De « ustedes » abrégé","De « vuestra merced », « votre grâce »"]'::jsonb, 3, 'Usted vient de vuestra merced : on s’adresse à la « grâce » de la personne, d’où la 3e personne.', 3),
    ('61a17138-3a4c-52a2-8109-de849000d935'::uuid, 'espagnol', '3e', 'Les pronoms personnels sujets', 'En Argentine, comment dit-on couramment « tu es » ?', 'mcq', '["vos sos","vos eres","tú sos","vos es"]'::jsonb, 0, 'Avec le voseo, vos remplace tú et a ses formes propres : vos sos, vos tenés, vos hablás. C’est une norme régionale.', 4),
    ('10263576-42ed-50e6-87bd-d43d6de68a46'::uuid, 'espagnol', '3e', 'Les pronoms personnels compléments', 'Veo a Marta y ___ hablo.', 'mcq', '["la","le","lo","se"]'::jsonb, 1, 'Hablar a alguien : Marta est ici complément indirect, on emploie le (je lui parle). La serait le COD (je la vois).', 1),
    ('212c187e-1b62-57ed-997e-90190b89bf37'::uuid, 'espagnol', '3e', 'Les pronoms personnels compléments', 'Compro los libros: ___ compro hoy.', 'mcq', '["Los","Les","Se","Las"]'::jsonb, 0, 'Los libros est COD masculin pluriel : on le reprend par los.', 2),
    ('d49d167b-0b52-5618-88e2-02e361aeb800'::uuid, 'espagnol', '3e', 'Les pronoms personnels compléments', 'Qu’est-ce que le « leísmo » toléré par la RAE ?', 'mcq', '["Employer le à la place de se","Employer les pour une chose","Employer le comme COD pour une personne masculine","Supprimer le pronom COI"]'::jsonb, 2, 'En Castille, on dit souvent Le vi pour Lo vi quand il s’agit d’un homme : la RAE ne le tolère que dans ce cas.', 3),
    ('6bd71378-b133-5422-8958-4701939219bd'::uuid, 'espagnol', '3e', 'Les pronoms personnels compléments', 'Comment souder les pronoms au gérondif « diciendo » ?', 'mcq', '["diciendo te lo","te lo diciendo","diciendotelo","diciéndotelo"]'::jsonb, 3, 'Au gérondif, les pronoms se soudent derrière le verbe, et un accent écrit garde la syllabe tonique : diciéndotelo.', 4),
    ('78655fee-9cfd-573c-9666-ae19ce36ebfd'::uuid, 'espagnol', '3e', 'Les possessifs', 'Pour préciser que « su casa » est la maison d’une femme, on dit…', 'mcq', '["la su casa","su casa suya","la casa de ella","la casa de su"]'::jsonb, 2, 'Su a quatre possesseurs possibles ; de él, de ella ou de usted lèvent l’ambiguïté.', 1),
    ('aebae8f7-8536-560b-8a10-fc1e3856a136'::uuid, 'espagnol', '3e', 'Les possessifs', 'Este libro es ___.', 'mcq', '["mi","mío","el mi","me"]'::jsonb, 1, 'Comme attribut, on emploie la forme tonique : Este libro es mío.', 2),
    ('c506a2f2-50d8-5ea8-adaa-5d0deae30889'::uuid, 'espagnol', '3e', 'Les possessifs', 'Comment dit-on « mes livres » ?', 'mcq', '["mis libros","míos libros","mi libros","mías libros"]'::jsonb, 0, 'L’atone s’accorde en nombre avec ce qui est possédé : mi devient mis devant un pluriel.', 3),
    ('f1c47f11-d72f-534d-ac99-68130ead6dff'::uuid, 'espagnol', '3e', 'Les possessifs', 'Comment dit-on « nos maisons » ?', 'mcq', '["nuestros casas","nuestra casas","nos casas","nuestras casas"]'::jsonb, 3, 'Nuestro varie en genre et en nombre selon la chose possédée : casas est féminin pluriel, donc nuestras.', 4),
    ('0b81d278-8055-56fb-93e7-db9d2b22b0be'::uuid, 'espagnol', '3e', 'Les pronoms relatifs', 'La persona con ___ hablo es mi tía.', 'mcq', '["que","quien","cuyo","cual"]'::jsonb, 1, 'Après une préposition, pour une personne, on emploie quien (ou la que) : con quien hablo.', 1),
    ('909c4e43-78af-54c6-ac4c-19b684617f87'::uuid, 'espagnol', '3e', 'Les pronoms relatifs', 'Dans « Mi hermano, quien vive en Madrid, es médico », pourquoi « quien » est-il possible ?', 'mcq', '["Parce que la relative est déterminative","Parce qu’il n’y a pas d’antécédent","Parce que la relative est explicative et l’antécédent une personne","Parce que quien remplace une idée"]'::jsonb, 2, 'Quien s’emploie pour une personne, après préposition ou dans une relative explicative, comme ici entre virgules.', 2),
    ('3a3d66a1-cbb5-5f54-9064-5046d55721c1'::uuid, 'espagnol', '3e', 'Les pronoms relatifs', 'Employés comme relatifs, « donde, cuando, como » portent-ils un accent ?', 'mcq', '["Oui, toujours","Seulement donde","Seulement à l’écrit soutenu","Non, jamais comme relatifs"]'::jsonb, 3, 'L’accent est réservé aux interrogatifs : la ciudad donde vivo, sans accent.', 3),
    ('03d0323b-924a-57a3-99c0-e4c7ba1d1575'::uuid, 'espagnol', '3e', 'Les pronoms relatifs', 'El libro del ___ te hablé es este.', 'mcq', '["que","quien","cuyo","donde"]'::jsonb, 0, 'Après une préposition, que prend l’article : del que (de + el que). Quien ne s’emploie que pour des personnes.', 4),
    ('fa7fe437-84a6-5ef8-b25e-2faf5710c818'::uuid, 'espagnol', '3e', 'Les indéfinis', 'No hay ___ problema.', 'mcq', '["ningún","ninguno","ninguna","ningunos"]'::jsonb, 0, 'Devant un nom masculin singulier, ninguno s’apocope en ningún ; il s’emploie presque toujours au singulier.', 1),
    ('bd27c4a3-a0f7-5ae2-be76-463309b5daaa'::uuid, 'espagnol', '3e', 'Les indéfinis', '¿Tienes ___ pregunta?', 'mcq', '["algún","alguna","alguno","algunos"]'::jsonb, 1, 'Devant un féminin, alguno garde sa forme complète : alguna pregunta.', 2),
    ('1712d467-77a5-555e-abfd-96b0d800a4fe'::uuid, 'espagnol', '3e', 'Les indéfinis', 'Pourquoi dit-on « Cualquiera puede hacerlo » sans apocope ?', 'mcq', '["Parce que le verbe est au présent","Parce que c’est un féminin","Parce que cualquiera est employé seul, sans nom","Parce que l’apocope est facultative"]'::jsonb, 2, 'Cualquiera ne devient cualquier que devant un nom ; employé seul, il garde son -a.', 3),
    ('6ac068c5-5bb3-5b99-b339-bcbd3380bf89'::uuid, 'espagnol', '3e', 'Les indéfinis', 'Que signifie « ambos » ?', 'mcq', '["Aucun des deux","L’un ou l’autre","Quelques-uns","Tous les deux"]'::jsonb, 3, 'Ambos (ambas au féminin) signifie « tous les deux » : ambos hermanos.', 4),
    ('b70beaa7-4e54-5f07-b8ff-78dbf5afe1a9'::uuid, 'espagnol', '3e', 'La comparaison', 'Tengo menos dinero ___ tú.', 'mcq', '["que","de","como","cual"]'::jsonb, 0, 'Le comparatif d’infériorité se construit avec menos… que : menos dinero que tú.', 1),
    ('cfa21e47-9a76-5e88-a147-c180e96a68a3'::uuid, 'espagnol', '3e', 'La comparaison', 'Comment dit-on « mon frère aîné » ?', 'mcq', '["mi hermano más grande","mi hermano mayor","mi hermano más mayor","mi hermano grande"]'::jsonb, 1, 'Mayor et menor servent surtout pour l’âge ; ils ne prennent jamais más.', 2),
    ('82a3a75f-3934-5ab9-9ec0-260d4817cd95'::uuid, 'espagnol', '3e', 'La comparaison', 'Comment traduire « il fait de plus en plus chaud » ?', 'mcq', '["Hace más y más calor","Hace tanto calor","Hace cada vez más calor","Hace más calor que nunca"]'::jsonb, 2, 'Le comparatif progressif se dit cada vez más (ou cada vez menos).', 3),
    ('51ac611b-b159-539c-b18f-a898fd8196a1'::uuid, 'espagnol', '3e', 'La comparaison', 'Quel est le comparatif de supériorité de « bien » ?', 'mcq', '["más bien","bueno","mayor","mejor"]'::jsonb, 3, 'Bueno et bien ont le même comparatif irrégulier : mejor. Más bien signifie « plutôt ».', 4),
    ('fde08e21-f846-5c98-9929-1e0d7073ba62'::uuid, 'espagnol', '3e', 'Le superlatif', 'Comment dit-on « Mon frère est le plus grand » ?', 'mcq', '["Mi hermano es el más alto","Mi hermano es más alto","Mi hermano es el alto más","Mi hermano es lo más alto"]'::jsonb, 0, 'Quand le nom est déjà exprimé, l’article ne le répète pas : es el más alto.', 1),
    ('70155d3f-c893-567a-911e-8131f9641071'::uuid, 'espagnol', '3e', 'Le superlatif', 'Quel est le superlatif savant de « malo » ?', 'mcq', '["máximo","pésimo","mínimo","óptimo"]'::jsonb, 1, 'Malo a pour superlatif savant pésimo (bueno : óptimo ; grande : máximo ; pequeño : mínimo).', 2),
    ('a5e01e49-1087-55d9-b888-9ba644a4f447'::uuid, 'espagnol', '3e', 'Le superlatif', 'Quel est le superlatif absolu de « fuerte » selon la norme ?', 'mcq', '["fuertísimo","fuertesísimo","fortísimo","fuertismo"]'::jsonb, 2, 'La diphtongue se réduit devant -ísimo : fuerte donne fortísimo.', 3),
    ('53f582bf-0b83-581a-a7e6-3698f6383ad3'::uuid, 'espagnol', '3e', 'Le superlatif', 'Quel adverbe permet aussi de renforcer un adjectif ?', 'mcq', '["muyísimo","tantamente","máximamente","sumamente"]'::jsonb, 3, 'Sumamente et extremadamente renforcent un adjectif : sumamente difícil.', 4),
    ('982239f2-7acc-5a66-8265-ed8e7cd8a7ac'::uuid, 'espagnol', '3e', 'L’apocope', 'Vivo en el ___ piso.', 'mcq', '["primero","primer","primera","primo"]'::jsonb, 1, 'Devant un nom masculin singulier, primero perd son -o : el primer piso.', 1),
    ('42cdbfad-dccc-500f-944e-34b2d5a94491'::uuid, 'espagnol', '3e', 'L’apocope', 'Comment dit-on « de grands hommes » ?', 'mcq', '["gran hombres","grande hombres","grandes hombres","grans hombres"]'::jsonb, 2, 'Grande ne s’apocope qu’au singulier : au pluriel, la forme entière revient.', 2),
    ('dd63aa96-bbd2-57ee-9a10-cff8345fdca1'::uuid, 'espagnol', '3e', 'L’apocope', 'Comment dit-on « sainte Thérèse » ?', 'mcq', '["san Teresa","sant Teresa","santo Teresa","santa Teresa"]'::jsonb, 3, 'Santo devient san devant un prénom masculin, mais le féminin ne s’apocope jamais : santa Teresa.', 3),
    ('caf10508-c189-5fca-853d-7979317bbf41'::uuid, 'espagnol', '3e', 'L’apocope', 'Es el ___ de la clase.', 'mcq', '["primero","primer","primo","primeros"]'::jsonb, 0, 'Sans nom derrière lui, primero garde sa forme pleine : l’apocope n’a lieu que juste devant le nom.', 4),
    ('a6bf444d-99f8-5d1f-8af3-b926eb35e739'::uuid, 'espagnol', '3e', 'L’auxiliaire haber', 'Mañana a las ocho ya ___ terminado.', 'mcq', '["habré","he","hube","haya"]'::jsonb, 0, 'Un fait accompli à un moment futur se dit au futur antérieur : habré + participe.', 1),
    ('1ab04af5-cbe6-5b76-a12c-7b333c43a5f2'::uuid, 'espagnol', '3e', 'L’auxiliaire haber', 'Espero que ___ llegado bien.', 'mcq', '["ha","haya","habrá","hubo"]'::jsonb, 1, 'Après esperar que, le subjonctif s’impose : le subjonctif passé se forme avec haya + participe.', 2),
    ('cacc1714-d165-548a-8294-692f9c43888b'::uuid, 'espagnol', '3e', 'L’auxiliaire haber', 'Quel est le passé simple de « hay » ?', 'mcq', '["hubieron","habió","hubo","hayó"]'::jsonb, 2, 'Hay est invariable à tous les temps : hubo un accidente, même devant un pluriel (hubo accidentes).', 3),
    ('0d157e69-b7ae-5c29-b45f-f9543d6df2ea'::uuid, 'espagnol', '3e', 'L’auxiliaire haber', 'Que signifie « He de irme » ?', 'mcq', '["Je suis déjà parti","Je viens de partir","Il y a un départ","Je dois partir"]'::jsonb, 3, 'Haber de + infinitif exprime une obligation atténuée, dans un registre littéraire.', 4),
    ('22bcea36-9cf6-5520-b6fa-1abafd1ec90a'::uuid, 'espagnol', '3e', 'Les verbes pronominaux', 'Que signifie « acordarse de » ?', 'mcq', '["Se souvenir de","Se mettre d’accord","Décider","S’accorder avec"]'::jsonb, 0, 'Acordar veut dire « décider » ; pronominal, acordarse de signifie « se souvenir de ».', 1),
    ('55644e5f-e8a4-58ef-961f-96cb21a94a2e'::uuid, 'espagnol', '3e', 'Les verbes pronominaux', 'Que signifie « quedarse » ?', 'mcq', '["Convenir","Rester sur place","Se plaindre","Partir"]'::jsonb, 1, 'Quedar signifie « convenir, se donner rendez-vous » ; quedarse, « rester » : Me quedo en casa.', 2),
    ('82f1711a-3c9b-5997-8e18-59666d772b34'::uuid, 'espagnol', '3e', 'Les verbes pronominaux', 'Comment dit-on « Lève-toi ! » à un ami ?', 'mcq', '["¡Te levanta!","¡Levanta te!","¡Levántate!","¡Levántete!"]'::jsonb, 2, 'À l’impératif affirmatif, le pronom se soude derrière le verbe, et l’accent garde la syllabe tonique.', 3),
    ('68d81add-84ac-530c-b9de-96eeae8d574b'::uuid, 'espagnol', '3e', 'Les verbes pronominaux', 'Dans « Se puso rojo », que signifie « ponerse » ?', 'mcq', '["Mettre","Poser","Se lever","Devenir"]'::jsonb, 3, 'Poner signifie « mettre » ; ponerse, « se mettre » ou « devenir » : il est devenu rouge.', 4),
    ('cb52dc1d-c3ec-5e3e-b8bd-f7c774b39e5d'::uuid, 'espagnol', '3e', 'Les verbes à diphtongue', 'Mis hermanos ___ al fútbol los sábados.', 'mcq', '["juegan","jugan","juegen","jugamos"]'::jsonb, 0, 'Jugar diphtongue u en ue sous l’accent : juegan. Seuls nosotros et vosotros y échappent.', 1),
    ('80b36881-9169-543f-87cf-bd30c056f8bd'::uuid, 'espagnol', '3e', 'Les verbes à diphtongue', 'Quelle est la 3e personne du pluriel du présent de « volver » ?', 'mcq', '["volven","vuelven","vuelvan","volvén"]'::jsonb, 1, 'Volver diphtongue o en ue sous l’accent : vuelven. Vuelvan est le subjonctif.', 2),
    ('72221b69-466e-531a-aaa2-da28abb84e60'::uuid, 'espagnol', '3e', 'Les verbes à diphtongue', 'Quel est le subjonctif présent de « pensar » à « nosotros » ?', 'mcq', '["piensemos","pensamos","pensemos","piensamos"]'::jsonb, 2, 'Au subjonctif, la diphtongue suit la même botte : nosotros n’est pas touché, et la voyelle bascule en e : pensemos.', 3),
    ('0601d069-404d-5eb3-8f50-c71ba11d55dd'::uuid, 'espagnol', '3e', 'Les verbes à diphtongue', 'Quel est l’impératif de « cerrar » à « tú » ?', 'mcq', '["cerra","cierre","cierras","cierra"]'::jsonb, 3, 'L’impératif diphtongue aussi : ¡Cierra la puerta!', 4),
    ('9a9dd0a3-7407-5035-b517-7e185953691c'::uuid, 'espagnol', '3e', 'Les verbes à affaiblissement', 'Quel est le subjonctif présent de « servir » à « nosotros » ?', 'mcq', '["sirvamos","servamos","sirvimos","servimos"]'::jsonb, 0, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes, nosotros compris : sirvamos.', 1),
    ('8797595d-f92f-509f-b847-30950b182ed1'::uuid, 'espagnol', '3e', 'Les verbes à affaiblissement', 'Quelle est la 1re personne du passé simple de « pedir » ?', 'mcq', '["pidí","pedí","pidé","pedió"]'::jsonb, 1, 'Au passé simple, l’affaiblissement ne touche que les 3es personnes (pidió, pidieron) : on dit pedí.', 2),
    ('a16e14c0-709d-5997-a8ad-50f27aa3aaa8'::uuid, 'espagnol', '3e', 'Les verbes à affaiblissement', 'Quel est le gérondif de « reír » ?', 'mcq', '["reyendo","reíendo","riendo","rindo"]'::jsonb, 2, 'Reír s’affaiblit au gérondif : riendo.', 3),
    ('be929798-21ad-5a78-9de4-d982b37abd31'::uuid, 'espagnol', '3e', 'Les verbes à affaiblissement', 'Quelle est la 3e personne du singulier du passé simple de « sentir » ?', 'mcq', '["sentió","sientió","sentó","sintió"]'::jsonb, 3, 'Sentir est un verbe mixte : diphtongue au présent (siento), affaiblissement au passé simple (sintió). Sentó vient de sentar.', 4),
    ('f4138537-22cb-5c34-9ee5-cd61de000f19'::uuid, 'espagnol', '3e', 'Ser et estar', 'Que signifie « La fruta está verde » ?', 'mcq', '["Le fruit n’est pas mûr","Le fruit est de couleur verte","Le fruit est bio","Le fruit est cher"]'::jsonb, 0, 'Ser verde, c’est être de couleur verte ; estar verde, c’est ne pas être mûr.', 1),
    ('40b3128a-96d1-5191-9105-85d8db181ff9'::uuid, 'espagnol', '3e', 'Ser et estar', 'Esta mesa ___ de madera.', 'mcq', '["está","es","hay","tiene"]'::jsonb, 1, 'La matière définit l’objet : on emploie ser (es de madera).', 2),
    ('6ab7cbaa-1917-50e8-b857-8433ae714615'::uuid, 'espagnol', '3e', 'Ser et estar', 'Que signifie « Esta paella está muy rica » ?', 'mcq', '["Elle est chère","Elle est riche en calories","Elle est délicieuse","Elle est pour les riches"]'::jsonb, 2, 'Ser rico, c’est être riche ; estar rico, c’est être délicieux.', 3),
    ('90b19667-d721-51a1-b1d2-70048d4a282a'::uuid, 'espagnol', '3e', 'Ser et estar', 'Que signifie « estar aburrido » ?', 'mcq', '["Être ennuyeux","Être pressé","Être endormi","S’ennuyer"]'::jsonb, 3, 'Ser aburrido : être ennuyeux (c’est sa nature). Estar aburrido : s’ennuyer (c’est son état du moment).', 4),
    ('492b7337-33d6-5d14-afd1-dbc62ea2c268'::uuid, 'espagnol', '3e', 'Le gérondif', 'Que signifie « Salió corriendo » ?', 'mcq', '["Il est sorti en courant","Il sortait pour courir","Il sortira courir","Il a fini de courir"]'::jsonb, 0, 'Seul, le gérondif exprime la manière ou la simultanéité : il est sorti en courant.', 1),
    ('69126ccf-eb3d-5228-83e9-9ad09db794f0'::uuid, 'espagnol', '3e', 'Le gérondif', 'Quel est le gérondif de « ir » ?', 'mcq', '["iendo","yendo","ando","iyendo"]'::jsonb, 1, 'Le -iendo devient -yendo après une voyelle : ir donne yendo.', 2),
    ('ca802d20-ab5d-569a-9294-8bcccf4932e4'::uuid, 'espagnol', '3e', 'Le gérondif', 'Que signifie « Va mejorando » ?', 'mcq', '["Il va s’améliorer demain","Il s’est amélioré","Il s’améliore peu à peu","Il va mieux que moi"]'::jsonb, 2, 'Ir + gérondif exprime une progression lente.', 3),
    ('b0e06a14-b678-5a2b-8255-2b119db45650'::uuid, 'espagnol', '3e', 'Le gérondif', 'Que signifie « Acabó aceptando » ?', 'mcq', '["Il vient d’accepter","Il a refusé","Il accepte encore","Il a fini par accepter"]'::jsonb, 3, 'Acabar + gérondif marque le point d’aboutissement : il a fini par accepter.', 4),
    ('508f3249-cedd-5c77-9cb9-1a59a3fb3ae9'::uuid, 'espagnol', '3e', 'Le participe passé', 'Quel est le participe passé de « poner » ?', 'mcq', '["puesto","ponido","pondido","posto"]'::jsonb, 0, 'Poner fait partie des participes irréguliers : puesto.', 1),
    ('a597e385-e74f-5499-a4ba-8e9cd3ae3c73'::uuid, 'espagnol', '3e', 'Le participe passé', 'Quel est le participe passé de « romper » ?', 'mcq', '["rompido","roto","rupto","rompedo"]'::jsonb, 1, 'Romper a un participe irrégulier : roto (una ventana rota).', 2),
    ('9f9cd237-cfcc-5857-95c3-837b158fbd0f'::uuid, 'espagnol', '3e', 'Le participe passé', 'Comment l’espagnol préfère-t-il dire « la maison a été construite en 1920 » ?', 'mcq', '["La casa ha sido construida en 1920","La casa está construyendo en 1920","Se construyó la casa en 1920","La casa construyó en 1920"]'::jsonb, 2, 'L’espagnol emploie peu la passive avec ser : il lui préfère la tournure en se (ou la 3e personne du pluriel).', 3),
    ('5051d09f-5a06-5699-9b80-6d6cc9d1e6f0'::uuid, 'espagnol', '3e', 'Le participe passé', 'Comment dit-on « un texte imprimé » ?', 'mcq', '["un texto imprimido","un texto imprimida","un texto impresado","un texto impreso"]'::jsonb, 3, 'Imprimir a deux participes : imprimido pour les temps composés, impreso comme adjectif.', 4),
    ('f40c31a0-20ee-5474-9c7b-b29bcadd4147'::uuid, 'espagnol', '3e', 'Les verbes du type « gustar »', 'No me gusta ___ el pescado.', 'mcq', '["nada","muy","ningún","ni"]'::jsonb, 0, 'Pour dire « pas du tout », on emploie no… nada : No me gusta nada.', 1),
    ('94a74d59-03dd-5f3a-92cc-b53b6f6cc126'::uuid, 'espagnol', '3e', 'Les verbes du type « gustar »', 'A mis padres ___ gustan los viajes.', 'mcq', '["le","les","se","los"]'::jsonb, 1, 'La personne est complément indirect pluriel : les. Le verbe, lui, s’accorde avec los viajes.', 2),
    ('c1bd2466-2875-538b-b58b-9185549d6f47'::uuid, 'espagnol', '3e', 'Les verbes du type « gustar »', 'Que signifie « Nos hacen falta dos sillas » ?', 'mcq', '["Nous avons deux chaises de trop","Nous faisons deux chaises","Il nous faut deux chaises","Deux chaises nous plaisent"]'::jsonb, 2, 'Hacer falta se construit comme gustar : dos sillas est le sujet, d’où le pluriel hacen.', 3),
    ('03446b42-caab-5d46-b92d-186125422027'::uuid, 'espagnol', '3e', 'Les verbes du type « gustar »', 'Que signifie « Me queda poco dinero » ?', 'mcq', '["J’ai trop d’argent","Je garde mon argent","Je dois de l’argent","Il me reste peu d’argent"]'::jsonb, 3, 'Quedar se construit comme gustar : me queda signifie « il me reste ».', 4),
    ('a49466a1-2458-5278-b387-8228f3eac03e'::uuid, 'espagnol', '3e', 'L’obligation', 'Hace ___ que estudies más.', 'mcq', '["falta","necesario","que","preciso"]'::jsonb, 0, 'Hacer falta que + subjonctif exprime une nécessité, dans un registre courant.', 1),
    ('57a3639d-c07c-58de-b437-1727960c0c6a'::uuid, 'espagnol', '3e', 'L’obligation', 'Quelle nuance exprime « deber » + infinitif ?', 'mcq', '["La probabilité","Le devoir moral, le conseil pressant","Une obligation valable pour tous","L’habitude"]'::jsonb, 1, 'Debes respetar a tus padres : deber exprime le devoir moral. Deber de exprimerait la probabilité.', 2),
    ('869adce8-2189-5a69-9562-20b57350aadc'::uuid, 'espagnol', '3e', 'L’obligation', 'Comment interdire à un ami de sortir ?', 'mcq', '["¡No sales!","¡No sal!","¡No salgas!","¡No saliste!"]'::jsonb, 2, 'L’ordre négatif passe toujours par le subjonctif présent : ¡No salgas!', 3),
    ('de6ed268-5792-5750-ae40-baf87ded8310'::uuid, 'espagnol', '3e', 'L’obligation', 'Comment dit-on « il fallait partir » (en général, pour tous) ?', 'mcq', '["Hay que salir","Habían que salir","Tenían que salir","Había que salir"]'::jsonb, 3, 'Hay que reste invariable et se conjugue seulement en temps : había que, habrá que, hubo que.', 4),
    ('a90a00dd-519b-5b36-908b-3ccf119abf26'::uuid, 'espagnol', '3e', 'L’habitude', 'Mis abuelos ___ cenar a las nueve.', 'mcq', '["suelen","solen","suelan","sueles"]'::jsonb, 0, 'Soler diphtongue o en ue : suelen. Il est suivi directement de l’infinitif.', 1),
    ('308dd5f0-94c8-53b2-8b1e-d2854e56317c'::uuid, 'espagnol', '3e', 'L’habitude', 'Quelle tournure signifie « avoir l’habitude de » dans un registre soutenu ?', 'mcq', '["soler de","acostumbrar a","acostumbrarse de","usar a"]'::jsonb, 1, 'Acostumbrar a + infinitif est soutenu ; acostumbrarse a veut dire « s’habituer à ».', 2),
    ('29671da4-fb5b-5c8f-add7-9013be7ff305'::uuid, 'espagnol', '3e', 'L’habitude', 'Que signifie « a menudo » ?', 'mcq', '["Jamais","Parfois","Souvent","Toujours"]'::jsonb, 2, 'A menudo signifie « souvent » ; a veces, « parfois ».', 3),
    ('46966751-7981-5403-83a3-fa1b6946e38f'::uuid, 'espagnol', '3e', 'L’habitude', 'Quelle nuance sépare « cada día » de « todos los días » ?', 'mcq', '["Aucune","Cada día est au passé","Todos los días est familier","Cada día détaille jour après jour, todos los días embrasse l’ensemble"]'::jsonb, 3, 'Cada día insiste sur chaque jour pris un à un, todos los días sur la totalité des jours.', 4),
    ('0ac8500e-ccfa-515a-b92a-9e7ab997477d'::uuid, 'espagnol', '3e', 'La probabilité', 'Parece que ___ a llover.', 'mcq', '["va","vaya","vayan","ir"]'::jsonb, 0, 'Parecer que est suivi de l’indicatif : Parece que va a llover.', 1),
    ('fe6168ef-1c3a-507f-94f9-1e7867d9102d'::uuid, 'espagnol', '3e', 'La probabilité', 'Es probable que ___ esta tarde.', 'mcq', '["llueve","llueva","lloverá","llovía"]'::jsonb, 1, 'Es probable que exprime une probabilité et commande le subjonctif.', 2),
    ('c3f29df3-0400-5fb5-b461-9d5463170a9b'::uuid, 'espagnol', '3e', 'La probabilité', '« Cuando llegué, no estaba: habría salido. » Que signifie « habría salido » ici ?', 'mcq', '["Il était sorti, c’est certain","Il sortirait plus tard","Il avait dû sortir","Il doit sortir"]'::jsonb, 2, 'Le conditionnel passé exprime une supposition sur un fait accompli, vue du passé : il avait dû sortir.', 3),
    ('d32fb3d1-cdea-5de1-8ab0-e6c7875b49ed'::uuid, 'espagnol', '3e', 'La probabilité', 'Lequel se construit à l’indicatif OU au subjonctif selon la force du doute ?', 'mcq', '["a lo mejor","puede que","sin duda","tal vez"]'::jsonb, 3, 'Tal vez (comme quizás) prend l’indicatif si le doute est faible, le subjonctif s’il est fort. A lo mejor prend toujours l’indicatif, puede que toujours le subjonctif.', 4),
    ('f1403793-5c01-5452-8ec1-55dd23e4c6a9'::uuid, 'espagnol', '3e', 'Le conseil', 'Quel est l’impératif de « ir » à « tú » ?', 'mcq', '["ve","va","vaya","id"]'::jsonb, 0, 'L’impératif de ir à tú est irrégulier : ve (¡Ve a casa!). Vaya sert pour usted, id pour vosotros.', 1),
    ('2bb97e0d-519a-58b6-aa4b-0c102f7691e7'::uuid, 'espagnol', '3e', 'Le conseil', 'Quelle structure exprime une suggestion plus douce que « deberías » ?', 'mcq', '["L’impératif","Podrías + infinitif","Tener que + infinitif","Hay que + infinitif"]'::jsonb, 1, 'Sur l’échelle du conseil, podrías llamarle suggère, là où deberías conseille fermement et l’impératif ordonne.', 2),
    ('b78f11b2-fdcd-51b8-87e8-f7b1ea932304'::uuid, 'espagnol', '3e', 'Le conseil', 'Quel est l’impératif de « comer » à « vosotros » ?', 'mcq', '["comáis","comes","comed","comid"]'::jsonb, 2, 'L’impératif affirmatif de vosotros remplace le -r de l’infinitif par -d : comed. Le négatif, lui, est no comáis.', 3),
    ('66d4fbe5-1ef9-5159-8a90-c0a7f1e0978c'::uuid, 'espagnol', '3e', 'Le conseil', 'Comment dit-on « Ne me le dis pas » ?', 'mcq', '["No dímelo","No me lo dices","No digasmelo","No me lo digas"]'::jsonb, 3, 'À l’impératif négatif, on emploie le subjonctif et les pronoms passent devant le verbe.', 4),
    ('14f0b5f9-8d81-596a-87a5-b408b3ee540d'::uuid, 'espagnol', '3e', 'Le présent de l’indicatif', 'Nosotros ___ en Madrid.', 'mcq', '["vivimos","vivemos","vivamos","viviemos"]'::jsonb, 0, 'Les verbes en -ir font -imos à nosotros : vivimos. C’est là qu’ils se distinguent des verbes en -er (comemos).', 1),
    ('96eeac6b-a959-5cfc-bc38-cd86358880b5'::uuid, 'espagnol', '3e', 'Le présent de l’indicatif', 'Quelle est la 1re personne du présent de « salir » ?', 'mcq', '["salo","salgo","saligo","salgue"]'::jsonb, 1, 'Salir a un yo irrégulier : salgo. Le reste de la conjugaison est régulier.', 2),
    ('8fda4f5f-3410-5c53-a498-f2a42f31ef57'::uuid, 'espagnol', '3e', 'Le présent de l’indicatif', 'Quelle est la 1re personne du présent de « saber » ?', 'mcq', '["sabo","sepo","sé","sabe"]'::jsonb, 2, 'Saber fait sé à la première personne, avec un accent écrit qui le distingue du pronom se.', 3),
    ('dbfd5294-5337-5515-a6e6-ff039fd5a4d0'::uuid, 'espagnol', '3e', 'Le présent de l’indicatif', 'Quelle est la 1re personne du présent de « caber » ?', 'mcq', '["cabo","cabgo","cabro","quepo"]'::jsonb, 3, 'Caber (tenir dans) a un yo très irrégulier : quepo.', 4),
    ('195bafcc-33f4-56af-b750-36a405dd6563'::uuid, 'espagnol', '3e', 'Le subjonctif présent', 'Lo haré antes de que ___ tus padres.', 'mcq', '["lleguen","llegan","llegarán","llegar"]'::jsonb, 0, 'Antes de que est toujours suivi du subjonctif.', 1),
    ('c97ac80c-458d-5708-bfac-381996b6ea3e'::uuid, 'espagnol', '3e', 'Le subjonctif présent', 'Quel est le subjonctif présent de « saber » ?', 'mcq', '["sabe","sepa","saba","supiera"]'::jsonb, 1, 'Saber fait partie des six irréguliers du subjonctif, parce que sa première personne (sé) ne finit pas par -o : sepa.', 2),
    ('0eb8c5e4-d6f5-5ae5-b31e-787cdc205b85'::uuid, 'espagnol', '3e', 'Le subjonctif présent', 'Quel est le subjonctif présent de « conocer » à la 1re personne ?', 'mcq', '["conoca","conozco","conozca","conosca"]'::jsonb, 2, 'On part de conozco, on retire le -o et on bascule la voyelle : conozca. L’irrégularité de yo se propage.', 3),
    ('2f6dda0c-0adf-5492-9943-383d3d58fc68'::uuid, 'espagnol', '3e', 'Le subjonctif présent', 'Quel est le subjonctif présent de « sentir » à « nosotros » ?', 'mcq', '["sentamos","sientamos","sentimos","sintamos"]'::jsonb, 3, 'Les verbes en -ir mixtes s’affaiblissent au subjonctif à nosotros et vosotros : sintamos.', 4),
    ('8afbf15c-d7fa-5556-9dad-ea349102d39b'::uuid, 'espagnol', '3e', 'L’imparfait', 'Quel est l’imparfait de « ir » à « nosotros » ?', 'mcq', '["íbamos","ibamos","iamos","ibámos"]'::jsonb, 0, 'Ir est l’un des trois irréguliers de l’imparfait : iba… íbamos, avec l’accent sur le í.', 1),
    ('91579109-c5e4-52f9-92b7-a11d1e3ce650'::uuid, 'espagnol', '3e', 'L’imparfait', 'Comment s’écrit « nous parlions » ?', 'mcq', '["hablabamos","hablábamos","hablabámos","hablávamos"]'::jsonb, 1, 'L’imparfait en -aba prend un accent écrit à nosotros : hablábamos.', 2),
    ('08746e5c-87e0-5e88-8d5f-0f695853c730'::uuid, 'espagnol', '3e', 'L’imparfait', 'Quel est l’imparfait de « ser » à la 1re personne ?', 'mcq', '["sía","fui","era","seía"]'::jsonb, 2, 'Ser est irrégulier à l’imparfait : era, eras, era… Fui est le passé simple.', 3),
    ('2c969c95-dea1-5add-9137-7c587236ef31'::uuid, 'espagnol', '3e', 'L’imparfait', 'Quel est l’imparfait de « vivir » à la 3e personne du pluriel ?', 'mcq', '["vivieron","vivaban","viviban","vivían"]'::jsonb, 3, 'Les verbes en -er et -ir font -ía à l’imparfait : vivían. Vivieron est le passé simple.', 4),
    ('325245bc-bdf3-5896-b805-6bb0333bbc12'::uuid, 'espagnol', '3e', 'Le passé composé', '¿Ya ___ comido, chicos?', 'mcq', '["habéis","hemos","habés","ha"]'::jsonb, 0, 'Haber au présent fait habéis à vosotros : ¿Ya habéis comido?', 1),
    ('ef7782d2-3907-50a7-b4b9-78c80f8c594d'::uuid, 'espagnol', '3e', 'Le passé composé', 'Te he ___ la verdad.', 'mcq', '["decido","dicho","dicido","dijo"]'::jsonb, 1, 'Decir a un participe irrégulier : dicho.', 2),
    ('fb893235-44d2-57e4-84f6-4b06f0882a86'::uuid, 'espagnol', '3e', 'Le passé composé', 'Quel emploi illustre « Me he roto la pierna » (et je porte encore le plâtre) ?', 'mcq', '["Une habitude passée","Un récit historique","Un fait dont les effets durent","Une supposition"]'::jsonb, 2, 'Le pretérito perfecto rattache au présent un fait dont les effets se font encore sentir.', 3),
    ('188148e2-a137-5e73-9d87-e27824f13f47'::uuid, 'espagnol', '3e', 'Le passé composé', 'Que fait le passé simple par rapport au passé composé ?', 'mcq', '["Il raccroche le fait au présent","Il décrit un décor","Il exprime une habitude","Il coupe le fait du présent"]'::jsonb, 3, 'Le passé simple coupe le fait du présent ; le passé composé l’y raccroche.', 4),
    ('31491063-a325-5939-b862-648dc1c5279a'::uuid, 'espagnol', '3e', 'Le passé simple', 'Quelle est la 2e personne du singulier du passé simple de « comer » ?', 'mcq', '["comiste","comistes","comías","comió"]'::jsonb, 0, 'Comiste, sans -s final : « comistes » est une faute fréquente. Comías est l’imparfait.', 1),
    ('45709526-75a1-5316-8c35-9c58d80091af'::uuid, 'espagnol', '3e', 'Le passé simple', 'Quel est le passé simple de « hacer » à la 3e personne du singulier ?', 'mcq', '["hició","hizo","hico","hació"]'::jsonb, 1, 'Hacer a un prétérit fort (hice) ; à la 3e personne, le c devient z pour garder le son : hizo.', 2),
    ('b116936a-4cc4-58ae-a414-a79762144c2f'::uuid, 'espagnol', '3e', 'Le passé simple', 'Quel est le passé simple de « poner » à la 1re personne ?', 'mcq', '["pusé","poní","puse","pusí"]'::jsonb, 2, 'Poner a un prétérit fort, radical pus-, sans accent écrit : puse.', 3),
    ('cdd981fc-21c4-5d36-a551-46c869bc198c'::uuid, 'espagnol', '3e', 'Le passé simple', 'Quel est le passé simple de « querer » à la 1re personne ?', 'mcq', '["quisé","querí","quiso","quise"]'::jsonb, 3, 'Querer a un prétérit fort, radical quis- : quise (yo), quiso (él).', 4),
    ('859eae87-489a-58d0-b258-d9a3596c5792'::uuid, 'espagnol', '3e', 'Le futur', 'Que signifie « Será muy inteligente, pero no lo parece » ?', 'mcq', '["Il est peut-être très intelligent, mais ça ne se voit pas","Il sera très intelligent plus tard","Il était très intelligent","Il faut qu’il soit intelligent"]'::jsonb, 0, 'C’est le futur de concession : il exprime une réserve sur le présent.', 1),
    ('1e47653c-54fc-58f4-bdd0-29d0f26e39f7'::uuid, 'espagnol', '3e', 'Le futur', 'Quel est le futur de « decir » à la 1re personne ?', 'mcq', '["deciré","diré","dicé","dirá"]'::jsonb, 1, 'Decir raccourcit son radical au futur : diré. Dirá est la 3e personne.', 2),
    ('e78909fc-f344-5fe2-b7cd-5f114da3b8e7'::uuid, 'espagnol', '3e', 'Le futur', 'Quel est le futur de « salir » à la 1re personne ?', 'mcq', '["saliré","salré","saldré","salgré"]'::jsonb, 2, 'Salir fait partie des verbes où un d remplace la voyelle : saldré.', 3),
    ('b9d6a1a2-531e-5a1d-a946-766fa17372d0'::uuid, 'espagnol', '3e', 'Le futur', 'Quel est le futur de « mantener » à la 1re personne ?', 'mcq', '["mantenderé","manteneré","mantenré","mantendré"]'::jsonb, 3, 'Les composés suivent leur base : tener donne tendré, donc mantener donne mantendré.', 4),
    ('19633b2d-1dca-542f-a124-507bddf2e878'::uuid, 'francais', '3e', 'L’autoportrait', 'À quelle question l’autoportrait cherche-t-il à répondre ?', 'mcq', '["« Qu’est-ce qui m’est arrivé ? »","« Qui suis-je ? »","« Que vais-je devenir ? »","« Que pensent les autres de moi ? »"]'::jsonb, 1, 'L’autobiographie raconte ce qui est arrivé ; l’autoportrait décrit un être et répond à « qui suis-je ? ».', 1),
    ('999f986e-738d-5be9-a588-5082ea5f683e'::uuid, 'francais', '3e', 'L’autoportrait', 'Quelle peintre a fait de son corps blessé le sujet même de ses autoportraits ?', 'mcq', '["Élisabeth Vigée Le Brun","Berthe Morisot","Frida Kahlo","Camille Claudel"]'::jsonb, 2, 'Frida Kahlo, gravement blessée dans un accident, peint son corps souffrant dans de nombreux autoportraits.', 2),
    ('03db9282-7442-5656-aac5-940291c8e39e'::uuid, 'francais', '3e', 'L’autoportrait', 'Pourquoi un autoportrait honnête emploie-t-il le champ lexical des défauts ?', 'mcq', '["Parce qu’un autoportrait n’est pas un éloge","Pour se moquer du lecteur","Parce que c’est obligatoire au présent","Pour raconter sa vie dans l’ordre"]'::jsonb, 0, 'Un autoportrait qui ne montre que des qualités tourne à l’éloge ; nommer ses défauts donne un portrait plus juste.', 3),
    ('93a58957-f365-53a0-8717-e564eb919c91'::uuid, 'francais', '3e', 'L’autoportrait', 'En peinture, qu’est-ce qui « parle » autant que les traits du visage dans un autoportrait ?', 'mcq', '["Le prix du tableau","La signature","La taille du cadre","La pose, la lumière et le décor choisis"]'::jsonb, 3, 'Le peintre choisit comment il se montre : la pose, la lumière et le décor disent l’image qu’il veut donner de lui.', 4),
    ('26c03985-5b2c-5d6b-9748-dd3a78c45439'::uuid, 'francais', '3e', 'L’autobiographie : se raconter', 'Quelle œuvre de Rousseau s’ouvre sur « Je forme une entreprise qui n’eut jamais d’exemple » ?', 'mcq', '["Les Rêveries du promeneur solitaire","Les Confessions","Émile","Julie ou la Nouvelle Héloïse"]'::jsonb, 1, 'Rousseau ouvre *Les Confessions* par cette promesse : se montrer tel qu’il est, ce qu’aucun livre n’avait fait avant.', 1),
    ('a05cd4b6-d838-59d8-9287-7311c4454e2e'::uuid, 'francais', '3e', 'L’autobiographie : se raconter', 'Qu’est-ce qui distingue le roman autobiographique d’une autobiographie ?', 'mcq', '["Il est écrit au futur","Il ne parle que d’enfance","Il utilise la matière d’une vie, mais sans le pacte autobiographique","Il est toujours écrit par un proche"]'::jsonb, 2, 'Le roman autobiographique s’inspire de la vie de l’auteur sans s’engager à dire la vérité : il n’y a pas de pacte.', 2),
    ('6e079c01-339b-5e16-91d4-d699b5c138b1'::uuid, 'francais', '3e', 'L’autobiographie : se raconter', 'Quand l’adulte tire une leçon de son enfance, quel temps emploie-t-il volontiers ?', 'mcq', '["Le présent de vérité générale","Le passé simple","L’imparfait d’habitude","Le plus-que-parfait"]'::jsonb, 0, 'Pour énoncer une leçon valable encore aujourd’hui, l’adulte qui écrit passe au présent de vérité générale.', 3),
    ('67eea9f8-fc2c-57b7-9a47-eecf00179c94'::uuid, 'francais', '3e', 'L’autobiographie : se raconter', 'Quel auteur a écrit les *Mémoires d’outre-tombe* ?', 'mcq', '["Rousseau","Perec","Sarraute","Chateaubriand"]'::jsonb, 3, 'Chateaubriand y raconte sa vie mêlée aux grands événements de son temps : c’est l’exemple type des Mémoires.', 4),
    ('9ec5f474-4f00-5d2a-9c0d-5e366d25dea7'::uuid, 'francais', '3e', 'L’autobiographie : raconter le monde', 'Dans *W ou le souvenir d’enfance*, que dit le « trou » de la mémoire chez Perec ?', 'mcq', '["Une maladie de l’auteur","La disparition de ses parents","Un voyage oublié","Un refus d’écrire sur la guerre"]'::jsonb, 1, 'Les souvenirs qui manquent disent l’absence de ses parents, disparus pendant la guerre : le vide devient le sujet.', 1),
    ('11dd97c3-b175-5fea-9d01-84a8b8cbaf51'::uuid, 'francais', '3e', 'L’autobiographie : raconter le monde', 'À quoi sert l’adresse au lecteur dans un témoignage ?', 'mcq', '["À raccourcir le récit","À cacher l’auteur","À impliquer le lecteur et l’obliger","À donner des dates précises"]'::jsonb, 2, 'En s’adressant directement au lecteur, comme Primo Levi, le témoin l’implique : il ne peut plus rester indifférent.', 2),
    ('0b571287-9a0a-577f-887c-802ed409b7d1'::uuid, 'francais', '3e', 'L’autobiographie : raconter le monde', 'Quel changement le témoignage produit-il chez le lecteur ?', 'mcq', '["Il passe de « je sais que cela a eu lieu » à « je vois ce que cela faisait »","Il passe de la lecture au jeu","Il oublie les faits pour ne garder que l’émotion","Il connaît enfin toutes les dates"]'::jsonb, 0, 'Le témoignage ne se contente pas d’informer : il fait voir et ressentir ce que l’événement a été pour ceux qui l’ont vécu.', 3),
    ('a9c3e669-40b5-52f9-b5f9-6991d53c3f75'::uuid, 'francais', '3e', 'L’autobiographie : raconter le monde', 'Quel effet produit l’alternance du récit et du commentaire ?', 'mcq', '["Elle supprime le point de vue","Elle rend le texte plus court","Elle évite les dates","Elle donne deux regards sur les mêmes faits"]'::jsonb, 3, 'Le récit montre ce qui s’est passé, le commentaire l’éclaire avec le recul : deux regards se croisent.', 4),
    ('99cbaec3-e3e0-53b1-bf00-ec0ecfc75130'::uuid, 'francais', '3e', 'Les formes de satire', 'Que signifie la formule latine *castigat ridendo mores* ?', 'mcq', '["Le rire est le propre de l’homme","Elle corrige les mœurs par le rire","Il faut rire de tout","La vérité sort de la bouche des enfants"]'::jsonb, 1, 'C’est la devise de la comédie reprise par Molière : faire rire des défauts pour les corriger.', 1),
    ('c11e603a-9b00-50d9-9516-2b4d1e6a3545'::uuid, 'francais', '3e', 'Les formes de satire', 'Des héros nobles qui parlent comme des valets : quel est ce procédé ?', 'mcq', '["L’héroï-comique","Le pastiche","Le burlesque","La caricature"]'::jsonb, 2, 'Le burlesque est l’inverse de l’héroï-comique : un sujet noble traité dans un style bas.', 2),
    ('921d5e3d-28ed-5497-b47f-2897620bb30e'::uuid, 'francais', '3e', 'Les formes de satire', 'Dans *Candide*, que répète Voltaire au milieu des désastres, par ironie ?', 'mcq', '["« Tout est pour le mieux dans le meilleur des mondes possibles »","« La raison du plus fort est toujours la meilleure »","« Je pense, donc je suis »","« Il faut cultiver la vertu »"]'::jsonb, 0, 'Répétée au milieu des catastrophes, la formule optimiste devient absurde : l’ironie dénonce ce qu’elle feint d’approuver.', 3),
    ('0275afec-53d5-5bfe-9a27-b008f574bf8a'::uuid, 'francais', '3e', 'Les formes de satire', 'Qu’est-ce qui distingue le comique de la satire ?', 'mcq', '["Le comique est toujours en vers","La satire ne fait jamais rire","Le comique attaque frontalement","Le comique fait rire sans forcément critiquer"]'::jsonb, 3, 'Le comique peut viser seulement le rire ; la satire attaque une cible, par le détour du rire.', 4),
    ('d9c5d88d-045e-5f3b-a1ad-3feb7ccb405f'::uuid, 'francais', '3e', 'La satire : une arme', 'Quel « regard étranger » Montesquieu utilise-t-il pour critiquer la société française ?', 'mcq', '["Celui d’un Huron","Celui d’un Persan","Celui d’un lion","Celui d’un enfant"]'::jsonb, 1, 'Dans les *Lettres persanes*, des voyageurs persans trouvent étrange ce que les Français jugent normal ; le Huron est celui de Voltaire.', 1),
    ('0851702e-0470-58f1-9c85-1e18b905f55e'::uuid, 'francais', '3e', 'La satire : une arme', 'Quel procédé consiste à feindre de ne pas comprendre pour faire voir l’absurde ?', 'mcq', '["L’hyperbole","L’accumulation","La fausse naïveté","La chute brève"]'::jsonb, 2, 'La fausse naïveté fait semblant de ne pas comprendre une coutume et oblige ainsi le lecteur à la regarder autrement.', 2),
    ('4801bf19-a2d1-5ab1-8486-591bb2d1fa75'::uuid, 'francais', '3e', 'La satire : une arme', 'Qu’est-ce qu’une satire réussie, selon le cours ?', 'mcq', '["Elle fait rire de ce qui mérite d’être combattu, pas de ceux qui subissent déjà","Elle fait rire de tout le monde sans distinction","Elle vise d’abord les plus faibles","Elle évite de désigner une cible"]'::jsonb, 0, 'Une satire qui rit des victimes renforce les préjugés ; elle doit viser ce qui mérite d’être combattu.', 3),
    ('b42bcd8f-429e-5946-9787-9ce59f7f6ed0'::uuid, 'francais', '3e', 'La satire : une arme', 'Quel est l’effet d’une énumération ridicule ?', 'mcq', '["Elle adoucit la critique","Elle ralentit le récit sans effet","Elle remplace l’argument par un chiffre","Elle met sur le même plan des choses incomparables"]'::jsonb, 3, 'En plaçant côte à côte le grave et le dérisoire, l’énumération ridicule révèle l’absurdité de la cible.', 4),
    ('9cfb0270-aa0c-5921-abbf-753a8c99c041'::uuid, 'francais', '3e', 'Le regard du poète sur le monde', 'Quels poètes ont fait de la ville moderne, de ses foules et de ses vitrines, un thème poétique ?', 'mcq', '["Ronsard et Lamartine","Apollinaire et Cendrars","Ponge et Hugo","Baudelaire et Ronsard"]'::jsonb, 1, 'Apollinaire et Cendrars chantent la ville moderne ; Lamartine et Hugo sont plutôt associés à la nature.', 1),
    ('8b3ab256-bd62-53e2-a288-1511ec8a98da'::uuid, 'francais', '3e', 'Le regard du poète sur le monde', 'Quand la nature devient le miroir des états d’âme du poète, on parle de…', 'mcq', '["satire","registre épique","lyrisme","calligramme"]'::jsonb, 2, 'Le lyrisme exprime les sentiments personnels ; chez Lamartine ou Hugo, les paysages reflètent l’âme du poète.', 2),
    ('f16ba35c-184d-5b5d-90c6-8a65af179f56'::uuid, 'francais', '3e', 'Le regard du poète sur le monde', 'Selon le cours, un poème se lit comme…', 'mcq', '["un trajet","une liste","une notice","un tableau statistique"]'::jsonb, 0, 'Un poème part d’un point et arrive ailleurs : il faut repérer son mouvement.', 3),
    ('b619a612-a810-508e-8303-8369d630ddd8'::uuid, 'francais', '3e', 'Le regard du poète sur le monde', 'Qu’est-ce qu’une assonance ?', 'mcq', '["La répétition d’une consonne","La reprise d’un mot en début de vers","Une rime entre deux strophes","La répétition d’une voyelle"]'::jsonb, 3, 'L’assonance répète un son voyelle ; l’allitération répète une consonne.', 4),
    ('7e774802-e682-5d7a-b4da-ed9500441ca1'::uuid, 'francais', '3e', 'Le poète métamorphose le monde', 'Dans « la mer, ce grand miroir », quelle figure reconnaît-on ?', 'mcq', '["Une comparaison","Une métaphore","Une personnification","Une allitération"]'::jsonb, 1, 'La mer et le miroir sont rapprochés sans outil de comparaison : c’est une métaphore.', 1),
    ('4b10944b-3350-5abd-9025-42a3b11a7db5'::uuid, 'francais', '3e', 'Le poète métamorphose le monde', 'Quel effet produit un vers court dans un poème ?', 'mcq', '["Il déploie la phrase","Il martèle un mot","Il accélère le rythme","Il supprime la rime"]'::jsonb, 2, 'Le vers court accélère ; l’alexandrin, plus long, déploie ; l’anaphore martèle.', 2),
    ('099e1f78-788f-52b7-8002-c7c898ab702e'::uuid, 'francais', '3e', 'Le poète métamorphose le monde', 'Quel poème de Baudelaire imagine un ailleurs où le désir peut enfin se dire ?', 'mcq', '["*L’Invitation au voyage*","*Le Pont Mirabeau*","*Demain, dès l’aube*","*Liberté*"]'::jsonb, 0, 'Dans *L’Invitation au voyage*, Baudelaire rêve d’un pays où « tout n’est qu’ordre et beauté ».', 3),
    ('d6707b54-26e8-54cd-b531-34ef733bf731'::uuid, 'francais', '3e', 'Le poète métamorphose le monde', 'Selon le cours, que doit apporter une métaphore réussie ?', 'mcq', '["Un simple ornement","Une rime de plus","Un vers plus long","Une connaissance qu’aucune phrase littérale ne donnerait"]'::jsonb, 3, 'Une bonne métaphore n’est pas décorative : en rapprochant deux réalités, elle fait voir quelque chose de nouveau.', 4),
    ('c4b73283-a346-59c1-b532-7b7e0d56e7c7'::uuid, 'francais', '3e', 'L’art comme outil de dénonciation des horreurs de la guerre', 'Quel peintre a dénoncé l’occupation napoléonienne de l’Espagne dans *Les Désastres de la guerre* ?', 'mcq', '["Picasso","Goya","Delacroix","Géricault"]'::jsonb, 1, 'Goya grave *Les Désastres de la guerre* et peint *Tres de Mayo* contre les violences de l’occupation française.', 1),
    ('90d3df08-8004-510b-ad86-ef3806ea0a30'::uuid, 'francais', '3e', 'L’art comme outil de dénonciation des horreurs de la guerre', 'Qu’est-ce que *Guernica* ne montre pas ?', 'mcq', '["Des victimes","Une mère et son enfant","Ni avion, ni soldat, ni uniforme","Des animaux"]'::jsonb, 2, 'Picasso ne montre pas les bombardiers : la souffrance des victimes suffit à désigner le crime.', 2),
    ('39c97a65-1d8b-56ec-9f48-7e4d20528ceb'::uuid, 'francais', '3e', 'L’art comme outil de dénonciation des horreurs de la guerre', 'Quel registre accuse directement les responsables ?', 'mcq', '["Le registre polémique","Le registre pathétique","Le registre lyrique","Le registre comique"]'::jsonb, 0, 'Le registre polémique attaque et accuse ; le pathétique cherche à provoquer la pitié.', 3),
    ('6a38cddc-1c72-51b4-9269-12070c0cf6b8'::uuid, 'francais', '3e', 'L’art comme outil de dénonciation des horreurs de la guerre', 'Pourquoi le détail vrai (une odeur, un prénom) est-il si fort dans un texte de guerre ?', 'mcq', '["Parce qu’il allonge le texte","Parce qu’il remplace les dates","Parce qu’il est plus facile à inventer","Parce qu’il pèse plus lourd qu’une abstraction"]'::jsonb, 3, 'Un détail concret rend l’horreur réelle et proche, là où un chiffre ou une idée générale reste lointain.', 4),
    ('41b0e36d-9475-5abf-85ac-b3afe1a8a27c'::uuid, 'francais', '3e', 'La littérature témoin de l’Histoire', 'Dans quel journal Zola publie-t-il « J’accuse… ! » en 1898 ?', 'mcq', '["Le Figaro","L’Aurore","Le Monde","Le Petit Journal"]'::jsonb, 1, '« J’accuse… ! » paraît en une de *L’Aurore* : Zola y défend Dreyfus et risque un procès.', 1),
    ('20b7e3d3-7d12-511c-b095-c4bb3e6f471a'::uuid, 'francais', '3e', 'La littérature témoin de l’Histoire', 'À quoi sert une question rhétorique dans un texte engagé ?', 'mcq', '["À demander une information","À conclure le texte","À obliger le lecteur à répondre en lui-même","À introduire un dialogue"]'::jsonb, 2, 'La question rhétorique n’attend pas de réponse écrite : la réponse s’impose d’elle-même dans l’esprit du lecteur.', 2),
    ('d27d07d3-bffc-5983-b16a-1cf5188adc0d'::uuid, 'francais', '3e', 'La littérature témoin de l’Histoire', 'Quel effet produit l’alternance du « je » et du « nous » ?', 'mcq', '["Elle transforme une voix en collectif","Elle cache l’auteur","Elle rend le texte comique","Elle marque un changement de temps"]'::jsonb, 0, 'En passant du « je » au « nous », l’auteur entraîne le lecteur dans une cause commune.', 3),
    ('1a8cac9d-16bb-51dd-b84e-64162d3d52cb'::uuid, 'francais', '3e', 'La littérature témoin de l’Histoire', 'Quel est le risque de passer par la fiction pour dénoncer ?', 'mcq', '["La censure immédiate","Un procès certain","L’exil de l’auteur","Que le message se perde"]'::jsonb, 3, 'La fiction protège l’auteur, mais un lecteur peut ne pas saisir la critique cachée derrière l’histoire.', 4),
    ('e9afa058-7785-5aff-a262-1cf816865913'::uuid, 'francais', '3e', 'La science, source d’espoirs et d’exaltation', 'Quel roman de Jules Verne explore les profondeurs de la mer ?', 'mcq', '["*De la Terre à la Lune*","*Vingt Mille Lieues sous les mers*","*Voyage au centre de la Terre*","*Le Tour du monde en quatre-vingts jours*"]'::jsonb, 1, 'Dans *Vingt Mille Lieues sous les mers*, le capitaine Nemo parcourt les océans à bord du Nautilus.', 1),
    ('c5b0048d-65f3-575d-997e-5f19d180479a'::uuid, 'francais', '3e', 'La science, source d’espoirs et d’exaltation', 'Qu’est-ce qui garantit la vraisemblance des textes qui exaltent la science ?', 'mcq', '["Le registre comique","Les rimes","Le vocabulaire technique","L’absence de description"]'::jsonb, 2, 'Le vocabulaire technique donne l’impression d’un savoir précis : le lecteur croit à la machine parce que le texte explique.', 2),
    ('6e5d5c8b-fdc4-56a7-9334-7cf2d6af7ecd'::uuid, 'francais', '3e', 'La science, source d’espoirs et d’exaltation', 'Dans *Plein Ciel*, que voit Victor Hugo dans le vol humain ?', 'mcq', '["La promesse d’une humanité enfin libérée","Une menace pour la paix","Un simple divertissement","Une punition des dieux"]'::jsonb, 0, 'Hugo célèbre le vol comme un symbole du progrès qui libère l’humanité.', 3),
    ('6f65f896-dd2b-5ed6-a6f5-8da7a8215150'::uuid, 'francais', '3e', 'La science, source d’espoirs et d’exaltation', 'Quels événements du XIXe siècle célèbrent le progrès aux yeux du public ?', 'mcq', '["Les salons littéraires","Les jeux Olympiques antiques","Les procès célèbres","Les Expositions universelles"]'::jsonb, 3, 'Les Expositions universelles présentent au public les inventions et les machines nouvelles : elles portent l’idée de progrès.', 4),
    ('12a16fed-dc5a-5d4a-9c53-85e27f084dc8'::uuid, 'francais', '3e', 'La science, source de désillusion et d’inquiétudes', 'Quelle question Mary Shelley pose-t-elle à la science ?', 'mcq', '["« Peut-on le faire ? »","« Doit-on le faire ? »","« Combien cela coûte-t-il ? »","« Qui l’a inventé en premier ? »"]'::jsonb, 1, 'Shelley ne s’interroge pas sur la possibilité technique, mais sur la responsabilité morale du savant.', 1),
    ('d131fe95-d3f2-586d-9744-ac3c6b5e1894'::uuid, 'francais', '3e', 'La science, source de désillusion et d’inquiétudes', 'Que représente la figure de l’apprenti sorcier ?', 'mcq', '["Un savant qui refuse d’inventer","Un magicien bienveillant","Quelqu’un qui déclenche un processus qu’il ne sait plus arrêter","Un élève qui apprend la chimie"]'::jsonb, 2, 'L’apprenti sorcier lance une force qu’il ne maîtrise plus : c’est la peur d’une science qui échappe à son créateur.', 2),
    ('3c2ccd32-3660-5a81-9fc7-a882072be54b'::uuid, 'francais', '3e', 'La science, source de désillusion et d’inquiétudes', 'Quel événement de 1945 donne une réalité brutale aux récits sur la science destructrice ?', 'mcq', '["La bombe atomique","La découverte de la pénicilline","Le premier pas sur la Lune","L’invention du télégraphe"]'::jsonb, 0, 'Avec la bombe atomique, la peur d’un savoir capable de détruire l’humanité devient bien réelle.', 3),
    ('f0bc29b5-dd3d-5181-bb66-e47c011eb785'::uuid, 'francais', '3e', 'La science, source de désillusion et d’inquiétudes', 'Quelle œuvre met en scène la figure du savant fou ?', 'mcq', '["*Vingt Mille Lieues sous les mers*","*Plein Ciel*","*Fahrenheit 451*","*Docteur Jekyll et Mister Hyde*"]'::jsonb, 3, 'Le docteur Jekyll expérimente sur lui-même et libère Mister Hyde : le savoir sans conscience tourne au cauchemar.', 4),
    ('b9a336df-58f3-5031-872b-cc001da8d159'::uuid, 'francais', '3e', 'Les différents types de discours', 'Au discours indirect, que devient un passé composé ?', 'mcq', '["Un imparfait","Un plus-que-parfait","Un conditionnel","Un passé simple"]'::jsonb, 1, 'Dans un récit au passé, le passé composé du discours direct devient un plus-que-parfait : « j’ai fini » → « qu’il avait fini ».', 1),
    ('bee5a8dc-31bf-55fa-bf8b-8badf8fd135a'::uuid, 'francais', '3e', 'Les différents types de discours', 'Au discours indirect, que devient un futur ?', 'mcq', '["Un futur antérieur","Un imparfait","Un conditionnel","Un présent"]'::jsonb, 2, '« Je viendrai » devient « il dit qu’il viendrait » : le futur se transforme en conditionnel.', 2),
    ('13adf126-2640-5228-a52f-b99f732ccc5b'::uuid, 'francais', '3e', 'Les différents types de discours', '« Il annonça son départ. » De quel type de discours s’agit-il ?', 'mcq', '["Du discours narrativisé","Du discours direct","Du discours indirect","Du discours indirect libre"]'::jsonb, 0, 'La parole n’est pas rapportée, seulement résumée par un verbe : c’est le discours narrativisé.', 3),
    ('39957e7b-303b-5cb8-bf9a-16db1e67b974'::uuid, 'francais', '3e', 'Les différents types de discours', 'Quel écrivain a fait du discours indirect libre son outil favori ?', 'mcq', '["Molière","Rousseau","Voltaire","Flaubert"]'::jsonb, 3, 'Chez Flaubert, la parole du personnage traverse le récit du narrateur sans guillemets ni « que ».', 4),
    ('31071b90-0aaa-5c53-aefb-2545956012ea'::uuid, 'francais', '3e', 'Les différences de focalisation dans un texte', 'Quel effet produit la focalisation zéro sur le lecteur ?', 'mcq', '["Il est plongé dans le mystère","Il domine l’histoire","Il ne connaît que les gestes","Il partage l’ignorance d’un seul personnage"]'::jsonb, 1, 'Avec un narrateur omniscient, le lecteur sait tout, y compris les pensées de plusieurs personnages.', 1),
    ('dd6fc1a8-0085-5b70-bc20-8de1964ee3f8'::uuid, 'francais', '3e', 'Les différences de focalisation dans un texte', 'Quels romanciers du XIXe siècle emploient volontiers la focalisation zéro ?', 'mcq', '["Ionesco et Beckett","Perec et Ernaux","Balzac et Hugo","Ponge et Apollinaire"]'::jsonb, 2, 'Le roman du XIXe siècle, chez Balzac ou Hugo, adopte souvent un narrateur qui sait tout.', 2),
    ('60f3584c-3f18-5b04-a383-e245c3c4ca88'::uuid, 'francais', '3e', 'Les différences de focalisation dans un texte', 'Quel effet produit la focalisation externe ?', 'mcq', '["Le mystère et une certaine inquiétude","Une identification totale au héros","La connaissance de l’avenir","L’accès à toutes les pensées"]'::jsonb, 0, 'On ne voit que les gestes, sans accès aux consciences : le lecteur doit deviner, d’où le mystère.', 3),
    ('b9457d34-892d-5a90-9224-61178c99d477'::uuid, 'francais', '3e', 'Les différences de focalisation dans un texte', 'Comment justifier le point de vue adopté dans une réponse de brevet ?', 'mcq', '["En donnant son avis personnel","En citant le titre du livre","En comptant les personnages","Par un relevé dans le texte"]'::jsonb, 3, 'On justifie toujours par des indices précis cités dans le texte, puis on dit l’effet produit.', 4),
    ('55038b03-f894-5188-ae5b-9658c873a600'::uuid, 'francais', '3e', 'Les valeurs du présent, du passé simple, de l’imparfait et du futur', 'Quelle valeur a le présent dans « Il court tous les matins » ?', 'mcq', '["Vérité générale","Habitude","Narration","Énonciation"]'::jsonb, 1, 'L’action se répète régulièrement : c’est un présent d’habitude.', 1),
    ('ce1b97ee-c3e8-5098-8afc-0aaae5d851c5'::uuid, 'francais', '3e', 'Les valeurs du présent, du passé simple, de l’imparfait et du futur', 'Quelle valeur a le futur dans « Je vous demanderai de patienter » ?', 'mcq', '["Futur historique","Futur antérieur","Futur de politesse","Futur de prédiction"]'::jsonb, 2, 'Le futur atténue ici une demande : c’est un futur de politesse.', 2),
    ('f4432ff5-8299-5893-9621-5eb86a2e09a6'::uuid, 'francais', '3e', 'Les valeurs du présent, du passé simple, de l’imparfait et du futur', 'Dans « Si j’avais le temps, je viendrais », quelle valeur a l’imparfait ?', 'mcq', '["L’hypothèse","L’habitude","La description","La rupture"]'::jsonb, 0, 'Après « si », l’imparfait exprime une hypothèse, ici suivie d’un conditionnel.', 3),
    ('971c58ab-13da-51ad-80f7-01e7afb82c3d'::uuid, 'francais', '3e', 'Les valeurs du présent, du passé simple, de l’imparfait et du futur', '« Il sort à l’instant » : quelle valeur a ce présent ?', 'mcq', '["Vérité générale","Habitude","Futur proche","Passé proche"]'::jsonb, 3, 'L’action vient juste d’avoir lieu : c’est un présent à valeur de passé proche.', 4),
    ('511484b0-dd97-54ce-af73-3d73d1848c97'::uuid, 'francais', '3e', 'Les principales figures de style', '« Mourir de rire » : quelle figure reconnaît-on ?', 'mcq', '["Une litote","Une hyperbole","Un euphémisme","Un oxymore"]'::jsonb, 1, 'On exagère volontairement : personne ne meurt vraiment de rire, c’est une hyperbole.', 1),
    ('f7e14d6b-a0ac-50aa-88d2-d9f918f51e0c'::uuid, 'francais', '3e', 'Les principales figures de style', '« L’astre du jour » pour désigner le soleil est…', 'mcq', '["une métonymie","une antithèse","une périphrase","une ellipse"]'::jsonb, 2, 'La périphrase remplace un mot par une expression de plusieurs mots qui le désigne.', 2),
    ('db4644cc-a9ed-5e88-b931-0d334521c24b'::uuid, 'francais', '3e', 'Les principales figures de style', 'La Justice représentée par une femme aux yeux bandés est…', 'mcq', '["une allégorie","une comparaison","une gradation","une anaphore"]'::jsonb, 0, 'Une idée abstraite, la justice, prend la forme d’une figure concrète : c’est une allégorie.', 3),
    ('711e1931-6569-5187-abbc-df4b620c3eef'::uuid, 'francais', '3e', 'Les principales figures de style', 'Quelles sont les trois étapes de la méthode pour analyser une figure ?', 'mcq', '["Lire, résumer, conclure","Nommer, compter, citer","Citer, résumer, juger","Repérer, nommer, interpréter"]'::jsonb, 3, 'On repère et cite, on nomme la figure, puis on interprète son effet dans ce texte précis.', 4),
    ('dcb60c84-c2a1-5cf3-90f6-7cf647025e78'::uuid, 'francais', '3e', 'Construire une argumentation', 'Qu’appelle-t-on la contre-thèse ?', 'mcq', '["L’exemple qui illustre la thèse","L’opinion que l’on combat","La conclusion du texte","Un argument de plus"]'::jsonb, 1, 'La contre-thèse est l’opinion adverse, que l’on peut concéder en partie avant de la réfuter.', 1),
    ('121ddf2b-1874-526a-80d3-d063e22cf21e'::uuid, 'francais', '3e', 'Construire une argumentation', 'Quel connecteur exprime la cause ?', 'mcq', '["Donc","Cependant","En effet","Certes"]'::jsonb, 2, '« En effet », « car » et « parce que » introduisent une cause ; « donc » exprime la conséquence.', 2),
    ('2c24ebf4-2268-57d2-99c5-10533ef039e3'::uuid, 'francais', '3e', 'Construire une argumentation', 'Quels moyens emploie-t-on pour persuader ?', 'mcq', '["Images, émotion, apostrophe, question rhétorique","Chiffres et preuves uniquement","Définitions et dates","Notes de bas de page"]'::jsonb, 0, 'Persuader s’adresse aux sentiments ; convaincre s’appuie sur la raison, les preuves et les chiffres.', 3),
    ('1405ce60-4991-5b31-b351-93faabdcd4a4'::uuid, 'francais', '3e', 'Construire une argumentation', 'Dans un paragraphe argumenté, que vient faire la troisième étape ?', 'mcq', '["Donner un deuxième exemple","Annoncer la conclusion","Répéter la thèse","Expliquer l’exemple pour montrer son lien avec l’argument"]'::jsonb, 3, 'Sans explication, l’exemple reste décoratif : le lecteur ne voit pas en quoi il prouve l’argument.', 4),
    ('5ed7d7f7-ed4d-553b-b35b-7c03638eafc5'::uuid, 'francais', '3e', 'Le vocabulaire de la poésie', 'Combien de syllabes compte un décasyllabe ?', 'mcq', '["8","10","12","6"]'::jsonb, 1, 'Le décasyllabe compte 10 syllabes, l’octosyllabe 8, l’alexandrin 12.', 1),
    ('dc118b96-7fab-5fad-9529-eff3ad2b5aa8'::uuid, 'francais', '3e', 'Le vocabulaire de la poésie', 'Quelle est la disposition des rimes embrassées ?', 'mcq', '["AABB","ABAB","ABBA","ABCA"]'::jsonb, 2, 'Dans les rimes embrassées, deux rimes identiques sont « embrassées » par une autre : ABBA.', 2),
    ('3356fa1c-00c4-571b-b07e-1116d68f2931'::uuid, 'francais', '3e', 'Le vocabulaire de la poésie', 'Qu’est-ce qu’un contre-rejet ?', 'mcq', '["Un mot bref placé à la fin d’un vers, qui annonce la phrase du vers suivant","Un mot bref renvoyé au début du vers suivant","Une rime intérieure","La coupe au milieu de l’alexandrin"]'::jsonb, 0, 'Le contre-rejet se place à la fin du vers précédent ; le rejet, au début du vers suivant.', 3),
    ('bb49681e-d16a-5dcf-b5da-1357aa6d9232'::uuid, 'francais', '3e', 'Le vocabulaire de la poésie', 'Quand le e muet d’un vers compte-t-il comme une syllabe ?', 'mcq', '["Toujours","En fin de vers","Devant une voyelle","Devant une consonne"]'::jsonb, 3, 'Le e muet se prononce et compte devant une consonne ; il s’efface devant une voyelle et en fin de vers.', 4),
    ('cb3d273c-d5a5-5256-8c42-551eb8bbda22'::uuid, 'francais', '3e', 'Le vocabulaire du théâtre', 'Qu’est-ce qu’une tirade ?', 'mcq', '["Un échange de répliques très brèves","Une longue réplique ininterrompue","Une indication scénique","Une parole dite à part"]'::jsonb, 1, 'La tirade est une longue réplique adressée à d’autres personnages ; le monologue, lui, se dit seul en scène.', 1),
    ('b6f3c752-c4f4-5c7e-b6ea-830f5068f4b8'::uuid, 'francais', '3e', 'Le vocabulaire du théâtre', 'Quand change-t-on de scène dans une pièce ?', 'mcq', '["À chaque changement de décor seulement","À la fin de chaque tirade","Dès qu’un personnage entre ou sort","Toutes les dix répliques"]'::jsonb, 2, 'La scène est délimitée par les entrées et sorties des personnages ; l’acte, plus large, marque souvent un changement de lieu ou de temps.', 2),
    ('8178ce0f-253d-5402-8819-cad163a63b67'::uuid, 'francais', '3e', 'Le vocabulaire du théâtre', 'Quel type de théâtre montre un langage en panne et une action réduite ?', 'mcq', '["Le théâtre de l’absurde","La tragédie classique","Le drame romantique","La comédie de mœurs"]'::jsonb, 0, 'Chez Ionesco et Beckett, le langage tourne à vide et l’action se réduit : c’est le théâtre de l’absurde.', 3),
    ('3773be69-9006-5531-8de2-9919a3e153de'::uuid, 'francais', '3e', 'Le vocabulaire du théâtre', 'Un personnage avare poussé jusqu’au ridicule relève du comique…', 'mcq', '["de gestes","de mots","de situation","de caractère"]'::jsonb, 3, 'Le comique de caractère naît d’un défaut poussé à l’extrême, comme l’avarice d’Harpagon.', 4),
    ('90b9e146-a89b-5e9e-9c32-fc20e3e91685'::uuid, 'histoire-geo', '3e', 'La Première Guerre mondiale : vers une guerre totale', 'Quel événement du 28 juin 1914 déclenche le jeu des alliances ?', 'mcq', '["L’invasion de la Belgique","La bataille de la Marne","L’attentat de Sarajevo","La révolution russe"]'::jsonb, 2, 'L’attentat de Sarajevo contre l’héritier d’Autriche-Hongrie met en marche les alliances : un conflit local devient européen en quelques semaines.', 1),
    ('5abe0f23-0cc3-55ae-883e-6e10119cc4dd'::uuid, 'histoire-geo', '3e', 'La Première Guerre mondiale : vers une guerre totale', 'Quelle bataille de 1914 bloque le front et met fin à la guerre de mouvement ?', 'mcq', '["Verdun","La Somme","La Marne","Tannenberg"]'::jsonb, 2, 'Après la Marne, les armées s’enterrent : c’est le début de la guerre de position et de 700 km de tranchées.', 2),
    ('0046af5f-c34e-5204-81b4-ec366ef06c8d'::uuid, 'histoire-geo', '3e', 'La Première Guerre mondiale : vers une guerre totale', 'Que désigne l’expression « bourrage de crâne » ?', 'mcq', '["Les exercices imposés aux jeunes recrues","La propagande qui cache aux civils la réalité du front","Les bombardements d’artillerie avant une offensive","Les blessures au visage des « gueules cassées »"]'::jsonb, 1, 'La mobilisation est aussi morale : censure et propagande entretiennent l’arrière dans l’idée d’une victoire proche.', 3),
    ('9af6b4bf-019f-5173-8204-9a9f24679e32'::uuid, 'histoire-geo', '3e', 'La Première Guerre mondiale : vers une guerre totale', 'Quel pays fait partie des Empires centraux ?', 'mcq', '["L’Italie","La Russie","Le Royaume-Uni","L’Empire ottoman"]'::jsonb, 3, 'Les Empires centraux réunissent l’Allemagne, l’Autriche-Hongrie et l’Empire ottoman ; l’Italie rejoint l’Entente en 1915.', 4),
    ('ad1a6bcf-5b2b-50b9-9336-b329b132699f'::uuid, 'histoire-geo', '3e', 'Les régimes totalitaires dans les années 1930', 'En quoi consiste la collectivisation des terres en URSS ?', 'mcq', '["La vente des terres aux paysans les plus riches","Le partage des grands domaines entre familles paysannes","Le regroupement forcé des terres sous le contrôle de l’État","L’abandon de l’agriculture au profit de l’industrie"]'::jsonb, 2, 'Staline impose des fermes collectives et liquide les « koulaks » : la famine qui suit, l’Holodomor, fait des millions de morts en Ukraine.', 1),
    ('139d2ce9-1e57-5906-aa40-a1a1d7ec08bd'::uuid, 'histoire-geo', '3e', 'Les régimes totalitaires dans les années 1930', 'Quel coup de force porte Mussolini au pouvoir en 1922 ?', 'mcq', '["L’incendie du Reichstag","La marche sur Rome","La Nuit des longs couteaux","Le putsch de la Brasserie"]'::jsonb, 1, 'La marche sur Rome des chemises noires pousse le roi à nommer Mussolini chef du gouvernement.', 2),
    ('a3192262-f5f6-5f2c-901c-0ad6c367462e'::uuid, 'histoire-geo', '3e', 'Les régimes totalitaires dans les années 1930', 'Que sont les Grandes Purges de 1936-1938 ?', 'mcq', '["Des réformes pour moderniser l’agriculture","L’expulsion des étrangers d’URSS","Des élections internes au parti communiste","Une vague de répression qui frappe jusqu’aux cadres du parti"]'::jsonb, 3, 'Procès truqués, exécutions et envois au Goulag : la terreur stalinienne n’épargne pas les dirigeants du parti eux-mêmes.', 3),
    ('184fdcca-2496-5aa4-bfc8-8d6b793ec9ae'::uuid, 'histoire-geo', '3e', 'Les régimes totalitaires dans les années 1930', 'Quel pays l’Italie fasciste conquiert-elle en 1935 ?', 'mcq', '["La Libye","L’Albanie","L’Éthiopie","La Grèce"]'::jsonb, 2, 'La conquête de l’Éthiopie sert la propagande du Duce, qui rêve d’un nouvel empire romain.', 4),
    ('cea8b171-c574-5116-ab67-1eace750040c'::uuid, 'histoire-geo', '3e', 'La France durant l’entre-deux-guerres', 'Quels accords de 1925 nourrissent l’espoir d’une paix durable ?', 'mcq', '["Les accords de Munich","Les accords de Locarno","Les accords Matignon","Les accords d’Évian"]'::jsonb, 1, 'Les années 1920 apportent une relative prospérité et, avec Locarno, l’espoir d’une réconciliation franco-allemande.', 1),
    ('91df0bbf-cf13-5658-87a8-aaa21859ca89'::uuid, 'histoire-geo', '3e', 'La France durant l’entre-deux-guerres', 'Quel groupe fait partie des ligues d’extrême droite du 6 février 1934 ?', 'mcq', '["La SFIO","Les radicaux","La CGT","Les Croix-de-Feu"]'::jsonb, 3, 'Croix-de-Feu, Action française et Jeunesses patriotes manifestent devant la Chambre ; la gauche y voit une menace fasciste.', 2),
    ('1c0eddb0-9f3a-5803-a9f5-54c8980f56a1'::uuid, 'histoire-geo', '3e', 'La France durant l’entre-deux-guerres', 'Quand le Front populaire remporte-t-il les élections ?', 'mcq', '["En février 1934","En juin 1937","En mai 1936","En octobre 1929"]'::jsonb, 2, 'La victoire de mai 1936 porte Léon Blum au pouvoir, dans une immense vague de grèves avec occupation d’usines.', 3),
    ('b1a7c101-203a-524b-b637-b57fd977dc41'::uuid, 'histoire-geo', '3e', 'La France durant l’entre-deux-guerres', 'Quelle autre réforme accompagne les accords Matignon sous le Front populaire ?', 'mcq', '["La scolarité obligatoire jusqu’à 14 ans","Le droit de vote des femmes","La Sécurité sociale","La retraite à 60 ans"]'::jsonb, 0, 'La scolarité obligatoire passe à 14 ans ; le droit de vote des femmes n’arrive qu’en 1944 et la Sécurité sociale en 1945.', 4),
    ('1bd5a6a6-8e68-5a02-a378-1714819d80d9'::uuid, 'histoire-geo', '3e', 'La Seconde Guerre mondiale : une guerre d’anéantissement', 'Quel nom porte l’invasion de l’URSS par l’Allemagne en juin 1941 ?', 'mcq', '["L’opération Overlord","L’opération Barbarossa","Le plan Marshall","L’opération Torch"]'::jsonb, 1, 'Barbarossa ouvre à l’Est une guerre idéologique d’anéantissement contre des populations jugées « inférieures ».', 1),
    ('e59cf7df-037b-5556-b9a2-4ee0b314a34e'::uuid, 'histoire-geo', '3e', 'La Seconde Guerre mondiale : une guerre d’anéantissement', 'Que désigne la « Shoah par balles » ?', 'mcq', '["Les combats de la Résistance juive","Les bombardements des villes allemandes","Les exécutions dans les camps de l’Ouest","Les fusillades de masse des Einsatzgruppen à l’Est dès 1941"]'::jsonb, 3, 'Avant les chambres à gaz, des unités mobiles fusillent les Juifs par centaines de milliers, comme à Babi Yar.', 2),
    ('9ba766ac-9322-5db1-bf5f-56b209ccdfa5'::uuid, 'histoire-geo', '3e', 'La Seconde Guerre mondiale : une guerre d’anéantissement', 'Quand l’Allemagne capitule-t-elle ?', 'mcq', '["Le 6 juin 1944","Le 2 septembre 1945","Le 8 mai 1945","Le 6 août 1945"]'::jsonb, 2, 'La guerre continue ensuite dans le Pacifique jusqu’à la capitulation japonaise du 2 septembre 1945.', 3),
    ('4fad157c-6a69-54f3-8954-3e4558e96330'::uuid, 'histoire-geo', '3e', 'La Seconde Guerre mondiale : une guerre d’anéantissement', 'Quelles villes japonaises sont frappées par la bombe atomique en août 1945 ?', 'mcq', '["Hiroshima et Nagasaki","Tokyo et Osaka","Kyoto et Kobe","Midway et Guadalcanal"]'::jsonb, 0, 'Employée deux fois, les 6 et 9 août, l’arme nucléaire change la nature même de la guerre.', 4),
    ('bf346cc9-69fd-5ff4-a05f-c370c38ff2fb'::uuid, 'histoire-geo', '3e', 'La France de Vichy (1940-1944)', 'Qu’est-ce que la Milice, créée en janvier 1943 ?', 'mcq', '["Une force de police française qui traque résistants et Juifs","Une armée de la France libre","Un mouvement de Résistance du Sud","Une unité allemande stationnée à Vichy"]'::jsonb, 0, 'La Milice illustre la collaboration policière : des Français au service de la répression.', 1),
    ('f726f40f-2424-5c81-8e01-b1edfb81f789'::uuid, 'histoire-geo', '3e', 'La France de Vichy (1940-1944)', 'Environ combien de Juifs sont déportés depuis la France ?', 'mcq', '["Environ 13 000","Environ 75 000","Environ 750 000","Environ 5 000"]'::jsonb, 1, 'Environ 75 000 Juifs sont déportés de France, et moins de 3 % reviennent.', 2),
    ('3e04a47f-35df-5272-9ae7-9ed7f2a7f809'::uuid, 'histoire-geo', '3e', 'La France de Vichy (1940-1944)', 'Quelle entrevue du 24 octobre 1940 symbolise la collaboration politique ?', 'mcq', '["L’entrevue de Munich","L’entrevue de Rethondes","L’entrevue de Montoire","L’entrevue de Yalta"]'::jsonb, 2, 'À Montoire, Pétain serre la main d’Hitler et engage la France dans la voie de la collaboration.', 3),
    ('75c2f212-a955-5423-be39-c4ad96377f08'::uuid, 'histoire-geo', '3e', 'La France de Vichy (1940-1944)', 'Quel président reconnaît officiellement en 1995 la responsabilité de l’État français dans la déportation ?', 'mcq', '["François Mitterrand","Charles de Gaulle","Valéry Giscard d’Estaing","Jacques Chirac"]'::jsonb, 3, 'Il a fallu un demi-siècle pour reconnaître que la collaboration avait été décidée par un État français.', 4),
    ('e5d10e74-1a91-52bd-9cc3-7a928a726276'::uuid, 'histoire-geo', '3e', 'La décolonisation', 'Quel mouvement déclenche la guerre d’Algérie le 1er novembre 1954 ?', 'mcq', '["L’OAS","Le FLN","Le GPRF","Le Kominform"]'::jsonb, 1, 'Lors de la « Toussaint rouge », le FLN lance une série d’attentats : c’est le début de huit ans de guerre.', 1),
    ('73fe5c4b-ae52-5693-8bba-7729997b3e83'::uuid, 'histoire-geo', '3e', 'La décolonisation', 'Qui a forgé le mot « tiers-monde » en 1952 ?', 'mcq', '["Jean Fourastié","Raymond Aron","Nehru","Alfred Sauvy"]'::jsonb, 3, 'Le mot désigne les pays pauvres et nouvellement indépendants, qui refusent souvent de s’aligner sur un bloc.', 2),
    ('c417f1a0-a8b7-5d64-9a53-cb3054993fdc'::uuid, 'histoire-geo', '3e', 'La décolonisation', 'Quel prix paie l’indépendance négociée de l’Inde en 1947 ?', 'mcq', '["Une guerre de huit ans contre le Royaume-Uni","L’exode d’un million de colons","Une partition sanglante entre l’Inde et le Pakistan","La perte de sa capitale"]'::jsonb, 2, 'Même une décolonisation négociée peut être violente : la partition entraîne massacres et déplacements de populations.', 3),
    ('6d99733e-263b-591c-97e3-da3149de6e51'::uuid, 'histoire-geo', '3e', 'La décolonisation', 'Quelle conséquence la guerre d’Algérie a-t-elle en France en 1958 ?', 'mcq', '["La chute de la IVe République et le retour de de Gaulle","L’entrée de la France dans l’OTAN","La fin de la guerre d’Indochine","Le Front populaire"]'::jsonb, 0, 'La crise algérienne emporte la IVe République : de Gaulle revient et fonde la Ve.', 4),
    ('a819908a-f04d-5dfc-ad3a-e7cafc1d878e'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1947-1962)', 'Quelle doctrine soviétique de 1947 présente le monde divisé en deux camps ?', 'mcq', '["La doctrine Truman","La doctrine Brejnev","La doctrine Jdanov","La doctrine Monroe"]'::jsonb, 2, 'Réponse à la doctrine Truman, la doctrine Jdanov oppose un camp « impérialiste » à un camp « anti-impérialiste ».', 1),
    ('8052b752-4789-567f-b664-1caf0272ef69'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1947-1962)', 'Qui annonce dès 1946 qu’un « rideau de fer » est tombé sur l’Europe ?', 'mcq', '["Truman","Churchill","De Gaulle","Staline"]'::jsonb, 1, 'Churchill décrit la coupure de l’Europe entre démocraties de l’Ouest et régimes communistes de l’Est.', 2),
    ('53759ad2-01f0-51fd-969c-d195752544d5'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1947-1962)', 'Quelle formule de Raymond Aron résume la guerre froide ?', 'mcq', '["« Guerre totale, paix armée »","« Un monde, deux modèles »","« La paix par le droit »","« Paix impossible, guerre improbable »"]'::jsonb, 3, 'La paix est impossible car les idéologies s’opposent, la guerre improbable car la dissuasion nucléaire la rend suicidaire.', 3),
    ('e6dc4fa0-940a-5331-baed-e9b2a7714cb5'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1947-1962)', 'Qu’installe-t-on après la crise de Cuba pour éviter un nouveau malentendu ?', 'mcq', '["Un « téléphone rouge » entre Washington et Moscou","Un mur autour de Cuba","Une base de l’ONU en Floride","Un conseil militaire commun"]'::jsonb, 0, 'Ce lien direct permet aux deux dirigeants de se parler en cas de crise.', 4),
    ('2a841e9d-62d4-5d4b-a20d-983d476b98f0'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1963-1991)', 'Quel accord de 1975 porte à la fois sur les frontières et sur les droits de l’homme ?', 'mcq', '["Le traité SALT I","L’acte final d’Helsinki","Le traité de non-prolifération","Le traité de l’Élysée"]'::jsonb, 1, 'Signé pendant la détente, l’acte d’Helsinki sert ensuite d’appui aux dissidents de l’Est.', 1),
    ('d8d1cec1-1ae9-5b4c-8bc1-f2592063078f'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1963-1991)', 'Que signifie la « glasnost » lancée par Gorbatchev ?', 'mcq', '["La restructuration économique","Le retour aux plans quinquennaux","La transparence","La réunification allemande"]'::jsonb, 2, 'La glasnost libère la parole ; la perestroïka, elle, désigne la restructuration de l’économie.', 2),
    ('ff176942-52e4-50bb-b673-b9b2698f753a'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1963-1991)', 'Quel syndicat incarne la contestation du régime en Pologne ?', 'mcq', '["Solidarność","Le Kominform","La Stasi","Le Politburo"]'::jsonb, 0, 'Solidarność ouvre la brèche : en 1989, la Pologne est la première à sortir du communisme.', 3),
    ('8317d751-ea55-55bd-8db2-15dab770276a'::uuid, 'histoire-geo', '3e', 'Le monde durant la guerre froide (1963-1991)', 'Quand l’Allemagne est-elle réunifiée ?', 'mcq', '["Le 9 novembre 1989","Le 25 décembre 1991","En juillet 1991","Le 3 octobre 1990"]'::jsonb, 3, 'Moins d’un an après la chute du Mur, la RDA rejoint la RFA.', 4),
    ('b72dcd3c-e259-5a11-bc44-4b19105b3707'::uuid, 'histoire-geo', '3e', 'La construction européenne', 'Pourquoi la déclaration Schuman propose-t-elle de mettre en commun le charbon et l’acier ?', 'mcq', '["Parce qu’ils sont les produits les moins chers","Pour aider les agriculteurs","Parce que ce sont les matières premières de l’armement","Pour préparer la monnaie unique"]'::jsonb, 2, 'En partageant ce qui sert à faire la guerre, on rend la guerre entre voisins matériellement impossible.', 1),
    ('067fa005-3026-507e-9f43-a753ace38c45'::uuid, 'histoire-geo', '3e', 'La construction européenne', 'Combien de membres compte l’Union après l’élargissement de 2004 ?', 'mcq', '["15","25","28","12"]'::jsonb, 1, 'En 2004, les pays d’Europe centrale et orientale font passer l’Union de 15 à 25 membres.', 2),
    ('20a26b8d-5206-5161-8784-9112ddb754d6'::uuid, 'histoire-geo', '3e', 'La construction européenne', 'Quel traité de 2007 réforme les institutions après le rejet du projet de Constitution ?', 'mcq', '["Le traité de Nice","Le traité de Maastricht","Le traité d’Amsterdam","Le traité de Lisbonne"]'::jsonb, 3, 'Le projet de Constitution ayant été rejeté en 2005, le traité de Lisbonne reprend l’essentiel de la réforme institutionnelle.', 3),
    ('f2cb2a05-0d90-53a4-b457-e5e4114935e4'::uuid, 'histoire-geo', '3e', 'La construction européenne', 'Quel est le rôle de la Commission européenne ?', 'mcq', '["Elle propose les textes et veille à l’application des traités","Elle réunit les chefs d’État","Elle est élue par les citoyens","Elle tranche les litiges"]'::jsonb, 0, 'La Commission incarne la logique supranationale ; les chefs d’État se réunissent au Conseil européen.', 4),
    ('ce072d17-1b83-56b9-b54c-7b5eead43afc'::uuid, 'histoire-geo', '3e', 'La géopolitique du monde actuel', 'Sur quoi repose principalement la puissance de l’Union européenne ?', 'mcq', '["Sur son armée commune","Sur son marché et ses normes","Sur ses ressources en pétrole","Sur son droit de veto à l’ONU"]'::jsonb, 1, 'L’Union pèse par ses règles et son marché bien plus que par la force militaire.', 1),
    ('70c7e177-64cc-5b36-a77e-b71a86f88482'::uuid, 'histoire-geo', '3e', 'La géopolitique du monde actuel', 'Quelle organisation terroriste connaît un essor puis un recul entre 2014 et 2019 ?', 'mcq', '["L’ETA","Le Hezbollah","Daech","Les Brigades rouges"]'::jsonb, 2, 'Daech a contrôlé un territoire en Irak et en Syrie avant d’en être chassé par une coalition internationale.', 2),
    ('83f28f47-8783-577d-a420-cf4ca6beb3b1'::uuid, 'histoire-geo', '3e', 'La géopolitique du monde actuel', 'Quelle région africaine est marquée par des États fragiles, des groupes armés et des coups d’État ?', 'mcq', '["Le Sahel","L’Afrique australe","Le Maghreb","La Corne de l’Afrique"]'::jsonb, 0, 'Le Sahel est l’un des grands foyers de tension du monde actuel.', 3),
    ('c7688e92-e64b-5c9f-9f5e-a4d9b6515fa8'::uuid, 'histoire-geo', '3e', 'La géopolitique du monde actuel', 'Quand la Russie lance-t-elle l’invasion de l’Ukraine ?', 'mcq', '["En mars 2014","En septembre 2001","En décembre 1991","En février 2022"]'::jsonb, 3, 'Après l’annexion de la Crimée en 2014, l’invasion de 2022 ramène une guerre de haute intensité en Europe.', 4),
    ('7f66e719-004a-5b74-a316-bd2a22087843'::uuid, 'histoire-geo', '3e', '1944-1947 : refonder la République, redéfinir la démocratie', 'Sous quel titre le programme du CNR est-il adopté en mars 1944 ?', 'mcq', '["« Travail, Famille, Patrie »","« La France libre »","« Les Jours heureux »","« Le Pain, la Paix, la Liberté »"]'::jsonb, 2, 'Le programme du CNR prévoit la refondation démocratique et sociale du pays après la Libération.', 1),
    ('60be3a7d-2218-5d01-b65b-942a6aa341e8'::uuid, 'histoire-geo', '3e', '1944-1947 : refonder la République, redéfinir la démocratie', 'Quand de Gaulle quitte-t-il la tête du gouvernement, hostile au futur régime ?', 'mcq', '["En août 1944","En janvier 1946","En octobre 1946","En mai 1958"]'::jsonb, 1, 'De Gaulle rejette un régime qui donne l’essentiel du pouvoir à l’Assemblée et démissionne dès janvier 1946.', 2),
    ('97b2b1ca-3acb-54f7-bf83-88e88ff0723e'::uuid, 'histoire-geo', '3e', '1944-1947 : refonder la République, redéfinir la démocratie', 'Qu’est-ce que l’épuration à la Libération ?', 'mcq', '["La reconstruction des villes détruites","La nationalisation des banques","Le retour des prisonniers de guerre","Le châtiment des collaborateurs, par des cours de justice mais parfois de façon sauvage"]'::jsonb, 3, 'L’épuration est d’abord sauvage dans les premières semaines, puis encadrée par des cours de justice.', 3),
    ('8fdd801a-ec62-543d-9e36-6c5bb1ede44c'::uuid, 'histoire-geo', '3e', '1944-1947 : refonder la République, redéfinir la démocratie', 'Quels droits le préambule de la Constitution de 1946 proclame-t-il ?', 'mcq', '["Le droit au travail, à la santé, à l’instruction et l’égalité femmes-hommes","Le droit de porter des armes et de faire sécession","Le droit de propriété seulement","Le droit de grève réservé aux fonctionnaires"]'::jsonb, 0, 'Ces droits sociaux forment encore aujourd’hui une partie du socle de notre Constitution.', 4),
    ('ab0ca1d1-b8e7-53f3-9784-4726912cd393'::uuid, 'histoire-geo', '3e', 'Les années de Gaulle (1958-1969)', 'Quel événement d’avril 1961 tente de s’opposer à la politique algérienne de De Gaulle ?', 'mcq', '["La Toussaint rouge","Le putsch des généraux","La crise de Suez","La journée du 13 mai"]'::jsonb, 1, 'Des généraux tentent un coup de force à Alger contre l’autodétermination ; il échoue en quelques jours.', 1),
    ('ef700177-e4c2-5d19-949a-410897fded24'::uuid, 'histoire-geo', '3e', 'Les années de Gaulle (1958-1969)', 'Quand la France réalise-t-elle son premier essai nucléaire ?', 'mcq', '["En 1945","En 1966","En 1960","En 1974"]'::jsonb, 2, 'L’arme nucléaire est au cœur de la politique d’indépendance nationale voulue par de Gaulle.', 2),
    ('16760269-bda1-5774-8141-202ba1500fff'::uuid, 'histoire-geo', '3e', 'Les années de Gaulle (1958-1969)', 'Quel pays de Gaulle reconnaît-il en 1964, en se démarquant des États-Unis ?', 'mcq', '["L’URSS","Cuba","Le Vietnam du Nord","La Chine populaire"]'::jsonb, 3, 'Cette reconnaissance illustre une diplomatie qui refuse l’alignement automatique sur Washington.', 3),
    ('807d73dd-bf63-5a6a-ab83-866d9da97ef7'::uuid, 'histoire-geo', '3e', 'Les années de Gaulle (1958-1969)', 'Qui succède à de Gaulle à la présidence en 1969 ?', 'mcq', '["Georges Pompidou","Valéry Giscard d’Estaing","François Mitterrand","Michel Debré"]'::jsonb, 0, 'Après la démission du général, Georges Pompidou est élu et préside jusqu’en 1974.', 4),
    ('870ceb73-badc-5aeb-941a-5fe67ebd71fb'::uuid, 'histoire-geo', '3e', 'Les Trente Glorieuses', 'Que permet aux femmes une loi de 1965 ?', 'mcq', '["Voter aux élections","Avorter légalement","Ouvrir un compte bancaire sans l’accord de leur mari","Entrer dans la fonction publique"]'::jsonb, 2, 'Cette loi marque une étape de l’émancipation juridique des femmes, avant la contraception (1967) et l’IVG (1975).', 1),
    ('1b478616-037c-59f4-875b-6b6870600a92'::uuid, 'histoire-geo', '3e', 'Les Trente Glorieuses', 'Quelle nouvelle forme de commerce apparaît durant les Trente Glorieuses ?', 'mcq', '["Le marché couvert","Les grandes surfaces","Le commerce en ligne","Les foires médiévales"]'::jsonb, 1, 'Les grandes surfaces et le crédit accompagnent l’essor de la société de consommation.', 2),
    ('e2fa2d16-7cf5-56c5-af25-2ec12667180a'::uuid, 'histoire-geo', '3e', 'Les Trente Glorieuses', 'Comment évolue le pouvoir d’achat des Français durant cette période ?', 'mcq', '["Il baisse de moitié","Il stagne","Il augmente de 10 %","Il double"]'::jsonb, 3, 'La forte croissance permet aux ménages de s’équiper en automobile, télévision, réfrigérateur…', 3),
    ('a193279c-8e6b-59c7-af3d-d7e2aa7546e4'::uuid, 'histoire-geo', '3e', 'Les Trente Glorieuses', 'Quel problème touche les grands ensembles avec le temps ?', 'mcq', '["L’enclavement","L’absence de salle de bains","Le manque d’eau chaude","La surpopulation agricole"]'::jsonb, 0, 'Modernes à leur construction, ces quartiers souffrent ensuite d’être mal reliés au reste de la ville.', 4),
    ('795c8c65-2b41-5253-b12a-54e3af6b624e'::uuid, 'histoire-geo', '3e', 'La Ve République à l’épreuve de la durée (1958-2012)', 'Combien de cohabitations la Ve République a-t-elle connues ?', 'mcq', '["Trois","Une","Cinq","Deux"]'::jsonb, 0, 'Il y en a eu trois : 1986-1988, 1993-1995 et 1997-2002.', 1),
    ('854d8780-f9f9-5af9-b910-2cd1f7469670'::uuid, 'histoire-geo', '3e', 'La Ve République à l’épreuve de la durée (1958-2012)', 'Quelle union civile est créée en 1999 ?', 'mcq', '["Le mariage pour tous","Le PACS","Le divorce par consentement mutuel","La parité"]'::jsonb, 1, 'Le pacte civil de solidarité est l’une des réformes qui accompagnent la transformation de la société.', 2),
    ('75f9cb9c-9362-5d02-a343-5876f0db7028'::uuid, 'histoire-geo', '3e', 'La Ve République à l’épreuve de la durée (1958-2012)', 'Quelle décision de Jacques Chirac concerne directement les jeunes hommes ?', 'mcq', '["La majorité à 18 ans","Le collège unique","La fin du service militaire","La retraite à 60 ans"]'::jsonb, 2, 'La fin du service militaire obligatoire professionnalise l’armée ; la majorité à 18 ans date de Giscard d’Estaing.', 3),
    ('e5f61b3a-3461-509f-a688-aaa6290d506e'::uuid, 'histoire-geo', '3e', 'La Ve République à l’épreuve de la durée (1958-2012)', 'Que proclame la révision constitutionnelle de 2003 ?', 'mcq', '["La fin du Sénat","Le quinquennat","La parité obligatoire","Une République à l’organisation décentralisée"]'::jsonb, 3, 'Elle inscrit dans la Constitution la décentralisation lancée par les lois Defferre de 1982.', 4),
    ('505a8986-951c-5585-9981-3c163e934577'::uuid, 'histoire-geo', '3e', 'Les aires urbaines en France', 'Comment l’INSEE appelle-t-il l’aire urbaine depuis 2020 ?', 'mcq', '["L’aire d’attraction des villes","La métropole du Grand Paris","L’unité urbaine élargie","Le bassin de vie"]'::jsonb, 0, 'Le nom change, le principe reste : mesurer jusqu’où une ville fait vivre les gens.', 1),
    ('54ca41d0-870e-5853-a501-e20506a5dbc5'::uuid, 'histoire-geo', '3e', 'Les aires urbaines en France', 'Quel objectif la loi fixe-t-elle désormais face à l’étalement urbain ?', 'mcq', '["Construire une ville nouvelle par région","Le « zéro artificialisation nette »","Interdire les maisons individuelles","Doubler les zones commerciales"]'::jsonb, 1, 'L’artificialisation des sols fait disparaître terres agricoles et espaces naturels : la loi veut la compenser entièrement.', 2),
    ('1875acbb-3244-507f-addd-70977c1ecb51'::uuid, 'histoire-geo', '3e', 'Les aires urbaines en France', 'Quel quartier d’affaires concentre des sièges sociaux près de Paris ?', 'mcq', '["La Part-Dieu","Euralille","La Défense","Montmartre"]'::jsonb, 2, 'La Défense illustre la métropolisation : les fonctions de commandement se concentrent dans les plus grandes villes.', 3),
    ('be55c5ee-4e80-565d-bd89-679a4aa63947'::uuid, 'histoire-geo', '3e', 'Les aires urbaines en France', 'Qu’appelle-t-on le mitage des campagnes ?', 'mcq', '["Le regroupement des fermes","Le reboisement des terres","La disparition des haies","La dispersion de constructions au milieu des espaces agricoles et naturels"]'::jsonb, 3, 'Le mitage accompagne la périurbanisation : maisons et lotissements grignotent la campagne par petits morceaux.', 4),
    ('e2792f5b-9039-54f5-a7a2-2a63091256b9'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France industrielle', 'Qu’est-ce qu’un pôle de compétitivité ?', 'mcq', '["Un regroupement d’industriels et de chercheurs labellisé par l’État","Une usine exonérée d’impôts","Un port spécialisé dans l’acier","Un centre commercial de périphérie"]'::jsonb, 0, 'L’État labellise ces pôles pour faire travailler ensemble entreprises et laboratoires sur l’innovation.', 1),
    ('b59add19-1d5a-5688-b34c-060d9b034447'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France industrielle', 'Quelle part de ses emplois l’industrie française a-t-elle perdue depuis les années 1970 ?', 'mcq', '["Un dixième","La moitié","La totalité","Un quart"]'::jsonb, 1, 'Concurrence mondiale, délocalisations et automatisation expliquent cette forte baisse.', 2),
    ('2714aa47-b126-54dc-8d1b-364906d9956c'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France industrielle', 'Quel technopôle de la Côte d’Azur est souvent cité en exemple ?', 'mcq', '["Fos-sur-Mer","La Défense","Sophia Antipolis","Euralille"]'::jsonb, 2, 'Sophia Antipolis associe entreprises de haute technologie, laboratoires et universités.', 3),
    ('9db36736-7306-58ce-92b3-1a769f097fbf'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France industrielle', 'Qu’est-ce qu’une délocalisation ?', 'mcq', '["La fermeture définitive d’une mine","Le passage d’une usine en centre-ville","La création d’un technopôle","Le transfert d’une production vers un pays à main-d’œuvre moins chère"]'::jsonb, 3, 'C’est l’une des causes de la désindustrialisation liées à la concurrence mondiale.', 4),
    ('4b32536e-2241-54bb-bd25-2c2821221503'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France agricole', 'Quelle part des actifs français travaille aujourd’hui dans l’agriculture ?', 'mcq', '["Environ 20 %","Environ 10 %","Environ 2 %","Environ 35 %"]'::jsonb, 2, 'Très peu d’actifs, mais une production énorme : c’est l’effet de la mécanisation et des intrants.', 1),
    ('fd906ae3-41ea-5b37-80ef-eae4cd298fe4'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France agricole', 'Que trouve-t-on en aval de l’agriculture ?', 'mcq', '["Les fabricants de tracteurs","Les industries agroalimentaires et la grande distribution","Les vendeurs de semences","Les fournisseurs d’engrais"]'::jsonb, 1, 'En amont se trouvent machines et intrants ; en aval, ceux qui transforment et vendent les produits.', 2),
    ('9b0c1251-9f0a-5ddc-ae32-490fcccbe5f1'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France agricole', 'Depuis quand la PAC verse-t-elle des aides aux agriculteurs ?', 'mcq', '["Depuis 1992","Depuis 2004","Depuis 1945","Depuis 1962"]'::jsonb, 3, 'Mise en place dès 1962, la PAC oriente les productions ; sans elle, beaucoup d’exploitations ne seraient pas rentables.', 3),
    ('f48fa2ef-8c28-58c8-be58-4bae9058af0c'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France agricole', 'Qu’est-ce qui caractérise l’agriculture biologique ?', 'mcq', '["Elle n’utilise pas de produits de synthèse","Elle est pratiquée uniquement en montagne","Elle repose sur l’élevage hors-sol","Elle est interdite à l’exportation"]'::jsonb, 0, 'Le bio progresse, avec les labels et les circuits courts, comme alternative au modèle productiviste.', 4),
    ('16f7a7cc-8cb4-5e77-9f4e-064962d1eab4'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France des services', 'Que désigne la tertiarisation de l’économie ?', 'mcq', '["Le retour à l’agriculture","La place croissante des services dans l’emploi","La délocalisation des usines","La hausse des exportations industrielles"]'::jsonb, 1, 'Près de 80 % des actifs travaillent aujourd’hui dans les services.', 1),
    ('37fb18ae-eddf-5350-a4d1-68747d02c6b1'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France des services', 'Quel type de tourisme illustrent les châteaux de la Loire ?', 'mcq', '["Le tourisme balnéaire","Le tourisme de montagne","Le tourisme urbain et culturel","Le tourisme vert"]'::jsonb, 2, 'Paris, les villes d’art et les châteaux attirent un tourisme tourné vers le patrimoine.', 2),
    ('1274a5da-f45b-56bb-af9d-453d13b03e66'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France des services', 'Qu’appelle-t-on le surtourisme ?', 'mcq', '["L’afflux excessif de visiteurs dans certains sites","Le tourisme d’affaires","Le tourisme hors saison","La hausse du prix des billets d’avion"]'::jsonb, 0, 'Trop de visiteurs usent les sites et gênent les habitants : le tourisme menace ce qui le rend attirant.', 3),
    ('78165daf-77d2-598a-a64f-eecece5b569f'::uuid, 'histoire-geo', '3e', 'Les espaces productifs : la France des services', 'Combien de salariés rassemble le quartier d’affaires de La Défense ?', 'mcq', '["Environ 5 000","Environ 20 000","Plus d’un million","Plus de 180 000"]'::jsonb, 3, 'La Défense concentre des services à haute valeur ajoutée : finance, conseil, sièges sociaux.', 4),
    ('3e6c4e56-8cbc-54f1-845a-f6e12b384d69'::uuid, 'histoire-geo', '3e', 'Les espaces de faible densité', 'Quelle part du territoire français les espaces de faible densité couvrent-ils ?', 'mcq', '["Environ 10 %","Environ 6 %","Près de la moitié","Plus de 90 %"]'::jsonb, 2, 'Près de la moitié du territoire, mais seulement 6 % de la population.', 1),
    ('dd29d37d-e328-56d6-80c2-be3fb7013925'::uuid, 'histoire-geo', '3e', 'Les espaces de faible densité', 'Qu’est-ce qui favorise l’installation de néoruraux depuis 2020 ?', 'mcq', '["La fermeture des écoles","Le télétravail","La hausse du prix de l’essence","La fin des parcs naturels"]'::jsonb, 1, 'Travailler à distance permet à des citadins de choisir le cadre de vie des campagnes.', 2),
    ('02d6901e-a44d-5120-8473-9014b9abcec5'::uuid, 'histoire-geo', '3e', 'Les espaces de faible densité', 'Quelle campagne gagne généralement des habitants ?', 'mcq', '["Une campagne proche d’une ville ou touristique","Une campagne isolée de moyenne montagne","Une campagne sans aucun service","Toutes les campagnes, sans exception"]'::jsonb, 0, 'Les espaces de faible densité ne suivent pas tous la même dynamique : la proximité d’une ville fait la différence.', 3),
    ('7b33dbaa-1c24-5756-8b85-5239270784c4'::uuid, 'histoire-geo', '3e', 'Les espaces de faible densité', 'Que désigne la déprise d’un espace rural ?', 'mcq', '["L’arrivée de nouveaux habitants","La création d’un parc naturel","L’agrandissement des exploitations","Le recul de sa population et de ses activités"]'::jsonb, 3, 'Après l’exode rural, la déprise laisse des villages vieillissants qui perdent habitants et services.', 4),
    ('c6de59c7-017b-541d-a6e9-caf309fb21d0'::uuid, 'histoire-geo', '3e', 'L’aménagement comme réponse aux inégalités territoriales', 'Quelle collectivité gère les collèges, les routes et l’action sociale ?', 'mcq', '["La région","Le département","La commune","L’Union européenne"]'::jsonb, 1, 'La région s’occupe des lycées et des transports, le département des collèges et de l’action sociale.', 1),
    ('b066708b-66c5-54d1-8638-db9853b01bb2'::uuid, 'histoire-geo', '3e', 'L’aménagement comme réponse aux inégalités territoriales', 'Quel organisme de l’État menait autrefois l’aménagement du territoire ?', 'mcq', '["L’ANRU","Le FEDER","La DATAR","L’INSEE"]'::jsonb, 2, 'La DATAR a porté l’aménagement pendant des décennies ; l’ANCT a pris sa suite.', 2),
    ('4c4461fa-3cf6-560a-9df5-14cb5c162577'::uuid, 'histoire-geo', '3e', 'L’aménagement comme réponse aux inégalités territoriales', 'À quoi servent les maisons France Services ?', 'mcq', '["À faciliter l’accès aux services publics","À vendre des produits locaux","À loger les étudiants","À former des médecins"]'::jsonb, 0, 'Elles rassemblent en un lieu des démarches administratives, souvent dans des territoires éloignés.', 3),
    ('15bc8e41-64fd-537c-af42-eb625ad863b4'::uuid, 'histoire-geo', '3e', 'L’aménagement comme réponse aux inégalités territoriales', 'Quel grand projet concerne les transports de la métropole parisienne ?', 'mcq', '["Action cœur de ville","France Très Haut Débit","Interreg","Le Grand Paris Express"]'::jsonb, 3, 'Ce réseau de métro automatique doit mieux relier les banlieues entre elles.', 4),
    ('049fa412-c38c-5c07-b16a-72165f558e95'::uuid, 'histoire-geo', '3e', 'La politique de la ville', 'Quel est le taux de pauvreté des quartiers prioritaires par rapport à la moyenne nationale ?', 'mcq', '["Trois fois plus élevé","Identique","Deux fois plus faible","Dix fois plus élevé"]'::jsonb, 0, 'Ce taux de pauvreté, avec le chômage des jeunes et l’enclavement, justifie une action ciblée.', 1),
    ('ca7f1631-e9bb-5804-b415-233af6a23e44'::uuid, 'histoire-geo', '3e', 'La politique de la ville', 'Quand la politique de la ville est-elle née ?', 'mcq', '["Au lendemain de 1945","Dans les années 1980","Dans les années 1950","Dans les années 2010"]'::jsonb, 1, 'Elle naît dans les années 1980, alors que les grands ensembles se dégradent.', 2),
    ('ca40cb69-9dce-5945-9f05-6753e3ca5995'::uuid, 'histoire-geo', '3e', 'La politique de la ville', 'Combien compte-t-on environ de quartiers prioritaires en France ?', 'mcq', '["Environ 150","Environ 15 000","Environ 1 500","Environ 50"]'::jsonb, 2, 'Environ 1 500 quartiers, où vivent près de 5 millions d’habitants.', 3),
    ('62893930-94c7-5156-93b3-47a99acf62e9'::uuid, 'histoire-geo', '3e', 'La politique de la ville', 'Que font beaucoup de communes face à l’obligation de la loi SRU ?', 'mcq', '["Elles démolissent leurs logements sociaux","Elles quittent leur intercommunalité","Elles construisent au-delà de 50 %","Elles préfèrent payer l’amende plutôt que construire"]'::jsonb, 3, 'C’est une limite de la politique de mixité : le logement social reste concentré dans les mêmes communes.', 4),
    ('941aa803-c6b6-5bbe-a507-e6ed4f6cd511'::uuid, 'histoire-geo', '3e', 'Les territoires ultra-marins français', 'Quel est le statut de la Polynésie française ?', 'mcq', '["Une collectivité d’outre-mer, plus autonome qu’un DROM","Un département et région d’outre-mer","Un État indépendant","Une terre sans population permanente"]'::jsonb, 0, 'Les COM disposent d’une plus grande autonomie que les DROM, qui sont des départements à part entière.', 1),
    ('aebd8a11-dcbd-561c-b914-f6e32da29376'::uuid, 'histoire-geo', '3e', 'Les territoires ultra-marins français', 'Combien d’habitants vivent dans les territoires ultramarins français ?', 'mcq', '["Environ 800 000","Environ 2,8 millions","Environ 10 millions","Environ 28 millions"]'::jsonb, 1, 'Répartis dans les trois océans, ils représentent environ 2,8 millions d’habitants.', 2),
    ('002ca7ae-6f60-54b3-8dfb-d16657028109'::uuid, 'histoire-geo', '3e', 'Les territoires ultra-marins français', 'Quel DROM n’est pas une île ?', 'mcq', '["La Martinique","Mayotte","La Guyane","La Réunion"]'::jsonb, 2, 'La Guyane, en Amérique du Sud, échappe à la contrainte de l’insularité.', 3),
    ('caa25476-a473-5e93-a5e1-f64499eb5126'::uuid, 'histoire-geo', '3e', 'Les territoires ultra-marins français', 'Quel territoire a un statut particulier, avec un titre propre dans la Constitution ?', 'mcq', '["La Guadeloupe","Saint-Pierre-et-Miquelon","Les TAAF","La Nouvelle-Calédonie"]'::jsonb, 3, 'La Nouvelle-Calédonie a un statut unique, distinct des DROM et des COM.', 4),
    ('de46ae3b-5e28-5e41-a0e8-e78b71baa452'::uuid, 'histoire-geo', '3e', 'L’Union européenne : un territoire en construction', 'Combien d’États utilisent aujourd’hui l’euro ?', 'mcq', '["27","12","20","6"]'::jsonb, 2, 'Tous les membres de l’Union n’ont pas adopté l’euro : la zone euro compte 20 États.', 1),
    ('69cc7c08-44a9-54e6-8c2e-87caaf100259'::uuid, 'histoire-geo', '3e', 'L’Union européenne : un territoire en construction', 'Où siège la Commission européenne ?', 'mcq', '["À Strasbourg","À Bruxelles","À Luxembourg","À Francfort"]'::jsonb, 1, 'La Commission siège à Bruxelles ; le Parlement européen, lui, siège à Strasbourg.', 2),
    ('60f2ee66-9266-58a5-b041-97c992ebddd0'::uuid, 'histoire-geo', '3e', 'L’Union européenne : un territoire en construction', 'Combien de pays rejoignent l’Union lors du grand élargissement de 2004 ?', 'mcq', '["Dix","Trois","Six","Vingt"]'::jsonb, 0, 'Dix pays, surtout d’Europe centrale et orientale, entrent d’un coup.', 3),
    ('3926e5ae-6eed-55e2-a97b-f23bf2b47ea0'::uuid, 'histoire-geo', '3e', 'L’Union européenne : un territoire en construction', 'Que permet la citoyenneté européenne ?', 'mcq', '["Voter aux élections présidentielles d’un autre pays","Ne plus payer d’impôts","Obtenir la nationalité de tous les États","Voter aux municipales et aux européennes dans son pays de résidence"]'::jsonb, 3, 'Créée par Maastricht, elle s’ajoute à la nationalité sans la remplacer.', 4),
    ('cf730def-705c-5f50-8591-f027adc77099'::uuid, 'histoire-geo', '3e', 'Les contrastes territoriaux à l’intérieur de l’Union européenne', 'Quel surnom donne-t-on parfois à la mégalopole européenne ?', 'mcq', '["L’arc latin","Le croissant d’or","La banane bleue","La diagonale du vide"]'::jsonb, 2, 'Cette dorsale de Londres à Milan concentre densités, places financières et grands ports.', 1),
    ('7e89840d-f8ea-57dd-b512-8d42e4a1ac5a'::uuid, 'histoire-geo', '3e', 'Les contrastes territoriaux à l’intérieur de l’Union européenne', 'Dans quelle périphérie se trouvent le Sud de l’Italie et la Grèce ?', 'mcq', '["La périphérie orientale","La périphérie méridionale","La périphérie ultrapériphérique","La périphérie nordique"]'::jsonb, 1, 'La périphérie méridionale est marquée par un chômage élevé.', 2),
    ('964002c6-6172-50f6-b1d2-a97723de5b84'::uuid, 'histoire-geo', '3e', 'Les contrastes territoriaux à l’intérieur de l’Union européenne', 'Quelle part du budget européen la politique de cohésion représente-t-elle environ ?', 'mcq', '["Un tiers","Un centième","La moitié","Les trois quarts"]'::jsonb, 0, 'Environ un tiers du budget va aux régions les moins riches, par le FEDER et le Fonds social européen.', 3),
    ('c59bf67c-e8d4-5ea7-a8ce-a0c69890027e'::uuid, 'histoire-geo', '3e', 'Les contrastes territoriaux à l’intérieur de l’Union européenne', 'Comment évoluent aujourd’hui les écarts de richesse dans l’Union ?', 'mcq', '["Ils disparaissent partout","Ils se creusent entre pays et se réduisent à l’intérieur","Ils restent strictement identiques","Ils se réduisent entre pays mais se creusent à l’intérieur de chaque pays"]'::jsonb, 3, 'Les pays de l’Est rattrapent leur retard, mais capitales et campagnes s’éloignent au sein d’un même pays.', 4),
    ('dee8f021-45a9-5516-8914-8c6dc53256ba'::uuid, 'histoire-geo', '3e', 'L’Europe dans le monde', 'Quelle part du PIB mondial l’Union européenne représente-t-elle environ ?', 'mcq', '["Environ 3 %","Environ 17 %","Environ 40 %","Environ 60 %"]'::jsonb, 1, 'Avec 450 millions d’habitants et environ 17 % du PIB mondial, l’Union est un géant économique.', 1),
    ('daa3afcb-8043-5e00-8c56-3087a3d392a3'::uuid, 'histoire-geo', '3e', 'L’Europe dans le monde', 'Sur quoi repose la défense des pays de l’Union ?', 'mcq', '["Sur une armée européenne unique","Sur les casques bleus de l’ONU","Sur l’OTAN et les armées nationales","Sur la seule dissuasion française"]'::jsonb, 2, 'L’Union n’a pas d’armée commune : c’est l’une des limites de sa puissance politique.', 2),
    ('495a90ba-7a31-5211-9b8a-f910e15f3de9'::uuid, 'histoire-geo', '3e', 'L’Europe dans le monde', 'Dans quels domaines l’Union cherche-t-elle une plus grande autonomie ?', 'mcq', '["Vaccins, semi-conducteurs, énergie, armement","Football, cinéma, mode, gastronomie","Agriculture, pêche, forêts, chasse","Monnaie, langue, religion, drapeau"]'::jsonb, 0, 'Les crises récentes ont montré sa dépendance énergétique, technologique et militaire.', 3),
    ('216862b6-541e-5143-8b5f-d57768566b79'::uuid, 'histoire-geo', '3e', 'L’Europe dans le monde', 'Quelle place occupe l’Union européenne pour l’aide publique au développement ?', 'mcq', '["Elle n’en verse aucune","Elle est cinquième","Elle est dernière du G20","Elle est le premier donateur mondial"]'::jsonb, 3, 'L’Union pèse aussi par son aide, sa diplomatie climatique et son attractivité touristique.', 4),
    ('8864803d-345a-5f4e-9bc1-812f9357f6c6'::uuid, 'histoire-geo', '3e', 'La France dans l’Union européenne', 'Quel rang économique la France occupe-t-elle dans l’Union européenne ?', 'mcq', '["La première","La deuxième","La cinquième","La dixième"]'::jsonb, 1, 'La France est la deuxième économie de l’Union, derrière l’Allemagne, et son pays le plus étendu.', 1),
    ('5ac35b96-9269-5eac-911c-6bccf3c19873'::uuid, 'histoire-geo', '3e', 'La France dans l’Union européenne', 'À quelle échelle la France agit-elle pour le commerce, le climat ou les normes ?', 'mcq', '["Seule, sans ses partenaires","Avec les seuls États-Unis","À 27, au sein de l’Union","Uniquement à l’ONU"]'::jsonb, 2, 'La France agit seule pour sa défense et son siège à l’ONU, à 27 pour le commerce, le climat et les normes.', 2),
    ('a59d0d48-ef83-587d-9c31-4d94fe90042e'::uuid, 'histoire-geo', '3e', 'La France dans l’Union européenne', 'Quel rang occupe le réseau diplomatique français dans le monde ?', 'mcq', '["Le deuxième","Le premier","Le dixième","Le vingtième"]'::jsonb, 0, 'Ambassades et consulats sur tous les continents font partie des atouts de la puissance française.', 3),
    ('12ee73ac-d55d-5c86-96d5-47f6e08466f4'::uuid, 'histoire-geo', '3e', 'La France dans l’Union européenne', 'Combien de locuteurs compte la francophonie ?', 'mcq', '["Environ 30 millions","Environ 67 millions","Plus d’un milliard","Plus de 320 millions"]'::jsonb, 3, 'La langue est un pilier du soft power français, avec les lycées et instituts culturels à l’étranger.', 4),
    ('98c8a832-d90c-5fc0-b95b-19b647aef73a'::uuid, 'maths', '3e', 'Puissances d’un nombre et écriture scientifique', 'Combien vaut 2⁻³ ?', 'mcq', '["8","−8","1/8","−6"]'::jsonb, 2, 'Un exposant négatif signifie « on divise » : 2⁻³ = 1 / 2³ = 1/8.', 1),
    ('c8cc39e4-960e-5ddb-a233-aa4a58cd7516'::uuid, 'maths', '3e', 'Puissances d’un nombre et écriture scientifique', 'Que vaut 10⁷ ÷ 10³ ?', 'mcq', '["10¹⁰","10⁴","10²¹","1⁴"]'::jsonb, 1, 'Pour diviser deux puissances de même base, on soustrait les exposants : 7 − 3 = 4.', 2),
    ('fae456c1-dfe3-594e-8990-4971538e96f5'::uuid, 'maths', '3e', 'Puissances d’un nombre et écriture scientifique', 'Comment simplifier 2³ × 5³ ?', 'mcq', '["10⁶","7³","10³","7⁶"]'::jsonb, 2, 'Les bases diffèrent : on regroupe (2 × 5)³ = 10³ = 1 000, les exposants ne s’additionnent pas.', 3),
    ('fd54b4e7-ef04-5302-9ed6-83c03f9b11dd'::uuid, 'maths', '3e', 'Puissances d’un nombre et écriture scientifique', 'Quel nombre est le plus grand : 3,2 × 10⁵ ou 9,8 × 10⁴ ?', 'mcq', '["9,8 × 10⁴, car 9,8 est plus grand que 3,2","3,2 × 10⁵, car son exposant est plus grand","Ils sont égaux","On ne peut pas les comparer"]'::jsonb, 1, 'En écriture scientifique, c’est d’abord l’exposant qui compte : 3,2 × 10⁵ = 320 000 et 9,8 × 10⁴ = 98 000.', 4),
    ('3bc5d13d-e401-52f1-83a9-b4a1562c3c4e'::uuid, 'maths', '3e', 'Nombres premiers et fractions irréductibles', 'Pourquoi 1 n’est-il pas un nombre premier ?', 'mcq', '["Parce qu’il est impair","Parce qu’il n’a qu’un seul diviseur","Parce qu’il divise tous les nombres","Parce qu’il est trop petit pour être décomposé"]'::jsonb, 1, 'Un nombre premier a exactement deux diviseurs, 1 et lui-même ; 1 n’en a qu’un seul.', 1),
    ('ad19bf73-9f91-5016-ae92-fac6ebc47cf4'::uuid, 'maths', '3e', 'Nombres premiers et fractions irréductibles', 'Lequel de ces nombres est premier ?', 'mcq', '["21","27","29","33"]'::jsonb, 2, '29 n’est divisible que par 1 et 29 ; 21 = 3 × 7, 27 = 3 × 9 et 33 = 3 × 11.', 2),
    ('4d5406ad-42ea-5892-81c3-d344c104732d'::uuid, 'maths', '3e', 'Nombres premiers et fractions irréductibles', 'Lequel de ces nombres est divisible par 9 ?', 'mcq', '["2 345","3 456","1 234","4 321"]'::jsonb, 1, 'La somme des chiffres de 3 456 vaut 3 + 4 + 5 + 6 = 18, qui est divisible par 9.', 3),
    ('197b5ac6-a1c5-5f8a-a3fb-6c61fbe268a1'::uuid, 'maths', '3e', 'Nombres premiers et fractions irréductibles', 'Quelle est la décomposition en facteurs premiers de 84 ?', 'mcq', '["2 × 42","2² × 21","4 × 3 × 7","2² × 3 × 7"]'::jsonb, 3, '84 = 2 × 42 = 2 × 2 × 21 = 2² × 3 × 7 : tous les facteurs doivent être premiers, ce que 42, 21 et 4 ne sont pas.', 4),
    ('5e0ff630-a193-592a-bfc8-5c367df699a1'::uuid, 'maths', '3e', 'Calcul littéral et équation', 'Que donne le développement de (x − 4)² ?', 'mcq', '["x² − 16","x² − 8x + 16","x² + 16","x² − 4x + 16"]'::jsonb, 1, 'On applique (a − b)² = a² − 2ab + b² : x² − 2 × x × 4 + 4² = x² − 8x + 16.', 1),
    ('e561366e-a71d-5768-be30-189dbadabd95'::uuid, 'maths', '3e', 'Calcul littéral et équation', 'Que donne le développement de (x + 2)(x + 5) ?', 'mcq', '["x² + 10","2x + 7","x² + 7x + 10","x² + 10x + 7"]'::jsonb, 2, 'Double distributivité : x × x + x × 5 + 2 × x + 2 × 5 = x² + 7x + 10.', 2),
    ('fccd546d-fa31-5b86-9418-2dc0c4fb264b'::uuid, 'maths', '3e', 'Calcul littéral et équation', 'Que devient 3x + 3x² une fois réduite ?', 'mcq', '["6x³","6x²","Elle reste 3x + 3x² : les termes ne sont pas de même nature","9x"]'::jsonb, 2, 'On ne regroupe que des termes de même nature : des x avec des x, des x² avec des x².', 3),
    ('cb60ba3b-a104-5058-a657-f2a1e01f8864'::uuid, 'maths', '3e', 'Calcul littéral et équation', 'Développer une expression, c’est transformer…', 'mcq', '["une somme en produit","une équation en inégalité","une fraction en nombre décimal","un produit en somme"]'::jsonb, 3, 'Développer transforme un produit en somme ; factoriser fait l’inverse.', 4),
    ('da0b7cf5-f155-55c3-b762-381ae6b28f31'::uuid, 'maths', '3e', 'Caractéristiques d’une série statistique', 'Quelle est la moyenne de la série 8, 12, 12, 16, 17 ?', 'mcq', '["12","13","14","65"]'::jsonb, 1, 'La somme vaut 65 et il y a 5 valeurs : 65 ÷ 5 = 13.', 1),
    ('ff8774ca-017f-51b7-86bc-7cf30dfea75b'::uuid, 'maths', '3e', 'Caractéristiques d’une série statistique', 'Quelle est la médiane de la série 3, 5, 9, 10 ?', 'mcq', '["9","6,75","7","5"]'::jsonb, 2, 'L’effectif est pair : on fait la moyenne des deux valeurs centrales, (5 + 9) ÷ 2 = 7. 6,75 est la moyenne de la série.', 2),
    ('06c3c998-5682-5bea-943e-50dfbe9f83e4'::uuid, 'maths', '3e', 'Caractéristiques d’une série statistique', 'Que vaut la somme des fréquences de toutes les valeurs d’une série ?', 'mcq', '["1, soit 100 %","L’effectif total","La moyenne de la série","Cela dépend de la série"]'::jsonb, 0, 'Chaque fréquence est une part de l’effectif total : toutes ensemble, elles font 1, soit 100 %.', 3),
    ('ef330947-4305-5305-b3f5-c7b8ad4cf8e7'::uuid, 'maths', '3e', 'Caractéristiques d’une série statistique', 'Dans une classe, 6 élèves ont 10 et 4 élèves ont 15. Quelle est la moyenne ?', 'mcq', '["12,5","25","11","12"]'::jsonb, 3, 'Moyenne pondérée : (6 × 10 + 4 × 15) ÷ 10 = 120 ÷ 10 = 12. 12,5 serait la moyenne des deux notes sans tenir compte des effectifs.', 4),
    ('aa9537e4-6cbc-51d2-b938-f5589dfa5346'::uuid, 'maths', '3e', 'Les probabilités', 'Que vaut la probabilité d’un événement certain ?', 'mcq', '["0","0,5","1","100"]'::jsonb, 2, 'Une probabilité est comprise entre 0 (impossible) et 1 (certain).', 1),
    ('49ec3613-43b2-50dd-a625-b59dcdc4d12c'::uuid, 'maths', '3e', 'Les probabilités', 'Dans un arbre de probabilités, que fait-on le long d’une branche ?', 'mcq', '["On additionne les probabilités","On multiplie les probabilités","On soustrait les probabilités","On divise les probabilités"]'::jsonb, 1, 'On multiplie le long d’une branche, puis on additionne les branches qui réalisent l’événement.', 2),
    ('540040e7-862c-57f6-af5b-a22cd70e651f'::uuid, 'maths', '3e', 'Les probabilités', 'On lance deux pièces équilibrées. Quelle est la probabilité d’obtenir deux fois pile ?', 'mcq', '["1/2","1/3","3/4","1/4"]'::jsonb, 3, 'Il y a quatre issues équiprobables (PP, PF, FP, FF) et une seule favorable : 1/2 × 1/2 = 1/4.', 3),
    ('f3964ef3-f205-5a71-80fa-bcf90421fd1c'::uuid, 'maths', '3e', 'Les probabilités', 'Quel est le chemin le plus court pour calculer la probabilité d’obtenir « au moins un 6 » en plusieurs lancers ?', 'mcq', '["Passer par l’événement contraire « aucun 6 »","Additionner la probabilité de chaque lancer","Multiplier 1/6 par le nombre de lancers","Tracer un diagramme en bâtons"]'::jsonb, 0, '« Au moins un » a pour contraire « aucun » : P(au moins un 6) = 1 − P(aucun 6).', 4),
    ('f20d1239-c006-5cc5-90e8-202d5e387416'::uuid, 'maths', '3e', 'Comprendre et utiliser la notion de fonction', 'Pour f(x) = 2x + 5, quel est l’antécédent de 17 ?', 'mcq', '["39","6","11","8,5"]'::jsonb, 1, 'On résout 2x + 5 = 17 : 2x = 12, donc x = 6. 39 serait l’image de 17.', 1),
    ('833067d1-8afd-5aa9-8bc3-5ddf9cdfff49'::uuid, 'maths', '3e', 'Comprendre et utiliser la notion de fonction', 'Dans un tableau de valeurs, que lit-on sur la ligne du bas ?', 'mcq', '["Les antécédents","Les coefficients","Les images","Les abscisses des points"]'::jsonb, 2, 'La ligne du haut porte les antécédents x, celle du bas leurs images f(x).', 2),
    ('1eb0e9a5-7f7a-527e-8007-3475194b80dd'::uuid, 'maths', '3e', 'Comprendre et utiliser la notion de fonction', 'Si f(3) = 7, que peut-on affirmer ?', 'mcq', '["7 est l’antécédent de 3","3 est un antécédent de 7","3 est l’image de 7","7 est un antécédent de 3"]'::jsonb, 1, '7 est l’image de 3, et 3 est UN antécédent de 7 : il peut y en avoir d’autres.', 3),
    ('e2f403e8-acf6-50aa-9c3e-aa5168c06ecf'::uuid, 'maths', '3e', 'Comprendre et utiliser la notion de fonction', 'Sur un graphique, comment lit-on un antécédent de 7 ?', 'mcq', '["On part de 7 en abscisse, on monte jusqu’à la courbe, on lit en ordonnée","On lit la pente de la courbe au point 7","On cherche le point de coordonnées (7 ; 7)","On part de 7 en ordonnée, on va horizontalement jusqu’à la courbe, on lit en abscisse"]'::jsonb, 3, 'Pour un antécédent, on part de l’axe des ordonnées ; la ligne horizontale peut couper la courbe en plusieurs points.', 4),
    ('4009c512-60d8-5b20-b59e-778515202cc6'::uuid, 'maths', '3e', 'Fonction linéaire et proportionnalité', 'Par quel nombre multiplie-t-on pour diminuer une valeur de 15 % ?', 'mcq', '["0,15","1,15","0,85","−15"]'::jsonb, 2, 'Diminuer de 15 %, c’est garder 85 % de la valeur : on multiplie par 1 − 0,15 = 0,85.', 1),
    ('f200c539-3ad4-5292-ab02-ce9d5697134e'::uuid, 'maths', '3e', 'Fonction linéaire et proportionnalité', 'f est linéaire et f(4) = 10. Que vaut son coefficient a ?', 'mcq', '["40","2,5","0,4","6"]'::jsonb, 1, 'a = f(x) ÷ x = 10 ÷ 4 = 2,5 : une seule valeur non nulle suffit à connaître toute la fonction.', 2),
    ('cf7a6504-6766-5092-bfe2-88984525efd0'::uuid, 'maths', '3e', 'Fonction linéaire et proportionnalité', 'Pour f(x) = 3x, que devient f(x) quand x double ?', 'mcq', '["Il double","Il augmente de 2","Il est multiplié par 3","Il est multiplié par 9"]'::jsonb, 0, 'C’est la proportionnalité : f(2x) = 3 × 2x = 2 × f(x).', 3),
    ('69f0bdd7-41b0-531f-8827-b3608a3b6819'::uuid, 'maths', '3e', 'Fonction linéaire et proportionnalité', 'Dans un tableau de valeurs, à quoi reconnaît-on une fonction linéaire ?', 'mcq', '["La différence f(x) − x est constante","Les images augmentent toujours","L’image de 0 vaut 1","Le quotient f(x) ÷ x est constant"]'::jsonb, 3, 'Ce quotient constant est le coefficient a ; une fonction linéaire peut aussi être décroissante si a est négatif.', 4),
    ('0e4191c5-decc-5313-93fd-c60cc4799f68'::uuid, 'maths', '3e', 'Les fonctions affines', 'Quelle est l’ordonnée à l’origine de f(x) = −2x + 7 ?', 'mcq', '["7","−2","2","−7"]'::jsonb, 0, 'L’ordonnée à l’origine est b = f(0) = 7 ; −2 est le coefficient directeur.', 1),
    ('907602a1-aef7-5e0c-9ce9-68db54ab5e75'::uuid, 'maths', '3e', 'Les fonctions affines', 'Laquelle de ces droites est la plus raide ?', 'mcq', '["y = 0,5x + 4","y = 2x","y = x − 5","y = −3x + 1"]'::jsonb, 3, 'La raideur dépend de la valeur absolue de a : 3 est la plus grande, même si cette droite descend.', 2),
    ('80872834-aca6-540c-97db-44fb6c48118f'::uuid, 'maths', '3e', 'Les fonctions affines', 'Un forfait de 15 € plus 2 € par heure : quelle fonction donne le prix pour x heures ?', 'mcq', '["f(x) = 15x + 2","f(x) = 17x","f(x) = 2x + 15","f(x) = 2x"]'::jsonb, 2, 'Le prix à l’heure est le coefficient a = 2, le forfait est l’ordonnée à l’origine b = 15.', 3),
    ('9d2be904-1a09-58cf-bfc5-846d61c76fe3'::uuid, 'maths', '3e', 'Les fonctions affines', 'Pour quelle valeur de x les offres f(x) = 2x + 15 et g(x) = 5x coûtent-elles le même prix ?', 'mcq', '["3","5","15","7,5"]'::jsonb, 1, 'On résout 2x + 15 = 5x : 15 = 3x, donc x = 5. C’est l’abscisse du point d’intersection des deux droites.', 4),
    ('bca39518-decc-55a5-98fd-b7b679369075'::uuid, 'maths', '3e', 'Sphère et boule', 'Une sphère a un diamètre de 10 cm. Quelle est son aire ?', 'mcq', '["400π cm²","40π cm²","25π cm²","100π cm²"]'::jsonb, 3, 'Le rayon vaut 10 ÷ 2 = 5 cm, donc A = 4 × π × 5² = 100π cm². 400π vient d’un diamètre pris pour un rayon.', 1),
    ('468b16d4-9bd3-574b-ad0b-4b9c5b183d1b'::uuid, 'maths', '3e', 'Sphère et boule', 'Quel est le volume d’une boule de rayon 3 cm ?', 'mcq', '["12π cm³","108π cm³","36π cm³, soit environ 113,1 cm³","9π cm³"]'::jsonb, 2, 'V = (4/3) × π × 3³ = (4/3) × 27π = 36π cm³.', 2),
    ('e07e40aa-6f8b-540f-8217-94d9f49beada'::uuid, 'maths', '3e', 'Sphère et boule', 'À combien équivaut 1 litre ?', 'mcq', '["1 cm³","1 dm³","1 m³","10 cm³"]'::jsonb, 1, '1 L = 1 dm³, et 1 mL = 1 cm³ : utile pour convertir le volume d’une boule en contenance.', 3),
    ('b9c7ab2f-d30f-5f42-87cb-ad1d8ed28185'::uuid, 'maths', '3e', 'Sphère et boule', 'Qu’appelle-t-on un grand cercle d’une sphère ?', 'mcq', '["La section par un plan passant par son centre","Toute section de la sphère par un plan","Le cercle de l’équateur uniquement","Un cercle de rayon supérieur à celui de la sphère"]'::jsonb, 0, 'Un plan passant par le centre coupe la sphère selon un cercle de même rayon qu’elle : c’est la plus grande section possible.', 4),
    ('acaba002-2956-5afd-b844-03cdada6c897'::uuid, 'maths', '3e', 'Sections planes de solides', 'Quelle section obtient-on en coupant une pyramide à base carrée par un plan parallèle à sa base ?', 'mcq', '["Un triangle","Un carré plus petit","Un rectangle non carré","Un disque"]'::jsonb, 1, 'La section parallèle à la base d’une pyramide a la même forme que la base : c’en est une réduction.', 1),
    ('c334d32f-0d15-5ef3-a3ba-352119d622c3'::uuid, 'maths', '3e', 'Sections planes de solides', 'Quelle section obtient-on en coupant un pavé droit par un plan parallèle à une arête ?', 'mcq', '["Un triangle","Un disque","Un rectangle","Un cercle"]'::jsonb, 2, 'Un plan parallèle à une arête d’un pavé droit le coupe selon un rectangle.', 2),
    ('495ef011-fcf8-5b5e-9f5e-df81b3a25e87'::uuid, 'maths', '3e', 'Sections planes de solides', 'Un cône est coupé parallèlement à sa base, à mi-hauteur depuis le sommet. Quelle fraction du volume du grand cône représente le petit cône ?', 'mcq', '["1/2","1/4","1/8","1/6"]'::jsonb, 2, 'Le rapport de réduction vaut k = 1/2 ; les volumes sont multipliés par k³ = 1/8.', 3),
    ('6d9033ef-db24-5785-9fe9-d855e8924dac'::uuid, 'maths', '3e', 'Sections planes de solides', 'Quel est le volume d’un cylindre de rayon 2 cm et de hauteur 5 cm ?', 'mcq', '["10π cm³","(20/3)π cm³","40π cm³","20π cm³"]'::jsonb, 3, 'V = π × R² × h = π × 4 × 5 = 20π cm³ ; le tiers ne concerne que le cône et la pyramide.', 4),
    ('33610c32-de06-5b37-820b-56b21b04f98b'::uuid, 'maths', '3e', 'L’homothétie', 'Avec quelle valeur de k une homothétie laisse-t-elle la figure immobile ?', 'mcq', '["0","1","−1","2"]'::jsonb, 1, 'Avec k = 1, chaque point est sa propre image ; k = −1 donne une symétrie centrale.', 1),
    ('271d44f9-d749-5efe-99ce-36cae37a9683'::uuid, 'maths', '3e', 'L’homothétie', 'Par l’homothétie de centre O et de rapport 2, OM = 3 cm. Combien vaut OM′ ?', 'mcq', '["1,5 cm","5 cm","6 cm","9 cm"]'::jsonb, 2, 'OM′ = 2 × OM = 6 cm, et M′ est sur la droite (OM), du même côté que M puisque k est positif.', 2),
    ('88e2b57d-47ea-55c6-ae69-26f139e72fb6'::uuid, 'maths', '3e', 'L’homothétie', 'Par combien une homothétie de rapport −2 multiplie-t-elle les longueurs ?', 'mcq', '["−2","4","1/2","2"]'::jsonb, 3, 'Les longueurs sont multipliées par la valeur absolue de k, soit 2 ; le signe moins indique seulement que l’image est de l’autre côté du centre.', 3),
    ('dfe4b0bd-2a11-5876-9607-25952c537d7b'::uuid, 'maths', '3e', 'L’homothétie', 'Quel théorème décrit la même configuration qu’une homothétie ?', 'mcq', '["Le théorème de Thalès","Le théorème de Pythagore","La trigonométrie","La règle du produit nul"]'::jsonb, 0, 'Une homothétie transforme une droite en une droite parallèle : c’est la configuration de Thalès.', 4),
    ('1e4624d5-0e98-5421-b770-f608a1d52c9d'::uuid, 'maths', '3e', 'Utiliser le théorème de Thalès', '(MN) et (BC) sont parallèles, avec AM = 3, AB = 6 et AC = 10. Combien vaut AN ?', 'mcq', '["20","2","5","7"]'::jsonb, 2, 'AM / AB = AN / AC donne 3 / 6 = AN / 10, donc AN = 10 × 3 ÷ 6 = 5.', 1),
    ('2dea4385-ff8e-5f50-938f-231e932362b9'::uuid, 'maths', '3e', 'Utiliser le théorème de Thalès', 'Pour utiliser la réciproque de Thalès, que faut-il vérifier en plus de l’égalité des quotients ?', 'mcq', '["Que le triangle est rectangle","Que les points sont alignés dans le même ordre","Que les segments ont la même longueur","Que l’angle en A mesure 90°"]'::jsonb, 1, 'Sans le même ordre des points sur les deux droites, l’égalité des quotients ne suffit pas à conclure au parallélisme.', 2),
    ('d31ee623-b143-5af6-bb52-e5df55445014'::uuid, 'maths', '3e', 'Utiliser le théorème de Thalès', 'Quel réflexe évite de mélanger les segments dans les quotients de Thalès ?', 'mcq', '["Écrire toujours petit sur grand, en partant du sommet commun","Mettre le côté parallèle au numérateur","Additionner les longueurs connues","Commencer par le plus grand segment"]'::jsonb, 0, 'Chaque quotient commence par le sommet commun A et compare le petit segment au grand : AM / AB, AN / AC, MN / BC.', 3),
    ('691a14cd-841b-53fb-b278-6b82c00b6360'::uuid, 'maths', '3e', 'Utiliser le théorème de Thalès', '(MN) et (BC) sont parallèles, avec AM = 4, AB = 10 et BC = 15. Combien vaut MN ?', 'mcq', '["37,5","9","11","6"]'::jsonb, 3, 'AM / AB = MN / BC donne 4 / 10 = MN / 15, donc MN = 15 × 4 ÷ 10 = 6.', 4),
    ('bdbeee68-4bef-5beb-b04b-2617252cffe2'::uuid, 'maths', '3e', 'Trigonométrie dans un triangle rectangle', 'Que vaut sin 30° ?', 'mcq', '["1","0,5","0","Environ 0,87"]'::jsonb, 1, 'sin 30° = 0,5, comme cos 60° : l’opposé à un angle de 30° mesure la moitié de l’hypoténuse.', 1),
    ('26c6ceaa-8437-536b-8b60-f5c50a66f839'::uuid, 'maths', '3e', 'Trigonométrie dans un triangle rectangle', 'Que vaut cos 60° ?', 'mcq', '["0","1","0,5","60"]'::jsonb, 2, 'cos 60° = 0,5 : c’est une des valeurs à connaître par cœur.', 2),
    ('c8944226-3978-5d67-8c25-6c88a9bc8aef'::uuid, 'maths', '3e', 'Trigonométrie dans un triangle rectangle', 'L’hypoténuse mesure 10 cm et un angle aigu mesure 30°. Combien mesure le côté opposé à cet angle ?', 'mcq', '["Environ 8,66 cm","20 cm","10 cm","5 cm"]'::jsonb, 3, 'sin 30° = opposé ÷ hypoténuse, donc opposé = 10 × 0,5 = 5 cm.', 3),
    ('41a8503f-9082-574f-be51-9dcca02ee5eb'::uuid, 'maths', '3e', 'Trigonométrie dans un triangle rectangle', 'Quel moyen mnémotechnique résume les trois formules de trigonométrie ?', 'mcq', '["CAH – SOH – TOA","SOS – TAC – CHA","COT – SAH – TOH","HYP – ADJ – OPP"]'::jsonb, 0, 'CAH : cos = adjacent / hypoténuse ; SOH : sin = opposé / hypoténuse ; TOA : tan = opposé / adjacent.', 4),
    ('a90ca94e-23fe-52a4-aa14-107fc7ad3e82'::uuid, 'maths', '3e', 'Triangles semblables', 'Deux triangles semblables ont un rapport k = 3. Un côté du petit mesure 4 cm : combien mesure son côté homologue dans le grand ?', 'mcq', '["7 cm","12 cm","36 cm","4/3 cm"]'::jsonb, 1, 'Les longueurs sont multipliées par k : 4 × 3 = 12 cm. 36 serait le coefficient des aires appliqué à tort.', 1),
    ('8fefdede-1b75-5882-ac4b-cc47c7627ad3'::uuid, 'maths', '3e', 'Triangles semblables', 'Un triangle a des angles de 50° et 70°, un autre des angles de 70° et 60°. Sont-ils semblables ?', 'mcq', '["Non, les deux angles donnés ne sont pas les mêmes","On ne peut pas savoir sans les côtés","Oui : tous deux ont pour angles 50°, 60° et 70°","Seulement s’ils ont la même aire"]'::jsonb, 2, 'Le troisième angle se déduit de la somme de 180° : 60° pour le premier, 50° pour le second. Deux angles égaux suffisent.', 2),
    ('23b8dd33-fb13-53d4-8aed-8fb246262f7a'::uuid, 'maths', '3e', 'Triangles semblables', 'Deux solides semblables ont un rapport k = 2. Par combien le volume est-il multiplié ?', 'mcq', '["2","4","6","8"]'::jsonb, 3, 'Les volumes sont multipliés par k³ = 2³ = 8, les aires par k² = 4.', 3),
    ('fdd7f3f1-cee5-5fb2-9080-ed07d9e441ea'::uuid, 'maths', '3e', 'Triangles semblables', 'Comment les triangles semblables permettent-ils de mesurer la hauteur d’un arbre ?', 'mcq', '["En comparant son ombre à celle d’un bâton de hauteur connue","En mesurant la circonférence de son tronc","En comptant ses branches","En calculant l’aire de son ombre"]'::jsonb, 0, 'L’arbre, le bâton et leurs ombres forment deux triangles semblables : le rapport des ombres donne le rapport des hauteurs.', 4),
    ('7c32a207-ddf7-55e7-b45c-f5bb2eb681a2'::uuid, 'physique-chimie', '3e', 'Mélanges et corps purs', 'Lequel de ces mélanges est hétérogène ?', 'mcq', '["L’eau salée","L’air","Le vinaigre","L’eau boueuse"]'::jsonb, 3, 'Dans l’eau boueuse, on distingue au moins deux constituants ; l’eau salée, l’air et le vinaigre sont homogènes.', 1),
    ('ff7064c6-597d-51fe-b7d5-8e700e8388f0'::uuid, 'physique-chimie', '3e', 'Mélanges et corps purs', 'Que laisse l’évaporation complète d’une eau minérale ?', 'mcq', '["Rien du tout","Un résidu : elle contient des substances dissoutes","Un gaz coloré","Un précipité bleu"]'::jsonb, 1, 'Une eau pure ne laisse aucun résidu ; l’eau minérale, qui est un mélange, laisse ses sels minéraux.', 2),
    ('4f88dd20-7e2d-5ffd-aebf-85c48ac5b890'::uuid, 'physique-chimie', '3e', 'Mélanges et corps purs', 'Comment un mélange se comporte-t-il pendant un changement d’état ?', 'mcq', '["Il change d’état sur un intervalle de températures","Sa température reste parfaitement constante","Sa masse double","Il ne change jamais d’état"]'::jsonb, 0, 'Seul un corps pur garde une température constante ; un mélange change d’état sur un intervalle.', 3),
    ('83655bf7-bc1a-5ea9-a500-0537687a6950'::uuid, 'physique-chimie', '3e', 'Mélanges et corps purs', 'Quelle technique consiste à laisser reposer un mélange pour que le plus dense tombe au fond ?', 'mcq', '["La filtration","La distillation","La décantation","L’évaporation"]'::jsonb, 2, 'La décantation sépare un mélange hétérogène ; la filtration vient souvent la compléter.', 4),
    ('17eb974c-2ef3-5f3c-8e87-b5b15bd8abcb'::uuid, 'physique-chimie', '3e', 'Les états de la matière', 'Quel état possède une forme propre ?', 'mcq', '["Le liquide","Le gaz","Le solide","Aucun"]'::jsonb, 2, 'Le solide a une forme et un volume propres ; le liquide prend la forme du récipient, le gaz occupe tout l’espace.', 1),
    ('a921a3f9-8540-5e90-b558-9675529bb0e4'::uuid, 'physique-chimie', '3e', 'Les états de la matière', 'Pourquoi dit-on qu’un gaz est expansible ?', 'mcq', '["Il se liquéfie facilement","Il remplit tout le volume qui lui est offert","Il est plus léger que l’air","Il ne se dilate que si on le chauffe"]'::jsonb, 1, 'Ses molécules, très éloignées et très agitées, se répartissent dans tout l’espace disponible.', 2),
    ('10c6b54b-b154-5f4d-a078-c19395eca002'::uuid, 'physique-chimie', '3e', 'Les états de la matière', 'Quelle est la forme de la surface d’un liquide au repos ?', 'mcq', '["Plane et horizontale","Bombée vers le haut","Inclinée","Irrégulière"]'::jsonb, 0, 'N’ayant pas de forme propre, le liquide au repos présente une surface plane et horizontale.', 3),
    ('3e74b2bb-3f61-5a42-8131-8aef20b5d6c8'::uuid, 'physique-chimie', '3e', 'Les états de la matière', 'À quelle température correspond le zéro absolu ?', 'mcq', '["0 °C","−100 °C","−373 °C","−273 °C"]'::jsonb, 3, 'À −273 °C, l’agitation des molécules cesserait : c’est le zéro de l’échelle des kelvins.', 4),
    ('e4e9a3a6-0ee3-58e1-a8cf-ba562411ec17'::uuid, 'physique-chimie', '3e', 'Les changements d’état de l’eau', 'Comment appelle-t-on la vaporisation qui se produit en surface, à toute température ?', 'mcq', '["L’ébullition","L’évaporation","La sublimation","La liquéfaction"]'::jsonb, 1, 'L’évaporation se fait en surface ; l’ébullition se produit dans toute la masse, à température fixe.', 1),
    ('a20591c9-e0fc-55f0-8512-349d7e752103'::uuid, 'physique-chimie', '3e', 'Les changements d’état de l’eau', 'Quel changement d’état forme le givre ?', 'mcq', '["La solidification","La fusion","La condensation solide","La liquéfaction"]'::jsonb, 2, 'La vapeur d’eau de l’air passe directement à l’état solide : c’est une condensation solide.', 2),
    ('47e747b7-9b34-5526-95bc-3e1323233a5b'::uuid, 'physique-chimie', '3e', 'Les changements d’état de l’eau', 'On continue de chauffer de l’eau pure qui bout, sous pression normale. Que fait sa température ?', 'mcq', '["Elle monte jusqu’à 120 °C","Elle baisse","Elle double","Elle reste à 100 °C : l’eau se vaporise plus vite"]'::jsonb, 3, 'Toute l’énergie reçue sert au changement d’état : la température forme un palier.', 3),
    ('43cf1e5b-ee84-5b82-8893-3a687bb76a86'::uuid, 'physique-chimie', '3e', 'Les changements d’état de l’eau', 'Quel changement d’état produit la rosée du matin ?', 'mcq', '["La liquéfaction","La vaporisation","La sublimation","La solidification"]'::jsonb, 0, 'La vapeur d’eau de l’air se liquéfie au contact des surfaces froides, comme la buée sur une vitre.', 4),
    ('039ecdf7-5901-58e2-ae31-a49f9f227997'::uuid, 'physique-chimie', '3e', 'La miscibilité et la solubilité', 'Lequel de ces couples de liquides est miscible ?', 'mcq', '["Eau et huile","Eau et cyclohexane","Eau et alcool","Huile et vinaigre"]'::jsonb, 2, 'L’eau et l’alcool forment un mélange homogène ; les trois autres couples se séparent en deux phases.', 1),
    ('02f792e6-664e-5d89-8e3c-21b3e1f4b569'::uuid, 'physique-chimie', '3e', 'La miscibilité et la solubilité', 'On dissout 10 g de sel dans 200 g d’eau. Quelle est la masse de la solution ?', 'mcq', '["200 g","210 g","190 g","20 g"]'::jsonb, 1, 'Masse de la solution = masse du solvant + masse du soluté : 200 + 10 = 210 g. La masse se conserve.', 2),
    ('e1fa1e56-e4c7-51fb-ade4-288a66442b37'::uuid, 'physique-chimie', '3e', 'La miscibilité et la solubilité', 'En quelle unité s’exprime la solubilité ?', 'mcq', '["En °C","En mL","En kg","En g/L"]'::jsonb, 3, 'C’est la masse maximale de soluté dissoute dans un litre de solvant, à une température donnée.', 3),
    ('910448c3-3dcc-5462-b6b3-ede380df0c14'::uuid, 'physique-chimie', '3e', 'La miscibilité et la solubilité', 'Pourquoi une eau réchauffée est-elle moins favorable à la vie aquatique ?', 'mcq', '["Elle contient moins de dioxygène dissous","Elle contient plus de sel","Elle devient forcément acide","Elle ne peut plus dissoudre de gaz du tout"]'::jsonb, 0, 'La solubilité d’un gaz diminue quand la température augmente : l’eau chaude retient moins de dioxygène.', 4),
    ('7f8b3373-5e4f-53f8-bff7-64e38cea61bb'::uuid, 'physique-chimie', '3e', 'La composition de l’air', 'Quelle est la pression atmosphérique au niveau de la mer ?', 'mcq', '["Environ 100 hPa","Environ 10 000 hPa","Environ 1 013 hPa","Environ 1 hPa"]'::jsonb, 2, 'Elle vaut environ 1 013 hPa au niveau de la mer et diminue avec l’altitude.', 1),
    ('f989a59f-e15a-5fa9-82f5-5e482271962e'::uuid, 'physique-chimie', '3e', 'La composition de l’air', 'Quel instrument mesure la pression atmosphérique ?', 'mcq', '["Le thermomètre","Le baromètre","L’hygromètre","L’anémomètre"]'::jsonb, 1, 'Le baromètre mesure la pression ; le thermomètre la température, l’anémomètre la vitesse du vent.', 2),
    ('c3d93933-156e-5e0b-843a-54a53dcce347'::uuid, 'physique-chimie', '3e', 'La composition de l’air', 'Comment prouver que l’air a une masse ?', 'mcq', '["En mesurant son volume","En regardant un ballon s’envoler","En chauffant de l’air","En pesant un ballon gonflé, puis dégonflé"]'::jsonb, 3, 'La différence entre les deux pesées est la masse de l’air sorti : environ 1,2 g par litre.', 3),
    ('cf7eb5ff-4b9a-520b-880b-43316bf04283'::uuid, 'physique-chimie', '3e', 'La composition de l’air', 'Quel gaz de l’air augmente à cause de la combustion des énergies fossiles ?', 'mcq', '["Le dioxyde de carbone","Le diazote","L’argon","Le dioxygène"]'::jsonb, 0, 'Le CO₂, gaz à effet de serre, augmente : la composition de l’air n’est pas fixe à l’échelle du siècle.', 4),
    ('c5084337-15a0-5011-b7a9-839f1ad869c3'::uuid, 'physique-chimie', '3e', 'La masse volumique', 'Pourquoi l’huile surnage-t-elle sur l’eau ?', 'mcq', '["Elle est plus visqueuse","Sa masse volumique, environ 0,92 g/cm³, est inférieure à celle de l’eau","Elle est plus chaude","Sa masse est toujours plus faible"]'::jsonb, 1, 'Un liquide flotte sur un autre s’il est moins dense, quelle que soit la quantité versée.', 1),
    ('966be5d9-d76f-5fd3-a6b2-979bef7e32b5'::uuid, 'physique-chimie', '3e', 'La masse volumique', 'Un objet de 60 g occupe 20 cm³. Quelle est sa masse volumique ?', 'mcq', '["1 200 g/cm³","0,33 g/cm³","3 g/cm³","80 g/cm³"]'::jsonb, 2, 'ρ = m ÷ V = 60 ÷ 20 = 3 g/cm³.', 2),
    ('cb652853-053e-50d2-89a0-2260a184dfea'::uuid, 'physique-chimie', '3e', 'La masse volumique', 'Un objet de masse volumique 2,7 g/cm³ est plongé dans l’eau. Que fait-il ?', 'mcq', '["Il coule","Il flotte","Il reste entre deux eaux","Il se dissout"]'::jsonb, 0, 'Sa masse volumique est supérieure à celle de l’eau (1 g/cm³) : il coule.', 3),
    ('175d0803-0fb4-5546-af19-8c26ca9d1192'::uuid, 'physique-chimie', '3e', 'La masse volumique', 'Quelle est la masse d’un litre d’eau ?', 'mcq', '["1 g","10 g","100 g","1 kg"]'::jsonb, 3, '1 L = 1 000 cm³, et chaque cm³ d’eau a une masse de 1 g : 1 000 g, soit 1 kg.', 4),
    ('94255aca-2c86-59c3-9a4f-5573be5546c6'::uuid, 'physique-chimie', '3e', 'Les atomes et la transformation chimique', 'Lequel de ces signes révèle une transformation chimique ?', 'mcq', '["La glace qui fond","L’apparition d’un précipité","Le sucre qui se dissout","L’eau qui bout"]'::jsonb, 1, 'Un précipité est un nouveau solide : de nouvelles espèces sont apparues. Les trois autres sont des transformations physiques.', 1),
    ('bd27551a-d6aa-510a-90fe-367424635aaf'::uuid, 'physique-chimie', '3e', 'Les atomes et la transformation chimique', 'Qui a énoncé « rien ne se perd, rien ne se crée, tout se transforme » ?', 'mcq', '["Mendeleïev","Pasteur","Lavoisier","Newton"]'::jsonb, 2, 'La loi de Lavoisier traduit la conservation des atomes et de la masse au cours d’une transformation chimique.', 2),
    ('3f31e708-a062-5170-8b8d-ee73dc1b6306'::uuid, 'physique-chimie', '3e', 'Les atomes et la transformation chimique', '12 g de carbone brûlent entièrement avec 32 g de dioxygène. Quelle masse de dioxyde de carbone se forme ?', 'mcq', '["20 g","32 g","12 g","44 g"]'::jsonb, 3, 'La masse se conserve : 12 + 32 = 44 g de dioxyde de carbone.', 3),
    ('0194f58e-b3a7-567d-9ea6-b1e7df062204'::uuid, 'physique-chimie', '3e', 'Les atomes et la transformation chimique', 'Dans CH₄ + 2 O₂ → CO₂ + 2 H₂O, combien d’atomes d’oxygène compte-t-on de chaque côté ?', 'mcq', '["4","2","3","6"]'::jsonb, 0, 'À gauche, 2 × 2 = 4 ; à droite, 2 dans CO₂ et 2 dans les deux H₂O : 4. L’équation est ajustée.', 4),
    ('56f70a50-226b-5863-9775-a2b9cf5d5eb7'::uuid, 'physique-chimie', '3e', 'Les tests caractéristiques des espèces chimiques', 'Quel précipité obtient-on en ajoutant de la soude à une solution d’ions fer II ?', 'mcq', '["Un précipité bleu","Un précipité rouille","Un précipité vert","Un précipité blanc"]'::jsonb, 2, 'Le fer II donne un précipité vert, le fer III un précipité rouille : ne pas confondre les deux.', 1),
    ('29e20569-0c44-586e-844a-e7dcf85cbd58'::uuid, 'physique-chimie', '3e', 'Les tests caractéristiques des espèces chimiques', 'Que devient le précipité blanc obtenu avec le nitrate d’argent et les ions chlorure ?', 'mcq', '["Il devient bleu","Il noircit à la lumière","Il se dissout","Il devient rouille"]'::jsonb, 1, 'Ce noircissement à la lumière confirme la présence d’ions chlorure.', 2),
    ('d8fe2e1a-ad71-5bf5-92fa-cc8da83d781b'::uuid, 'physique-chimie', '3e', 'Les tests caractéristiques des espèces chimiques', 'Quelles protections faut-il pour manipuler le nitrate d’argent ?', 'mcq', '["Aucune","Un masque seulement","Des gants seulement","Lunettes, gants et blouse"]'::jsonb, 3, 'Il est corrosif et tache durablement la peau et les vêtements.', 3),
    ('448b3c71-8e50-5009-9761-00e2e8b34b05'::uuid, 'physique-chimie', '3e', 'Les tests caractéristiques des espèces chimiques', 'Quelle est la première étape d’une identification d’ion ?', 'mcq', '["Prélever un peu de solution dans un tube à essai","Ajouter le réactif directement dans le flacon","Conclure en nommant l’espèce","Chauffer la solution"]'::jsonb, 0, 'On prélève, on ajoute le réactif, on observe, puis on conclut en nommant l’espèce identifiée.', 4),
    ('5cfa218f-edca-5db4-a3f8-3337d0ad5c70'::uuid, 'physique-chimie', '3e', 'Les ions', 'L’ion hydroxyde OH⁻ est…', 'mcq', '["un anion : un groupe d’atomes qui a gagné un électron","un cation qui a perdu un électron","un atome neutre","un ion hydrogène"]'::jsonb, 0, 'Un ion peut être formé de plusieurs atomes ; sa charge négative indique qu’il a gagné un électron.', 1),
    ('a5dde78c-d6e4-5d2b-8283-9211f21a41a2'::uuid, 'physique-chimie', '3e', 'Les ions', 'Comment appelle-t-on un ion chargé négativement ?', 'mcq', '["Un cation","Un anion","Un neutron","Un proton"]'::jsonb, 1, 'L’anion a gagné des électrons ; le cation en a perdu.', 2),
    ('6c8198e4-4fd1-5d66-a9ee-4d439d891e6a'::uuid, 'physique-chimie', '3e', 'Les ions', 'Qu’est-ce qui transporte le courant électrique dans un métal ?', 'mcq', '["Les ions","Les protons","Les électrons libres","Les neutrons"]'::jsonb, 2, 'Dans un métal, ce sont les électrons libres ; dans une solution, ce sont les ions mobiles.', 3),
    ('55347b18-af69-5f91-a6a6-eacdee11aad6'::uuid, 'physique-chimie', '3e', 'Les ions', 'Pourquoi le noyau ne change-t-il pas quand un atome devient un ion ?', 'mcq', '["Parce qu’il n’a pas de charge","Parce qu’il est vide","Parce qu’il est trop léger","Parce que sinon ce ne serait plus le même élément chimique"]'::jsonb, 3, 'L’élément est défini par son nombre de protons : un ion ne gagne ou ne perd que des électrons.', 4),
    ('e006960c-131c-5827-8a9d-4845adfee009'::uuid, 'physique-chimie', '3e', 'Le pH ou potentiel hydrogène', 'Quel est le pH approximatif du vinaigre ?', 'mcq', '["3","7","9","13"]'::jsonb, 0, 'Le vinaigre est acide, avec un pH d’environ 3 ; l’eau savonneuse est vers 9, le déboucheur vers 13.', 1),
    ('bf0c1808-49f9-5c04-b9a6-774d3841db23'::uuid, 'physique-chimie', '3e', 'Le pH ou potentiel hydrogène', 'Quels ions sont majoritaires dans une solution basique ?', 'mcq', '["Les ions hydrogène H⁺","Les ions hydroxyde OH⁻","Les ions chlorure Cl⁻","Les ions sodium Na⁺"]'::jsonb, 1, 'Une solution basique contient plus d’ions OH⁻ que d’ions H⁺.', 2),
    ('550b9faf-b847-54c7-a841-2c7bd9856915'::uuid, 'physique-chimie', '3e', 'Le pH ou potentiel hydrogène', 'Quelle est la précision du papier pH ?', 'mcq', '["Au centième","Au dixième","Environ une unité","Aucune erreur possible"]'::jsonb, 2, 'Le papier pH donne une valeur à une unité près ; le pH-mètre étalonné mesure au dixième.', 3),
    ('8af649e6-35c8-514e-beb4-bf19cbdb5b8e'::uuid, 'physique-chimie', '3e', 'Le pH ou potentiel hydrogène', 'Que devient le pH d’une solution basique qu’on dilue ?', 'mcq', '["Il monte vers 14","Il ne change pas","Il passe sous 7","Il descend vers 7"]'::jsonb, 3, 'La dilution rapproche le pH de 7 sans jamais le dépasser : une solution basique reste basique.', 4),
    ('8d3d88d8-f574-56de-80e9-fe8a1ee33d69'::uuid, 'physique-chimie', '3e', 'Les réactions aux solutions acides', 'Quelle équation traduit l’action de l’acide chlorhydrique sur le fer ?', 'mcq', '["Fe + 2 H⁺ → Fe²⁺ + H₂","Fe + H⁺ → Fe³⁺ + H₂","Fe + 2 Cl⁻ → Fe²⁺ + Cl₂","Fe + O₂ → Fe²⁺ + H₂O"]'::jsonb, 0, 'Les ions H⁺ réagissent avec le fer : il se forme des ions fer II et du dihydrogène.', 1),
    ('de8a5a7a-4120-5fe4-a810-1e1b764bb876'::uuid, 'physique-chimie', '3e', 'Les réactions aux solutions acides', 'Comment appelle-t-on l’ion chlorure, qui ne participe pas à la réaction du fer avec l’acide ?', 'mcq', '["Un réactif limitant","Un ion spectateur","Un catalyseur","Un précipité"]'::jsonb, 1, 'Présent dans la solution avant et après, il ne réagit pas : c’est un ion spectateur.', 2),
    ('9a4475e0-9542-509a-8f20-0e22e29396cf'::uuid, 'physique-chimie', '3e', 'Les réactions aux solutions acides', 'Comment confirme-t-on la présence d’ions fer II dans la solution obtenue ?', 'mcq', '["Avec l’eau de chaux","Avec une bûchette incandescente","Avec la soude, qui donne un précipité vert","Avec le nitrate d’argent"]'::jsonb, 2, 'Le précipité vert à la soude identifie les ions fer II.', 3),
    ('49ae2e8c-df37-52bc-afc9-0e67fecaca19'::uuid, 'physique-chimie', '3e', 'Les réactions aux solutions acides', 'Quel métal réagit avec l’acide chlorhydrique en dégageant du dihydrogène ?', 'mcq', '["Le cuivre","L’or","L’argent","Le zinc"]'::jsonb, 3, 'Le zinc, l’aluminium et le magnésium sont attaqués ; le cuivre, l’or et l’argent ne le sont pas.', 4),
    ('ee0cbb03-f4c0-509f-804a-ba79332274b6'::uuid, 'physique-chimie', '3e', 'L’Univers et le Système solaire', 'Quelle est l’étoile la plus proche de nous après le Soleil ?', 'mcq', '["Sirius","Proxima du Centaure","L’étoile Polaire","Bételgeuse"]'::jsonb, 1, 'Proxima du Centaure se trouve à environ 4,2 années-lumière.', 1),
    ('9a08651f-4533-5cc9-abd4-40f16f4456d7'::uuid, 'physique-chimie', '3e', 'L’Univers et le Système solaire', 'À combien de kilomètres correspond environ une année-lumière ?', 'mcq', '["300 000 km","1,5 × 10⁸ km","9,5 × 10¹² km","9,5 × 10⁶ km"]'::jsonb, 2, 'La lumière parcourt environ 300 000 km chaque seconde pendant un an : près de 9 500 milliards de km.', 2),
    ('b6febae1-c2a9-5e78-97b0-07722c8c812f'::uuid, 'physique-chimie', '3e', 'L’Univers et le Système solaire', 'Quelles sont les quatre planètes gazeuses du Système solaire ?', 'mcq', '["Mercure, Vénus, la Terre, Mars","La Lune, Mars, Vénus, Pluton","Le Soleil, Jupiter, Mars, Saturne","Jupiter, Saturne, Uranus, Neptune"]'::jsonb, 3, 'Les quatre planètes proches du Soleil sont telluriques, les quatre plus lointaines gazeuses.', 3),
    ('b1ab0ba7-35e7-5ae6-a971-b55ac56cd994'::uuid, 'physique-chimie', '3e', 'L’Univers et le Système solaire', 'Quelle distance la lumière parcourt-elle dans le vide en 10 secondes ?', 'mcq', '["3 000 000 km","30 000 km","300 000 km","3 × 10⁹ km"]'::jsonb, 0, 'd = v × t = 300 000 km/s × 10 s = 3 000 000 km.', 4),
    ('a9abd8b6-a7fe-5760-9eee-af25bfbf664f'::uuid, 'physique-chimie', '3e', 'La continuité de la matière dans l’Univers', 'Quel est l’ordre de grandeur de la taille d’une cellule ?', 'mcq', '["10⁻¹⁰ m","10⁻⁵ m","1 m","10⁷ m"]'::jsonb, 1, 'Une cellule mesure environ 10⁻⁵ m ; 10⁻¹⁰ m est la taille d’un atome, 10⁷ m celle d’une planète.', 1),
    ('044e98a1-b349-57b5-908c-5fb36e2d68fe'::uuid, 'physique-chimie', '3e', 'La continuité de la matière dans l’Univers', 'Qu’est-ce qu’une molécule ?', 'mcq', '["Un atome chargé","Un noyau d’atome","Un assemblage d’atomes","Une particule de lumière"]'::jsonb, 2, 'H₂O, CO₂ ou O₂ sont des molécules ; un atome chargé est un ion.', 2),
    ('73150f08-f118-5eab-803c-334b2cbe6730'::uuid, 'physique-chimie', '3e', 'La continuité de la matière dans l’Univers', 'Comment le carbone, l’oxygène et le fer fabriqués dans les étoiles se sont-ils dispersés dans l’espace ?', 'mcq', '["Par le vent terrestre","Par les comètes uniquement","Ils ne se sont jamais dispersés","Lors de l’explosion de ces étoiles"]'::jsonb, 3, 'En explosant, les étoiles ont dispersé leurs éléments : nos atomes viennent d’étoiles mortes.', 3),
    ('22bfd32e-3cf8-5297-bbcc-c0efcd93f2b0'::uuid, 'physique-chimie', '3e', 'La continuité de la matière dans l’Univers', 'Quand l’hydrogène et l’hélium se sont-ils formés ?', 'mcq', '["Peu après la naissance de l’Univers","Au cœur de la Terre","Dans les volcans","Lors de la formation du Système solaire"]'::jsonb, 0, 'Ces deux éléments, les plus abondants de l’Univers, datent de ses tout premiers instants.', 4),
    ('34859333-7d5c-5302-93b5-7246799c71a2'::uuid, 'physique-chimie', '3e', 'Les constituants de l’atome', 'Quelle est la charge d’un électron ?', 'mcq', '["Positive","Nulle","Négative","Variable"]'::jsonb, 2, 'L’électron est négatif, le proton positif, le neutron neutre.', 1),
    ('0759fb95-ba95-5782-ad32-6ec76e57cf56'::uuid, 'physique-chimie', '3e', 'Les constituants de l’atome', 'Combien de protons le noyau d’un atome de carbone contient-il ?', 'mcq', '["1","6","8","12"]'::jsonb, 1, 'Le carbone a 6 protons ; l’hydrogène en a 1, l’oxygène 8.', 2),
    ('668e055d-0edd-5474-90ce-493ec5893d97'::uuid, 'physique-chimie', '3e', 'Les constituants de l’atome', 'Que désigne le symbole Co ?', 'mcq', '["Le monoxyde de carbone","Le cuivre","Le carbone","Le cobalt"]'::jsonb, 3, 'La casse compte : Co est le cobalt, CO la molécule de monoxyde de carbone, Cu le cuivre.', 3),
    ('7b329aaf-d0b2-5e11-bb4e-c0d412a11163'::uuid, 'physique-chimie', '3e', 'Les constituants de l’atome', 'Comment la masse d’un électron se compare-t-elle à celle d’un proton ?', 'mcq', '["Elle est environ 2 000 fois plus petite","Elle est égale","Elle est deux fois plus grande","Elle est nulle"]'::jsonb, 0, 'C’est pourquoi presque toute la masse de l’atome est concentrée dans son noyau.', 4),
    ('4d738201-b5f7-5303-a36d-b0a9dd513dae'::uuid, 'physique-chimie', '3e', 'Les mouvements', 'À combien de m/s correspond une vitesse de 36 km/h ?', 'mcq', '["3,6 m/s","10 m/s","129,6 m/s","100 m/s"]'::jsonb, 1, 'Pour passer des km/h aux m/s, on divise par 3,6 : 36 ÷ 3,6 = 10 m/s.', 1),
    ('60e59463-6059-5553-877c-f6a498166694'::uuid, 'physique-chimie', '3e', 'Les mouvements', 'Comment qualifie-t-on une trajectoire en forme de cercle ?', 'mcq', '["Rectiligne","Curviligne quelconque","Circulaire","Uniforme"]'::jsonb, 2, 'Une trajectoire est rectiligne, circulaire ou curviligne ; « uniforme » qualifie la vitesse, pas la trajectoire.', 2),
    ('df8408bb-9f8e-5234-893b-4cfbb1a73351'::uuid, 'physique-chimie', '3e', 'Les mouvements', 'Un cycliste parcourt 30 km en 2 h. Quelle est sa vitesse moyenne ?', 'mcq', '["60 km/h","32 km/h","28 km/h","15 km/h"]'::jsonb, 3, 'v = d ÷ t = 30 ÷ 2 = 15 km/h.', 3),
    ('d498aadc-60b1-55e6-8b44-aac4b87dc3ac'::uuid, 'physique-chimie', '3e', 'Les mouvements', 'Qu’est-ce qu’un mouvement rectiligne uniforme ?', 'mcq', '["Une trajectoire droite et une vitesse constante","Une trajectoire circulaire à vitesse constante","Une trajectoire droite avec une vitesse qui augmente","Un objet immobile"]'::jsonb, 0, 'Il cumule les deux conditions : c’est le seul mouvement où l’objet ne subit aucune force résultante.', 4),
    ('6d831b8d-b1a8-5ddc-b4d6-5e7a2ee7ded9'::uuid, 'physique-chimie', '3e', 'Interactions et forces', 'Quel instrument mesure la valeur d’une force ?', 'mcq', '["La balance","Le dynamomètre","Le thermomètre","Le voltmètre"]'::jsonb, 1, 'Le dynamomètre mesure une force en newtons ; la balance mesure une masse.', 1),
    ('01ab397a-888f-5350-a5b7-d453810bf8a4'::uuid, 'physique-chimie', '3e', 'Interactions et forces', 'Lequel de ces exemples est une interaction de contact ?', 'mcq', '["La gravitation","Le magnétisme","Les frottements de l’air","L’électrostatique"]'::jsonb, 2, 'Les frottements exigent un contact ; gravitation, magnétisme et électrostatique agissent à distance.', 2),
    ('084727ba-cf43-5639-9f4e-2a424dda303d'::uuid, 'physique-chimie', '3e', 'Interactions et forces', 'Sur la flèche qui représente une force, que traduit sa longueur ?', 'mcq', '["Son sens","Son point d’application","Sa direction","Sa valeur"]'::jsonb, 3, 'La longueur de la flèche est proportionnelle à la valeur de la force, en newtons.', 3),
    ('297ebb80-fedc-57ac-a3dc-ff4273a3b37e'::uuid, 'physique-chimie', '3e', 'Interactions et forces', 'Un nageur pousse l’eau vers l’arrière. Que fait l’eau ?', 'mcq', '["Elle le pousse vers l’avant","Elle n’exerce aucune force","Elle le tire vers le fond","Elle le pousse vers l’arrière"]'::jsonb, 0, 'C’est le principe des actions réciproques : même direction, même valeur, sens opposé.', 4),
    ('a34f8a57-401e-5031-af1e-8f40f1b5ba40'::uuid, 'physique-chimie', '3e', 'Poids et gravitation', 'Quel est le poids, sur Terre, d’un objet de 10 kg ?', 'mcq', '["10 N","98 N","0,98 N","980 N"]'::jsonb, 1, 'P = m × g = 10 × 9,8 = 98 N.', 1),
    ('04ba1e81-43cc-53c7-812a-b9c643e2bed0'::uuid, 'physique-chimie', '3e', 'Poids et gravitation', 'Que vaut l’intensité de la pesanteur sur la Lune ?', 'mcq', '["9,8 N/kg","6 N/kg","1,6 N/kg","0 N/kg"]'::jsonb, 2, 'Environ 1,6 N/kg, soit six fois moins que sur Terre : le poids y est divisé par 6.', 2),
    ('bbb3b558-9e20-5fa3-b4aa-25362f83261f'::uuid, 'physique-chimie', '3e', 'Poids et gravitation', 'Où se situe le point d’application du poids d’un objet ?', 'mcq', '["Au point de contact avec le sol","Au sommet de l’objet","Au centre de la Terre","Au centre de gravité de l’objet"]'::jsonb, 3, 'Le poids s’applique au centre de gravité de l’objet et il est dirigé vers le centre de l’astre.', 3),
    ('69ccffac-eec4-5f22-ba55-35fda7d7dbd0'::uuid, 'physique-chimie', '3e', 'Poids et gravitation', 'Pourquoi ne sent-on pas l’attraction gravitationnelle entre deux personnes ?', 'mcq', '["Parce qu’avec des masses ordinaires, elle est imperceptible","Parce qu’elle n’existe qu’entre astres","Parce qu’elle est répulsive","Parce que l’air l’annule"]'::jsonb, 0, 'La gravitation est universelle, mais elle n’est sensible qu’avec des masses énormes, comme celles des astres.', 4),
    ('3965d912-033e-5b81-9909-53e9d6e34e4c'::uuid, 'physique-chimie', '3e', 'Les différentes formes d’énergie', 'Quelle forme d’énergie est liée à l’agitation des particules ?', 'mcq', '["L’énergie cinétique","L’énergie nucléaire","L’énergie thermique","L’énergie lumineuse"]'::jsonb, 2, 'L’énergie thermique est liée à l’agitation des particules ; la cinétique au mouvement d’ensemble de l’objet.', 1),
    ('86f1e440-6e60-5fb8-a6c8-97e49ac98d71'::uuid, 'physique-chimie', '3e', 'Les différentes formes d’énergie', 'À combien de joules correspond environ une calorie ?', 'mcq', '["1 000 J","4,18 J","3,6 × 10⁶ J","0,24 J"]'::jsonb, 1, '1 cal ≈ 4,18 J : c’est l’unité employée en nutrition.', 2),
    ('265f8ed9-1448-569b-9d74-5a1d9c6a4110'::uuid, 'physique-chimie', '3e', 'Les différentes formes d’énergie', 'Quelle est la formule de l’énergie de position ?', 'mcq', '["Epp = ½ × m × v²","Epp = m × g","Epp = m × h","Epp = m × g × h"]'::jsonb, 3, 'Elle dépend de la masse, de la pesanteur et de la hauteur ; ½ × m × v² est l’énergie cinétique.', 3),
    ('a6471e37-e4a6-5562-9532-54b74be79102'::uuid, 'physique-chimie', '3e', 'Les différentes formes d’énergie', 'Quelle énergie faut-il environ pour soulever une pomme d’un mètre ?', 'mcq', '["1 J","1 kJ","1 kWh","10⁶ J"]'::jsonb, 0, 'Environ 1 J ; une barre chocolatée contient environ un million de fois plus.', 4),
    ('1d4d77e3-ba3b-55ce-a903-f736091ad1c7'::uuid, 'physique-chimie', '3e', 'Transferts et conversions d’énergie', 'Quel mode de transfert thermique explique que l’air chaud monte ?', 'mcq', '["La conduction","La convection","Le rayonnement","La conversion"]'::jsonb, 1, 'La convection se fait par déplacement de matière dans un fluide, comme l’air ou l’eau.', 1),
    ('23e800e4-166b-5d37-b303-984755217284'::uuid, 'physique-chimie', '3e', 'Transferts et conversions d’énergie', 'Quelle conversion réalise un alternateur ?', 'mcq', '["Électrique → cinétique","Chimique → thermique","Lumineuse → électrique","Cinétique → électrique"]'::jsonb, 3, 'L’alternateur transforme un mouvement en énergie électrique ; le moteur fait l’inverse.', 2),
    ('59f1dedc-5f15-5f72-8b6a-0964ad097df4'::uuid, 'physique-chimie', '3e', 'Transferts et conversions d’énergie', 'Dans une centrale au charbon, quelle forme d’énergie la turbine fournit-elle à l’alternateur ?', 'mcq', '["Chimique","Thermique","Cinétique","Lumineuse"]'::jsonb, 2, 'Chimique (charbon) → thermique (chaudière) → cinétique (turbine) → électrique (alternateur).', 3),
    ('339018ad-4c6c-544f-bc27-afc2e9429ae3'::uuid, 'physique-chimie', '3e', 'Transferts et conversions d’énergie', 'Quel est environ le rendement lumineux d’une lampe à incandescence ?', 'mcq', '["5 %","50 %","90 %","100 %"]'::jsonb, 0, 'L’essentiel de l’énergie part en chaleur ; une LED dépasse 30 %.', 4),
    ('c4a4ed1a-b1d3-580e-b8f3-ff50c1a02014'::uuid, 'physique-chimie', '3e', 'Calculer la vitesse et l’énergie cinétique', 'Une moto de 200 kg roule à 10 m/s. Quelle est son énergie cinétique ?', 'mcq', '["2 000 J","10 000 J","20 000 J","1 000 J"]'::jsonb, 1, 'Ec = ½ × 200 × 10² = 0,5 × 200 × 100 = 10 000 J.', 1),
    ('585aa265-127f-50f0-90fe-f4c7a093a619'::uuid, 'physique-chimie', '3e', 'Calculer la vitesse et l’énergie cinétique', 'Par combien l’énergie cinétique est-elle multipliée si la vitesse triple ?', 'mcq', '["3","6","9","27"]'::jsonb, 2, 'La vitesse est au carré : 3² = 9.', 2),
    ('174cfbbb-bbe9-5406-913a-6f2874182446'::uuid, 'physique-chimie', '3e', 'Calculer la vitesse et l’énergie cinétique', 'Quelle part de la distance d’arrêt l’alcool, la fatigue et le téléphone allongent-ils ?', 'mcq', '["La distance de freinage","La longueur du véhicule","Aucune des deux","La distance de réaction"]'::jsonb, 3, 'Ils ralentissent la réaction du conducteur ; la pluie et les pneus usés allongent le freinage.', 3),
    ('784c90fc-3863-5a08-9d18-f2dd44eea154'::uuid, 'physique-chimie', '3e', 'Calculer la vitesse et l’énergie cinétique', 'Comment la distance de freinage évolue-t-elle avec la vitesse ?', 'mcq', '["Elle croît comme le carré de la vitesse","Elle ne dépend pas de la vitesse","Elle croît comme la vitesse","Elle diminue"]'::jsonb, 0, 'Elle sert à dissiper l’énergie cinétique, qui dépend du carré de la vitesse.', 4),
    ('75c68234-0a1a-5d73-8ca6-56067bb7027d'::uuid, 'physique-chimie', '3e', 'Conservation et pertes d’énergie', 'Un moteur reçoit 1 000 J et fournit 300 J d’énergie utile. Quelle énergie est dissipée ?', 'mcq', '["300 J","1 300 J","700 J","30 J"]'::jsonb, 2, 'Énergie reçue = énergie utile + énergie dissipée : 1 000 − 300 = 700 J.', 1),
    ('01bea48f-d44a-5edc-9fe4-baca5bdb61b0'::uuid, 'physique-chimie', '3e', 'Conservation et pertes d’énergie', 'Quel rendement peut atteindre un moteur électrique ?', 'mcq', '["Environ 5 %","Environ 30 %","Environ 50 %","Jusqu’à 90 %"]'::jsonb, 3, 'Bien plus qu’un moteur thermique, qui plafonne vers 30 %.', 2),
    ('6babc8bc-da32-5697-80bd-44b271a05611'::uuid, 'physique-chimie', '3e', 'Conservation et pertes d’énergie', 'Par quels phénomènes l’énergie est-elle dissipée sous forme thermique ?', 'mcq', '["La photosynthèse","Les frottements et l’effet Joule","La dilution","La réflexion de la lumière"]'::jsonb, 1, 'Les frottements et l’échauffement des conducteurs transforment une partie de l’énergie en chaleur inutilisable.', 3),
    ('3508e123-6f6d-5c68-be11-0fd3220d25a0'::uuid, 'physique-chimie', '3e', 'Conservation et pertes d’énergie', 'Pourquoi éteindre les veilles fait-il économiser de l’énergie ?', 'mcq', '["Parce qu’elles consomment en continu","Parce qu’elles augmentent la tension","Parce qu’elles abîment la prise","Parce qu’elles produisent de la chaleur utile"]'::jsonb, 0, 'Un appareil en veille consomme jour et nuit, même quand on ne s’en sert pas.', 4),
    ('5211a8f4-4d92-5340-bbad-474489d78949'::uuid, 'physique-chimie', '3e', 'Le courant électrique', 'Lequel de ces éléments est un récepteur ?', 'mcq', '["La pile","La batterie","Le moteur","L’alternateur"]'::jsonb, 2, 'Le moteur consomme l’énergie électrique ; pile, batterie et alternateur sont des générateurs.', 1),
    ('dea8953c-f7a6-5c75-bc8d-1103f98020e6'::uuid, 'physique-chimie', '3e', 'Le courant électrique', 'Quel est le symbole normalisé d’une lampe ?', 'mcq', '["Un rectangle","Un cercle barré d’une croix","Deux traits inégaux","Un triangle"]'::jsonb, 1, 'Le rectangle est la résistance, les deux traits inégaux la pile.', 2),
    ('5197e51e-d381-5790-a287-bda96ddaa310'::uuid, 'physique-chimie', '3e', 'Le courant électrique', 'Que fait un interrupteur ouvert ?', 'mcq', '["Il coupe la boucle : plus rien ne circule","Il augmente le courant","Il ne change rien","Il inverse le sens du courant"]'::jsonb, 0, 'Le courant ne circule que dans un circuit fermé.', 3),
    ('21c061de-31be-5270-a5ec-920cee195482'::uuid, 'physique-chimie', '3e', 'Le courant électrique', 'Pourquoi un court-circuit présente-t-il un danger d’incendie ?', 'mcq', '["La tension disparaît","Le générateur se refroidit","Le courant s’inverse","L’intensité devient énorme et les fils chauffent"]'::jsonb, 3, 'Les deux bornes du générateur étant reliées directement, l’intensité monte et les fils peuvent s’enflammer.', 4),
    ('5d3bc3f0-45cd-57e3-880f-29a346fdc4a0'::uuid, 'physique-chimie', '3e', 'Les montages électriques', 'Que risque-t-on en branchant un ampèremètre en dérivation ?', 'mcq', '["Un court-circuit","Une mesure nulle, sans danger","Une tension doublée","Rien du tout"]'::jsonb, 0, 'L’ampèremètre se branche toujours en série : en dérivation, il crée un court-circuit.', 1),
    ('e4e22b2a-092e-500d-abe0-86da4ca5677e'::uuid, 'physique-chimie', '3e', 'Les montages électriques', '0,5 A arrive à un nœud ; l’une des deux branches prend 0,2 A. Quelle intensité passe dans l’autre ?', 'mcq', '["0,7 A","0,3 A","0,5 A","0,2 A"]'::jsonb, 1, 'Loi des nœuds : 0,5 = 0,2 + I, donc I = 0,3 A.', 2),
    ('8cc71c84-1914-5f81-9dd2-8f9f7854f42b'::uuid, 'physique-chimie', '3e', 'Les montages électriques', 'Dans un montage en série, que se passe-t-il quand on ajoute une lampe ?', 'mcq', '["Les lampes brillent davantage","Rien ne change","Les lampes brillent moins","Le circuit s’ouvre"]'::jsonb, 2, 'La tension du générateur se partage entre plus de lampes : chacune brille moins.', 3),
    ('2fabf019-9d3a-5195-b91b-5ff9636723e9'::uuid, 'physique-chimie', '3e', 'Les montages électriques', 'Deux lampes en série sont alimentées en 6 V. La première a 2 V à ses bornes. Et la seconde ?', 'mcq', '["6 V","2 V","8 V","4 V"]'::jsonb, 3, 'En série, les tensions s’additionnent : 6 = 2 + U₂, donc U₂ = 4 V.', 4),
    ('c9e646e5-5d5f-5906-b432-50bcd4d8dfd7'::uuid, 'physique-chimie', '3e', 'La tension électrique', 'Quelle est la tension aux bornes d’un interrupteur ouvert ?', 'mcq', '["0 V","Toute la tension du générateur","La moitié de la tension du générateur","Une tension négative"]'::jsonb, 1, 'Fermé, il a environ 0 V à ses bornes ; ouvert, il reçoit toute la tension du générateur.', 1),
    ('08ae0c6f-0c5a-59a8-b5a6-e42a30c07d06'::uuid, 'physique-chimie', '3e', 'La tension électrique', 'Quelle est la tension d’une pile plate ?', 'mcq', '["1,5 V","9 V","4,5 V","12 V"]'::jsonb, 2, 'Une pile bâton fait 1,5 V, une pile plate 4,5 V, une batterie de voiture 12 V.', 2),
    ('caaa3585-7000-5346-b77a-bd0127d6c310'::uuid, 'physique-chimie', '3e', 'La tension électrique', 'Quel appareil rend visible une tension alternative sous forme de sinusoïde ?', 'mcq', '["L’ampèremètre","Le voltmètre","L’ohmmètre","L’oscilloscope"]'::jsonb, 3, 'L’oscilloscope trace la tension en fonction du temps.', 3),
    ('0fd79e46-7d30-5f58-a6c5-9d034adec9e2'::uuid, 'physique-chimie', '3e', 'La tension électrique', 'Quel est environ le seuil de sécurité de la tension pour le corps humain ?', 'mcq', '["25 V","230 V","1,5 V","1 000 V"]'::jsonb, 0, 'Au-delà d’environ 25 V, une tension peut être dangereuse ; le secteur à 230 V est mortel.', 4),
    ('30e9aa5e-9876-5f6b-9568-3c0e49240bc1'::uuid, 'physique-chimie', '3e', 'L’intensité électrique', 'Du côté de quelle borne du générateur place-t-on la borne A (ou mA) de l’ampèremètre ?', 'mcq', '["La borne +","La borne −","Peu importe","Aucune : on la laisse libre"]'::jsonb, 0, 'La borne A est du côté de la borne + du générateur, la borne COM de l’autre côté.', 1),
    ('348a93ad-c940-5d9b-9638-cf282be80cd5'::uuid, 'physique-chimie', '3e', 'L’intensité électrique', 'Quelle différence y a-t-il entre un fusible et un disjoncteur ?', 'mcq', '["Le disjoncteur fond, le fusible se réarme","Le fusible fond et se remplace, le disjoncteur se réarme","Aucune","Le fusible augmente la tension"]'::jsonb, 1, 'Tous deux coupent le circuit quand l’intensité dépasse une limite, avant que les fils ne chauffent trop.', 2),
    ('56e3a065-e9b8-5a72-8ccc-d4888764802e'::uuid, 'physique-chimie', '3e', 'L’intensité électrique', 'Quelle est l’intensité approximative dans une lampe de poche ?', 'mcq', '["Environ 30 A","Environ 300 A","Environ 0,3 A","Environ 3 000 A"]'::jsonb, 2, 'Environ 0,3 A ; une LED demande quelques mA, une plaque de cuisson plus de 10 A.', 3),
    ('214a2769-f390-522f-813d-b862284b336f'::uuid, 'physique-chimie', '3e', 'L’intensité électrique', 'Dans l’analogie de l’eau dans un tuyau, à quoi correspond l’intensité ?', 'mcq', '["À la pression","À la longueur du tuyau","À la couleur de l’eau","Au débit"]'::jsonb, 3, 'L’intensité est un débit de charges ; la tension correspond à la pression.', 4),
    ('3e4aeaa0-74d1-5287-b096-a20bb414e58b'::uuid, 'physique-chimie', '3e', 'La résistance électrique', 'Une résistance de 100 Ω est parcourue par 0,05 A. Quelle est la tension à ses bornes ?', 'mcq', '["2 000 V","5 V","0,0005 V","100,05 V"]'::jsonb, 1, 'U = R × I = 100 × 0,05 = 5 V.', 1),
    ('b9eb736b-3c6a-592a-861b-b302397d5f00'::uuid, 'physique-chimie', '3e', 'La résistance électrique', 'On applique 12 V aux bornes d’une résistance de 60 Ω. Quelle intensité la traverse ?', 'mcq', '["720 A","5 A","0,2 A","72 A"]'::jsonb, 2, 'I = U ÷ R = 12 ÷ 60 = 0,2 A.', 2),
    ('2ec7cd57-40b2-5e00-bcef-2016141790bc'::uuid, 'physique-chimie', '3e', 'La résistance électrique', 'Comment mesure-t-on une résistance avec un ohmmètre ?', 'mcq', '["En série, dans le circuit alimenté","En dérivation, circuit alimenté","En la chauffant","Hors circuit, le dipôle débranché"]'::jsonb, 3, 'L’ohmmètre se branche toujours sur un dipôle débranché du circuit.', 3),
    ('b1eb0083-3147-5f54-b47e-77eedc8f1b32'::uuid, 'physique-chimie', '3e', 'La résistance électrique', 'Que représente la pente de la droite U en fonction de I d’un conducteur ohmique ?', 'mcq', '["Sa résistance R","L’intensité","La puissance","La tension du générateur"]'::jsonb, 0, 'U = R × I : la droite passe par l’origine et sa pente vaut R.', 4),
    ('3f1bd4e8-7c90-5050-b8b7-3f972de4d7b5'::uuid, 'physique-chimie', '3e', 'Puissance et énergie électrique', 'Quelle est la puissance d’un appareil branché sous 230 V et traversé par 2 A ?', 'mcq', '["460 W","115 W","232 W","4 600 W"]'::jsonb, 0, 'P = U × I = 230 × 2 = 460 W.', 1),
    ('dba14da9-93c0-51cd-9985-1689257a01bf'::uuid, 'physique-chimie', '3e', 'Puissance et énergie électrique', 'Combien coûtent 3 kWh à 0,20 € le kWh ?', 'mcq', '["6 €","0,60 €","0,15 €","3,20 €"]'::jsonb, 1, 'Coût = énergie en kWh × prix du kWh = 3 × 0,20 = 0,60 €.', 2),
    ('63e4545c-5afa-5829-9bd5-04c47e35640e'::uuid, 'physique-chimie', '3e', 'Puissance et énergie électrique', 'Une ampoule de 60 W allumée une heure consomme autant qu’une ampoule de 6 W allumée pendant…', 'mcq', '["6 heures","1 heure","10 heures","60 heures"]'::jsonb, 2, 'E = P × t : 60 W × 1 h = 60 Wh = 6 W × 10 h.', 3),
    ('f36bc7bf-d9eb-526b-920e-4dd630249e6d'::uuid, 'physique-chimie', '3e', 'Puissance et énergie électrique', 'Quelle est environ la puissance d’un chargeur de téléphone ?', 'mcq', '["150 W","2 000 W","3 000 W","5 W"]'::jsonb, 3, 'Environ 5 W ; un réfrigérateur fait 150 W, un four 2 000 W.', 4),
    ('4101857e-9046-53c7-879b-6e2fe81587e0'::uuid, 'physique-chimie', '3e', 'Signal et information', 'Quel type de signal une télécommande infrarouge émet-elle ?', 'mcq', '["Un signal lumineux","Un signal sonore","Un signal chimique","Un signal mécanique"]'::jsonb, 0, 'L’infrarouge est une lumière invisible : comme la fibre optique, c’est un signal lumineux.', 1),
    ('b1233471-4257-5283-a1aa-c568aaadc8ef'::uuid, 'physique-chimie', '3e', 'Signal et information', 'Pourquoi le numérique a-t-il remplacé l’analogique pour la musique et la photo ?', 'mcq', '["Il est toujours plus coloré","Il se copie sans perte et se compresse","Il ne nécessite aucun appareil","Il voyage plus vite que la lumière"]'::jsonb, 1, 'Une suite de 0 et de 1 se recopie à l’identique ; un signal analogique se dégrade à chaque copie.', 2),
    ('0e959d7e-07d3-5dad-9eb4-afa248c1ef61'::uuid, 'physique-chimie', '3e', 'Signal et information', 'Dans quel ordre s’enchaîne une chaîne de transmission ?', 'mcq', '["Récepteur → émetteur → milieu","Capteur → actionneur → émetteur","Émetteur → milieu de propagation → récepteur","Milieu → émetteur → récepteur"]'::jsonb, 2, 'Le téléphone, la radio ou un feu tricolore suivent tous ce schéma.', 3),
    ('3741c4a9-3db9-569b-bf95-81cb628035b0'::uuid, 'physique-chimie', '3e', 'Signal et information', 'Combien d’octets contient 1 Mo ?', 'mcq', '["1 000","10⁹","8","10⁶"]'::jsonb, 3, '1 Mo = 10⁶ octets, soit un million ; 1 Go = 10⁹ octets.', 4),
    ('5fa0a5cc-aab9-54b8-8fc2-9a7bfd31f263'::uuid, 'physique-chimie', '3e', 'La lumière', 'Quelles sont les trois couleurs primaires de la synthèse soustractive ?', 'mcq', '["Cyan, magenta, jaune","Rouge, vert, bleu","Rouge, jaune, bleu","Noir, blanc, gris"]'::jsonb, 0, 'C’est la synthèse de la peinture et de l’imprimante : chaque pigment retire des couleurs à la lumière blanche.', 1),
    ('d0cca08b-cd25-53c0-af82-4d4d0b2a854d'::uuid, 'physique-chimie', '3e', 'La lumière', 'Comment appelle-t-on la face d’un objet qui n’est pas éclairée ?', 'mcq', '["L’ombre portée","L’ombre propre","Le cône d’ombre","Le spectre"]'::jsonb, 1, 'L’ombre propre est sur l’objet ; l’ombre portée se dessine sur le sol ou l’écran.', 2),
    ('8ceeaa9c-cb51-535e-ae19-9bf7cad2ff74'::uuid, 'physique-chimie', '3e', 'La lumière', 'Lequel de ces objets est un objet diffusant ?', 'mcq', '["Le Soleil","Une flamme","La Lune","Un écran allumé"]'::jsonb, 2, 'La Lune ne produit pas de lumière : elle renvoie celle du Soleil.', 3),
    ('c0386486-cfa0-5371-a316-647477060db1'::uuid, 'physique-chimie', '3e', 'La lumière', 'Pourquoi un tissu rouge paraît-il rouge en lumière blanche ?', 'mcq', '["Il produit sa propre lumière rouge","Il absorbe le rouge","Il transforme toute la lumière en rouge","Il diffuse le rouge et absorbe les autres couleurs"]'::jsonb, 3, 'C’est pourquoi, éclairé en lumière verte, il paraît noir : il n’a plus de rouge à renvoyer.', 4),
    ('eb36cf14-5965-54de-a093-06adc2e27cd9'::uuid, 'physique-chimie', '3e', 'Le son', 'Quel est le niveau sonore du seuil de douleur ?', 'mcq', '["120 dB","85 dB","50 dB","200 dB"]'::jsonb, 0, 'À 120 dB, le son fait mal ; dès 85 dB, une exposition prolongée abîme déjà l’oreille.', 1),
    ('f5f0a709-bdd2-5727-8526-7a8b0e65bccb'::uuid, 'physique-chimie', '3e', 'Le son', 'Quelle est environ la vitesse du son dans l’eau ?', 'mcq', '["340 m/s","1 500 m/s","5 000 m/s","300 000 km/s"]'::jsonb, 1, 'Le son va plus vite dans un milieu dense : 340 m/s dans l’air, 1 500 m/s dans l’eau, 5 000 m/s dans l’acier.', 2),
    ('ea7a574a-a2f0-590b-a34f-f6e1f843e83b'::uuid, 'physique-chimie', '3e', 'Le son', 'On compte 6 secondes entre l’éclair et le tonnerre. À quelle distance se trouve l’orage ?', 'mcq', '["6 km","18 km","2 km","340 m"]'::jsonb, 2, 'Le son parcourt environ 1 km en 3 s : on divise le nombre de secondes par 3.', 3),
    ('33fc686a-3584-573c-980d-8a324676b54a'::uuid, 'physique-chimie', '3e', 'Le son', 'Un sonar reçoit l’écho 2 s après l’émission, dans l’eau où le son va à 1 500 m/s. À quelle distance est l’obstacle ?', 'mcq', '["3 000 m","750 m","1 000 m","1 500 m"]'::jsonb, 3, 'Le son fait l’aller-retour : d = (1 500 × 2) ÷ 2 = 1 500 m.', 4),
    ('5ba80370-1357-5d5e-a30c-b50525bdd9e2'::uuid, 'physique-chimie', '3e', 'Les signaux sonores', 'Quelle est la période d’un son de fréquence 500 Hz ?', 'mcq', '["500 s","2 ms","0,5 s","20 ms"]'::jsonb, 1, 'T = 1 ÷ f = 1 ÷ 500 = 0,002 s, soit 2 ms.', 1),
    ('89178e5b-c19c-5407-8689-4b4ae3cbccf4'::uuid, 'physique-chimie', '3e', 'Les signaux sonores', 'Comment appelle-t-on les sons de fréquence inférieure à 20 Hz ?', 'mcq', '["Les ultrasons","Les harmoniques","Les infrasons","Les sons purs"]'::jsonb, 2, 'Les infrasons, inaudibles pour l’homme, sont émis par les éléphants ou les séismes.', 2),
    ('f91791ba-38c3-574c-9311-8cc66a5c3147'::uuid, 'physique-chimie', '3e', 'Les signaux sonores', 'Quel objet produit un son pur ?', 'mcq', '["Une voix","Une guitare","Un klaxon","Un diapason"]'::jsonb, 3, 'Le diapason donne une sinusoïde régulière ; une voix ou un instrument donnent un son composé.', 3),
    ('fdec29ce-7dd2-5eea-bf14-7866ae65caa6'::uuid, 'physique-chimie', '3e', 'Les signaux sonores', 'Quel appareil trace le signal sonore en fonction du temps ?', 'mcq', '["L’oscilloscope","Le voltmètre","Le haut-parleur","Le sonomètre"]'::jsonb, 0, 'Relié à un microphone, l’oscilloscope « dessine » le son : on y lit la période et l’amplitude.', 4),
    ('de0b8d13-e9d4-51a7-9e54-b83c74701555'::uuid, 'svt', '3e', 'La Terre et le système solaire', 'Combien de temps dure la révolution de la Terre autour du Soleil ?', 'mcq', '["24 heures","365,25 jours","28 jours","23,5 jours"]'::jsonb, 1, 'La révolution autour du Soleil dure 365,25 jours : c’est l’année. La rotation sur elle-même dure 24 heures.', 1),
    ('ac858b41-e659-5cbb-b0fe-8c3442296b86'::uuid, 'svt', '3e', 'La Terre et le système solaire', 'Pourquoi Vénus est-elle trop chaude pour être habitable ?', 'mcq', '["Elle a perdu son atmosphère","Elle tourne trop vite","Son effet de serre s’est emballé","Elle n’a pas de noyau"]'::jsonb, 2, 'Vénus souffre d’un emballement de l’effet de serre ; c’est Mars qui a perdu son atmosphère.', 2),
    ('1515f521-860e-5f9d-b4e6-15689f3bcdbe'::uuid, 'svt', '3e', 'La Terre et le système solaire', 'Qu’est-ce qui dévie le vent solaire autour de la Terre ?', 'mcq', '["La couche d’ozone","L’effet de serre","La Lune","Le champ magnétique"]'::jsonb, 3, 'Le champ magnétique terrestre dévie le vent solaire ; l’ozone, lui, filtre les ultraviolets.', 3),
    ('72d2add1-607d-5117-93b9-445a069a4b81'::uuid, 'svt', '3e', 'La Terre et le système solaire', 'À quelle famille de planètes appartiennent Uranus et Neptune ?', 'mcq', '["Aux géantes glacées","Aux planètes telluriques","Aux planètes naines","Aux astéroïdes"]'::jsonb, 0, 'Volumineuses et peu denses comme Jupiter et Saturne, elles sont plus froides : ce sont des géantes glacées.', 4),
    ('b0fd1ef9-c511-5c40-9049-6a2ef7ba2761'::uuid, 'svt', '3e', 'La tectonique des plaques', 'Comment s’appelait le supercontinent qui réunissait les terres il y a environ 250 millions d’années ?', 'mcq', '["La Pangée","Le Gondwana","La Laurasie","L’Atlantide"]'::jsonb, 0, 'La Pangée s’est ensuite disloquée : le déplacement des plaques a dispersé les continents.', 1),
    ('7ba4b9b7-61f2-54b0-a3e2-a3e615b0d0e7'::uuid, 'svt', '3e', 'La tectonique des plaques', 'Sur quelle couche plus ductile les plaques lithosphériques se déplacent-elles ?', 'mcq', '["La croûte","L’asthénosphère","Le noyau","L’atmosphère"]'::jsonb, 1, 'La lithosphère rigide glisse sur l’asthénosphère, plus ductile.', 2),
    ('051a26c3-7586-5531-a3c9-c3b563b73dab'::uuid, 'svt', '3e', 'La tectonique des plaques', 'Qu’est-ce qu’une faille transformante ?', 'mcq', '["Une zone où une plaque plonge sous une autre","Une dorsale océanique","Une frontière où deux plaques glissent l’une contre l’autre","Une chaîne de montagnes"]'::jsonb, 2, 'Elle marque une frontière coulissante : on y observe des séismes, mais pas de volcanisme.', 3),
    ('0a215638-52fe-514f-b3de-70237af75e82'::uuid, 'svt', '3e', 'La tectonique des plaques', 'Quelles observations ont confirmé l’expansion océanique dans les années 1960 ?', 'mcq', '["La forme des côtes","Les fossiles de dinosaures","Les éruptions d’Hawaï","Les anomalies magnétiques symétriques de part et d’autre des dorsales"]'::jsonb, 3, 'Avec la cartographie des fonds et la sismologie, elles ont montré que le plancher océanique se crée aux dorsales.', 4),
    ('f6f35208-55e7-595e-8413-cddfcef56fae'::uuid, 'svt', '3e', 'Les séismes : causes et risques associés', 'Où les dégâts d’un séisme sont-ils en général les plus importants ?', 'mcq', '["Au foyer, en profondeur","Le plus loin possible de la faille","À l’épicentre","Au centre de la Terre"]'::jsonb, 2, 'L’épicentre est le point de la surface situé à la verticale du foyer.', 1),
    ('cb172276-4aa7-5fdc-abe5-7ece9554e9ec'::uuid, 'svt', '3e', 'Les séismes : causes et risques associés', 'Sur quel élément du risque sismique peut-on agir ?', 'mcq', '["L’aléa","La vulnérabilité","La magnitude","Le mouvement des plaques"]'::jsonb, 1, 'On ne peut pas empêcher un séisme, mais on peut réduire l’exposition des personnes et des bâtiments.', 2),
    ('dbe377ad-1ffd-5de1-8ea4-e052c34a9f9a'::uuid, 'svt', '3e', 'Les séismes : causes et risques associés', 'Combien de valeurs d’intensité un même séisme possède-t-il ?', 'mcq', '["Une seule pour tout le séisme","Deux","Aucune","Une par lieu où il est ressenti"]'::jsonb, 3, 'L’intensité décrit les effets en un lieu ; la magnitude, elle, est unique pour un séisme.', 3),
    ('50b22802-9a47-53ab-ab1b-02105ca032bd'::uuid, 'svt', '3e', 'Les séismes : causes et risques associés', 'Quelle région française présente une sismicité forte, avec des normes parasismiques obligatoires ?', 'mcq', '["Les Antilles","La Bretagne","Le Bassin parisien","Les Landes"]'::jsonb, 0, 'Les Antilles sont en zone de subduction ; les Alpes, les Pyrénées ou l’Alsace ont une sismicité modérée.', 4),
    ('8cb47971-c106-52b1-9155-b56d3bee4869'::uuid, 'svt', '3e', 'Volcanisme et risques associés', 'Quel volcan est connu pour ses éruptions explosives ?', 'mcq', '["Le Piton de la Fournaise","Un volcan d’Hawaï","Un volcan d’Islande","La Montagne Pelée"]'::jsonb, 3, 'La Montagne Pelée, comme le Vésuve ou le Merapi, a un magma visqueux ; les trois autres sont effusifs.', 1),
    ('0432e9a7-3ccf-5b75-8ca7-9c5878fc1b1f'::uuid, 'svt', '3e', 'Volcanisme et risques associés', 'Quel magma donne une éruption effusive ?', 'mcq', '["Un magma visqueux, riche en silice","Un magma fluide, pauvre en silice","Un magma solide","Un magma sans gaz ni lave"]'::jsonb, 1, 'Dans un magma fluide, les gaz s’échappent facilement : la lave coule au lieu d’exploser.', 2),
    ('3eff885c-b9e0-55da-9a57-71eb1b12227d'::uuid, 'svt', '3e', 'Volcanisme et risques associés', 'Qu’est-ce qu’un lahar ?', 'mcq', '["Une nuée ardente","Un gaz toxique","Une coulée de boue","Une coulée de lave"]'::jsonb, 2, 'Les lahars sont des coulées de boue volcanique, un des risques associés aux volcans.', 3),
    ('5b4f536a-7c1d-50ef-89ba-09e52aaf7b00'::uuid, 'svt', '3e', 'Volcanisme et risques associés', 'Quelle éruption de 1991 a été anticipée, sauvant des dizaines de milliers de vies ?', 'mcq', '["Celle du Pinatubo","Celle du Vésuve","Celle de la Montagne Pelée","Celle du Merapi"]'::jsonb, 0, 'La surveillance de l’observatoire et l’évacuation préparée ont permis de sauver la population.', 4),
    ('3f65abf5-ab65-5c84-a5d7-733f7c4e25b5'::uuid, 'svt', '3e', 'La dynamique des masses d’air et d’eau', 'Qu’est-ce qu’un front, en météorologie ?', 'mcq', '["La rencontre de masses d’air différentes","Un nuage d’orage isolé","Une zone de haute pression","Un courant marin"]'::jsonb, 0, 'Au contact de deux masses d’air de températures différentes se forment nuages et précipitations.', 1),
    ('e8a2582d-3d5e-5b85-a79a-d30686c6cee5'::uuid, 'svt', '3e', 'La dynamique des masses d’air et d’eau', 'Qu’est-ce qu’un anticyclone ?', 'mcq', '["Une zone de basse pression où l’air monte","Une zone de haute pression où l’air froid descend","Un courant océanique","Un cyclone tropical"]'::jsonb, 1, 'L’air froid, plus dense, descend et crée une haute pression ; l’air chaud qui s’élève crée une dépression.', 2),
    ('429341a7-595a-5f67-ac81-c4f5589fde25'::uuid, 'svt', '3e', 'La dynamique des masses d’air et d’eau', 'Comment appelle-t-on la déviation des vents due à la rotation de la Terre ?', 'mcq', '["La convection","L’effet de serre","La force de Coriolis","La circulation thermohaline"]'::jsonb, 2, 'Elle organise l’atmosphère en grandes cellules et en vents dominants, comme les alizés.', 3),
    ('e9816575-4be9-5adf-af02-075a6b47302f'::uuid, 'svt', '3e', 'La dynamique des masses d’air et d’eau', 'Qu’est-ce qui entraîne les courants océaniques de surface ?', 'mcq', '["La salinité","La Lune","Les séismes","Les vents"]'::jsonb, 3, 'Les vents entraînent les courants de surface ; en profondeur, ce sont la température et la salinité.', 4),
    ('6eb9bcf1-93ef-590f-8dca-402ed80be205'::uuid, 'svt', '3e', 'L’évolution du climat, les risques climatiques et météorologiques', 'Laquelle de ces actions relève de l’adaptation au changement climatique ?', 'mcq', '["Construire des digues","Isoler les logements","Développer les énergies décarbonées","Reboiser"]'::jsonb, 0, 'Les digues réduisent la vulnérabilité ; isoler, décarboner et reboiser réduisent les émissions : c’est l’atténuation.', 1),
    ('c3b4cf6c-7fbc-52cf-9427-fee3cc3af088'::uuid, 'svt', '3e', 'L’évolution du climat, les risques climatiques et météorologiques', 'Qu’est-ce qui explique naturellement l’alternance des glaciations sur des dizaines de milliers d’années ?', 'mcq', '["Les éruptions volcaniques","Les variations de l’orbite terrestre, ou paramètres de Milankovitch","Les cyclones","Les courants marins de surface"]'::jsonb, 1, 'Ces variations lentes de l’orbite produisent l’alternance des périodes glaciaires et interglaciaires.', 2),
    ('a07eca97-7597-5cd2-afa2-af4874e75a26'::uuid, 'svt', '3e', 'L’évolution du climat, les risques climatiques et météorologiques', 'Quelles activités émettent surtout du méthane ?', 'mcq', '["La fabrication du ciment","Les engrais azotés","L’élevage et les rizières","Les éoliennes"]'::jsonb, 2, 'Le méthane vient de l’élevage, des rizières et des fuites de gaz ; les engrais émettent du protoxyde d’azote.', 3),
    ('367390bb-b818-5a43-9709-060b0f4993fa'::uuid, 'svt', '3e', 'L’évolution du climat, les risques climatiques et météorologiques', 'Pourquoi une partie du réchauffement à venir est-elle déjà engagée ?', 'mcq', '["Parce que le Soleil chauffe de plus en plus","Parce que les volcans vont se réveiller","Parce que la Terre se rapproche du Soleil","Parce que le climat ne réagit pas instantanément aux émissions passées"]'::jsonb, 3, 'Les gaz déjà émis continueront de réchauffer la planète pendant des décennies.', 4),
    ('2a580b37-c7bc-5782-a88c-7cf7961c1baf'::uuid, 'svt', '3e', 'L’exploitation de l’eau', 'Quelle technique d’irrigation économise l’eau ?', 'mcq', '["Le goutte-à-goutte","L’arrosage par submersion","L’aspersion en plein midi","Le pompage en bord de mer"]'::jsonb, 0, 'Le goutte-à-goutte apporte l’eau au pied des plantes, sans perte par évaporation ni ruissellement.', 1),
    ('1bca807c-6168-5937-91a8-f9ae30f97b43'::uuid, 'svt', '3e', 'L’exploitation de l’eau', 'Quelle part de toute l’eau de la planète est de l’eau douce accessible ?', 'mcq', '["2,5 %","Moins de 1 %","30 %","70 %"]'::jsonb, 1, 'L’eau douce fait 2,5 %, mais l’essentiel est bloqué dans les glaces et les nappes profondes.', 2),
    ('af436b0c-8af6-57f8-9373-28a9db4a257d'::uuid, 'svt', '3e', 'L’exploitation de l’eau', 'Quelle étape du cycle de l’eau alimente les nappes phréatiques ?', 'mcq', '["Le ruissellement","L’évaporation","L’infiltration","La condensation"]'::jsonb, 2, 'L’eau qui s’infiltre dans le sol recharge les nappes ; celle qui ruisselle rejoint les rivières.', 3),
    ('aa23e127-15fa-5270-ba51-f9350ab0176d'::uuid, 'svt', '3e', 'L’exploitation de l’eau', 'Quelle étape de la potabilisation retient les molécules dissoutes ?', 'mcq', '["Le dégrillage","La floculation","La filtration sur sable","La filtration sur charbon actif"]'::jsonb, 3, 'Le sable retient les particules fines, le charbon actif les molécules dissoutes ; la désinfection vient ensuite.', 4),
    ('f2eda2d0-ca6b-5cc6-882d-6ad344dce8ff'::uuid, 'svt', '3e', 'L’exploitation du pétrole', 'Dans quel milieu la matière organique de la roche mère s’est-elle déposée ?', 'mcq', '["Un milieu pauvre en oxygène","Un milieu très oxygéné","Un désert chaud","Le cratère d’un volcan"]'::jsonb, 0, 'Sans oxygène, la matière organique ne se décompose pas entièrement : elle peut se transformer en hydrocarbures.', 1),
    ('ed5fb6a6-ebb9-53a6-95d3-c8149781a902'::uuid, 'svt', '3e', 'L’exploitation du pétrole', 'Quel produit du raffinage sert de carburant à l’aviation ?', 'mcq', '["Le bitume","Le kérosène","Le fioul lourd","Le gazole"]'::jsonb, 1, 'Le kérosène alimente les avions ; le bitume sert aux routes, le gazole et les fiouls au transport lourd et au chauffage.', 2),
    ('61d1a789-4698-587d-b7f7-4d5ac64680b3'::uuid, 'svt', '3e', 'L’exploitation du pétrole', 'Dans quelle roche poreuse les hydrocarbures migrent-ils et s’accumulent-ils ?', 'mcq', '["La roche mère","La roche couverture","La roche réservoir","Le basalte"]'::jsonb, 2, 'Ils se forment dans la roche mère, migrent dans la roche réservoir et restent piégés sous la roche couverture.', 3),
    ('abd8f4ad-6dc4-5789-a125-11d084d86c7b'::uuid, 'svt', '3e', 'L’exploitation du pétrole', 'Lesquels de ces produits viennent de la pétrochimie ?', 'mcq', '["Le verre et la céramique","Le bois et le papier","Le fer et l’acier","Les plastiques et les textiles synthétiques"]'::jsonb, 3, 'Plastiques, textiles synthétiques, engrais ou médicaments : sortir du pétrole ne concerne pas que les voitures.', 4),
    ('79c35caf-8862-53f9-bfae-d8d2af2a76bf'::uuid, 'svt', '3e', 'Le changement climatique et les écosystèmes', 'Quelles espèces s’adaptent le mieux au changement climatique ?', 'mcq', '["Celles à génération courte et à forte descendance","Les plus grandes","Celles qui vivent longtemps avec peu de petits","Celles de haute montagne"]'::jsonb, 0, 'Avec des générations rapides et nombreuses, la sélection naturelle agit plus vite.', 1),
    ('14c7cd98-2264-598c-8f66-af202650a529'::uuid, 'svt', '3e', 'Le changement climatique et les écosystèmes', 'Lequel de ces faits est un changement de phénologie ?', 'mcq', '["Le blanchissement des coraux","Des floraisons plus précoces","L’acidification des océans","La fonte du permafrost"]'::jsonb, 1, 'La phénologie est le calendrier du vivant : floraisons, migrations, éclosions.', 2),
    ('8fd83bdb-94f0-5301-a123-ad751e845aed'::uuid, 'svt', '3e', 'Le changement climatique et les écosystèmes', 'Pourquoi les espèces de haute montagne sont-elles particulièrement menacées ?', 'mcq', '["Elles sont trop nombreuses","Elles migrent trop vite","Elles n’ont plus où monter pour trouver le froid","Elles ne supportent pas le froid"]'::jsonb, 2, 'Les aires de répartition remontent en altitude ; au sommet, il n’y a plus de refuge.', 3),
    ('44859884-09ab-5b80-93a3-e21472dac914'::uuid, 'svt', '3e', 'Le changement climatique et les écosystèmes', 'Quel effet l’acidification des océans a-t-elle sur les êtres vivants marins ?', 'mcq', '["Elle fait grossir les poissons","Elle réchauffe les pôles","Elle augmente la salinité","Elle fragilise les coquilles et les squelettes calcaires"]'::jsonb, 3, 'Le CO₂ dissous abaisse le pH de l’eau, ce qui gêne la fabrication du calcaire.', 4),
    ('6e7f64ad-843c-5515-9dc5-bb6847aaed8e'::uuid, 'svt', '3e', 'Les impacts globaux de l’activité humaine', 'Qu’est-ce que l’empreinte carbone ?', 'mcq', '["Les émissions de gaz à effet de serre liées à un mode de vie","La surface forestière d’un pays","La quantité de charbon extraite","Le nombre d’espèces disparues"]'::jsonb, 0, 'Elle se distingue de l’empreinte écologique, qui mesure une surface.', 1),
    ('bd2d1212-f84a-5378-882a-e98cc6633fa4'::uuid, 'svt', '3e', 'Les impacts globaux de l’activité humaine', 'Qu’est-ce que le jour du dépassement ?', 'mcq', '["Le jour le plus chaud de l’année","La date où l’humanité a consommé ce que la planète renouvelle en un an","La date d’un sommet sur le climat","Le jour de la première extinction connue"]'::jsonb, 1, 'Il tombe chaque année plus tôt : l’humanité consomme plus que ce que la planète renouvelle.', 2),
    ('ac58fbea-ed0b-539f-a66a-7ae031b55f00'::uuid, 'svt', '3e', 'Les impacts globaux de l’activité humaine', 'Pourquoi la disparition d’une espèce est-elle plus grave qu’une pollution ?', 'mcq', '["Parce qu’elle coûte plus cher","Parce qu’elle se voit davantage","Parce qu’elle est irréversible","Parce qu’elle est plus rapide"]'::jsonb, 2, 'Une pollution peut être traitée ; une espèce disparue ne revient pas.', 3),
    ('259ea4f7-2a5f-56dc-a441-85bc8fbff7a6'::uuid, 'svt', '3e', 'Les impacts globaux de l’activité humaine', 'Comment beaucoup d’espèces invasives ont-elles été introduites ?', 'mcq', '["Par les courants marins uniquement","Par la déforestation","Par les saisons","Transportées par le commerce mondial"]'::jsonb, 3, 'Bateaux, avions et marchandises les déplacent loin de leur milieu d’origine.', 4),
    ('ab24f739-1207-5054-bb56-233032a30e4d'::uuid, 'svt', '3e', 'Les besoins nutritifs des cellules et l’organisation des organes chez les êtres vivants', 'Quelle est l’étendue approximative de la surface des villosités intestinales ?', 'mcq', '["200 m²","2 m²","20 cm²","2 km²"]'::jsonb, 0, 'Environ 200 m², le double des alvéoles pulmonaires : une très grande surface dans un petit volume.', 1),
    ('73edb0cd-b7fd-5d57-aeec-afc557e263b4'::uuid, 'svt', '3e', 'Les besoins nutritifs des cellules et l’organisation des organes chez les êtres vivants', 'Qu’est-ce qu’un tissu ?', 'mcq', '["Plusieurs organes réunis","Un ensemble de cellules de même type","Un appareil complet","Une molécule"]'::jsonb, 1, 'Cellule, tissu, organe, appareil, organisme : le tissu regroupe des cellules semblables.', 2),
    ('8ee1277c-299d-5fce-bcc9-220c1b080a02'::uuid, 'svt', '3e', 'Les besoins nutritifs des cellules et l’organisation des organes chez les êtres vivants', 'À quoi servent les acides gras pour la cellule ?', 'mcq', '["À fabriquer l’ADN","À transporter le dioxygène","À construire les membranes et à former une réserve d’énergie","À capter la lumière"]'::jsonb, 2, 'Les acides gras entrent dans les membranes et constituent une réserve d’énergie.', 3),
    ('9cf952ab-45e0-5d81-ae9f-855dfd6dd097'::uuid, 'svt', '3e', 'Les besoins nutritifs des cellules et l’organisation des organes chez les êtres vivants', 'Quel appareil fournit les nutriments en simplifiant les aliments ?', 'mcq', '["L’appareil respiratoire","L’appareil circulatoire","L’appareil excréteur","L’appareil digestif"]'::jsonb, 3, 'L’appareil digestif fournit les nutriments, que l’appareil circulatoire transporte jusqu’aux cellules.', 4),
    ('526a2042-35e5-582a-843d-2ae362a960c1'::uuid, 'svt', '3e', 'L’approvisionnement du corps en dioxygène et en nutriments', 'Dans quel sens le dioxyde de carbone traverse-t-il la paroi de l’alvéole ?', 'mcq', '["Du sang vers l’air","De l’air vers le sang","Il ne la traverse pas","Du sang vers l’intestin"]'::jsonb, 0, 'Il diffuse du plus concentré (le sang) vers le moins concentré (l’air alvéolaire), en sens inverse du dioxygène.', 1),
    ('0530d72e-93cf-55fa-b5ed-d9a81108ef48'::uuid, 'svt', '3e', 'L’approvisionnement du corps en dioxygène et en nutriments', 'Que fait le diaphragme lors de l’inspiration ?', 'mcq', '["Il remonte","Il s’abaisse","Il reste immobile","Il se replie sur le cœur"]'::jsonb, 1, 'En s’abaissant, avec les côtes qui se soulèvent, il augmente le volume de la cage thoracique : l’air entre.', 2),
    ('42c764d4-3337-5d90-a029-6c97b4ed4d91'::uuid, 'svt', '3e', 'L’approvisionnement du corps en dioxygène et en nutriments', 'Sous quelle forme le foie stocke-t-il le glucose ?', 'mcq', '["L’amidon","La cellulose","Le glycogène","L’urée"]'::jsonb, 2, 'Le foie met le glucose en réserve sous forme de glycogène ; l’amidon est la réserve des plantes.', 3),
    ('dc7e231e-a1d8-5fa2-97c6-4dfa6dd01d26'::uuid, 'svt', '3e', 'L’approvisionnement du corps en dioxygène et en nutriments', 'Comment les nutriments sont-ils transportés dans le sang ?', 'mcq', '["Fixés sur l’hémoglobine","Dans les plaquettes","Dans les globules blancs","Dissous dans le plasma"]'::jsonb, 3, 'Les nutriments voyagent dissous dans le plasma ; l’hémoglobine des globules rouges transporte le dioxygène.', 4),
    ('ef49d697-b22a-57da-b03b-9cf47c4e769d'::uuid, 'svt', '3e', 'Le système de transport du sang, l’élimination des déchets et les micro-organismes', 'À quoi sert le microbiote intestinal ?', 'mcq', '["Il aide la digestion, fournit des vitamines et éduque le système immunitaire","Il provoque la plupart des maladies","Il fabrique les globules rouges","Il filtre l’urine"]'::jsonb, 0, 'La plupart des micro-organismes qui nous habitent sont utiles ; seule une minorité est pathogène.', 1),
    ('d353c883-3fd1-5412-a99c-f45b9791ad31'::uuid, 'svt', '3e', 'Le système de transport du sang, l’élimination des déchets et les micro-organismes', 'Quel ventricule envoie le sang vers tous les organes ?', 'mcq', '["Le ventricule droit","Le ventricule gauche","L’oreillette droite","L’oreillette gauche"]'::jsonb, 1, 'Le ventricule gauche, le plus musclé, lance la circulation générale ; le droit envoie le sang aux poumons.', 2),
    ('0b5827df-9d00-526e-ba57-fdd2de63d468'::uuid, 'svt', '3e', 'Le système de transport du sang, l’élimination des déchets et les micro-organismes', 'Comment est la paroi d’une artère ?', 'mcq', '["Fine, avec des valvules","Faite d’une seule cellule","Épaisse et élastique","Absente"]'::jsonb, 2, 'Elle résiste ainsi à la pression du sang qui part du cœur ; la veine a une paroi fine, le capillaire une seule cellule.', 3),
    ('e8068ceb-926d-55db-882e-b8c8f160219d'::uuid, 'svt', '3e', 'Le système de transport du sang, l’élimination des déchets et les micro-organismes', 'Quel constituant représente 55 % du sang ?', 'mcq', '["Les globules rouges","Les plaquettes","Les globules blancs","Le plasma"]'::jsonb, 3, 'Le plasma, essentiellement de l’eau, transporte nutriments, hormones et déchets.', 4),
    ('eca637fe-a75a-54c7-b0be-19f9cd34220f'::uuid, 'svt', '3e', 'Nutrition et organisation des plantes', 'Quel rôle les plantes chlorophylliennes jouent-elles dans les réseaux trophiques ?', 'mcq', '["Producteurs primaires","Décomposeurs","Consommateurs secondaires","Prédateurs"]'::jsonb, 0, 'Elles fabriquent la matière organique dont dépendent tous les autres maillons.', 1),
    ('31e849de-b000-5801-a8aa-e264aed8403e'::uuid, 'svt', '3e', 'Nutrition et organisation des plantes', 'Quel vaisseau transporte la sève élaborée ?', 'mcq', '["Le xylème","Le phloème","Le poil absorbant","Le stomate"]'::jsonb, 1, 'Le phloème distribue la sève élaborée, riche en sucres ; le xylème conduit la sève brute.', 2),
    ('a100cdcd-9045-572f-b230-a98122a50115'::uuid, 'svt', '3e', 'Nutrition et organisation des plantes', 'Quelles structures des racines multiplient la surface d’absorption ?', 'mcq', '["Les stomates","Les chloroplastes","Les poils absorbants","Les feuilles caduques"]'::jsonb, 2, 'Les poils absorbants prélèvent l’eau et les sels minéraux sur une très grande surface.', 3),
    ('797860b1-881c-52f7-b4de-d371b6d4d345'::uuid, 'svt', '3e', 'Nutrition et organisation des plantes', 'Qu’est-ce qui fait monter la sève brute des racines vers les feuilles ?', 'mcq', '["La photosynthèse des racines","La gravité","La respiration nocturne","La transpiration par les stomates"]'::jsonb, 3, 'L’eau qui s’évapore par les stomates tire la colonne de sève brute vers le haut.', 4),
    ('8dcc88ba-ecd4-5c5f-8870-cef14985c891'::uuid, 'svt', '3e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Quelle mesure aide les poissons migrateurs à se reproduire malgré les barrages ?', 'mcq', '["Les passes à poissons","La pêche des adultes reproducteurs","L’éclairage des rivières la nuit","L’introduction d’espèces concurrentes"]'::jsonb, 0, 'Les passes à poissons rétablissent l’accès aux sites de reproduction, comme les corridors pour les espèces terrestres.', 1),
    ('8304bd6d-5642-5c23-abdf-c7c0c42d9710'::uuid, 'svt', '3e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Lequel de ces animaux pratique la fécondation externe ?', 'mcq', '["Le chat","L’oursin","Le pigeon","Le lézard"]'::jsonb, 1, 'Chez l’oursin, comme chez les poissons et les amphibiens, la fécondation a lieu dans l’eau.', 2),
    ('5d32a8a6-ff30-592e-a240-de78fc44c9af'::uuid, 'svt', '3e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Comment certains polluants dérèglent-ils la fertilité ?', 'mcq', '["En modifiant la durée du jour","En augmentant la température de l’eau","En agissant comme perturbateurs endocriniens","En attirant des prédateurs"]'::jsonb, 2, 'Les perturbateurs endocriniens interfèrent avec les hormones qui contrôlent la reproduction.', 3),
    ('a3e26edf-a17e-5b4f-a393-348258ab0c6f'::uuid, 'svt', '3e', 'La reproduction sexuée et l’influence de l’environnement sur la reproduction d’une population', 'Quels facteurs font diminuer l’effectif d’une population ?', 'mcq', '["La natalité et l’immigration","La natalité et la mortalité","L’immigration et l’émigration","La mortalité et l’émigration"]'::jsonb, 3, 'Les morts et les départs réduisent l’effectif ; les naissances et les arrivées l’augmentent.', 4),
    ('fd6b6889-b000-5a67-b50d-dbd80e3ac19d'::uuid, 'svt', '3e', 'La reproduction asexuée', 'Quel animal peut reconstituer un individu entier à partir d’un fragment ?', 'mcq', '["L’étoile de mer","Le puceron","La levure","Le lézard"]'::jsonb, 0, 'C’est la fragmentation suivie de régénération, observée aussi chez la planaire.', 1),
    ('018cc87f-d6cf-5846-aaab-db37769cfed4'::uuid, 'svt', '3e', 'La reproduction asexuée', 'Comment la pomme de terre se multiplie-t-elle de façon asexuée ?', 'mcq', '["Par stolons","Par tubercules","Par bulbes","Par drageons"]'::jsonb, 1, 'Chaque tubercule peut donner une nouvelle plante, clone de la plante mère.', 2),
    ('e5959471-e377-5a81-858a-327978da8cc6'::uuid, 'svt', '3e', 'La reproduction asexuée', 'Quel mode de reproduction asexuée pratiquent les bactéries ?', 'mcq', '["Le bourgeonnement","La parthénogenèse","La scissiparité","Le bouturage"]'::jsonb, 2, 'La bactérie se divise en deux individus identiques : c’est la scissiparité.', 3),
    ('dc1c6f86-ef36-50ca-a9c7-aee60548b5bf'::uuid, 'svt', '3e', 'La reproduction asexuée', 'Quel épisode historique montre le danger d’une culture faite de clones ?', 'mcq', '["La peste noire","L’éruption du Vésuve","La disparition des dinosaures","La grande famine irlandaise de la pomme de terre"]'::jsonb, 3, 'Toutes les plantes, identiques, ont réagi de la même façon à la maladie : la récolte entière a été détruite.', 4),
    ('447a3b2f-4484-55b8-b692-c7919b5f43b8'::uuid, 'svt', '3e', 'La transmission du patrimoine génétique', 'À quoi sert la mitose dans l’organisme ?', 'mcq', '["À la croissance, au renouvellement et à la réparation des tissus","À produire les gamètes","À la fécondation","À réduire le nombre de chromosomes"]'::jsonb, 0, 'La mitose donne deux cellules identiques à 46 chromosomes ; la méiose produit les gamètes.', 1),
    ('eb3ad2c8-182b-5de2-ba43-2fc7b5d38fb8'::uuid, 'svt', '3e', 'La transmission du patrimoine génétique', 'Quelle est la 23e paire de chromosomes d’un homme ?', 'mcq', '["XX","XY","YY","Un seul X"]'::jsonb, 1, 'Chez la femme, la 23e paire est XX ; chez l’homme, XY.', 2),
    ('879f9e1c-b767-58cc-8630-51a55fdd1fe8'::uuid, 'svt', '3e', 'La transmission du patrimoine génétique', 'Sans méiose, combien de chromosomes aurait la cellule œuf humaine ?', 'mcq', '["23","46","92","69"]'::jsonb, 2, 'Deux gamètes à 46 chromosomes donneraient 92 : la méiose, en les réduisant à 23, garde le nombre constant.', 3),
    ('383d988a-2c27-5f30-8804-9dd758148ce3'::uuid, 'svt', '3e', 'La transmission du patrimoine génétique', 'Comment appelle-t-on la photographie ordonnée des chromosomes d’une cellule ?', 'mcq', '["L’ADN","Le génotype","L’allèle","Le caryotype"]'::jsonb, 3, 'Le caryotype permet de repérer un chromosome en trop ou en moins, comme dans la trisomie 21.', 4),
    ('21ec780a-35b3-5e46-8c25-3dee361a694c'::uuid, 'svt', '3e', 'Parenté et évolution des êtres vivants', 'À quoi les mammifères doivent-ils en grande partie leur essor ?', 'mcq', '["À la disparition des dinosaures non aviens","À la sortie des eaux","À l’apparition d’Homo sapiens","À l’explosion du Cambrien"]'::jsonb, 0, 'Après chaque extinction de masse, les survivants se diversifient dans les milieux libérés.', 1),
    ('5b58540a-dfd4-5734-9ba7-2c50f932d021'::uuid, 'svt', '3e', 'Parenté et évolution des êtres vivants', 'L’aile d’un oiseau et l’aile d’un insecte sont un exemple…', 'mcq', '["d’homologie","de convergence","de mutation","de spéciation"]'::jsonb, 1, 'Elles se ressemblent par la fonction, mais n’ont pas le même plan d’organisation : ce n’est pas un héritage commun.', 2),
    ('5541b118-89ae-5950-a587-abab23f6d847'::uuid, 'svt', '3e', 'Parenté et évolution des êtres vivants', 'À quand remonte l’explosion du Cambrien ?', 'mcq', '["−66 millions d’années","−3,8 milliards d’années","−540 millions d’années","−300 000 ans"]'::jsonb, 2, 'Il y a environ 540 millions d’années, les formes animales se diversifient brusquement.', 3),
    ('544a8784-157a-58c8-8186-0dd7786469cf'::uuid, 'svt', '3e', 'Parenté et évolution des êtres vivants', 'Dans un arbre phylogénétique, que représente une branche ?', 'mcq', '["Un ancêtre commun","Une extinction","Un fossile daté","Une lignée"]'::jsonb, 3, 'Les branches sont des lignées ; les nœuds, des ancêtres communs hypothétiques.', 4),
    ('a67cc88e-fa7e-5cda-b923-e8537a5959dc'::uuid, 'svt', '3e', 'L’évolution des espèces et la sélection naturelle', 'Selon Darwin, pourquoi y a-t-il compétition entre les individus ?', 'mcq', '["Parce qu’ils produisent plus de descendants que le milieu ne peut en nourrir","Parce qu’ils sont tous identiques","Parce que le milieu ne change jamais","Parce que les mutations sont dirigées"]'::jsonb, 0, 'Tous ne peuvent pas survivre : les mieux adaptés se reproduisent davantage.', 1),
    ('0f5b8c92-d779-5671-9f0a-fb6e00731544'::uuid, 'svt', '3e', 'L’évolution des espèces et la sélection naturelle', 'Qu’est-ce que la sélection sexuelle ?', 'mcq', '["La sélection par les prédateurs","La sélection des caractères qui facilitent l’accès aux partenaires, même coûteux","Le hasard dans les petites populations","Le choix du sexe des petits par les parents"]'::jsonb, 1, 'La queue du paon, encombrante, est favorisée parce qu’elle attire les femelles.', 2),
    ('20c80894-e540-5a28-8b53-9c134eeb2031'::uuid, 'svt', '3e', 'L’évolution des espèces et la sélection naturelle', 'Comment expliquer correctement le long cou des girafes ?', 'mcq', '["Elles ont allongé leur cou à force de tendre vers les branches","Leur cou s’est allongé parce qu’elles en avaient besoin","Celles dont le cou était déjà plus long se sont mieux reproduites","Elles ont décidé d’évoluer"]'::jsonb, 2, 'Les variations existaient avant ; le milieu a favorisé les cous longs. L’évolution n’a pas de but.', 3),
    ('36cd6457-c979-56cd-8a6c-04e8cb9c28fd'::uuid, 'svt', '3e', 'L’évolution des espèces et la sélection naturelle', 'Que montrent les variations de la taille du bec des pinsons des Galápagos ?', 'mcq', '["Que les pinsons choisissent la forme de leur bec","Que les becs grandissent à force de servir","Que l’évolution vise la perfection","Que la sélection naturelle agit selon les sécheresses"]'::jsonb, 3, 'Les sécheresses changent les graines disponibles, et donc les becs avantagés : la sélection s’observe en quelques années.', 4),
    ('011f4fcb-dfdd-589e-9fb2-e5942e6487d0'::uuid, 'svt', '3e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Que permet de fabriquer, plus exactement, l’information portée par un gène ?', 'mcq', '["Une protéine","Un chromosome","Une cellule","Un sucre"]'::jsonb, 0, 'Un gène est un segment d’ADN qui porte l’information de fabrication d’une protéine.', 1),
    ('b9c2560f-e865-5bc6-b78a-48be57c138d1'::uuid, 'svt', '3e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Qui a décrit la structure de l’ADN en 1953 ?', 'mcq', '["Darwin et Wallace","Watson, Crick, Franklin et Wilkins","Mendel","Pasteur et Koch"]'::jsonb, 1, 'Ils ont établi que l’ADN est une double hélice de deux brins complémentaires.', 2),
    ('c9291664-7c6a-5517-9593-5dc8b8280a6f'::uuid, 'svt', '3e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Lequel de ces caractères est un caractère individuel ?', 'mcq', '["Avoir deux yeux","Avoir une colonne vertébrale","Le groupe sanguin","Avoir cinq doigts"]'::jsonb, 2, 'Le groupe sanguin varie d’une personne à l’autre ; les trois autres sont des caractères d’espèce.', 3),
    ('b6628b2e-73c9-5102-84cc-7e2e1137c977'::uuid, 'svt', '3e', 'La diversité des individus au sein d’une espèce et la localisation de l’information génétique', 'Combien de bases différentes composent l’ADN ?', 'mcq', '["Deux","Vingt","Quarante-six","Quatre"]'::jsonb, 3, 'A, T, G et C : un alphabet de quatre lettres, universel dans tout le vivant.', 4),
    ('012ae863-55e1-566f-b7cc-5ed9d6b581da'::uuid, 'svt', '3e', 'La diversité génétique au sein d’une espèce, le gène et ses allèles', 'Lequel de ces agents peut provoquer des mutations ?', 'mcq', '["Les ultraviolets","L’eau potable","Le sommeil","Une alimentation variée"]'::jsonb, 0, 'Ultraviolets, tabac, certains produits chimiques et rayonnements ionisants peuvent modifier l’ADN.', 1),
    ('9e3cccfb-1412-54b1-ab6e-84813e8b007c'::uuid, 'svt', '3e', 'La diversité génétique au sein d’une espèce, le gène et ses allèles', 'Que signifie être homozygote pour un gène ?', 'mcq', '["Porter deux allèles différents","Porter deux allèles identiques","Ne porter aucun allèle","Porter trois allèles"]'::jsonb, 1, 'Homozygote : deux allèles identiques ; hétérozygote : deux allèles différents.', 2),
    ('10949f0b-45f9-5097-82f2-4b1621b2c16b'::uuid, 'svt', '3e', 'La diversité génétique au sein d’une espèce, le gène et ses allèles', 'Quel est le génotype d’une personne du groupe sanguin O ?', 'mcq', '["A//O","B//O","O//O","A//B"]'::jsonb, 2, 'L’allèle O est récessif : il ne s’exprime que s’il est présent en double.', 3),
    ('be546d32-1e0f-54c8-b5b7-cebd90f7aa0f'::uuid, 'svt', '3e', 'La diversité génétique au sein d’une espèce, le gène et ses allèles', 'Quels allèles du groupe sanguin sont codominants ?', 'mcq', '["A et O","B et O","O et O","A et B"]'::jsonb, 3, 'A et B s’expriment tous les deux : c’est le groupe AB.', 4),
    ('b5ce3c70-5088-5523-95d3-528994151a51'::uuid, 'svt', '3e', 'La transmission de l’information génétique et des informations héréditaires', 'Quelle application de la génétique consiste à corriger un gène ?', 'mcq', '["La thérapie génique","Le diagnostic prénatal","La sélection variétale","L’empreinte génétique"]'::jsonb, 0, 'La thérapie génique vise à corriger un gène défaillant ; ces applications posent des questions éthiques.', 1),
    ('b6b2fd62-e42b-52bc-9e86-9f1bc5d6c4c8'::uuid, 'svt', '3e', 'La transmission de l’information génétique et des informations héréditaires', 'Qu’obtient-on à la fin de la réplication d’une molécule d’ADN ?', 'mcq', '["Deux molécules différentes","Deux molécules identiques","Une protéine","Quatre chromosomes"]'::jsonb, 1, 'Chaque brin sert de modèle, et la complémentarité A-T, G-C garantit une copie fidèle.', 2),
    ('34d6c7da-92ab-5262-a446-28df306e75f5'::uuid, 'svt', '3e', 'La transmission de l’information génétique et des informations héréditaires', 'Quel caractère, porté par le chromosome X, touche presque uniquement les garçons ?', 'mcq', '["La trisomie 21","Le groupe sanguin","Le daltonisme","La couleur des yeux"]'::jsonb, 2, 'Le daltonisme et l’hémophilie sont portés par le chromosome X.', 3),
    ('8f8331c3-1f95-5cab-bccb-e50262709546'::uuid, 'svt', '3e', 'La transmission de l’information génétique et des informations héréditaires', 'À quoi servent les empreintes génétiques ?', 'mcq', '["À soigner un cancer","À vacciner","À corriger un gène","À identifier une personne"]'::jsonb, 3, 'L’ADN de chacun est unique (sauf chez les vrais jumeaux) : il permet l’identification.', 4),
    ('f6577ebe-8f70-5e17-9de7-f67568c07f47'::uuid, 'svt', '3e', 'L’effort physique', 'À quoi sert l’échauffement ?', 'mcq', '["À préparer progressivement le cœur, les muscles et les articulations","À épuiser les réserves avant l’effort","À se déshydrater","À augmenter la fréquence cardiaque de repos"]'::jsonb, 0, 'Il met le corps en route peu à peu et limite les blessures.', 1),
    ('476a4800-57fb-50ab-ab4b-4e363760a109'::uuid, 'svt', '3e', 'L’effort physique', 'Par combien le débit cardiaque peut-il être multiplié à l’effort ?', 'mcq', '["Par 2","Par 5","Par 50","Il ne change pas"]'::jsonb, 1, 'Le cœur bat plus vite et plus fort : le débit est multiplié par 5.', 2),
    ('ff00848e-3122-5d95-907f-1219c2b187b4'::uuid, 'svt', '3e', 'L’effort physique', 'Dans quelle réserve le muscle puise-t-il pour les efforts longs ?', 'mcq', '["Le calcium des os","Les protéines du cœur","Les lipides","L’eau"]'::jsonb, 2, 'Après le glycogène du muscle et le glucose du sang, les lipides prennent le relais.', 3),
    ('0b880938-05bb-5010-98b5-942c37ddc737'::uuid, 'svt', '3e', 'L’effort physique', 'Que produit la fermentation lactique ?', 'mcq', '["De l’urée","Du glycogène","Du dioxygène","De l’acide lactique"]'::jsonb, 3, 'Quand le dioxygène manque, cette voie fournit peu d’énergie et produit de l’acide lactique.', 4),
    ('c02fe08e-2400-5356-834c-3f3c37bc9ec1'::uuid, 'svt', '3e', 'Sport et santé', 'Pourquoi les régimes restrictifs sont-ils dangereux à l’adolescence ?', 'mcq', '["Parce qu’ils compromettent la croissance","Parce qu’ils font grandir trop vite","Parce qu’ils améliorent trop les performances","Parce qu’ils remplacent le sport"]'::jsonb, 0, 'L’adolescent en croissance a des besoins élevés : aucun complément ne remplace une alimentation variée.', 1),
    ('33fde2c9-bf95-5e7f-852f-ed26e261263b'::uuid, 'svt', '3e', 'Sport et santé', 'Quel apport sert surtout à la réparation des muscles ?', 'mcq', '["Les glucides complexes","Les protéines","Les fibres","L’eau"]'::jsonb, 1, 'Les protéines réparent les muscles ; les glucides complexes soutiennent l’endurance.', 2),
    ('c37b76ea-8e3a-5ed3-ae3a-43616e22b955'::uuid, 'svt', '3e', 'Sport et santé', 'Quel diabète l’activité physique aide-t-elle à prévenir ?', 'mcq', '["Le diabète de type 1","Aucun diabète","Le diabète de type 2","Tous les diabètes sans exception"]'::jsonb, 2, 'En augmentant la dépense énergétique, l’activité aide à contrôler le poids et prévient le diabète de type 2.', 3),
    ('290d1247-99dd-5aa7-843b-f03a5bbc9560'::uuid, 'svt', '3e', 'Sport et santé', 'Quels bénéfices sociaux l’activité physique apporte-t-elle ?', 'mcq', '["Une meilleure vue","Une taille plus grande","Une peau plus claire","L’appartenance à un groupe, des règles partagées, la coopération"]'::jsonb, 3, 'La santé selon l’OMS est aussi sociale : le sport crée des liens.', 4),
    ('81e7a997-902c-5381-a567-9dc0dadc476e'::uuid, 'svt', '3e', 'Système nerveux et comportement responsable', 'Pourquoi le manque de sommeil nuit-il aux apprentissages ?', 'mcq', '["Parce que le sommeil consolide les apprentissages","Parce que dormir détruit des neurones","Parce que le sommeil ne sert qu’aux muscles","Parce que le sommeil n’a aucun rôle"]'::jsonb, 0, 'En manquer dégrade la mémoire, l’humeur et l’attention.', 1),
    ('53d85f99-95c3-59de-85a9-a6534e5a1c88'::uuid, 'svt', '3e', 'Système nerveux et comportement responsable', 'Combien de neurones compte environ le cerveau adulte ?', 'mcq', '["86 millions","86 milliards","8 600","86 000 milliards"]'::jsonb, 1, 'Environ 86 milliards de neurones, reliés par des milliers de milliards de connexions.', 2),
    ('84f08750-4e43-5025-b711-507fd51348cd'::uuid, 'svt', '3e', 'Système nerveux et comportement responsable', 'Quelle partie du neurone transmet le message nerveux ?', 'mcq', '["Les dendrites","Le corps cellulaire","L’axone","Le récepteur sensoriel"]'::jsonb, 2, 'Les dendrites reçoivent, l’axone transmet jusqu’à la synapse.', 3),
    ('cf17e8e7-1af7-5e9a-9ebb-46628447a455'::uuid, 'svt', '3e', 'Système nerveux et comportement responsable', 'Où agissent la plupart des drogues ?', 'mcq', '["Dans les os","Dans les muscles","Dans la peau","Au niveau des synapses"]'::jsonb, 3, 'Elles perturbent les neurotransmetteurs qui font passer le message d’un neurone à l’autre.', 4),
    ('07fdbda9-fe64-59f4-8b0a-cd8a9ac67c9f'::uuid, 'svt', '3e', 'Alimentation et digestion', 'Quelles bactéries peuvent provoquer des intoxications alimentaires ?', 'mcq', '["Salmonella et Listeria","Les bactéries du microbiote intestinal","Les levures du pain","Les ferments du yaourt"]'::jsonb, 0, 'Chaîne du froid, cuisson et lavage des mains évitent ces intoxications.', 1),
    ('433229f5-77e3-57ea-be84-9f1af5ffae2c'::uuid, 'svt', '3e', 'Alimentation et digestion', 'Quelle enzyme attaque l’amidon ?', 'mcq', '["La lipase","L’amylase","La protéase","La bile"]'::jsonb, 1, 'Chaque enzyme est spécifique : l’amylase pour l’amidon, les protéases pour les protéines, les lipases pour les graisses.', 2),
    ('2bda0ed8-cdcf-540c-8414-777f122092c0'::uuid, 'svt', '3e', 'Alimentation et digestion', 'Que devient l’amidon au terme de la digestion ?', 'mcq', '["Des acides aminés","Des acides gras","Du glucose","Du glycérol"]'::jsonb, 2, 'L’amidon, glucide complexe, est simplifié en glucose, qui traverse la paroi intestinale.', 3),
    ('98d4dc1a-d381-5e27-88fe-32a38128eed0'::uuid, 'svt', '3e', 'Alimentation et digestion', 'Quel est le rôle du gros intestin ?', 'mcq', '["Digérer les protéines","Absorber l’essentiel du glucose","Produire la salive","Réabsorber l’eau et former les matières fécales"]'::jsonb, 3, 'Il héberge aussi une grande partie du microbiote ; l’absorption des nutriments se fait avant, dans l’intestin grêle.', 4),
    ('36d54f11-3ead-5414-ae9a-7b084202d897'::uuid, 'svt', '3e', 'La contamination par les micro-organismes et la mémoire immunitaire', 'Quelle maladie la vaccination a-t-elle permis d’éradiquer en 1980 ?', 'mcq', '["La variole","La grippe","La tuberculose","Le rhume"]'::jsonb, 0, 'Grâce à une immunité collective suffisante, le virus a cessé de circuler.', 1),
    ('863a50fe-6faa-5dd1-bb6f-ffc93bfaca74'::uuid, 'svt', '3e', 'La contamination par les micro-organismes et la mémoire immunitaire', 'Que fait un lymphocyte T ?', 'mcq', '["Il fabrique des anticorps","Il détruit directement les cellules infectées","Il englobe et digère les microbes","Il referme les plaies"]'::jsonb, 1, 'Les lymphocytes B fabriquent les anticorps ; les T détruisent les cellules infectées.', 2),
    ('d7df6268-943e-5a86-8d5c-4d1b173fbb27'::uuid, 'svt', '3e', 'La contamination par les micro-organismes et la mémoire immunitaire', 'Combien de temps la réponse adaptative met-elle à se mettre en place lors d’un premier contact ?', 'mcq', '["Quelques secondes","Quelques minutes","Quelques jours","Plusieurs années"]'::jsonb, 2, 'La réponse innée agit en minutes ou en heures ; la réponse adaptative, spécifique, demande quelques jours.', 3),
    ('b650203f-f3a8-5fc7-ab26-ea01d3fc552f'::uuid, 'svt', '3e', 'La contamination par les micro-organismes et la mémoire immunitaire', 'Pourquoi peut-on attraper plusieurs fois un rhume ?', 'mcq', '["Parce que la mémoire immunitaire n’existe pas","Parce que les anticorps disparaissent en une heure","Parce que le rhume est une maladie bactérienne","Parce qu’il est provoqué chaque fois par un virus différent"]'::jsonb, 3, 'Un anticorps ne reconnaît qu’un seul antigène : un nouveau virus n’est pas reconnu.', 4),
    ('08a47f43-51a4-5259-b22b-d0d766b92380'::uuid, 'svt', '3e', 'Prévenir et soigner les infections', 'Qu’est-ce qu’un antiviral ?', 'mcq', '["Un médicament qui cible les virus, peu nombreux et très spécifiques","Un antibiotique à large spectre","Un vaccin","Un sérum d’anticorps"]'::jsonb, 0, 'Les antibiotiques n’agissent pas sur les virus ; les antiviraux existent, mais pour peu de virus.', 1),
    ('b8545a9a-f161-52bd-826d-15a7fd79c6d8'::uuid, 'svt', '3e', 'Prévenir et soigner les infections', 'Contre quelle infection un antibiotique est-il inutile ?', 'mcq', '["Une angine bactérienne","La grippe","Une plaie infectée par des bactéries","La tuberculose"]'::jsonb, 1, 'La grippe est due à un virus : les antibiotiques n’ont aucun effet dessus.', 2),
    ('f4ac1739-9ed0-5a89-9bb7-66aaf05fb352'::uuid, 'svt', '3e', 'Prévenir et soigner les infections', 'Quel test permet de distinguer une angine bactérienne d’une angine virale ?', 'mcq', '["L’antibiogramme","Le caryotype","Le test rapide d’angine","La radiographie"]'::jsonb, 2, 'Il évite de prescrire un antibiotique inutile ; l’antibiogramme, lui, choisit la molécule efficace.', 3),
    ('5b1e1248-fb82-514c-8002-0ce7ad433ba6'::uuid, 'svt', '3e', 'Prévenir et soigner les infections', 'Comment un usage excessif des antibiotiques favorise-t-il l’antibiorésistance ?', 'mcq', '["Il crée directement des mutations de résistance","Il renforce le système immunitaire","Il détruit les virus","Il sélectionne les bactéries résistantes, qui survivent et se multiplient"]'::jsonb, 3, 'C’est la sélection naturelle appliquée aux microbes : d’où « les antibiotiques, c’est pas automatique ».', 4),
    ('4c27ecd7-bd81-572b-9e9d-6ecdb77e11f7'::uuid, 'svt', '3e', 'La puberté et le fonctionnement des appareils génitaux', 'Comment appelle-t-on l’arrêt du fonctionnement cyclique des ovaires ?', 'mcq', '["La ménopause","La puberté","L’ovulation","La nidation"]'::jsonb, 0, 'Chez l’homme, la production de spermatozoïdes n’a pas d’arrêt net.', 1),
    ('8f8e4a97-306f-5ef7-b453-1ac26d6f8b64'::uuid, 'svt', '3e', 'La puberté et le fonctionnement des appareils génitaux', 'Quelle hormone les testicules produisent-ils ?', 'mcq', '["Les œstrogènes","La testostérone","L’insuline","La progestérone"]'::jsonb, 1, 'Les testicules produisent la testostérone ; les ovaires, les œstrogènes et la progestérone.', 2),
    ('e96173d5-51d1-52b2-919b-8f9b56a323b0'::uuid, 'svt', '3e', 'La puberté et le fonctionnement des appareils génitaux', 'Lequel de ces changements est un caractère sexuel secondaire ?', 'mcq', '["Le fonctionnement des ovaires","La production de spermatozoïdes","La mue de la voix","La formation des gamètes"]'::jsonb, 2, 'Pilosité, seins, mue de la voix ou poussée de croissance sont secondaires ; le fonctionnement des organes génitaux est primaire.', 3),
    ('56afc6f8-f9f2-593b-a049-3e3c2692609a'::uuid, 'svt', '3e', 'La puberté et le fonctionnement des appareils génitaux', 'Quand le stock d’ovocytes d’une femme est-il constitué ?', 'mcq', '["À la puberté","À chaque cycle","À la ménopause","Dès la naissance"]'::jsonb, 3, 'Le stock est constitué dès la naissance, alors que les spermatozoïdes sont fabriqués en permanence.', 4),
    ('30a23161-3bc4-52fc-b439-9d67cc612c13'::uuid, 'svt', '3e', 'De la fécondation à la naissance', 'Pourquoi le placenta n’est-il pas un filtre absolu ?', 'mcq', '["Parce que l’alcool, le tabac, les drogues et certains virus le traversent","Parce qu’il laisse passer le sang maternel","Parce qu’il bloque le dioxygène","Parce qu’il disparaît au sixième mois"]'::jsonb, 0, 'C’est pourquoi aucun alcool, ni tabac, ni drogue n’est sans risque pendant la grossesse.', 1),
    ('07a9c19e-b4fc-5bcc-afcb-75dc203ecab5'::uuid, 'svt', '3e', 'De la fécondation à la naissance', 'Qu’est-ce qui détermine le sexe de l’enfant ?', 'mcq', '["Le chromosome apporté par l’ovule","Le chromosome apporté par le spermatozoïde","La température de la mère","L’alimentation pendant la grossesse"]'::jsonb, 1, 'L’ovule apporte toujours un X ; le spermatozoïde apporte un X ou un Y.', 2),
    ('cb3d01d4-6c13-5e03-978b-ff6170098e0b'::uuid, 'svt', '3e', 'De la fécondation à la naissance', 'Quelle taille mesure l’embryon à 8 semaines ?', 'mcq', '["Environ 50 cm","Environ 15 cm","Environ 3 cm","Environ 3 mm"]'::jsonb, 2, 'À 8 semaines, tous les organes sont en place ; le bébé mesure environ 50 cm à terme.', 3),
    ('7bc05839-1374-5a43-873f-a1a7851b690e'::uuid, 'svt', '3e', 'De la fécondation à la naissance', 'Qu’appelle-t-on la délivrance ?', 'mcq', '["La naissance du bébé","La coupure du cordon","La première respiration","L’expulsion du placenta après la naissance"]'::jsonb, 3, 'Contractions, expulsion du bébé, coupure du cordon, puis délivrance du placenta.', 4),
    ('04c1b9f2-dc7d-589c-a7fc-f9e1f456f715'::uuid, 'svt', '3e', 'La contraception et la procréation médicalement assistée', 'Quelle proportion de couples consulte pour des difficultés à concevoir ?', 'mcq', '["Environ un sur six","Environ un sur deux","Environ un sur cent","Environ un sur mille"]'::jsonb, 0, 'L’infertilité peut être féminine, masculine, mixte ou inexpliquée.', 1),
    ('7f8225e2-ced2-580f-80e6-66d93a49d300'::uuid, 'svt', '3e', 'La contraception et la procréation médicalement assistée', 'Quelle loi a autorisé l’IVG en France en 1975 ?', 'mcq', '["La loi Neuwirth","La loi Veil","La loi Évin","La loi de bioéthique"]'::jsonb, 1, 'La loi Veil a fait de l’IVG un droit ; elle est aujourd’hui prise en charge à 100 %.', 2),
    ('477647c9-fe36-5ccf-a008-6f1d6c826810'::uuid, 'svt', '3e', 'La contraception et la procréation médicalement assistée', 'Qu’est-ce que l’ICSI ?', 'mcq', '["Le dépôt du sperme dans l’utérus","Une stimulation hormonale de l’ovulation","L’injection d’un spermatozoïde unique dans l’ovule","Le don de gamètes"]'::jsonb, 2, 'C’est une technique de laboratoire, proche de la FIV, utilisée surtout pour une infertilité masculine.', 3),
    ('8a11d2ea-e440-5606-b9c9-6b8a5cabf457'::uuid, 'svt', '3e', 'La contraception et la procréation médicalement assistée', 'Lequel de ces moyens de contraception est définitif ?', 'mcq', '["La pilule","L’implant","Le stérilet","La vasectomie"]'::jsonb, 3, 'La vasectomie et la ligature des trompes sont réservées à l’adulte, après réflexion et délai légal.', 4),
    ('e7299cd2-b07c-57cc-b11d-06c8185982d9'::uuid, 'technologie', '3e', 'Les OST', 'Pour une lampe de lecture, quelle est la matière d’œuvre ?', 'mcq', '["Le verre de l’ampoule","L’électricité du réseau","La lumière de la pièce","La personne qui lit"]'::jsonb, 2, 'La matière d’œuvre est ce sur quoi l’objet agit : la lampe modifie la lumière de la pièce. Celui qui lit est l’utilisateur.', 1),
    ('cbb393a2-086e-522d-8a37-2cc9ee76282f'::uuid, 'technologie', '3e', 'Les OST', 'Lequel de ces exemples est un système technique ?', 'mcq', '["Un tournevis","Une chaise","Un marteau","Un ascenseur"]'::jsonb, 3, 'Un ascenseur associe plusieurs objets qui travaillent ensemble, avec électronique et programme ; les trois autres répondent au besoin par eux-mêmes.', 2),
    ('938a7bc8-5dd9-55e3-b204-989925aa8473'::uuid, 'technologie', '3e', 'Les OST', 'Quelle fonction d’usage le vélo garde-t-il depuis 150 ans ?', 'mcq', '["Se déplacer","Freiner","Transmettre le mouvement","Éclairer"]'::jsonb, 0, 'Sa fonction d’usage n’a pas changé ; ses matériaux, sa transmission, ses freins et son assistance électrique, si.', 3),
    ('8851afe9-e4d5-505a-8d72-00f219c6cf57'::uuid, 'technologie', '3e', 'Les OST', 'La bougie, la lampe à huile, l’ampoule et la LED forment…', 'mcq', '["une lignée d’objets techniques","une famille d’objets techniques","un système technique","une chaîne d’énergie"]'::jsonb, 1, 'Ils remplissent la même fonction d’usage, éclairer, par des solutions différentes : c’est une famille.', 4),
    ('641272a0-d52e-5b04-a730-bc37252f657b'::uuid, 'technologie', '3e', 'La fonction technique et le principe technique', 'Sur quel principe technique reposent tous les freins de vélo ?', 'mcq', '["La gravité","Le magnétisme","Le frottement","La dilatation"]'::jsonb, 2, 'Patins, disque ou rétropédalage : ces solutions différentes exploitent toutes le frottement.', 1),
    ('1b3f2dfd-741c-5cc0-9d14-fdc68f0c6da8'::uuid, 'technologie', '3e', 'La fonction technique et le principe technique', 'Comment exprime-t-on une fonction d’usage ?', 'mcq', '["Par un verbe à l’infinitif","Par un nombre","Par le nom d’un composant","Par une unité de mesure"]'::jsonb, 0, 'On écrit le service rendu par un verbe à l’infinitif : « se déplacer », « éclairer ».', 2),
    ('cc7ded8c-6339-50cf-a8d1-21b9f8f5003d'::uuid, 'technologie', '3e', 'La fonction technique et le principe technique', 'Pour un vélo, lequel de ces éléments est une solution technique ?', 'mcq', '["Freiner","Le frottement","Se déplacer","Un frein à disque"]'::jsonb, 3, 'Le frein à disque est le composant concret retenu ; freiner est une fonction technique, le frottement un principe, se déplacer la fonction d’usage.', 3),
    ('b873af74-51c4-5d68-8d1c-6433bacab334'::uuid, 'technologie', '3e', 'La fonction technique et le principe technique', 'Dans l’exigence « distance de freinage : moins de 5 m à 20 km/h », que désigne « moins de 5 m » ?', 'mcq', '["Le critère","Le niveau","La fonction d’usage","Le principe technique"]'::jsonb, 1, 'Le critère est ce qu’on mesure (la distance de freinage) ; le niveau est la valeur à atteindre.', 4),
    ('c9eb9fb3-12a8-5e91-b3ef-8c521fc9e1c4'::uuid, 'technologie', '3e', 'Cycle de vie d’un OST', 'Qu’est-ce que l’obsolescence logicielle ?', 'mcq', '["Une pièce qui n’existe plus","L’arrêt des mises à jour","Un simple effet de mode","Une batterie usée"]'::jsonb, 1, 'L’objet fonctionne encore mais ne reçoit plus de mises à jour ; la pièce introuvable relève de l’obsolescence technique.', 1),
    ('71954eac-adde-55cc-943b-0129e898ace5'::uuid, 'technologie', '3e', 'Cycle de vie d’un OST', 'Quel est le principe du modèle économique linéaire ?', 'mcq', '["Extraire, fabriquer, jeter","Réduire, réemployer, recycler","Réparer avant de remplacer","Louer au lieu d’acheter"]'::jsonb, 0, 'Le modèle linéaire épuise les ressources ; l’économie circulaire cherche à refermer la boucle.', 2),
    ('05878b8f-10a9-5913-8959-5e25cf4537d8'::uuid, 'technologie', '3e', 'Cycle de vie d’un OST', 'Pourquoi un sac réutilisable n’est-il pas forcément plus écologique qu’un sac plastique ?', 'mcq', '["Il ne peut jamais être recyclé","Il est toujours fait en pétrole","Il n’est avantageux qu’après un certain nombre de réemplois","Il pollue pendant son utilisation"]'::jsonb, 2, 'Il coûte plus cher à fabriquer : seule l’analyse du cycle de vie dit à partir de combien d’usages il devient gagnant.', 3),
    ('d86a24c9-f0b0-55bf-b862-64c44ade2ccb'::uuid, 'technologie', '3e', 'Cycle de vie d’un OST', 'Pourquoi les DEEE ne vont-ils jamais à la poubelle ordinaire ?', 'mcq', '["Ils sont trop lourds","Ils sont trop volumineux","Ils brûlent mal","Ils contiennent des métaux précieux et des substances dangereuses"]'::jsonb, 3, 'Déposés en déchèterie ou en point de collecte, leurs métaux sont récupérés et leurs substances dangereuses traitées.', 4),
    ('49bef032-e10e-5506-84c9-43e79673ad50'::uuid, 'technologie', '3e', 'OST et interacteurs extérieurs', 'Pour un lampadaire de rue, « résister aux intempéries » est…', 'mcq', '["la fonction principale","une fonction contrainte","une solution technique","un principe technique"]'::jsonb, 1, 'Elle relie l’objet à un seul interacteur, le milieu : c’est une fonction contrainte.', 1),
    ('7b977e32-b91b-5352-8ba9-d090e5d4cf26'::uuid, 'technologie', '3e', 'OST et interacteurs extérieurs', 'Lequel de ces interacteurs fait partie du milieu ?', 'mcq', '["L’utilisateur","Le budget","La poussière","Les normes"]'::jsonb, 2, 'Le milieu, c’est l’air, l’eau, la température, la poussière ou les vibrations qui entourent l’objet.', 2),
    ('565c686c-8ea1-54f8-aa9d-3e60ab1142dd'::uuid, 'technologie', '3e', 'OST et interacteurs extérieurs', 'Quels interacteurs la fonction principale du lampadaire relie-t-elle ?', 'mcq', '["Le réseau électrique et le budget","Les intempéries et les normes","Le paysage urbain et la commune","Le piéton et la chaussée"]'::jsonb, 3, 'La fonction principale relie deux interacteurs à travers l’objet : permettre au piéton de voir la chaussée la nuit.', 3),
    ('3a55ac9c-6c89-5952-bd94-e744107fee5a'::uuid, 'technologie', '3e', 'OST et interacteurs extérieurs', 'Parmi ces interacteurs, lequel impose une limite de conception plutôt qu’un élément physique ?', 'mcq', '["L’énergie","Le budget","La matière d’œuvre","Le milieu"]'::jsonb, 1, 'Le budget, comme l’esthétique, ne touche pas l’objet physiquement : il borne les choix du concepteur.', 4),
    ('83f3fd91-6375-58f9-8d85-a27836cfdf3c'::uuid, 'technologie', '3e', 'OST et contraintes', 'Que signifie une flexibilité F0 dans un cahier des charges ?', 'mcq', '["Une exigence négociable","Une exigence impérative","Une exigence peu négociable","Une exigence facultative"]'::jsonb, 1, 'F0 est impératif, F1 peu négociable, F2 négociable.', 1),
    ('22285690-d910-5f77-9e49-d085493e9e39'::uuid, 'technologie', '3e', 'OST et contraintes', '« Être recyclable à 90 % » relève de quelle famille de contraintes ?', 'mcq', '["Économiques","Esthétiques","Environnementales","Ergonomiques"]'::jsonb, 2, 'Recyclabilité, consommation et matériaux interdits sont des contraintes environnementales.', 2),
    ('1e90c2c1-3d78-5e3f-91fa-db89f948986b'::uuid, 'technologie', '3e', 'OST et contraintes', 'Laquelle de ces formulations est une vraie exigence ?', 'mcq', '["Le casque doit être léger","Le casque doit être agréable","Le casque doit plaire aux clients","Masse inférieure à 300 g, tolérance ±20 g"]'::jsonb, 3, 'Elle donne un critère (la masse), un niveau (300 g) et une flexibilité (±20 g) : on peut la vérifier.', 3),
    ('5e1afe39-3883-5bfb-82fa-756db53bf25b'::uuid, 'technologie', '3e', 'OST et contraintes', 'Que coûte le plus souvent le fait de rendre un objet plus sûr ?', 'mcq', '["Il devient plus lourd","Il devient moins cher","Il devient plus rapide à fabriquer","Rien, c’est sans contrepartie"]'::jsonb, 0, 'Les contraintes s’opposent : la sécurité ajoute souvent de la matière, donc du poids. Concevoir, c’est arbitrer.', 4),
    ('36efdf11-4094-5b34-b9ec-fb2f0627dfc8'::uuid, 'technologie', '3e', 'Critères de choix d’un OST', 'Quelle est la dernière étape d’un tableau multicritère ?', 'mcq', '["Noter chaque case","Additionner les totaux pondérés","Choisir les solutions à comparer","Dessiner chaque solution"]'::jsonb, 1, 'On note les cases, on affecte les coefficients, puis on additionne les totaux pondérés pour départager les solutions.', 1),
    ('73a4c86f-8e37-5e6f-adde-629cf2f52e76'::uuid, 'technologie', '3e', 'Critères de choix d’un OST', 'Par rapport à une ampoule à filament, une LED…', 'mcq', '["coûte moins cher à l’achat et dure moins longtemps","consomme sept fois plus","coûte plus cher à l’achat mais consomme peu et dure bien plus longtemps","a la même durée de vie"]'::jsonb, 2, 'Son prix d’achat est plus élevé, mais sa faible consommation et sa durée de vie la rendent moins chère au coût global.', 2),
    ('3d6c071e-edf0-5687-a584-a2ea47e4d987'::uuid, 'technologie', '3e', 'Critères de choix d’un OST', 'Quelle question pose le critère d’encombrement ?', 'mcq', '["Combien de temps sans panne ?","Est-il conforme aux normes ?","Est-il facile à utiliser ?","Tient-il dans l’espace disponible ?"]'::jsonb, 3, 'L’encombrement et la masse vérifient que l’objet trouve sa place ; la fiabilité, l’ergonomie et la sécurité posent les autres questions.', 3),
    ('090ca5d4-37bc-5110-b3dd-cce77cd4fa3a'::uuid, 'technologie', '3e', 'Critères de choix d’un OST', 'Sur quels critères une solution doit-elle d’abord atteindre le niveau exigé ?', 'mcq', '["Les critères impératifs (F0)","Les critères esthétiques","Les critères négociables (F2)","Le seul critère du prix"]'::jsonb, 0, 'Une solution qui manque un critère F0 est écartée, quel que soit son score ailleurs.', 4),
    ('9c8a8b5c-f893-5463-b658-7035a1aeac50'::uuid, 'technologie', '3e', 'La chaîne d’énergie', 'Dans quelle fonction range-t-on une résistance chauffante ?', 'mcq', '["Alimenter","Distribuer","Convertir","Transmettre"]'::jsonb, 2, 'Elle transforme l’énergie électrique en chaleur : c’est un actionneur, qui assure la fonction « convertir ».', 1),
    ('290306a3-915f-5846-ba0c-50cf58241ca2'::uuid, 'technologie', '3e', 'La chaîne d’énergie', 'Comment appelle-t-on le résultat final de la chaîne d’énergie ?', 'mcq', '["L’acquisition","L’action","La consigne","Le traitement"]'::jsonb, 1, 'L’action, c’est la roue qui tourne, la porte qui s’ouvre ou l’air qui se réchauffe.', 2),
    ('e7669b11-16ef-5a2a-8527-bfedfa4d5925'::uuid, 'technologie', '3e', 'La chaîne d’énergie', 'Dans un portail automatique, quelle fonction assure le réseau 230 V ?', 'mcq', '["Convertir","Distribuer","Transmettre","Alimenter"]'::jsonb, 3, 'Le réseau fournit l’énergie ; le relais la distribue, le moteur la convertit, le réducteur et la crémaillère la transmettent.', 3),
    ('0a4247c2-0f35-5947-99b7-3b9780819686'::uuid, 'technologie', '3e', 'La chaîne d’énergie', 'Quel rôle joue un réducteur dans la chaîne d’énergie ?', 'mcq', '["Il transmet le mouvement en adaptant vitesse et effort","Il fournit l’énergie","Il laisse passer ou coupe l’énergie sur ordre","Il convertit l’énergie électrique en énergie mécanique"]'::jsonb, 0, 'Le réducteur appartient à la fonction « transmettre » : il ralentit le mouvement pour gagner de l’effort.', 4),
    ('1880326f-050c-5d1e-b8f6-2a96541786b8'::uuid, 'technologie', '3e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme transforme une rotation en translation lente et puissante, comme dans un étau ?', 'mcq', '["Le pignon-crémaillère","La vis-écrou","La bielle-manivelle","Les roues de friction"]'::jsonb, 1, 'La vis-écrou avance peu à chaque tour, mais avec beaucoup de force : étau, presse.', 1),
    ('531e6473-9f05-5038-9758-5ba4f08c35d3'::uuid, 'technologie', '3e', 'Les mécanismes de transmission et de transformation de mouvements', 'Dans quel sens tournent les deux pignons reliés par la chaîne d’un vélo ?', 'mcq', '["En sens inverse","Alternativement dans un sens puis dans l’autre","Dans le même sens","Cela dépend du nombre de dents"]'::jsonb, 2, 'Avec une chaîne, les pignons tournent dans le même sens ; deux engrenages en contact direct tournent en sens inverse.', 2),
    ('7d2a859d-c3ea-5137-990c-d57ece1624cd'::uuid, 'technologie', '3e', 'Les mécanismes de transmission et de transformation de mouvements', 'Un pignon d’entrée de 20 dents entraîne une roue de sortie de 60 dents. Que vaut le rapport de transmission ?', 'mcq', '["3","40","1/40","1/3"]'::jsonb, 3, 'r = dents de l’entrée ÷ dents de la sortie = 20 ÷ 60 = 1/3 : r < 1, c’est un réducteur.', 3),
    ('d8597605-1eb9-5da7-aca7-fab0b8870800'::uuid, 'technologie', '3e', 'Les mécanismes de transmission et de transformation de mouvements', 'Quel mécanisme actionne les soupapes d’un moteur ?', 'mcq', '["Came et poussoir","Poulies-courroie","Pignons-chaîne","Engrenages"]'::jsonb, 0, 'La came transforme la rotation en translation alternative du poussoir, qui ouvre et ferme la soupape.', 4),
    ('f056ec2d-5d91-5e14-b809-e500d953c505'::uuid, 'technologie', '3e', 'Matériaux et procédés', 'Quel est le principal défaut des céramiques ?', 'mcq', '["Elles conduisent l’électricité","Elles rouillent","Elles sont fragiles : elles cassent sans se déformer","Elles sont trop légères"]'::jsonb, 2, 'Très dures et résistantes à la chaleur, elles cassent pourtant d’un coup, sans se déformer avant.', 1),
    ('1a79ff8c-ba9e-5b41-aff4-d5a53d952edd'::uuid, 'technologie', '3e', 'Matériaux et procédés', 'Que désigne la ductilité d’un matériau ?', 'mcq', '["Sa résistance à la rayure","Sa capacité à être étiré en fil","Sa capacité à conduire la chaleur","Sa capacité à reprendre sa forme"]'::jsonb, 1, 'Un matériau ductile, comme le cuivre, s’étire en fil sans rompre.', 2),
    ('93935457-b48c-5103-ac16-5753042d5ed0'::uuid, 'technologie', '3e', 'Matériaux et procédés', 'À quelle famille de matériaux appartient le bois ?', 'mcq', '["Aux métalliques","Aux céramiques","Aux composites","Aux organiques"]'::jsonb, 3, 'Le bois, comme les plastiques, le cuir et le papier, est un matériau organique.', 3),
    ('4e0406b1-1b30-5497-9ae6-36d90d7a37a8'::uuid, 'technologie', '3e', 'Matériaux et procédés', 'Pourquoi un composite plastique est-il difficile à recycler ?', 'mcq', '["Ses matériaux sont quasi impossibles à séparer","Il est trop dur pour être broyé","Il contient toujours du métal","Il est interdit en déchèterie"]'::jsonb, 0, 'Un composite cumule les qualités de deux matériaux, mais on ne sait presque pas les séparer en fin de vie.', 4),
    ('64474487-8ef7-55bd-8973-10afa1790a6b'::uuid, 'technologie', '3e', 'La chaîne d’information', 'Quel composant acquiert une information sur la lumière ambiante ?', 'mcq', '["Le buzzer","La photorésistance","Le microcontrôleur","Le moteur"]'::jsonb, 1, 'La photorésistance est un capteur de lumière : elle assure la fonction « acquérir ».', 1),
    ('9b6fb27c-fd84-51d9-8000-7b549b1e995a'::uuid, 'technologie', '3e', 'La chaîne d’information', 'Quelle fonction de la chaîne d’information assure un buzzer ?', 'mcq', '["Acquérir","Traiter","Communiquer","Alimenter"]'::jsonb, 2, 'Il transmet une information à l’utilisateur par un son, comme l’écran ou la LED.', 2),
    ('6ab399c9-ddee-5ae4-9578-bc5b5662137e'::uuid, 'technologie', '3e', 'La chaîne d’information', 'Qu’exécute la partie commande pour décider quoi faire ?', 'mcq', '["Une conversion d’énergie","Une mesure","Un signal lumineux","Un programme"]'::jsonb, 3, 'Le microcontrôleur, la carte programmable ou l’automate exécutent un programme : c’est la fonction « traiter ».', 3),
    ('a7773e1e-2cef-5d46-a202-0b114551e85c'::uuid, 'technologie', '3e', 'La chaîne d’information', 'Lequel de ces moyens permet de communiquer sans fil ?', 'mcq', '["Le Bluetooth","Le fin de course","La thermistance","Le vérin"]'::jsonb, 0, 'Le Bluetooth, le Wi-Fi ou la radio transmettent l’information à un autre système ; le fin de course et la thermistance sont des capteurs.', 4),
    ('8b553c21-94af-5ac6-b348-647f37fb2457'::uuid, 'technologie', '3e', 'Procédés de fabrication', 'Quel est l’atout principal de la fabrication par déformation ?', 'mcq', '["Aucun outillage n’est nécessaire","Aucune perte de matière","Elle est idéale pour une pièce unique","Elle produit des pièces creuses complexes couche par couche"]'::jsonb, 1, 'La matière change de forme sans copeaux ; l’outillage est en revanche coûteux, ce qui la réserve aux séries.', 1),
    ('5b88a46c-fe74-5fa8-8ca6-44627e201a60'::uuid, 'technologie', '3e', 'Procédés de fabrication', 'Quel procédé convient à cent mille pièces en plastique ?', 'mcq', '["L’impression 3D","Le sciage","L’injection plastique","Le ponçage"]'::jsonb, 2, 'L’injection est rapide et répétable en grande série ; l’impression 3D est trop lente pour cela.', 2),
    ('d3923adb-bf16-576e-b239-6387ba96f7e2'::uuid, 'technologie', '3e', 'Procédés de fabrication', 'À quelle famille appartient le rivetage ?', 'mcq', '["À l’assemblage démontable","À l’enlèvement de matière","À l’ajout de matière","À l’assemblage non démontable"]'::jsonb, 3, 'Comme la soudure et le collage, le rivet est résistant mais définitif.', 3),
    ('19aef7d0-2eda-52f6-8a4b-287aceb4ea19'::uuid, 'technologie', '3e', 'Procédés de fabrication', 'Quelle est la limite de l’impression 3D ?', 'mcq', '["Elle est lente pour produire en série","Elle produit beaucoup de copeaux","Elle ne permet pas les formes complexes","Elle exige un outillage coûteux"]'::jsonb, 0, 'Idéale pour un prototype ou une forme complexe, elle construit couche par couche : trop lente pour une grande série.', 4),
    ('26d11ae4-2c89-57e7-b528-4a948efc569f'::uuid, 'technologie', '3e', 'Règles de sécurité', 'Que signifie un pictogramme carré vert ?', 'mcq', '["Une interdiction","Un danger","Une information de secours","Une obligation"]'::jsonb, 2, 'Le carré vert signale une issue de secours ou une trousse de premiers soins.', 1),
    ('c58aaa64-7bed-50bd-8c0c-8598eb73ea2e'::uuid, 'technologie', '3e', 'Règles de sécurité', 'De quelles couleurs est le bouton d’arrêt d’urgence ?', 'mcq', '["Vert sur fond blanc","Rouge sur fond jaune","Bleu sur fond rouge","Noir sur fond jaune"]'::jsonb, 1, 'Rouge sur fond jaune, il coupe immédiatement l’alimentation de la machine.', 2),
    ('900e96e0-3509-5829-80a7-fb496dc7fc4d'::uuid, 'technologie', '3e', 'Règles de sécurité', 'Quelle tenue est exigée en atelier ?', 'mcq', '["Des gants en permanence","Une écharpe pour se protéger","Des sandales pour être à l’aise","Cheveux attachés, aucun bijou ni écharpe"]'::jsonb, 3, 'Cheveux, bijoux et écharpes peuvent être happés par une pièce en rotation ; il faut aussi une blouse et des chaussures fermées.', 3),
    ('7d847446-51e0-51d1-aad9-738d89236a93'::uuid, 'technologie', '3e', 'Règles de sécurité', 'Que faut-il faire si l’on remarque un câble abîmé sur une machine ?', 'mcq', '["Le signaler","Continuer en faisant attention","Le réparer soi-même avec du ruban adhésif","L’ignorer si la machine fonctionne"]'::jsonb, 0, 'Toute anomalie — câble abîmé, bruit inhabituel — se signale avant de continuer.', 4),
    ('d0521cac-b2c9-534c-93c1-280e7643cc39'::uuid, 'technologie', '3e', 'Bases de la programmation', 'Quelle différence y a-t-il entre un algorithme et un programme ?', 'mcq', '["L’algorithme est toujours plus long","Le programme ne contient jamais de boucle","Le programme est la traduction de l’algorithme dans un langage compris par la machine","Il n’y en a aucune"]'::jsonb, 2, 'L’algorithme est la suite d’instructions ; le programme l’écrit dans un langage que la machine exécute.', 1),
    ('9bb6be11-ab47-588e-8082-f9167821d9a1'::uuid, 'technologie', '3e', 'Bases de la programmation', 'Quelle boucle convient pour « répéter tant que le bouton n’est pas appuyé » ?', 'mcq', '["Une boucle bornée","Une boucle non bornée","Une séquence","Une variable"]'::jsonb, 1, 'On ne connaît pas d’avance le nombre de tours : la boucle est non bornée.', 2),
    ('b1a104ee-c67e-551f-8114-ea71b7c40832'::uuid, 'technologie', '3e', 'Bases de la programmation', 'Dans un organigramme, quelle forme représente un test ?', 'mcq', '["Le rectangle","La flèche","Le cercle","Le losange"]'::jsonb, 3, 'Losanges pour les tests, rectangles pour les actions, flèches pour l’enchaînement.', 3),
    ('238f1169-9e6e-5541-9a7b-296f45e4d127'::uuid, 'technologie', '3e', 'Bases de la programmation', 'Pour un programme, un capteur est…', 'mcq', '["une entrée, que le programme lit","une sortie, que le programme commande","une variable","un opérateur logique"]'::jsonb, 0, 'Le programme lit les capteurs (entrées) et commande les actionneurs (sorties) : c’est le lien avec la chaîne d’information.', 4),
    ('6b034b6a-462e-5c18-a874-758ef654110e'::uuid, 'technologie', '3e', 'Programmation graphique et programmation textuelle', 'Quelle programmation convient le mieux aux programmes longs ?', 'mcq', '["La programmation graphique","La programmation textuelle","Aucune des deux","Les deux aussi bien"]'::jsonb, 1, 'Les blocs deviennent vite illisibles sur un long programme ; le texte n’a pas de limite de taille.', 1),
    ('fa564614-5c2a-591a-a73c-ffeec6ce0668'::uuid, 'technologie', '3e', 'Programmation graphique et programmation textuelle', 'Quel langage textuel sert souvent à programmer une carte Arduino ?', 'mcq', '["Scratch","Blockly","Le C ou le C++","Snap!"]'::jsonb, 2, 'Scratch, Blockly et Snap! sont des environnements par blocs ; l’Arduino se programme le plus souvent en C ou C++.', 2),
    ('de51f1e2-c15a-51bc-968c-8d7fa07de9f5'::uuid, 'technologie', '3e', 'Programmation graphique et programmation textuelle', 'En programmation par blocs, que se passe-t-il si deux blocs sont incompatibles ?', 'mcq', '["Le programme plante à l’exécution","Un message d’erreur de syntaxe s’affiche","Ils se transforment en texte","Ils ne s’emboîtent pas"]'::jsonb, 3, 'C’est pour cela qu’aucune faute de syntaxe n’est possible avec les blocs.', 3),
    ('57075834-14eb-588e-a413-5f35d6244c46'::uuid, 'technologie', '3e', 'Programmation graphique et programmation textuelle', 'Que demande le programme du cycle 4 à propos des deux façons de programmer ?', 'mcq', '["Savoir lire et modifier les deux","Maîtriser seulement les blocs","Maîtriser seulement Python","Savoir écrire un compilateur"]'::jsonb, 0, 'Les blocs servent à la logique, le texte à piloter une carte programmable ou à traiter des données.', 4),
    ('5c6b5d84-56e9-5003-9258-d2e14ebfd288'::uuid, 'technologie', '3e', 'Écrire mettre au point et exécuter un programme simple', 'Un programme s’arrête en cours de route à cause d’une division par zéro. De quelle erreur s’agit-il ?', 'mcq', '["Une erreur de syntaxe","Une erreur de logique","Une erreur d’exécution","Une erreur d’ergonomie"]'::jsonb, 2, 'Le programme a démarré, puis s’arrête : c’est une erreur d’exécution, comme un capteur absent.', 1),
    ('3df2981f-186c-5621-b5c9-93df4a5ab9c6'::uuid, 'technologie', '3e', 'Écrire mettre au point et exécuter un programme simple', 'Quel nom de variable est le plus explicite ?', 'mcq', '["v2","x","a1","vitesse"]'::jsonb, 3, 'Un nom explicite rend le programme lisible par un autre, ou par soi-même trois mois plus tard.', 2),
    ('bcda387f-6e85-55be-841d-c6f4d18e3f04'::uuid, 'technologie', '3e', 'Écrire mettre au point et exécuter un programme simple', 'Quelle technique aide à voir où le comportement d’un programme dévie ?', 'mcq', '["Supprimer les commentaires","Afficher les valeurs intermédiaires","Raccourcir les noms de variables","Relancer sans rien changer"]'::jsonb, 1, 'Afficher les valeurs en cours de route, ou exécuter pas à pas, montre l’endroit exact où le programme s’écarte de l’attendu.', 3),
    ('a7092ca8-0422-5802-94ea-2cc8827bfad7'::uuid, 'technologie', '3e', 'Écrire mettre au point et exécuter un programme simple', 'Que contient un bon jeu d’essai ?', 'mcq', '["Un cas normal, un cas limite et un cas interdit","Uniquement des cas qui fonctionnent","Un seul cas bien choisi","Les cas proposés par l’utilisateur, sans plus"]'::jsonb, 0, 'Le cas normal vérifie le fonctionnement, le cas limite et le cas interdit révèlent les défauts.', 4),
    ('deab03f0-1050-5ad4-a33b-759cb4a9cddb'::uuid, 'technologie', '3e', 'Structuration et traitement des données', 'Dans un tableau de données, que représente une colonne ?', 'mcq', '["Un enregistrement","Un champ","Une clé","Un filtre"]'::jsonb, 1, 'Une colonne est un champ (nom, date, valeur) ; une ligne est un enregistrement.', 1),
    ('288e09de-e15f-582c-b875-d88e3a4c8549'::uuid, 'technologie', '3e', 'Structuration et traitement des données', 'Quel type de données permet de tester « vrai » ou « faux » ?', 'mcq', '["Le texte","La date","Le nombre décimal","Le booléen"]'::jsonb, 3, 'Un booléen ne prend que deux valeurs, vrai ou faux : il sert aux tests.', 2),
    ('abb9e710-397e-5e1a-a288-ad186ea9fe3f'::uuid, 'technologie', '3e', 'Structuration et traitement des données', 'Quel graphique montre une répartition, les parts d’un tout ?', 'mcq', '["La courbe","L’histogramme","Le camembert","Le nuage de points"]'::jsonb, 2, 'Le camembert raconte une répartition ; la courbe une évolution, l’histogramme une comparaison.', 3),
    ('28a46aa0-5e98-5ddb-a626-9b53cea0b11c'::uuid, 'technologie', '3e', 'Structuration et traitement des données', 'Quel format d’échange organise les données en couples nom-valeur ?', 'mcq', '["JSON","CSV","JPEG","MP3"]'::jsonb, 0, 'Le JSON est très utilisé par les objets connectés et les sites web ; le CSV est un tableau en texte.', 4),
    ('5f7b9230-45e7-5ed5-bae8-b7e8427ffc01'::uuid, 'technologie', '3e', 'Système d’information et stockage de données', 'Combien de bits compte un octet ?', 'mcq', '["8","2","10","16"]'::jsonb, 0, 'Un octet vaut 8 bits et code à peu près un caractère.', 1),
    ('effbcdd3-ec6d-5c1b-9fc9-5b7ba1fe4139'::uuid, 'technologie', '3e', 'Système d’information et stockage de données', 'Qu’apporte l’authentification à deux facteurs ?', 'mcq', '["Elle chiffre le disque","Elle double l’espace de stockage","Le mot de passe seul ne suffit plus pour entrer dans le compte","Elle supprime le mot de passe"]'::jsonb, 2, 'Un second élément, comme un code reçu sur le téléphone, est exigé : un mot de passe volé ne suffit plus.', 2),
    ('e082a046-c91f-5f19-8ef3-3953aff849f4'::uuid, 'technologie', '3e', 'Système d’information et stockage de données', 'Quelle est la limite d’un stockage dans le nuage ?', 'mcq', '["Il n’est accessible que d’un seul endroit","Il ne peut pas être sauvegardé","Il est interdit par le RGPD","Il dépend du réseau et du prestataire"]'::jsonb, 3, 'Accessible de partout, il exige une connexion et dépend d’un prestataire, dont les centres de données sont bien réels.', 3),
    ('ecc0d0f5-dc3f-5c87-8dbc-a87f5f0f0944'::uuid, 'technologie', '3e', 'Système d’information et stockage de données', 'Quel principe du RGPD impose de dire à quoi serviront les données collectées ?', 'mcq', '["Le consentement","La finalité","La durée de conservation","Le droit de rectification"]'::jsonb, 1, 'La finalité de la collecte doit être déclarée ; le consentement, lui, doit être explicite.', 4),
    ('fa9de8f0-a0d7-51e0-a57d-f81265affab1'::uuid, 'technologie', '3e', 'La circulation de l’information dans un réseau informatique', 'Quel équipement relie les machines d’un même réseau local et aiguille les messages ?', 'mcq', '["Le routeur","Le DNS","Le switch","Le modem"]'::jsonb, 2, 'Le switch travaille dans un même réseau ; le routeur relie deux réseaux différents.', 1),
    ('3337ab76-d5be-57cc-b468-768d0877cdff'::uuid, 'technologie', '3e', 'La circulation de l’information dans un réseau informatique', 'Quel protocole sert au courrier électronique ?', 'mcq', '["HTTP","FTP","HTTPS","SMTP"]'::jsonb, 3, 'SMTP transporte le courrier ; HTTP et HTTPS servent le web, FTP le transfert de fichiers.', 2),
    ('650889c6-4c4f-5617-b65b-2b81a2bf53ee'::uuid, 'technologie', '3e', 'La circulation de l’information dans un réseau informatique', 'Que se passe-t-il si un paquet manque à l’arrivée ?', 'mcq', '["Il est redemandé","Tout le message est perdu","Le routeur le reconstitue au hasard","L’ordinateur s’arrête"]'::jsonb, 0, 'Les paquets numérotés sont réassemblés à l’arrivée, et un paquet manquant est redemandé.', 3),
    ('f2f14c21-999e-5bf9-95d3-0a8904eac04c'::uuid, 'technologie', '3e', 'La circulation de l’information dans un réseau informatique', 'Comment appelle-t-on la machine qui demande un service à un serveur ?', 'mcq', '["Le routeur","Le client","Le switch","La box"]'::jsonb, 1, 'Le serveur rend un service, le client le demande : c’est le cas de ton navigateur face à un site web.', 4),
    ('79eb5046-1ce4-5459-9f45-9d294420ae3a'::uuid, 'technologie', '3e', 'Organisation d’un projet technique', 'Que porte l’axe horizontal d’un diagramme de Gantt ?', 'mcq', '["Les tâches","Le temps","Les coûts","Les responsables"]'::jsonb, 1, 'Le temps est en abscisse, les tâches en ordonnée ; la longueur de chaque barre est la durée de la tâche.', 1),
    ('eec4a170-b465-5579-bf10-9301ec59a42d'::uuid, 'technologie', '3e', 'Organisation d’un projet technique', 'De quoi dispose une tâche qui n’est pas sur le chemin critique ?', 'mcq', '["D’un budget supplémentaire","D’une priorité absolue","D’une marge","D’aucun responsable"]'::jsonb, 2, 'Elle peut prendre un peu de retard sans décaler la fin du projet, ce qui est impossible sur le chemin critique.', 2),
    ('dec58466-6083-5b52-839b-84a333535b43'::uuid, 'technologie', '3e', 'Organisation d’un projet technique', 'Quelle phase vient juste après l’analyse du besoin ?', 'mcq', '["La réalisation","Le bilan","La conception","La recherche de solutions"]'::jsonb, 3, 'Après le cahier des charges, on cherche et compare plusieurs pistes, avant de concevoir.', 3),
    ('c5aef9ee-e5b0-5505-932e-2dd93b843f4b'::uuid, 'technologie', '3e', 'Organisation d’un projet technique', 'Quel document garde les décisions et les essais ratés d’un projet ?', 'mcq', '["Le carnet de bord","Le diagramme de Gantt","La nomenclature","Le cahier des charges"]'::jsonb, 0, 'Le carnet de bord assure la traçabilité : il évite qu’un autre refasse la même erreur.', 4),
    ('9f656952-0b29-583c-a1ab-bba1027c7796'::uuid, 'technologie', '3e', 'Modes de représentation d’un OST', 'Que signifie une échelle 2:1 ?', 'mcq', '["Le dessin est deux fois plus petit que l’objet","Le dessin est deux fois plus grand que l’objet","Le dessin est à taille réelle","L’objet mesure 2 cm"]'::jsonb, 1, 'Le premier nombre concerne le dessin : 2:1 agrandit deux fois, 1:2 réduit deux fois, 1:1 est la grandeur nature.', 1),
    ('34d433b5-dec5-518c-b909-f989fa0ac7f3'::uuid, 'technologie', '3e', 'Modes de représentation d’un OST', 'Quel trait représente un axe sur un dessin technique ?', 'mcq', '["Le trait continu fort","Le trait interrompu","Le trait mixte fin","Le trait ondulé"]'::jsonb, 2, 'Le trait continu fort montre une arête vue, l’interrompu une arête cachée, le mixte fin un axe.', 2),
    ('c752c8d6-f843-58c4-a61c-3ef43db05934'::uuid, 'technologie', '3e', 'Modes de représentation d’un OST', 'Quel schéma représente les composants normalisés d’un circuit ?', 'mcq', '["Le schéma de principe","Le schéma cinématique","Le croquis","Le schéma électrique"]'::jsonb, 3, 'Le schéma électrique utilise les symboles normalisés des composants ; le cinématique montre les liaisons et les mouvements.', 3),
    ('bb025a42-8767-54cf-b402-11103a26dbbb'::uuid, 'technologie', '3e', 'Modes de représentation d’un OST', 'À quoi sert une vue éclatée d’un modèle 3D ?', 'mcq', '["À comprendre l’assemblage des pièces","À calculer le prix de revient","À programmer la carte","À coter les dimensions réelles"]'::jsonb, 0, 'Les pièces écartées les unes des autres montrent comment elles s’assemblent.', 4),
    ('66ac1940-8c2b-5956-9c2c-ca8c78311b5c'::uuid, 'technologie', '3e', 'Concevoir et fabriquer un OST', 'Quel outil sert à choisir entre plusieurs solutions ?', 'mcq', '["Un diagramme de Gantt","Un tableau multicritère pondéré","Une nomenclature","Une gamme de fabrication"]'::jsonb, 1, 'Le tableau multicritère compare les solutions sur les critères du cahier des charges, avec une justification.', 1),
    ('2f132ca6-44d7-5e94-92a1-49876c8a8745'::uuid, 'technologie', '3e', 'Concevoir et fabriquer un OST', 'Un matériau devient indisponible : vers quelle étape la démarche renvoie-t-elle ?', 'mcq', '["La fabrication","Les tests","Le choix des solutions","La documentation finale"]'::jsonb, 2, 'La démarche est itérative : un test raté renvoie à la conception, un matériau indisponible au choix des solutions.', 2),
    ('83799d4f-4600-5274-bacf-74ab7d517fe7'::uuid, 'technologie', '3e', 'Concevoir et fabriquer un OST', 'Quel document de la documentation finale rend compte de l’impact du cycle de vie ?', 'mcq', '["La notice d’utilisation","La nomenclature","Le programme commenté","Le bilan environnemental"]'::jsonb, 3, 'Le bilan environnemental complète les plans, la nomenclature, le programme et la notice.', 3),
    ('842f02eb-9f32-5ca8-b80d-4709fc0708d5'::uuid, 'technologie', '3e', 'Concevoir et fabriquer un OST', 'À quelle étape choisit-on les procédés, les machines, les outils et les règles de sécurité ?', 'mcq', '["La préparation de la fabrication","L’analyse du besoin","La recherche de solutions","La validation"]'::jsonb, 0, 'On prépare la fabrication, avec sa gamme d’opérations, avant de fabriquer et d’assembler.', 4),
    ('9f42cdbc-0673-5701-8550-67c23350a2fd'::uuid, 'technologie', '3e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel essai consiste à charger une pièce en son milieu, appuyée à ses extrémités ?', 'mcq', '["L’essai de traction","L’essai de compression","L’essai de flexion","L’essai de torsion"]'::jsonb, 2, 'La flexion fait plier la pièce ; la traction l’étire, la compression l’écrase, la torsion la vrille.', 1),
    ('8c9d4688-9027-5c21-af6b-2a2793f7b2bb'::uuid, 'technologie', '3e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Pourquoi note-t-on l’incertitude d’une mesure ?', 'mcq', '["Pour rendre le résultat plus précis","Parce qu’une mesure sans incertitude n’en est pas une","Parce qu’elle remplace les conditions d’essai","Pour éviter de refaire l’essai"]'::jsonb, 1, 'Toute mesure a une marge d’erreur : sans elle, on ne peut pas juger si l’exigence est vraiment atteinte.', 2),
    ('a0d7526e-e825-51fe-8eda-bdf9e2e1ddf2'::uuid, 'technologie', '3e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Lequel de ces essais est un essai de performance ?', 'mcq', '["L’essai de traction","L’essai de torsion","L’essai de fatigue","La mesure de l’autonomie"]'::jsonb, 3, 'L’autonomie, la vitesse ou le niveau sonore sont des performances ; les trois autres sont des essais de tenue mécanique.', 3),
    ('29e5e863-6162-542a-8379-714c3de28ead'::uuid, 'technologie', '3e', 'Tester et valider la tenue mécanique, le comportement et les performances d’un objet technique', 'Quel verdict écrit-on pour chaque exigence, à la fin d’une validation ?', 'mcq', '["Conforme ou non conforme","Bon ou mauvais","Rapide ou lent","Cher ou bon marché"]'::jsonb, 0, 'On compare la valeur mesurée au niveau exigé et on conclut : conforme ou non conforme.', 4),
    ('dd0fbb25-2505-527c-90fd-0f97a6fd0def'::uuid, 'technologie', '3e', 'Prototypage de solutions', 'Quel degré de prototype valide le procédé de fabrication autant que l’objet ?', 'mcq', '["La maquette","Le prototype fonctionnel","La présérie","Le croquis"]'::jsonb, 2, 'La présérie utilise déjà les matériaux et les procédés du produit final.', 1),
    ('e6e1aa6f-8c30-5ead-90d9-f472ab5e7a6a'::uuid, 'technologie', '3e', 'Prototypage de solutions', 'Quel moyen permet de prototyper l’électronique sans soudure ?', 'mcq', '["La découpe vinyle","Le carton plume","L’impression 3D","Les cartes programmables et les modules enfichables"]'::jsonb, 3, 'Les modules s’enfichent sur la carte : on peut tester et modifier le montage en quelques minutes.', 2),
    ('cc364bd1-158b-504f-ad31-16eaca4c9af5'::uuid, 'technologie', '3e', 'Prototypage de solutions', 'Combien coûte une erreur découverte sur dix mille exemplaires vendus, par rapport à la même erreur trouvée sur un prototype ?', 'mcq', '["Deux fois plus","Cent fois plus","Dix fois moins","Autant"]'::jsonb, 1, 'Plus une erreur est découverte tard, plus elle coûte : c’est pour cela qu’on prototype avant de produire.', 3),
    ('b8bf73fb-5e94-5a45-8073-8aecbf1e05e2'::uuid, 'technologie', '3e', 'Prototypage de solutions', 'Que faut-il noter en documentant un prototype ?', 'mcq', '["Photos, mesures, difficultés, modifications et leurs raisons","Seulement le résultat final","Seulement le coût","Seulement les photos"]'::jsonb, 0, 'Cette mémoire du projet nourrit le dossier final et explique chaque choix.', 4),
    ('fcc714e1-b9ec-5e1a-ba51-b72b38e2c084'::uuid, 'sport', '3e', 'Les quatre champs d’apprentissage', 'Quel problème pose le champ « Conduire un affrontement » ?', 'mcq', '["Se dépasser et mesurer son progrès","Décider vite dans un rapport de force","Assumer un regard","Gérer sa sécurité dans un milieu incertain"]'::jsonb, 1, 'Dans les sports collectifs, de raquette ou de combat, il faut décider vite face à un adversaire.', 1),
    ('b2c80de5-47ca-513d-be4e-d787079bfe63'::uuid, 'sport', '3e', 'Les quatre champs d’apprentissage', 'À quel champ appartient la course d’orientation ?', 'mcq', '["Produire une performance mesurée","S’exprimer par une prestation artistique","Adapter son déplacement à des environnements variés","Conduire un affrontement"]'::jsonb, 2, 'La course d’orientation se pratique en pleine nature, un milieu qui change : c’est le champ « adapter son déplacement ».', 2),
    ('be16928b-9799-5f5f-9515-7c4d0f1c2b77'::uuid, 'sport', '3e', 'Les quatre champs d’apprentissage', 'Le judo et la lutte appartiennent au champ…', 'mcq', '["« Conduire un affrontement »","« Produire une performance mesurée »","« S’exprimer devant les autres »","« Adapter son déplacement »"]'::jsonb, 0, 'Les sports de combat opposent deux adversaires : ils relèvent de l’affrontement, comme les sports collectifs et les raquettes.', 3),
    ('3ba299ed-791c-5e01-b0d5-15521d551cb9'::uuid, 'sport', '3e', 'Les quatre champs d’apprentissage', 'En EPS, que mesure le critère de « progression » ?', 'mcq', '["Le résultat brut au chronomètre","Le nombre de séances suivies","Le classement dans la classe","L’écart avec son point de départ"]'::jsonb, 3, 'La progression compare ce qu’on fait aujourd’hui à ce qu’on faisait au départ, indépendamment du niveau des autres.', 4),
    ('1d97cd3f-bf81-5e20-94d6-8bfb8d54f206'::uuid, 'sport', '3e', 'Progresser : méthode et objectifs', 'Lequel de ces objectifs est précis et mesurable ?', 'mcq', '["Être meilleur en sport","Courir 8 minutes sans m’arrêter","Faire de mon mieux","Devenir le plus rapide"]'::jsonb, 1, 'Un objectif utile se vérifie : on peut constater si l’on a couru 8 minutes sans s’arrêter.', 1),
    ('0e23fb84-a972-5276-84aa-56bf1940271b'::uuid, 'sport', '3e', 'Progresser : méthode et objectifs', 'Que produit un objectif qui n’est pas atteignable ?', 'mcq', '["Il motive davantage","Il fait progresser plus vite","Il décourage","Il n’a aucun effet"]'::jsonb, 2, 'Un objectif hors de portée décourage ; un objectif atteignable motive.', 2),
    ('0e1f23da-a6f0-5eb6-8851-b0608e8e712d'::uuid, 'sport', '3e', 'Progresser : méthode et objectifs', 'Qu’apporte un carnet de suivi ?', 'mcq', '["Il transforme une suite de séances en progression consciente","Il remplace l’entraînement","Il sert seulement à la note","Il permet de sauter l’échauffement"]'::jsonb, 0, 'Noter performances, ressentis et objectifs permet de voir où l’on en est et d’ajuster, comme la révision espacée.', 3),
    ('166f7ed4-6bc6-5a0b-be8d-cb0d0b80fbd5'::uuid, 'sport', '3e', 'Progresser : méthode et objectifs', 'Que signifie la formule « Ce qui se mesure se travaille » ?', 'mcq', '["Qu’il faut s’entraîner avec un mètre ruban","Que seuls les sports chronométrés comptent","Qu’il faut toujours battre son record","Que mesurer son niveau permet de voir et de travailler son progrès"]'::jsonb, 3, 'Sans mesure, le progrès reste invisible ; une mesure de départ permet de le constater et de l’organiser.', 4),
    ('7df44c95-2e2e-577b-80e7-66a644f8f617'::uuid, 'sport', '3e', 'L’échauffement', 'Que produisent les articulations pendant l’échauffement ?', 'mcq', '["De l’acide lactique","Du liquide synovial qui les lubrifie","De la mélatonine","Du sang supplémentaire"]'::jsonb, 1, 'L’échauffement fait produire aux articulations du liquide synovial : elles sont lubrifiées et bougent mieux.', 1),
    ('66c70772-e177-5b38-a8af-8c0062c20dd1'::uuid, 'sport', '3e', 'L’échauffement', 'Que contient la phase spécifique de l’échauffement ?', 'mcq', '["Des étirements longs et statiques","Des rotations lentes de la nuque aux chevilles","Les gestes de l’activité à venir, de plus en plus vite","Un sprint dès la première minute"]'::jsonb, 2, 'Le temps spécifique prépare directement à l’activité : on en reprend les gestes en accélérant progressivement.', 2),
    ('c8f54757-6363-5394-b285-b04ac96e8b88'::uuid, 'sport', '3e', 'L’échauffement', 'Pourquoi un muscle échauffé est-il moins exposé au claquage ?', 'mcq', '["Parce qu’il devient plus élastique","Parce qu’il devient plus petit","Parce qu’il reçoit moins de sang","Parce qu’il se refroidit"]'::jsonb, 0, 'La température musculaire monte de 1 à 2 °C et le muscle devient élastique ; un muscle froid se déchire plus facilement.', 3),
    ('0f9fd788-cd98-5192-94a1-f52336c58340'::uuid, 'sport', '3e', 'L’échauffement', 'Quel effet ont les étirements longs et statiques faits avant l’effort ?', 'mcq', '["Ils augmentent la force","Ils remplacent l’échauffement","Ils accélèrent le cœur","Ils diminuent temporairement la force"]'::jsonb, 3, 'Avant l’effort, les étirements longs diminuent temporairement la force sans prévenir les blessures : leur place est au retour au calme.', 4),
    ('1b55f907-b4a1-51f4-8c97-3fa3797d74c3'::uuid, 'sport', '3e', 'L’effort, le souffle et le cœur', 'À quoi sert la transpiration pendant l’effort ?', 'mcq', '["À éliminer l’acide lactique","À refroidir le corps","À apporter du dioxygène aux muscles","À ralentir le cœur"]'::jsonb, 1, 'L’effort fait monter la température du corps ; la sueur qui s’évapore le refroidit.', 1),
    ('160cb271-bc9f-5179-83a1-366191242cca'::uuid, 'sport', '3e', 'L’effort, le souffle et le cœur', 'Quelle est la FCmax estimée d’un élève de 13 ans ?', 'mcq', '["Environ 150 battements par minute","Environ 190 battements par minute","Environ 207 battements par minute","Environ 233 battements par minute"]'::jsonb, 2, 'On estime la FCmax à 220 moins l’âge : 220 − 13 = 207 battements par minute.', 2),
    ('f8800600-0459-540c-9cdc-3cd307053007'::uuid, 'sport', '3e', 'L’effort, le souffle et le cœur', 'Quel test simple indique qu’on court en endurance ?', 'mcq', '["On peut tenir une conversation en courant","On a les jambes qui brûlent","On est essoufflé après 30 secondes","On a un point de côté"]'::jsonb, 0, 'En aérobie, le dioxygène suffit : on peut parler en courant. Si on ne peut plus parler, on est au-delà.', 3),
    ('59487ef6-7eea-5f1d-8f62-5bbe2f18dd75'::uuid, 'sport', '3e', 'L’effort, le souffle et le cœur', 'Où le sang est-il envoyé en priorité pendant l’effort ?', 'mcq', '["Vers l’estomac","Vers la peau uniquement","Vers le cerveau uniquement","Vers les muscles actifs"]'::jsonb, 3, 'Le sang est redistribué vers les muscles qui travaillent, pour leur livrer dioxygène et nutriments.', 4),
    ('a31adc0e-244b-5404-8f40-2db250e87503'::uuid, 'sport', '3e', 'Hygiène de vie : sommeil, alimentation, écrans', 'Pourquoi ne faut-il pas venir en cours d’EPS à jeun ?', 'mcq', '["Parce qu’on serait trop lourd","Parce que cela expose au malaise","Parce que le règlement l’interdit","Parce qu’on transpirerait moins"]'::jsonb, 1, 'Sans petit-déjeuner, le corps manque de carburant pour l’effort : le risque de malaise augmente.', 1),
    ('cb42e73e-ce68-5643-8d9e-e13482fa220b'::uuid, 'sport', '3e', 'Hygiène de vie : sommeil, alimentation, écrans', 'D’après le cours, quel est le principal facteur de performance à 13 ans ?', 'mcq', '["Les compléments protéinés","Les boissons énergisantes","Le sommeil","Les produits « performance »"]'::jsonb, 2, 'À cet âge, ni protéine ni boisson ne font la différence : c’est le sommeil qui compte le plus.', 2),
    ('ce68b0b4-384a-56ff-9d5b-1a674763ae4d'::uuid, 'sport', '3e', 'Hygiène de vie : sommeil, alimentation, écrans', 'Que penser des boissons énergisantes pour un adolescent ?', 'mcq', '["Inutiles, parfois dangereuses","Indispensables avant un match","Meilleures que l’eau","Recommandées par l’OMS"]'::jsonb, 0, 'Les boissons énergisantes n’apportent rien d’utile à un adolescent et peuvent être dangereuses ; l’eau suffit.', 3),
    ('ce52c17f-45ed-5aa0-ae40-f6a7b7d39f23'::uuid, 'sport', '3e', 'Hygiène de vie : sommeil, alimentation, écrans', 'Contre la sédentarité, quel geste compte réellement ?', 'mcq', '["Faire une longue séance le week-end","Boire plus de jus de fruit","Dormir moins","Se lever quelques minutes chaque heure"]'::jsonb, 3, 'Rester assis longtemps est un risque distinct : interrompre la position assise régulièrement compte, même quand on fait du sport.', 4),
    ('530941c8-d656-5ed3-9000-57d05036997a'::uuid, 'sport', '3e', 'Les rôles sociaux : arbitre, observateur, coach', 'De quoi l’observateur a-t-il besoin pour faire un relevé utile ?', 'mcq', '["D’un sifflet","D’un critère mesurable","D’être le meilleur joueur","D’un avis personnel"]'::jsonb, 1, 'L’observateur relève des données précises selon un critère : « 7 passes sur 10 réussies » se travaille, « il a bien joué » non.', 1),
    ('8deecda7-dc81-58c8-8a84-07445be00ebf'::uuid, 'sport', '3e', 'Les rôles sociaux : arbitre, observateur, coach', 'Que se passe-t-il, selon le cours, quand un arbitre hésite ?', 'mcq', '["Il gagne la confiance des joueurs","Le match devient plus juste","Il perd le match","Rien de particulier"]'::jsonb, 2, 'L’arbitre doit décider vite et assumer : un arbitre qui hésite perd le contrôle du match.', 2),
    ('4e6f65ed-073b-5475-ac9d-2133c418fba2'::uuid, 'sport', '3e', 'Les rôles sociaux : arbitre, observateur, coach', 'Face à une décision d’arbitrage qu’on juge injuste, que peut-on faire ?', 'mcq', '["Demander une explication, sans insulter","Quitter le terrain","Contester à chaque action","Arbitrer soi-même"]'::jsonb, 0, 'On peut demander une explication ; contester systématiquement ou insulter rend le rôle intenable.', 3),
    ('7848eb89-f34b-57ab-a24b-cbfbc03314a7'::uuid, 'sport', '3e', 'Les rôles sociaux : arbitre, observateur, coach', 'Tenir un rôle en EPS fait passer…', 'mcq', '["de joueur à spectateur","de débutant à expert","d’élève à professeur","du statut de participant à celui de responsable"]'::jsonb, 3, 'Arbitrer, observer, coacher ou organiser, c’est prendre une responsabilité pour le groupe.', 4),
    ('a7607029-2981-5071-89cf-f1f0f11b88cc'::uuid, 'sport', '3e', 'Les règles et le fair-play', 'Les règles fixant le terrain, les zones et la durée sont les règles…', 'mcq', '["de but","d’espace et de temps","de sécurité","de fair-play"]'::jsonb, 1, 'Les règles d’espace et de temps définissent où et combien de temps on joue.', 1),
    ('75d08cd9-b86e-52b9-a52f-37e9a85aeb60'::uuid, 'sport', '3e', 'Les règles et le fair-play', 'Respecter la règle seulement quand l’arbitre regarde, c’est…', 'mcq', '["du fair-play","de la triche","de l’obéissance","de l’excellence"]'::jsonb, 2, 'Le fair-play commence là où finit la surveillance : sous le regard de l’arbitre, ce n’est que de l’obéissance.', 2),
    ('b43966ff-0aaf-5145-ac64-1379bcdb97c2'::uuid, 'sport', '3e', 'Les règles et le fair-play', 'Quel geste de fair-play convient quand l’adversaire est largement dominé ?', 'mcq', '["Ne pas l’humilier","Accélérer pour creuser l’écart","Arrêter de jouer","Le provoquer"]'::jsonb, 0, 'Gagner sans mépriser fait partie du fair-play : on ne cherche pas à humilier un adversaire dominé.', 3),
    ('19b9e0c3-075d-57ab-a201-fb029eee1577'::uuid, 'sport', '3e', 'Les règles et le fair-play', 'Que demande la valeur olympique de l’amitié ?', 'mcq', '["Donner son meilleur","Respecter la règle","Gagner à tout prix","Placer le lien avant le résultat"]'::jsonb, 3, 'L’amitié met la relation avec les autres au-dessus du résultat ; l’excellence, elle, demande de donner son meilleur.', 4),
    ('031b19e1-9a03-5ee2-9272-0eaee1d0ba5d'::uuid, 'sport', '3e', 'La sécurité et les premiers secours', 'Quelle est la règle de sécurité non négociable en escalade ?', 'mcq', '["La parade","L’assurage","La zone de lancer dégagée","Le contact interdit"]'::jsonb, 1, 'En escalade, on est toujours assuré ; la parade est la règle de la gymnastique.', 1),
    ('d513bae6-c0b6-50fd-8866-d1a656722011'::uuid, 'sport', '3e', 'La sécurité et les premiers secours', 'Combien de temps applique-t-on la glace sur une entorse, et comment ?', 'mcq', '["1 heure, directement sur la peau","2 minutes, directement sur la peau","15 à 20 minutes, jamais à même la peau","Toute la nuit, sous un bandage serré"]'::jsonb, 2, 'Dans le protocole RICE, la glace s’applique 15 à 20 minutes, protégée par un tissu pour ne pas brûler la peau.', 2),
    ('b918add0-4000-529b-98b9-6a6bb55e1de1'::uuid, 'sport', '3e', 'La sécurité et les premiers secours', 'Quel numéro d’urgence permet d’alerter par SMS ?', 'mcq', '["Le 114","Le 15","Le 18","Le 112"]'::jsonb, 0, 'Le 114 reçoit les alertes par SMS, notamment pour les personnes sourdes ou malentendantes.', 3),
    ('86952c53-9589-5c3a-8587-f1e6684b261d'::uuid, 'sport', '3e', 'La sécurité et les premiers secours', 'Pâleur, sueurs et vertiges sont les signes…', 'mcq', '["d’une entorse","d’un claquage","d’une fracture","d’un malaise"]'::jsonb, 3, 'Le malaise se reconnaît à la pâleur, aux sueurs et aux vertiges ; on arrête l’effort et on prévient l’adulte.', 4),
    ('1c76bf25-fc06-5a9a-8f7a-93de29fb6713'::uuid, 'arts-plastiques', '3e', 'L’œuvre et son spectateur', 'Exposée dans une vitrine de magasin, une œuvre tend à devenir…', 'mcq', '["un patrimoine","une affaire de tous","une marchandise","une installation"]'::jsonb, 2, 'Le lieu change le statut de l’œuvre : la vitrine en fait une marchandise, le musée un patrimoine, la place publique une affaire de tous.', 1),
    ('72ce6d73-4d6c-5225-b5ab-bd269f3e0dd5'::uuid, 'arts-plastiques', '3e', 'L’œuvre et son spectateur', 'Que devient une œuvre installée sur une place publique ?', 'mcq', '["Une affaire de tous","Une marchandise","Une œuvre sans titre","Un ready-made"]'::jsonb, 0, 'Dans l’espace public, l’œuvre concerne tous les passants, qui ne l’ont pas choisie : elle devient l’affaire de tous.', 2),
    ('4756e3c6-c9d8-59d4-b5d5-5bde384bd8a6'::uuid, 'arts-plastiques', '3e', 'L’œuvre et son spectateur', 'Que signale un artiste qui intitule son œuvre *Sans titre* ?', 'mcq', '["Qu’il a oublié de la nommer","Qu’il laisse volontairement le sens libre","Que l’œuvre est inachevée","Que le musée choisira le titre"]'::jsonb, 1, '*Sans titre* est un choix : l’artiste refuse de fermer ou d’orienter le sens et laisse le spectateur libre.', 3),
    ('0fe477f1-6217-51ac-9f9c-0f8fd9058721'::uuid, 'arts-plastiques', '3e', 'L’œuvre et son spectateur', 'Devant une œuvre, quel geste du spectateur le hors-champ sollicite-t-il ?', 'mcq', '["Toucher l’œuvre","Entrer dedans","Se déplacer autour","Compléter mentalement ce qui n’est pas montré"]'::jsonb, 3, 'Le hors-champ travaille l’imagination : le spectateur complète dans sa tête ce que le cadre a laissé dehors.', 4),
    ('1095e5e3-19ee-52a0-92be-8d6c8dc1218e'::uuid, 'arts-plastiques', '3e', 'Image, message et publicité', 'Sur une publicité, une voiture seule sur une route déserte suggère la liberté. La liberté relève ici…', 'mcq', '["de la dénotation","de la connotation","de l’accroche","du cadrage serré"]'::jsonb, 1, 'La voiture est ce que l’image montre (dénotation) ; la liberté est ce qu’elle suggère (connotation).', 1),
    ('e49724d6-bf2c-5cda-bdf9-0d46aa4ca4f9'::uuid, 'arts-plastiques', '3e', 'Image, message et publicité', 'Quel effet produit un cadrage serré sur un produit ?', 'mcq', '["Il l’isole et le magnifie","Il le rend plus petit","Il montre son prix","Il le cache au spectateur"]'::jsonb, 0, 'En resserrant le cadre, on élimine tout ce qui distrait : le produit est isolé et mis en valeur.', 2),
    ('aea5d2a3-fce5-5133-9d1b-9ba1a67b1f42'::uuid, 'arts-plastiques', '3e', 'Image, message et publicité', 'De quel mouvement les artistes ont-ils hérité le principe du détournement ?', 'mcq', '["Du Pop art","Du land art","Des situationnistes","De l’art cinétique"]'::jsonb, 2, 'Le détournement vient des situationnistes : il retourne les codes existants, notamment publicitaires, contre eux-mêmes.', 3),
    ('5dad9c7f-1ea8-5ff1-9a2b-2bf63d7726c3'::uuid, 'arts-plastiques', '3e', 'Image, message et publicité', 'À quoi sert la question « À qui s’adresse l’image ? »', 'mcq', '["À connaître l’émetteur","À repérer la cible visée","À mesurer le format","À dater l’image"]'::jsonb, 1, 'Se demander « à qui ? », c’est identifier la cible : l’image est construite pour agir sur un public précis.', 4),
    ('248294c5-0dd8-5a81-8be8-e76d7c174421'::uuid, 'arts-plastiques', '3e', 'Volume, espace et sculpture', 'Quels matériaux se prêtent surtout à la taille ?', 'mcq', '["L’argile et le plâtre","La pierre et le bois","Le métal et les objets","La résine et le bronze"]'::jsonb, 1, 'Tailler, c’est retirer de la matière : on taille la pierre ou le bois, alors qu’on modèle l’argile.', 1),
    ('5732e416-a181-5aef-a8a4-b651a8340b73'::uuid, 'arts-plastiques', '3e', 'Volume, espace et sculpture', 'Quel sculpteur perce ses figures pour que l’espace les traverse ?', 'mcq', '["Marcel Duchamp","Constantin Brancusi","Andy Warhol","Henry Moore"]'::jsonb, 3, 'Henry Moore creuse et perce ses sculptures : le vide devient une partie de l’œuvre.', 2),
    ('505a8591-bebd-52e2-975e-df8c6fddf2ae'::uuid, 'arts-plastiques', '3e', 'Volume, espace et sculpture', 'Que produit le socle d’une sculpture ?', 'mcq', '["Il la désigne comme art et l’isole","Il la rend plus légère","Il la rend interactive","Il permet de la mouler"]'::jsonb, 0, 'Le socle sépare l’œuvre de notre espace et la signale comme œuvre d’art.', 3),
    ('dcbbdbf5-891a-55ba-b588-739a068752a2'::uuid, 'arts-plastiques', '3e', 'Volume, espace et sculpture', 'Dans un ready-made, qu’est-ce qui fait l’œuvre selon Duchamp ?', 'mcq', '["La fabrication soignée de l’objet","Sa rareté","Le choix de l’objet et son déplacement","Sa taille monumentale"]'::jsonb, 2, 'Duchamp ne fabrique rien : c’est le choix d’un objet ordinaire et son déplacement dans le monde de l’art qui font l’œuvre.', 4),
    ('2939ff67-252c-5252-8e82-73eceabdd452'::uuid, 'arts-plastiques', '2de', 'Démarche artistique et projet', 'Dans quel ordre se conduit un projet plastique ?', 'mcq', '["Réaliser, chercher, présenter, formuler","Formuler une intention, chercher, réaliser, présenter","Chercher, présenter, formuler, réaliser","Présenter, formuler, réaliser, chercher"]'::jsonb, 1, 'On part d’une intention, on cherche (et on a le droit de rater), on réalise, puis on présente.', 1),
    ('cbd59b8d-619b-5309-a653-10161181bf8a'::uuid, 'arts-plastiques', '2de', 'Démarche artistique et projet', 'Laquelle de ces formulations est une intention, et pas un simple thème ?', 'mcq', '["La mer","Les animaux","« Je veux que le spectateur hésite »","Le portrait"]'::jsonb, 2, 'Une intention se formule en phrase et dit ce qu’on veut produire ; « la mer » n’est qu’un thème.', 2),
    ('5703ef59-e2be-5946-8f91-7d0787aeb5e6'::uuid, 'arts-plastiques', '2de', 'Démarche artistique et projet', 'À quoi reconnaît-on une vraie problématique ?', 'mcq', '["Elle admet plusieurs réponses plastiques","Elle n’a qu’une seule bonne réponse","Elle impose une technique","Elle cite un artiste célèbre"]'::jsonb, 0, 'Si une seule réponse est possible, c’est une consigne ; une problématique ouvre plusieurs réponses plastiques.', 3),
    ('13e47ced-d004-5db8-8b7d-c30a332318f8'::uuid, 'arts-plastiques', '2de', 'Démarche artistique et projet', 'Reprendre le dispositif d’un artiste pour en renverser le sens, c’est…', 'mcq', '["le citer","le prolonger","le copier","le contredire"]'::jsonb, 3, 'Citer, prolonger et contredire sont trois relations légitimes à une référence ; renverser le sens d’un dispositif, c’est le contredire.', 4),
    ('aab59120-895c-5e06-b3e8-385e0efca0f8'::uuid, 'arts-plastiques', '1re', 'Démarche artistique et projet', 'Dans quel ordre se conduit un projet plastique ?', 'mcq', '["Réaliser, chercher, présenter, formuler","Formuler une intention, chercher, réaliser, présenter","Chercher, présenter, formuler, réaliser","Présenter, formuler, réaliser, chercher"]'::jsonb, 1, 'On part d’une intention, on cherche (et on a le droit de rater), on réalise, puis on présente.', 1),
