    ('cf47c5b7-3ea5-55a8-833c-57e01f183ae5'::uuid, 'arts-plastiques', '2de', 'Art contemporain : formes et enjeux', 'Dans l’art conceptuel, qu’est-ce qui peut valoir l’œuvre ?', 'mcq', '["Le cadre","Le protocole","Le prix de vente","Le socle"]'::jsonb, 1, 'L’art conceptuel fait passer de l’objet à l’idée : le protocole, la règle écrite, peut suffire à faire l’œuvre.', 1),
    ('64621eff-9566-5f12-9d04-b1dc42e5384e'::uuid, 'arts-plastiques', '2de', 'Art contemporain : formes et enjeux', 'Quel geste est associé à Christo et Jeanne-Claude ?', 'mcq', '["La reproduction sérielle","Le récit et l’enquête","L’emballage monumental","L’art politique"]'::jsonb, 2, 'Christo et Jeanne-Claude emballent des monuments et des paysages : l’œuvre devient éphémère et publique.', 2),
