    ('7a0db997-61e5-55e9-9172-9198731fc3ea'::uuid, 'arts-plastiques', '2de', 'Image numérique et création', 'Comment une image matricielle est-elle décrite ?', 'mcq', '["Par des formules géométriques","Par une grille de pixels colorés","Par du texte éditable","Par des calques uniquement"]'::jsonb, 1, 'L’image matricielle (bitmap) est une grille de pixels ; c’est pourquoi elle se pixellise quand on l’agrandit.', 1),
    ('8b7dac1e-5636-5fd5-9de9-d854053e8166'::uuid, 'arts-plastiques', '2de', 'Image numérique et création', 'Quel format choisir pour archiver une image avec une qualité maximale ?', 'mcq', '["JPEG","SVG","TIFF","GIF"]'::jsonb, 2, 'Le TIFF conserve la qualité maximale : c’est le format de l’archivage et de l’impression.', 2),
    ('d23dc2b8-0417-5c7a-8ee7-df17eb44d082'::uuid, 'arts-plastiques', '2de', 'Image numérique et création', 'Qu’est-ce que l’« aura » d’une œuvre selon Walter Benjamin ?', 'mcq', '["Son ici-et-maintenant, sa présence unique","Sa valeur marchande","Sa copie numérique","Le halo lumineux autour d’un tableau"]'::jsonb, 0, 'L’aura, c’est l’existence unique de l’œuvre, ici et maintenant ; la reproduction la lui fait perdre.', 3),
    ('0eebfc46-dade-5ce2-9505-8430120b45eb'::uuid, 'arts-plastiques', '2de', 'Image numérique et création', 'Quel format vectoriel peut s’éditer comme du texte ?', 'mcq', '["PNG","JPEG","TIFF","SVG"]'::jsonb, 3, 'Le SVG décrit l’image par des formes écrites en texte : on peut l’agrandir sans perte et le modifier directement.', 4),
