    ('9623629e-3730-5e14-9e0c-705692c4753e'::uuid, 'emc', '3e', 'Les discriminations et la loi', 'Pour qu’il y ait discrimination, combien de conditions doivent être réunies ?', 'mcq', '["Une seule suffit","Les trois : traitement défavorable, critère interdit, domaine protégé","Deux sur trois","Aucune : l’intention suffit"]'::jsonb, 1, 'Il faut à la fois un traitement défavorable, un critère interdit et un domaine protégé (emploi, logement, école…) : c’est ce qui distingue la discrimination d’une simple différence.', 1),
    ('3dc1bd6e-ef4e-5db7-a694-5db39e6453bf'::uuid, 'emc', '3e', 'Les discriminations et la loi', 'Lequel de ces critères est interdit par la loi pour refuser un logement ?', 'mcq', '["Des revenus insuffisants","Un dossier incomplet","Le lieu de résidence","L’absence de garant"]'::jsonb, 2, 'Le lieu de résidence fait partie des critères interdits, avec l’origine, le sexe, l’âge, le handicap ou la religion.', 2),
    ('68abdc8d-cb8b-5633-a25c-49fa1ea37ef1'::uuid, 'emc', '3e', 'Les discriminations et la loi', '« On ne loue pas à des étudiants » : de quelle forme de discrimination s’agit-il ?', 'mcq', '["Directe, car la différence est explicite","Indirecte, car la règle paraît neutre","Ce n’est pas une discrimination","Une diffamation"]'::jsonb, 0, 'La différence de traitement est affichée ouvertement : c’est une discrimination directe.', 3),
    ('4a7bcea2-d3d7-5928-abf5-0b41357e34bd'::uuid, 'emc', '3e', 'Les discriminations et la loi', 'Qu’encourt un service public qui discrimine ?', 'mcq', '["Aucune peine, l’État est protégé","Un simple rappel à l’ordre","Les mêmes peines qu’un particulier, sans plus","Des peines aggravées"]'::jsonb, 3, 'Quand l’auteur est un service public, les peines sont aggravées : il doit l’égalité à tous les usagers.', 4),
    ('7f6f5e32-593b-52a1-a247-6452b3c97d17'::uuid, 'emc', '3e', 'La liberté d’expression et ses limites', 'Quelle est la différence entre l’injure et la diffamation ?', 'mcq', '["L’injure est écrite, la diffamation orale","L’injure est une expression outrageante sans fait précis, la diffamation affirme un fait faux","L’injure vise un groupe, la diffamation un parti","Il n’y en a aucune"]'::jsonb, 1, 'L’injure outrage sans rien affirmer de précis ; la diffamation attribue un fait faux qui porte atteinte à l’honneur.', 1),
    ('8d756211-3768-5496-a3f1-76d98872b8c6'::uuid, 'emc', '3e', 'La liberté d’expression et ses limites', 'Quel article de la Déclaration de 1789 pose la libre communication des pensées ?', 'mcq', '["L’article 1","L’article 16","L’article 11","L’article 9"]'::jsonb, 2, 'L’article 11 fait de la libre communication des pensées et des opinions l’un des droits les plus précieux.', 2),
    ('a3146ca5-2154-512a-b582-4e96650398b0'::uuid, 'emc', '3e', 'La liberté d’expression et ses limites', 'Qu’est-ce qui permet de retrouver l’auteur d’un message posté sous pseudonyme ?', 'mcq', '["L’adresse IP","Le nombre d’abonnés","La photo de profil","Rien, le pseudonyme protège"]'::jsonb, 0, 'Un message en ligne est traçable par l’adresse IP : le pseudonyme ne garantit pas l’anonymat devant la justice.', 3),
    ('ecf0d77a-375c-5ae9-b8c8-bf0940977e03'::uuid, 'emc', '3e', 'La liberté d’expression et ses limites', 'Présenter favorablement un acte terroriste, c’est commettre…', 'mcq', '["une diffamation","une injure","un harcèlement","une apologie du terrorisme"]'::jsonb, 3, 'L’apologie du terrorisme est un délit : elle fait partie des limites légales de la liberté d’expression.', 4),
    ('233b1d72-e5a3-5fc6-afd7-d262d08fe451'::uuid, 'emc', '3e', 'Le respect de la vie privée et l’identité numérique', 'Parmi ces traces, laquelle fait partie de ce que les services enregistrent sans qu’on le voie ?', 'mcq', '["Une photo qu’on publie","Nos recherches et notre position","Un message envoyé à un ami","Une vidéo où un camarade nous identifie"]'::jsonb, 1, 'Recherches, position, temps passé, achats : cette troisième couche de l’identité numérique est enregistrée sans qu’on s’en rende compte.', 1),
    ('b1107bc4-b227-5f8a-b84f-066c07ca5066'::uuid, 'emc', '3e', 'Le respect de la vie privée et l’identité numérique', 'En quelle année le RGPD est-il entré en application ?', 'mcq', '["2004","2010","2018","2022"]'::jsonb, 2, 'Le règlement général sur la protection des données s’applique depuis 2018 dans toute l’Union européenne.', 2),
    ('330c334f-9464-598f-a0b7-0ad3584dddea'::uuid, 'emc', '3e', 'Le respect de la vie privée et l’identité numérique', 'Comment s’appelle le droit de demander qu’on supprime ses données ?', 'mcq', '["Le droit à l’effacement, ou « droit à l’oubli »","Le droit d’accès","Le droit de rectification","Le droit de réponse"]'::jsonb, 0, 'Le RGPD prévoit l’accès, la rectification, l’opposition et l’effacement, dit « droit à l’oubli ».', 3),
    ('f99af89f-cedc-5f3b-ba2f-fbdab2ba0476'::uuid, 'emc', '3e', 'Le respect de la vie privée et l’identité numérique', 'Avant 15 ans en France, que faut-il pour qu’un service traite ses données ?', 'mcq', '["Rien de particulier","Une carte d’identité","L’accord de la CNIL","L’accord d’un parent"]'::jsonb, 3, 'L’âge du consentement autonome est fixé à 15 ans ; en dessous, l’accord d’un parent est nécessaire.', 4),
    ('a9123488-33ea-500e-b6a8-1d27df524ec8'::uuid, 'emc', '3e', 'La laïcité en France', 'Que signifie le principe de séparation ?', 'mcq', '["Les religions sont interdites dans l’espace public","L’État ne reconnaît, ne salarie ni ne subventionne aucun culte","Chaque région choisit sa religion","Les croyants ne peuvent pas voter"]'::jsonb, 1, 'La séparation veut dire que l’État ne reconnaît ni ne finance aucun culte : il reste neutre.', 1),
    ('f7f70c23-db62-5aa8-ba0e-c7a5a2b31431'::uuid, 'emc', '3e', 'La laïcité en France', 'Un usager d’un service public, par exemple à la mairie, peut-il porter un signe religieux ?', 'mcq', '["Non, jamais","Seulement le dimanche","Oui, les usagers restent libres, sauf exception prévue par la loi","Seulement avec une autorisation"]'::jsonb, 2, 'La neutralité s’impose aux agents publics dans leurs fonctions, pas aux usagers, qui restent libres sauf exception légale.', 2),
    ('9d2d5aa9-170d-5d43-928a-c256292d4653'::uuid, 'emc', '3e', 'La laïcité en France', 'La loi du 15 mars 2004 s’applique-t-elle dans les établissements privés sous contrat ?', 'mcq', '["Non","Oui, comme dans le public","Seulement au lycée","Seulement pour les enseignants"]'::jsonb, 0, 'La loi de 2004 ne concerne que les écoles, collèges et lycées publics.', 3),
    ('de1f6c1f-8502-5f3d-8b1f-ba36895798d3'::uuid, 'emc', '3e', 'La laïcité en France', 'Pourquoi l’Alsace-Moselle a-t-elle gardé le Concordat ?', 'mcq', '["Parce qu’elle l’a voté par référendum","Parce qu’elle est une collectivité d’outre-mer","Parce qu’elle a refusé la loi de 2004","Parce qu’elle était allemande en 1905"]'::jsonb, 3, 'En 1905, l’Alsace-Moselle était allemande : la loi de séparation ne s’y est pas appliquée, et le Concordat est resté en vigueur.', 4),
    ('eaaf293d-2e63-5f01-8494-925182acb1a5'::uuid, 'emc', '3e', 'La justice en France', 'Quel tribunal juge une contravention, comme un excès de vitesse ?', 'mcq', '["Le tribunal correctionnel","Le tribunal de police","La cour d’assises","Le tribunal administratif"]'::jsonb, 1, 'Contravention → tribunal de police ; délit → tribunal correctionnel ; crime → cour d’assises ou cour criminelle.', 1),
    ('d5d7994f-b36f-5295-98f6-bfe73c74e524'::uuid, 'emc', '3e', 'La justice en France', 'Un citoyen conteste une décision de sa mairie. Quel ordre de juridiction est compétent ?', 'mcq', '["L’ordre judiciaire","La cour d’assises","L’ordre administratif","Le juge des enfants"]'::jsonb, 2, 'Les litiges entre les citoyens et l’administration relèvent de l’ordre administratif (tribunal administratif, Conseil d’État).', 2),
    ('aa34703c-7cf4-5f29-aa52-a0f24607aa65'::uuid, 'emc', '3e', 'La justice en France', 'Que permet l’aide juridictionnelle ?', 'mcq', '["D’accéder à la justice quand on a peu de moyens","De faire appel deux fois","D’éviter un procès","De choisir son juge"]'::jsonb, 0, 'L’aide juridictionnelle prend en charge les frais de justice des plus modestes : la justice doit être accessible à tous.', 3),
    ('2bb786db-6e68-5d71-93a1-055fdb76ed35'::uuid, 'emc', '3e', 'La justice en France', 'Quel acteur du procès consigne ce qui se dit à l’audience ?', 'mcq', '["Le procureur","L’avocat","Le juré","Le greffier"]'::jsonb, 3, 'Le greffier consigne les débats et les décisions ; le juge tranche, le procureur poursuit, l’avocat défend.', 4),
    ('2a5c79ad-0681-5a07-a843-b98fc0a7c83d'::uuid, 'emc', '3e', 'La citoyenneté française et européenne', 'Comment devient-on français par filiation ?', 'mcq', '["En naissant en France","En ayant au moins un parent français","En vivant cinq ans en France","En se mariant"]'::jsonb, 1, 'La filiation donne la nationalité française à l’enfant dont au moins un parent est français, où qu’il naisse.', 1),
    ('e8fec1dd-bce7-5147-8414-be0e7b2934ef'::uuid, 'emc', '3e', 'La citoyenneté française et européenne', 'Hors d’Europe, un citoyen européen peut demander la protection…', 'mcq', '["de l’ONU uniquement","de son seul pays d’origine","du consulat de n’importe quel État membre","du Parlement européen"]'::jsonb, 2, 'La citoyenneté européenne donne droit à la protection consulaire de n’importe quel État membre présent sur place.', 2),
    ('ef042215-045c-58b9-8210-7753130e8d91'::uuid, 'emc', '3e', 'La citoyenneté française et européenne', 'Adhérer à un parti politique est un droit…', 'mcq', '["politique","civil","social","européen uniquement"]'::jsonb, 0, 'Voter, être élu, adhérer à un parti sont des droits politiques ; l’expression ou la circulation sont des droits civils.', 3),
    ('f8be7302-02e0-5ca4-80fd-10f41560e217'::uuid, 'emc', '3e', 'La citoyenneté française et européenne', 'Devant quelle institution un citoyen européen peut-il déposer une pétition ?', 'mcq', '["Le Conseil constitutionnel","L’Assemblée nationale","La CNIL","Le Parlement européen"]'::jsonb, 3, 'Le droit de pétition devant le Parlement européen fait partie des droits de la citoyenneté européenne.', 4),
    ('956f4e15-4e20-5e1b-ae5f-b9dddff2f272'::uuid, 'emc', '3e', 'Voter : le droit de vote et les élections', 'Depuis quand l’isoloir et l’enveloppe garantissent-ils le secret du vote ?', 'mcq', '["1848","1913","1944","1974"]'::jsonb, 1, 'L’isoloir et l’enveloppe sont imposés en 1913 : ils protègent l’électeur de toute pression.', 1),
    ('ee5ad6b1-42b5-58e3-9de0-b82769c180d1'::uuid, 'emc', '3e', 'Voter : le droit de vote et les élections', 'Pour combien de temps les députés sont-ils élus ?', 'mcq', '["6 ans","7 ans","5 ans","4 ans"]'::jsonb, 2, 'Les députés, comme le président de la République et les députés européens, sont élus pour 5 ans ; les conseillers municipaux pour 6 ans.', 2),
    ('fe7588d7-b6ef-5dd1-82fd-8d29da5018cb'::uuid, 'emc', '3e', 'Voter : le droit de vote et les élections', 'Quel est l’avantage principal du scrutin majoritaire ?', 'mcq', '["Il dégage des majorités nettes","Il représente parfaitement toutes les opinions","Il supprime l’abstention","Il rend le vote obligatoire"]'::jsonb, 0, 'Le majoritaire donne des majorités claires, mais laisse des voix sans représentation ; le proportionnel fait l’inverse.', 3),
    ('63c100b5-e69e-5036-90ce-4eb983f19dda'::uuid, 'emc', '3e', 'Voter : le droit de vote et les élections', 'Qu’est-ce qu’un vote nul ?', 'mcq', '["Une enveloppe vide","Une abstention","Un vote par procuration","Un bulletin abîmé ou raturé"]'::jsonb, 3, 'Le vote nul est un bulletin abîmé ou raturé ; l’enveloppe vide est un vote blanc.', 4),
    ('8ad1aaba-fa5c-5cfc-a1dd-63e8bad330a4'::uuid, 'emc', '3e', 'S’informer : médias, sources et esprit critique', 'Combien de sources indépendantes un journaliste doit-il recouper au minimum ?', 'mcq', '["Une seule","Deux","Cinq","Aucune s’il est sûr de lui"]'::jsonb, 1, 'Le journaliste recoupe au moins deux sources indépendantes avant de publier, et il signe son travail.', 1),
    ('4867bade-0b7e-5a34-9b49-749177938d3b'::uuid, 'emc', '3e', 'S’informer : médias, sources et esprit critique', 'Qu’est-ce qu’une rumeur ?', 'mcq', '["Un fait vérifié et signé","Un jugement personnel","Une information sans source identifiable","Un message payé pour convaincre"]'::jsonb, 2, 'La rumeur circule sans source identifiable ; l’opinion est un jugement, la publicité un message payé.', 2),
    ('fe36e3d6-62f3-593d-b084-a97b399fd4b9'::uuid, 'emc', '3e', 'S’informer : médias, sources et esprit critique', 'Pourquoi la question « Quand ? » est-elle utile face à une photo ?', 'mcq', '["Parce qu’une vraie photo ancienne peut illustrer un faux propos","Parce que les vieilles photos sont toujours fausses","Parce que seules les photos récentes sont protégées","Parce qu’elle indique le nombre de partages"]'::jsonb, 0, 'Une photo authentique d’il y a dix ans peut être détournée pour illustrer un événement actuel.', 3),
    ('af2e073a-5fcf-5768-84f1-6ce219bf954b'::uuid, 'emc', '3e', 'S’informer : médias, sources et esprit critique', 'Comment sortir de sa bulle de filtre ?', 'mcq', '["En likant davantage de contenus","En suivant uniquement ses amis","En faisant confiance à l’algorithme","En allant chercher volontairement d’autres sources"]'::jsonb, 3, 'L’algorithme montre ce qui nous ressemble : il faut aller chercher soi-même d’autres points de vue.', 4),
    ('6c1026ba-3eac-525e-bba3-131e7bfe058a'::uuid, 'emc', '3e', 'L’engagement et la solidarité', 'Combien de temps dure une mission de service civique ?', 'mcq', '["Deux semaines","De 6 à 12 mois","Trois ans","Toute la scolarité"]'::jsonb, 1, 'Le service civique est une mission d’intérêt général indemnisée, de 6 à 12 mois, accessible dès 16 ans.', 1),
    ('224469c6-7fc8-5d5f-8cee-f9ce4182536f'::uuid, 'emc', '3e', 'L’engagement et la solidarité', 'Quelle forme d’engagement consiste à défendre des droits collectifs au travail ?', 'mcq', '["L’engagement associatif","L’engagement scolaire","L’engagement syndical","Le service civique"]'::jsonb, 2, 'Le syndicat défend les droits collectifs des salariés.', 2),
    ('be341d83-909d-5389-ae65-5991c1fc215b'::uuid, 'emc', '3e', 'L’engagement et la solidarité', 'Qu’est-ce qui finance la solidarité organisée ?', 'mcq', '["Les cotisations et l’impôt","Les dons des plus riches","La charité des associations","Les entreprises seules"]'::jsonb, 0, 'Ce n’est pas de la charité mais un droit, financé par les cotisations et l’impôt.', 3),
    ('fa8136ff-cd69-58b6-9962-7429c1f2a6da'::uuid, 'emc', '3e', 'L’engagement et la solidarité', 'Lequel de ces gestes relève de la solidarité de proximité ?', 'mcq', '["Payer ses cotisations","Voter aux élections","Toucher une pension de retraite","Donner son sang"]'::jsonb, 3, 'Don du sang, maraudes, aide aux devoirs : la solidarité de proximité complète le système public là où il n’atteint pas.', 4),
    ('872fe0b1-bcba-5087-a8fc-8b79779229ac'::uuid, 'emc', '3e', 'La défense et la sécurité nationale', 'En quelle année l’OTAN a-t-elle été fondée ?', 'mcq', '["1945","1949","1957","1997"]'::jsonb, 1, 'L’OTAN naît en 1949, au début de la guerre froide : une attaque contre un membre engage tous les autres.', 1),
    ('9eff1433-403e-5cf1-8ebe-1a71acc5d197'::uuid, 'emc', '3e', 'La défense et la sécurité nationale', 'À quel âge a lieu la Journée défense et citoyenneté ?', 'mcq', '["À 13 ans","À 21 ans","Entre 16 et 18 ans","À 25 ans"]'::jsonb, 2, 'Après le recensement à 16 ans, la JDC a lieu entre 16 et 18 ans.', 2),
    ('c1cf475e-90cc-55c3-9b8b-cb6f4e6b7059'::uuid, 'emc', '3e', 'La défense et la sécurité nationale', 'Quel domaine de la défense s’occupe des pompiers, des secours et des catastrophes ?', 'mcq', '["La sécurité civile","La cyberdéfense","La sécurité économique","La Marine nationale"]'::jsonb, 0, 'La sécurité civile gère les secours et les crises ; la défense ne se limite pas aux militaires.', 3),
    ('ce89912f-b018-5201-b8dc-82130a30e08d'::uuid, 'emc', '3e', 'La défense et la sécurité nationale', 'Quelle voie d’engagement permet de servir sans être militaire de carrière ?', 'mcq', '["Le service militaire obligatoire","Le vote","La JDC","La réserve opérationnelle"]'::jsonb, 3, 'Réserve opérationnelle, cadets de la défense, sapeur-pompier volontaire : plusieurs voies existent en plus du métier militaire.', 4),
    ('4afff57e-fcca-5bd3-bc96-ce963f73dd70'::uuid, 'emc', '2de', 'Qu’est-ce que l’État de droit ?', 'Quel est le contraire de l’État de droit ?', 'mcq', '["L’absence de lois","L’arbitraire","La démocratie directe","Le fédéralisme"]'::jsonb, 1, 'Un État autoritaire a beaucoup de lois : ce qui s’oppose à l’État de droit, c’est un pouvoir qui n’est pas lié par ses propres règles.', 1),
    ('a9ea25ca-6c9d-51b8-9874-43aa66d50950'::uuid, 'emc', '2de', 'Qu’est-ce que l’État de droit ?', 'Dans la hiérarchie des normes, où se placent les traités internationaux ?', 'mcq', '["Au-dessus de la Constitution","Sous les décrets","Au-dessus de la loi, sous la Constitution","Au même rang que les contrats"]'::jsonb, 2, 'L’ordre est : Constitution, traités et droit de l’Union, loi, règlements, contrats.', 2),
    ('da80dabd-1492-589f-a6fb-f8bb63d8432b'::uuid, 'emc', '2de', 'Qu’est-ce que l’État de droit ?', 'Quelle phrase résume l’idée de Montesquieu ?', 'mcq', '["« Il faut que le pouvoir arrête le pouvoir »","« L’État, c’est moi »","« Le peuple est souverain »","« Nul n’est censé ignorer la loi »"]'::jsonb, 0, 'Pour éviter l’abus, Montesquieu veut que les pouvoirs législatif, exécutif et judiciaire se limitent mutuellement.', 3),
    ('00ca1416-e10f-51e4-b4fd-0c71066c00ff'::uuid, 'emc', '2de', 'Qu’est-ce que l’État de droit ?', 'Quel est le rôle de la Cour de cassation ?', 'mcq', '["Contrôler l’administration","Vérifier la conformité des lois à la Constitution","Voter les lois","Veiller à l’interprétation du droit"]'::jsonb, 3, 'La Cour de cassation veille à l’interprétation du droit ; le Conseil d’État contrôle l’administration et le Conseil constitutionnel les lois.', 4),
    ('4f4e0488-eab1-5aad-9aea-4ce790acc790'::uuid, 'emc', '2de', 'L’État de droit : le fruit d’une longue évolution', 'Que garantit l’habeas corpus de 1679 ?', 'mcq', '["Le droit de vote","Le contrôle judiciaire de la détention","La liberté de la presse","La séparation des Églises et de l’État"]'::jsonb, 1, 'L’habeas corpus oblige à présenter devant un juge toute personne détenue : on ne peut plus emprisonner sans contrôle.', 1),
    ('431f126c-e5b9-5a12-9b50-4b714bb09bd8'::uuid, 'emc', '2de', 'L’État de droit : le fruit d’une longue évolution', 'Que dit l’article 8 de la Déclaration de 1789 ?', 'mcq', '["Les hommes naissent libres et égaux","La liberté consiste à faire ce qui ne nuit pas à autrui","Nul ne peut être puni qu’en vertu d’une loi antérieure","La propriété est inviolable"]'::jsonb, 2, 'L’article 8 interdit de punir pour un acte qui n’était pas interdit au moment où il a été commis.', 2),
    ('f479f86b-a1fe-555c-9caa-b086cd90e0dd'::uuid, 'emc', '2de', 'L’État de droit : le fruit d’une longue évolution', 'Quelle liberté la loi de 1884 garantit-elle ?', 'mcq', '["La liberté syndicale","La liberté d’association","La liberté de la presse","La liberté de conscience"]'::jsonb, 0, 'En 1884, les syndicats sont légalisés ; l’association suivra en 1901.', 3),
    ('7c732f9c-012e-5ea7-9530-79b5c5142d6b'::uuid, 'emc', '2de', 'L’État de droit : le fruit d’une longue évolution', 'En quelle année le Défenseur des droits est-il créé ?', 'mcq', '["1958","1981","2005","2011"]'::jsonb, 3, 'Le Défenseur des droits, autorité indépendante, est créé en 2011, un an après la QPC.', 4),
    ('4a514873-df80-5a5c-a5a5-4236983838e9'::uuid, 'emc', '2de', 'La laïcité en France', 'Pourquoi l’ordre des deux premiers articles de la loi de 1905 compte-t-il ?', 'mcq', '["Parce que la séparation passe avant la liberté","Parce qu’il pose d’abord la liberté, puis la séparation","Parce que l’article 1 a été abrogé","Il ne compte pas, c’est un détail"]'::jsonb, 1, 'D’abord la liberté de conscience, ensuite la séparation : l’ordre dit le sens même de la loi.', 1),
    ('e99900b0-e134-544d-ac8d-71216479bb02'::uuid, 'emc', '2de', 'La laïcité en France', 'Quel territoire, en plus de l’Alsace-Moselle, a un statut propre en matière de cultes ?', 'mcq', '["La Corse","La Bretagne","La Guyane","La Réunion"]'::jsonb, 2, 'La Guyane garde un statut particulier : la laïcité française n’est pas uniforme sur tout le territoire.', 2),
    ('4b4472ea-f5bb-55dc-b68b-de8d13f95609'::uuid, 'emc', '2de', 'La laïcité en France', 'Quel type de signes religieux la loi de 2004 interdit-elle aux élèves ?', 'mcq', '["Les signes manifestant ostensiblement une appartenance religieuse","Tous les signes, même discrets","Seulement les signes portés à la cantine","Aucun signe"]'::jsonb, 0, 'La loi vise les signes ou tenues ostensibles ; des signes discrets restent possibles.', 3),
    ('51d40f66-ca24-58e6-8234-6291cf180ca4'::uuid, 'emc', '2de', 'La laïcité en France', 'Comment la laïcité française se situe-t-elle en Europe ?', 'mcq', '["Toute l’Europe a la même règle","La France finance tous les cultes","Les autres pays interdisent les religions","C’est un cas particulier : d’autres démocraties financent des cultes ou ont une religion d’État"]'::jsonb, 3, 'D’autres démocraties européennes financent des cultes ou ont une religion d’État, tout en garantissant la liberté religieuse.', 4),
    ('7be52f2b-cc89-5032-a6fb-b789d264e864'::uuid, 'emc', '2de', 'Libertés fondamentales et ordre public', 'Quelle composante de l’ordre public a été ajoutée par la jurisprudence ?', 'mcq', '["La sécurité","La dignité de la personne humaine","La tranquillité","La salubrité"]'::jsonb, 1, 'Aux trois composantes classiques, le juge a ajouté le respect de la dignité de la personne humaine.', 1),
    ('9295ed10-3b9a-58cb-8404-fef9afbcfd83'::uuid, 'emc', '2de', 'Libertés fondamentales et ordre public', 'Que vérifie le critère « nécessaire » du test de proportionnalité ?', 'mcq', '["Que la mesure sert bien le but invoqué","Que la mesure a été votée","Qu’aucune mesure moins sévère ne suffirait","Que la mesure est populaire"]'::jsonb, 2, 'Une mesure est nécessaire si rien de moins contraignant ne permettrait d’atteindre le même but.', 2),
    ('fe8e9a94-5eb4-54ae-8995-3851a67b4944'::uuid, 'emc', '2de', 'Libertés fondamentales et ordre public', 'Quand l’état d’urgence a-t-il été appliqué en France après les attentats ?', 'mcq', '["De 2015 à 2017","De 1955 à 1962","De 2001 à 2003","Il n’a jamais été appliqué"]'::jsonb, 0, 'Prévu par la loi de 1955, l’état d’urgence a été appliqué de 2015 à 2017 ; il reste contrôlé par le juge et le Parlement.', 3),
    ('7fa3da26-90b7-5514-be61-1ca7a107ee6c'::uuid, 'emc', '2de', 'Libertés fondamentales et ordre public', 'Qu’est-ce qui peut justifier l’interdiction d’une manifestation ?', 'mcq', '["La gêne causée aux commerçants","Le désaccord du préfet avec la cause","L’absence d’autorisation","Un risque précis de trouble à l’ordre public"]'::jsonb, 3, 'La manifestation n’est soumise qu’à déclaration ; une interdiction doit reposer sur un risque précis de trouble, pas sur une gêne.', 4),
    ('f340a9bb-13d7-53c6-a7db-a277495e8f54'::uuid, 'emc', '2de', 'La liberté de la presse', 'Quel régime de contrôle la France applique-t-elle à la presse ?', 'mcq', '["Une autorisation préalable","Un contrôle a posteriori, devant un tribunal","Une censure administrative","Aucun contrôle"]'::jsonb, 1, 'Depuis 1881, on ne juge pas un journal avant sa parution : on répond devant le juge de ce qu’on a publié.', 1),
    ('c0c28ef3-0226-57bb-857e-859d8a6650a1'::uuid, 'emc', '2de', 'La liberté de la presse', 'Quelle loi de 1990 réprime la négation des crimes contre l’humanité ?', 'mcq', '["La loi Pleven","La loi Bloche","La loi Gayssot","La loi de 1881"]'::jsonb, 2, 'La loi Gayssot (1990) a renforcé la répression du négationnisme ; la loi Pleven (1972) celle des propos racistes.', 2),
    ('c6e8e6d6-256c-57ba-9426-dfc45da25bc9'::uuid, 'emc', '2de', 'La liberté de la presse', 'Quelle loi de 2016 protège l’indépendance des rédactions ?', 'mcq', '["La loi Bloche","La loi Gayssot","La loi Pleven","La LCEN"]'::jsonb, 0, 'La loi Bloche de 2016 renforce la liberté, l’indépendance et le pluralisme des médias.', 3),
    ('af5cd591-18aa-5275-b5f3-77e748ffbd6d'::uuid, 'emc', '2de', 'La liberté de la presse', 'De quelle fusion l’Arcom est-elle née en 2022 ?', 'mcq', '["De la CNIL et du CSA","De la CNIL et de l’Hadopi","Du Défenseur des droits et du CSA","Du CSA et de l’Hadopi"]'::jsonb, 3, 'L’Arcom réunit le CSA et l’Hadopi : elle régule l’audiovisuel et les plateformes.', 4),
    ('65ceeff5-bbbf-54aa-ab0b-b8eacc82b012'::uuid, 'emc', '2de', 'La liberté d’expression', 'Quel article de la Convention européenne des droits de l’homme protège la liberté d’expression ?', 'mcq', '["L’article 1","L’article 10","L’article 16","L’article 11"]'::jsonb, 1, 'L’article 10 de la Convention européenne fait écho à l’article 11 de la Déclaration de 1789.', 1),
    ('4fc9c9c7-8e60-58d5-b9b3-109b375a3fd7'::uuid, 'emc', '2de', 'La liberté d’expression', 'Détourner une œuvre ou un discours pour s’en moquer relève de…', 'mcq', '["la diffamation","l’injure","la satire, protégée","l’apologie"]'::jsonb, 2, 'La satire et la caricature sont protégées : on peut se moquer et détourner, tant qu’on n’attaque pas des personnes pour ce qu’elles sont.', 2),
    ('bfa080a6-e301-5633-a5b9-917a37720708'::uuid, 'emc', '2de', 'La liberté d’expression', 'Par quelles instances les lycéens exercent-ils notamment leur liberté d’expression collective ?', 'mcq', '["Les délégués, le CVL et les journaux lycéens","Le conseil municipal","Le Conseil constitutionnel","Le rectorat"]'::jsonb, 0, 'Les délégués, le conseil de la vie lycéenne et les journaux lycéens sont les lieux de cette expression.', 3),
    ('61ada5a9-f8bf-546c-8cc3-ac3f665d20d3'::uuid, 'emc', '2de', 'La liberté d’expression', 'Quelle limite encadre la liberté d’expression des lycéens ?', 'mcq', '["Ils n’en ont aucune","Ils ne peuvent parler que de sujets scolaires","Ils doivent tout faire valider par le proviseur","Le respect du pluralisme et de la neutralité, sans injure ni diffamation"]'::jsonb, 3, 'Leur liberté s’exerce dans le respect du pluralisme et de la neutralité du service public, sans propos injurieux ni diffamatoires.', 4),
    ('8b4eb97b-54b7-563e-a010-a28dcc8a7cd0'::uuid, 'emc', '2de', 'Comment réguler les réseaux sociaux ?', 'Qu’est-ce qui rend les plateformes difficiles à réguler par un seul pays ?', 'mcq', '["Leur petite taille","Leur caractère transnational","Leur absence de règles","Leur statut public"]'::jsonb, 1, 'Une même plateforme relève de dizaines de droits nationaux : le caractère transnational complique la régulation.', 1),
    ('7a5e3880-7eae-589a-9536-375446fb6aac'::uuid, 'emc', '2de', 'Comment réguler les réseaux sociaux ?', 'Quel numéro appeler pour signaler un cyberharcèlement ?', 'mcq', '["Le 15","Le 17","Le 3018","Le 114"]'::jsonb, 2, 'Le 3018 est le numéro national contre le cyberharcèlement ; Pharos reçoit les signalements de contenus illicites.', 2),
    ('7f050b95-5acd-5828-a44b-8f97a9c14546'::uuid, 'emc', '2de', 'Comment réguler les réseaux sociaux ?', 'Selon le cours, les contenus faux circulent-ils plus ou moins vite que les vrais ?', 'mcq', '["En moyenne plus vite","Plus lentement","À la même vitesse","Ils ne circulent pas"]'::jsonb, 0, 'Parce qu’ils suscitent l’indignation, les contenus faux circulent en moyenne plus vite que les vrais.', 3),
    ('5b6f7eba-e782-5f25-9eb3-e917c80cd4e7'::uuid, 'emc', '2de', 'Comment réguler les réseaux sociaux ?', 'Qu’impose le Digital Services Act aux très grandes plateformes ?', 'mcq', '["La suppression des publicités","La vérification préalable de chaque message","L’identification obligatoire par carte d’identité","La transparence des algorithmes et un audit indépendant"]'::jsonb, 3, 'Le DSA exige transparence des algorithmes, analyse des risques, signalement facilité et audit indépendant.', 4),
    ('cadb42e9-89e7-5259-975a-cb701ba7ae40'::uuid, 'emc', '2de', 'Droits environnementaux dans un contexte de transition écologique', 'Quelle différence entre prévention et précaution ?', 'mcq', '["Il n’y en a aucune","La prévention vise un risque connu, la précaution un risque incertain","La précaution vise un risque connu, la prévention un risque incertain","La prévention concerne l’État, la précaution les entreprises"]'::jsonb, 1, 'On prévient un risque connu ; on prend des précautions face à un risque encore incertain mais grave et irréversible.', 1),
    ('72469bcb-f38e-5581-b038-ff0a850ba2d5'::uuid, 'emc', '2de', 'Droits environnementaux dans un contexte de transition écologique', 'Quel sommet de 1992 a popularisé la notion de développement durable ?', 'mcq', '["Le sommet de Paris","La convention d’Aarhus","Le sommet de Rio","Le sommet de Kyoto"]'::jsonb, 2, 'Le sommet de la Terre de Rio, en 1992, fait du développement durable une référence internationale.', 2),
    ('bb336fca-7853-5c68-ab97-b908352108e9'::uuid, 'emc', '2de', 'Droits environnementaux dans un contexte de transition écologique', 'Quelle valeur a la Charte de l’environnement ?', 'mcq', '["La même que la Déclaration de 1789","Celle d’un simple décret","Celle d’une recommandation sans effet","Celle d’un traité européen"]'::jsonb, 0, 'Adossée à la Constitution en 2005, elle a la même valeur que la Déclaration de 1789.', 3),
    ('f252aeaa-bcd4-5e30-948f-d39405ed3081'::uuid, 'emc', '2de', 'Droits environnementaux dans un contexte de transition écologique', 'Que crée la loi Climat et résilience, en plus de l’écocide ?', 'mcq', '["Une taxe carbone mondiale","L’interdiction des voitures","Le principe de précaution","Un délit général de pollution des milieux"]'::jsonb, 3, 'La loi de 2021 crée un délit général de pollution des milieux et, pour les atteintes les plus graves et intentionnelles, l’écocide.', 4),
    ('bd43ac7e-1399-5e3b-9768-6c3b78684bbe'::uuid, 'emc', '2de', 'S’engager en faveur d’une démocratie environnementale', 'À quoi sert une étude d’impact ?', 'mcq', '["À voter un projet","À évaluer les effets d’un aménagement","À sanctionner une entreprise","À tirer au sort des citoyens"]'::jsonb, 1, 'L’étude d’impact mesure à l’avance les effets d’un aménagement sur l’environnement.', 1),
    ('35edc554-aa62-5207-9913-655032e92dd0'::uuid, 'emc', '2de', 'S’engager en faveur d’une démocratie environnementale', 'Combien de propositions la Convention citoyenne pour le climat a-t-elle formulées ?', 'mcq', '["12","50","149","577"]'::jsonb, 2, 'Les 150 citoyens tirés au sort ont formulé 149 propositions, dont une partie a nourri la loi Climat et résilience.', 2),
    ('7478597f-3dfd-590b-8caa-ef62162c280b'::uuid, 'emc', '2de', 'S’engager en faveur d’une démocratie environnementale', 'Quelle tension oppose deux droits dans les projets environnementaux ?', 'mcq', '["Propriété contre intérêt général","Emploi contre protection","Urgence contre concertation","Vote contre pétition"]'::jsonb, 0, 'Propriété et intérêt général sont deux droits ; emploi contre protection oppose deux intérêts, urgence contre concertation deux temporalités.', 3),
    ('1c2e14cf-6849-53c2-ad23-6331b8b663d9'::uuid, 'emc', '2de', 'S’engager en faveur d’une démocratie environnementale', 'Comment réagir en ligne à un projet de décret environnemental ?', 'mcq', '["Par un référendum","Par une enquête de police","Par un recours au Conseil constitutionnel","Par une consultation en ligne"]'::jsonb, 3, 'La consultation en ligne permet à chacun de donner son avis sur un projet de décret, sans décider à la place de l’autorité.', 4),
    ('32767e1c-02a2-52a4-b7d2-7faa7df28b00'::uuid, 'emc', '2de', 'Quelle protection et quels droits pour les animaux ?', 'Que punissait la loi Grammont de 1850 ?', 'mcq', '["Toute forme d’élevage","Les mauvais traitements infligés publiquement aux animaux domestiques","Le commerce des espèces menacées","La chasse"]'::jsonb, 1, 'La loi Grammont ne punissait que les mauvais traitements publics : elle protégeait autant la sensibilité des passants que l’animal.', 1),
    ('383e5a84-c254-5c3c-a85b-38e13e7cf2dc'::uuid, 'emc', '2de', 'Quelle protection et quels droits pour les animaux ?', 'Depuis 2015, quel régime juridique s’applique toujours aux animaux ?', 'mcq', '["Celui des personnes","Celui des mineurs","Celui des biens","Aucun régime"]'::jsonb, 2, 'Reconnus comme êtres doués de sensibilité, les animaux restent soumis au régime des biens : une catégorie intermédiaire.', 2),
    ('0e043b9c-ea95-5a32-87e6-3fdc13bd000c'::uuid, 'emc', '2de', 'Quelle protection et quels droits pour les animaux ?', 'Quel philosophe défend des droits fondamentaux pour certains animaux ?', 'mcq', '["Tom Regan","Montesquieu","Rousseau","Voltaire"]'::jsonb, 0, 'Tom Regan défend l’idée que certains animaux ont des droits fondamentaux, au-delà de la seule réduction de la souffrance.', 3),
    ('f39bdb72-3a0b-50bd-92e8-b1b2411254d9'::uuid, 'emc', '2de', 'Quelle protection et quels droits pour les animaux ?', 'Que mesurent les listes rouges de l’UICN ?', 'mcq', '["Le commerce des animaux","Les conditions d’abattage","Les sites Natura 2000","L’état de conservation des espèces"]'::jsonb, 3, 'Les listes rouges évaluent le risque d’extinction de chaque espèce.', 4),
    ('4968eb7e-c6ed-590a-a9ca-b67c87304424'::uuid, 'grec', '3e', 'L’alphabet grec', 'Quelle lettre grecque ressemble à un « v » mais note un N ?', 'mcq', '["υ (upsilon)","ν (nu)","η (êta)","ρ (rhô)"]'::jsonb, 1, 'Le ν (nu) ressemble à notre « v » mais se lit « n » : c’est l’un des pièges de lecture de l’alphabet.', 1),
    ('91e0b631-48ed-5cf8-8ddf-3218e9ed52b2'::uuid, 'grec', '3e', 'L’alphabet grec', 'Que note la lettre ρ (rhô) ?', 'mcq', '["Un P","Un B","Un R","Un F"]'::jsonb, 2, 'Le rhô ressemble à notre « p » mais note un R ; le P grec s’écrit π (pi).', 2),
    ('2b26eb93-5e00-5d1f-a464-25036efd9b6f'::uuid, 'grec', '3e', 'L’alphabet grec', 'Quelle est la seule lettre grecque qui change de forme selon sa place dans le mot ?', 'mcq', '["Le sigma","L’oméga","L’êta","Le khi"]'::jsonb, 0, 'Le sigma s’écrit σ à l’intérieur du mot et ς en fin de mot, comme dans λόγος.', 3),
    ('e9dd3d98-771c-5b64-ad12-169dd5b0dff3'::uuid, 'grec', '3e', 'L’alphabet grec', 'Pourquoi « hippodrome » s’écrit-il avec un « h » ?', 'mcq', '["Parce que le mot vient du latin","Parce que ἵππος commence par un êta","Parce que c’est une règle d’orthographe française","Parce que ἵππος porte un esprit rude"]'::jsonb, 3, 'L’esprit rude note une aspiration : il explique les « h » du vocabulaire savant français (histoire, hippodrome).', 4),
    ('dcd5d8e7-97ff-5dd8-974e-8616fc46e3d5'::uuid, 'grec', '3e', 'Les mots grecs dans le français', 'Que signifie le préfixe grec « péri- » ?', 'mcq', '["À travers","Autour","Au-delà","Contre"]'::jsonb, 1, 'Péri- signifie « autour » : le périmètre est la mesure du tour d’une figure.', 1),
    ('fb3c6979-c657-51aa-8a66-a631dcc17bd4'::uuid, 'grec', '3e', 'Les mots grecs dans le français', 'Que signifie la racine « graphein » que l’on retrouve dans « orthographe » ?', 'mcq', '["Aimer","Parler","Écrire","Voir"]'::jsonb, 2, 'Graphein veut dire « écrire » : l’orthographe, c’est l’art d’écrire correctement.', 2),
    ('6da67360-88ba-5230-9ea1-67729665fb6f'::uuid, 'grec', '3e', 'Les mots grecs dans le français', 'De quoi s’occupe un néphrologue ?', 'mcq', '["Des reins","Du cœur","De la peau","Des poumons"]'::jsonb, 0, 'La racine néphr- désigne le rein ; la peau se dit derm-, le poumon pneum-.', 3),
    ('12d0bbd1-7c07-5145-ba6b-1da85c99c6a6'::uuid, 'grec', '3e', 'Les mots grecs dans le français', 'Que signifie littéralement « chronologie » ?', 'mcq', '["L’amour du temps","La mesure de la vie","L’écriture de l’histoire","Le discours sur le temps"]'::jsonb, 3, 'Chronologie = χρόνος (le temps) + λόγος (le discours, la science).', 4),
    ('225111e5-439a-5e37-be68-cc35b82fbd17'::uuid, 'grec', '3e', 'La mythologie grecque', 'Quel héros a vaincu Méduse, dont le regard pétrifiait ?', 'mcq', '["Thésée","Persée","Achille","Ulysse"]'::jsonb, 1, 'Persée a tranché la tête de Méduse, la Gorgone qui changeait en pierre ceux qui la regardaient.', 1),
    ('79a585a2-9794-591a-8d36-015b9ec53514'::uuid, 'grec', '3e', 'La mythologie grecque', 'Quel phénomène le mythe de l’enlèvement de Perséphone explique-t-il ?', 'mcq', '["L’origine du feu","Les malheurs humains","Le retour des saisons","La naissance des étoiles"]'::jsonb, 2, 'Quand Perséphone rejoint Hadès aux Enfers, sa mère Déméter, déesse des moissons, fait mourir la végétation : c’est l’hiver.', 2),
    ('d307c359-af63-59f2-9e6c-2f87381e159c'::uuid, 'grec', '3e', 'La mythologie grecque', 'Quel dieu est le messager des dieux et le protecteur des voyageurs ?', 'mcq', '["Hermès","Apollon","Arès","Héphaïstos"]'::jsonb, 0, 'Hermès, aux sandales ailées, porte les messages des dieux et protège les voyageurs.', 3),
    ('18608228-ffc2-5cdc-b719-96ee06d75d31'::uuid, 'grec', '3e', 'La mythologie grecque', 'Quelle est la différence entre Athéna et Arès, tous deux liés à la guerre ?', 'mcq', '["Athéna protège la mer, Arès la terre","Arès est une déesse, Athéna un dieu","Ils sont en réalité la même divinité","Athéna incarne la guerre stratégique, Arès la guerre brutale"]'::jsonb, 3, 'Athéna est la déesse de la sagesse et de la stratégie ; Arès, dieu de la violence guerrière.', 4),
    ('604fe644-1089-5977-a1cd-a9fbde39e512'::uuid, 'grec', '2de', 'La déclinaison grecque', 'Combien de cas compte le grec de moins que le latin ?', 'mcq', '["Aucun, ils en ont autant","Un seul : le grec n’a pas d’ablatif","Deux","Trois"]'::jsonb, 1, 'Le grec a cinq cas, le latin six : il n’y a pas d’ablatif, dont le datif reprend une partie des fonctions (moyen, lieu).', 1),
    ('c69d7129-f95e-586b-b8a7-28262ac64f01'::uuid, 'grec', '2de', 'La déclinaison grecque', 'Quel est le génitif de ὁ λόγος ?', 'mcq', '["τῆς λόγης","τὸ λόγον","τοῦ λόγου","τῷ λόγῳ"]'::jsonb, 2, 'Les masculins en -ος de la 2e déclinaison font leur génitif en -ου : τοῦ λόγου, « de la parole ».', 2),
    ('4d201230-f436-574a-a826-38ed0cd18310'::uuid, 'grec', '2de', 'La déclinaison grecque', 'À quelle déclinaison appartient ἡ τιμή (l’honneur) ?', 'mcq', '["À la 1re","À la 2e","À la 3e","Elle ne se décline pas"]'::jsonb, 0, 'La 1re déclinaison regroupe surtout des féminins en -η ou -α, comme τιμή.', 3),
    ('ae909612-d434-5340-95de-105f3de7846b'::uuid, 'grec', '2de', 'La déclinaison grecque', 'Devant un nom inconnu, quel est le meilleur indice pour trouver son cas ?', 'mcq', '["Sa place dans la phrase","Sa longueur","Sa première lettre","La terminaison de l’article qui l’accompagne"]'::jsonb, 3, 'L’article ὁ / ἡ / τό se décline aussi : lire sa terminaison donne le cas et fait gagner la moitié du travail.', 4),
    ('c69a99f2-3275-5ddd-986b-2370b1d1bef5'::uuid, 'grec', 'Tle', 'La déclinaison grecque', 'Combien de cas compte le grec de moins que le latin ?', 'mcq', '["Aucun, ils en ont autant","Un seul : le grec n’a pas d’ablatif","Deux","Trois"]'::jsonb, 1, 'Le grec a cinq cas, le latin six : il n’y a pas d’ablatif, dont le datif reprend une partie des fonctions (moyen, lieu).', 1),
    ('0d8268bd-b782-5ab9-ae66-5df08abe397c'::uuid, 'grec', 'Tle', 'La déclinaison grecque', 'Quel est le génitif de ὁ λόγος ?', 'mcq', '["τῆς λόγης","τὸ λόγον","τοῦ λόγου","τῷ λόγῳ"]'::jsonb, 2, 'Les masculins en -ος de la 2e déclinaison font leur génitif en -ου : τοῦ λόγου, « de la parole ».', 2),
    ('c08ae657-dd85-5e84-a21d-9b27b82b0556'::uuid, 'grec', 'Tle', 'La déclinaison grecque', 'À quelle déclinaison appartient ἡ τιμή (l’honneur) ?', 'mcq', '["À la 1re","À la 2e","À la 3e","Elle ne se décline pas"]'::jsonb, 0, 'La 1re déclinaison regroupe surtout des féminins en -η ou -α, comme τιμή.', 3),
    ('ac03a627-8777-5071-8e63-ff8f272a1e5b'::uuid, 'grec', 'Tle', 'La déclinaison grecque', 'Devant un nom inconnu, quel est le meilleur indice pour trouver son cas ?', 'mcq', '["Sa place dans la phrase","Sa longueur","Sa première lettre","La terminaison de l’article qui l’accompagne"]'::jsonb, 3, 'L’article ὁ / ἡ / τό se décline aussi : lire sa terminaison donne le cas et fait gagner la moitié du travail.', 4),
    ('baef1593-6681-5c2b-8dcd-8d63ea4ba65c'::uuid, 'grec', '2de', 'Athènes et la démocratie', 'Quelle réforme de Solon, en 594 av. J.-C., a marqué Athènes ?', 'mcq', '["Le tirage au sort des stratèges","L’abolition de l’esclavage pour dettes","La création du misthos","Le droit de vote des femmes"]'::jsonb, 1, 'Solon abolit l’esclavage pour dettes et classe les citoyens selon leur richesse.', 1),
    ('a758865a-c999-5170-a9a7-e1268cbffed3'::uuid, 'grec', '2de', 'Athènes et la démocratie', 'Qu’est-ce que l’Héliée à Athènes ?', 'mcq', '["L’assemblée qui vote la guerre","Le conseil qui prépare les lois","Le tribunal populaire","Le collège des dix stratèges"]'::jsonb, 2, 'L’Héliée est le tribunal populaire, composé de jurés tirés au sort parmi les citoyens.', 2),
    ('fabdd0dd-e2e4-5ffd-a38b-1f59f7d64a1b'::uuid, 'grec', '2de', 'Athènes et la démocratie', 'Parmi les habitants d’Athènes, quelle proportion environ était citoyenne ?', 'mcq', '["Un sur six","La moitié","Neuf sur dix","Tous les hommes libres"]'::jsonb, 0, 'Environ 40 000 citoyens sur 250 000 habitants : la démocratie athénienne était directe mais restreinte.', 3),
    ('de2923c6-d702-5d4d-bcfd-b66e236e3047'::uuid, 'grec', '2de', 'Athènes et la démocratie', 'Pourquoi le morcellement du monde grec en cités a-t-il favorisé l’invention politique ?', 'mcq', '["Parce qu’un roi unique imposait la démocratie","Parce que les cités n’avaient pas de territoire","Parce que toutes les cités avaient les mêmes lois","Parce que des cités indépendantes pouvaient expérimenter chacune leur régime"]'::jsonb, 3, 'Le monde grec n’est jamais un État unifié : des cités rivales et indépendantes rendent possible l’expérimentation politique.', 4),
    ('3f9b6838-b263-5acd-aaf8-fd643752ae2a'::uuid, 'grec', 'Tle', 'Athènes et la démocratie', 'Quelle réforme de Solon, en 594 av. J.-C., a marqué Athènes ?', 'mcq', '["Le tirage au sort des stratèges","L’abolition de l’esclavage pour dettes","La création du misthos","Le droit de vote des femmes"]'::jsonb, 1, 'Solon abolit l’esclavage pour dettes et classe les citoyens selon leur richesse.', 1),
    ('9cff95ec-9a56-5fb4-a35c-06ef58801058'::uuid, 'grec', 'Tle', 'Athènes et la démocratie', 'Qu’est-ce que l’Héliée à Athènes ?', 'mcq', '["L’assemblée qui vote la guerre","Le conseil qui prépare les lois","Le tribunal populaire","Le collège des dix stratèges"]'::jsonb, 2, 'L’Héliée est le tribunal populaire, composé de jurés tirés au sort parmi les citoyens.', 2),
    ('4e066638-391a-562c-9241-196f6b68b198'::uuid, 'grec', 'Tle', 'Athènes et la démocratie', 'Parmi les habitants d’Athènes, quelle proportion environ était citoyenne ?', 'mcq', '["Un sur six","La moitié","Neuf sur dix","Tous les hommes libres"]'::jsonb, 0, 'Environ 40 000 citoyens sur 250 000 habitants : la démocratie athénienne était directe mais restreinte.', 3),
    ('27da6b6b-692c-5960-9ae0-768cc02355c1'::uuid, 'grec', 'Tle', 'Athènes et la démocratie', 'Pourquoi le morcellement du monde grec en cités a-t-il favorisé l’invention politique ?', 'mcq', '["Parce qu’un roi unique imposait la démocratie","Parce que les cités n’avaient pas de territoire","Parce que toutes les cités avaient les mêmes lois","Parce que des cités indépendantes pouvaient expérimenter chacune leur régime"]'::jsonb, 3, 'Le monde grec n’est jamais un État unifié : des cités rivales et indépendantes rendent possible l’expérimentation politique.', 4),
    ('5ad68840-224b-5783-b59b-840ff91f4491'::uuid, 'grec', '2de', 'Théâtre et philosophie', 'Que désigne la némésis dans la tragédie grecque ?', 'mcq', '["La démesure du héros","Le châtiment qu’appelle la démesure","Le chant du chœur","La purgation des passions"]'::jsonb, 1, 'L’hybris (démesure) appelle la némésis (châtiment) : c’est la mécanique même de la tragédie.', 1),
    ('a69ae33d-5002-54ef-8af2-117860a7dea5'::uuid, 'grec', '2de', 'Théâtre et philosophie', 'Lequel de ces auteurs n’a PAS écrit de tragédies ?', 'mcq', '["Eschyle","Sophocle","Aristophane","Euripide"]'::jsonb, 2, 'Aristophane est l’auteur comique qui raille la vie politique d’Athènes ; les trois autres sont les grands tragiques.', 2),
    ('76fc7c23-9c1e-571b-85b2-4d5ab1b3d180'::uuid, 'grec', '2de', 'Théâtre et philosophie', 'Comment s’appelle la méthode de questionnement de Socrate ?', 'mcq', '["La maïeutique","La catharsis","La rhétorique","L’hybris"]'::jsonb, 0, 'Socrate « accouche les esprits » par ses questions : c’est la maïeutique.', 3),
    ('880972b2-e07b-5c8b-a83b-2952f2b76cd4'::uuid, 'grec', '2de', 'Théâtre et philosophie', 'Quelle école Platon a-t-il fondée ?', 'mcq', '["Le Lycée","Le Portique","Le Jardin","L’Académie"]'::jsonb, 3, 'Platon fonde l’Académie et écrit les *Dialogues* ; son disciple Aristote fondera le Lycée.', 4),
    ('e8fe2dfa-9e9f-5d8c-b3fa-7c29c9b05ef3'::uuid, 'grec', 'Tle', 'Théâtre et philosophie', 'Que désigne la némésis dans la tragédie grecque ?', 'mcq', '["La démesure du héros","Le châtiment qu’appelle la démesure","Le chant du chœur","La purgation des passions"]'::jsonb, 1, 'L’hybris (démesure) appelle la némésis (châtiment) : c’est la mécanique même de la tragédie.', 1),
    ('f2b17fdb-c31b-50ee-951b-fa671363ec0b'::uuid, 'grec', 'Tle', 'Théâtre et philosophie', 'Lequel de ces auteurs n’a PAS écrit de tragédies ?', 'mcq', '["Eschyle","Sophocle","Aristophane","Euripide"]'::jsonb, 2, 'Aristophane est l’auteur comique qui raille la vie politique d’Athènes ; les trois autres sont les grands tragiques.', 2),
    ('a28c6991-cb52-5db0-a1db-75a187b86a79'::uuid, 'grec', 'Tle', 'Théâtre et philosophie', 'Comment s’appelle la méthode de questionnement de Socrate ?', 'mcq', '["La maïeutique","La catharsis","La rhétorique","L’hybris"]'::jsonb, 0, 'Socrate « accouche les esprits » par ses questions : c’est la maïeutique.', 3),
    ('54ea162d-b2ef-580a-b52d-3373d8aceb3c'::uuid, 'grec', 'Tle', 'Théâtre et philosophie', 'Quelle école Platon a-t-il fondée ?', 'mcq', '["Le Lycée","Le Portique","Le Jardin","L’Académie"]'::jsonb, 3, 'Platon fonde l’Académie et écrit les *Dialogues* ; son disciple Aristote fondera le Lycée.', 4),
    ('878ae885-aca0-5663-8d3f-27c5b713429c'::uuid, 'latin', '3e', 'Rhétorique et citoyenneté', 'Quelle étape du discours consiste à mettre les idées en ordre ?', 'mcq', '["L’inventio","La dispositio","L’elocutio","L’actio"]'::jsonb, 1, 'Après avoir trouvé les idées (inventio), l’orateur les organise : c’est la dispositio.', 1),
    ('cf590274-4560-5903-a804-0e8f33942c85'::uuid, 'latin', '3e', 'Rhétorique et citoyenneté', 'Quelle est la dernière étape de la préparation d’un discours ?', 'mcq', '["La memoria","L’elocutio","L’actio, la prononciation","L’inventio"]'::jsonb, 2, 'Les cinq étapes vont de l’inventio à l’actio : on finit par prononcer le discours devant l’auditoire.', 2),
    ('a6b92bcc-aab5-55e7-be8b-8c4ca993f280'::uuid, 'latin', '3e', 'Rhétorique et citoyenneté', 'Quels sont les trois buts de l’orateur ?', 'mcq', '["Instruire, plaire et émouvoir","Voter, juger et commander","Lire, écrire et compter","Menacer, punir et récompenser"]'::jsonb, 0, 'L’orateur veut instruire son auditoire, lui plaire et l’émouvoir pour le convaincre.', 3),
    ('7b17fffc-4735-5c11-9802-2281883fa47e'::uuid, 'latin', '3e', 'Rhétorique et citoyenneté', 'Que signifie l’expression latine res publica ?', 'mcq', '["Le peuple romain","Le Sénat","La loi écrite","La chose publique"]'::jsonb, 3, 'Res publica, « la chose publique », a donné notre mot « république » : l’État appartient à tous.', 4),
    ('02c404d6-d5a4-5330-a992-f6460c1e9979'::uuid, 'latin', '3e', 'L''Empire romain', 'Que signifie le titre « Auguste » reçu par Octave ?', 'mcq', '["Le vainqueur","Le vénérable","Le fils de César","Le premier citoyen"]'::jsonb, 1, 'Augustus signifie « le vénérable » : ce titre religieux place Octave au-dessus des autres hommes.', 1),
    ('c8b826c4-364e-55a1-a28d-fe0c0115d29b'::uuid, 'latin', '3e', 'L''Empire romain', 'Quel empereur porte l’Empire à son extension maximale ?', 'mcq', '["Néron","Auguste","Trajan","Caracalla"]'::jsonb, 2, 'Sous Trajan, au début du IIe siècle, l’Empire romain atteint sa plus grande étendue.', 2),
    ('ae82368c-938d-5c2f-8554-f7159a31385a'::uuid, 'latin', '3e', 'L''Empire romain', 'Quel empereur est surnommé « l’empereur philosophe » ?', 'mcq', '["Marc Aurèle","Néron","Trajan","Auguste"]'::jsonb, 0, 'Marc Aurèle a écrit des *Pensées* inspirées de la philosophie stoïcienne.', 3),
    ('bfd090d8-016a-5e37-875f-d9ac677d83d3'::uuid, 'latin', '3e', 'L''Empire romain', 'Parmi ces éléments, lequel ne relève PAS de la romanisation ?', 'mcq', '["La langue latine","Le droit romain","Les villes avec forum et thermes","Les invasions qui affaiblissent l’Empire"]'::jsonb, 3, 'La romanisation diffuse la langue, le droit et les villes romaines ; les invasions, elles, contribuent à la chute de l’Empire d’Occident.', 4),
    ('9c5f5fcf-6ccf-553b-b8a3-3c34eb066296'::uuid, 'latin', '3e', 'Traduire des textes authentiques', 'Que signifie la terminaison -nt d’un verbe latin ?', 'mcq', '["Il ou elle","Ils ou elles","Je","Nous"]'::jsonb, 1, 'La terminaison donne la personne : -t pour « il/elle », -nt pour « ils/elles ».', 1),
    ('a86247e6-969c-5ef6-b2f8-4382a635e6d1'::uuid, 'latin', '3e', 'Traduire des textes authentiques', 'Quel cas exprime le complément d’attribution (« à ») ?', 'mcq', '["Le génitif","L’ablatif","Le datif","L’accusatif"]'::jsonb, 2, 'Le datif marque à qui l’on donne ou attribue quelque chose : « je donne à… ».', 2),
    ('010e27bc-ad6c-5264-8655-36170f66014c'::uuid, 'latin', '3e', 'Traduire des textes authentiques', 'Quel auteur latin a écrit l’*Énéide* ?', 'mcq', '["Virgile","César","Ovide","Cicéron"]'::jsonb, 0, 'Virgile raconte dans l’*Énéide* le voyage d’Énée, ancêtre légendaire des Romains ; Ovide a écrit les *Métamorphoses*.', 3),
    ('dcea87ae-2343-558e-8b4c-796994ecf7c6'::uuid, 'latin', '3e', 'Traduire des textes authentiques', 'Quelle est la dernière étape de la méthode de traduction ?', 'mcq', '["Repérer le verbe","Chercher le sujet au nominatif","Identifier les compléments grâce aux cas","Reconstruire une phrase française naturelle"]'::jsonb, 3, 'On analyse d’abord (verbe, sujet, compléments), et seulement ensuite on rédige une phrase française correcte.', 4),
    ('a2f5ddf3-1020-56e3-b101-89ae1dfc471a'::uuid, 'latin', '2de', 'Les cinq déclinaisons', 'Quel cas sert à interpeller quelqu’un (« ô maître ! ») ?', 'mcq', '["Le nominatif","Le vocatif","Le datif","L’ablatif"]'::jsonb, 1, 'Le vocatif est le cas de l’interpellation : on s’adresse directement à quelqu’un.', 1),
    ('ec304f6e-9035-5743-a128-ceb7ca8e0148'::uuid, 'latin', '2de', 'Les cinq déclinaisons', 'À quelle déclinaison appartient « res, rei » ?', 'mcq', '["À la 2e","À la 3e","À la 5e","À la 4e"]'::jsonb, 2, 'La 5e déclinaison se reconnaît à son génitif en -ei : res, rei ; dies, diei.', 2),
    ('7653172a-cd46-5f95-8e48-cfbe59dcb2d5'::uuid, 'latin', '2de', 'Les cinq déclinaisons', 'Par quoi se termine le pluriel d’un nom neutre au nominatif et à l’accusatif ?', 'mcq', '["Par -a","Par -us","Par -is","Par -ei"]'::jsonb, 0, 'Le pluriel neutre se termine par -a : un mot en -a peut donc être un féminin singulier ou un neutre pluriel.', 3),
